#   也不加回名义额度); 置 True = 把移交仓成本也计入上限分子, 得到硬性累计投入上限
#   (需用户明确启用, 启用后 20 万即成为历史累计投入的硬顶)。
HANDOFF_COUNT_IN_CAP = False
# ---- 审计修复G4: 运行日志文件持久化 ----
# True=log()同时追加写入脚本同目录运行日志文件(RUN_LOG_FILE); False=仅客户端日志窗。
LOG_TO_FILE = True
# ---- P3-01: 运行日志缓冲落盘(回调风暴下避免每行一次open/close) ----
LOG_FLUSH_INTERVAL = 0.2        # 缓冲距上次落盘超过该秒数即写盘
