MAX_DAILY_BUYS_LIVE = 3        # 实盘每日买入笔数上限(按交易日累计, 0=不限制) | 20261004用户确认: 3笔/日
MAX_DAILY_BUYS_PAPER = 3       # 纸面(回测/模拟)每日买入笔数上限(0=不限制) | 20261004用户确认: 3笔/日(与实盘同口径)
BUY_BLOCK_TAG = '手工封锁'      # P1修复: set_daily_buys.py MODE='BLOCK' 写入状态文件 buys 的封锁标记;
EXT_MERGE_INTERVAL_SEC = 300    # P2-2修复(2026-10-17): 轮询主动合并外部BLOCK的间隔秒数 ——
                               #   旧版只在save_state(写盘)前合并, 静默日(无成交无事件)人工封锁
                               #   可能延迟数小时才生效; 现按此间隔主动读盘合并(只合并不写盘)
                               #   策略识别该标记后当日禁止开新仓 —— 原 BLOCK 只把 buys.n 写到 DAILY_CAP,
                               #   而 MAX_DAILY_BUYS_*=0(默认不限制)时 daily_buy_left() 恒为 9999, BLOCK 完全不生效。
                               #   该标记在任意配置下都封得住(优先级高于笔数上限)。
MAX_DAILY_SELLS_LIVE = 0       # 实盘每日卖出笔数上限(0=不限制)
MAX_DAILY_SELLS_PAPER = 0      # 纸面(回测/模拟)每日卖出笔数上限(0=不限制)
