def is_kcb_code(code):
    base = str(code or '').split('.')[0]
    return base.startswith('688') or base.startswith('689')

def normalize_buy_volume(code, vol):
    """D3：主板按100股整手；科创板首笔至少200股，超过部分允许1股递增。"""
    v = max(0, int(_f(vol)))
    if is_kcb_code(code):
        return v if v >= 200 else 0
    lot = int(LOT_SIZE) if LOT_SIZE > 0 else 100
    return int(v // lot * lot)


def _lot_of(code):
    """P1-1(2026-10-24 第18轮零预设独立审计): 按板块返回最小申报单位(每笔委托的股数步长下限)。
    科创板(688/689)首笔至少200股(超过200股部分允许1股递增); 其余板块按 LOT_SIZE(100股)整手。
    修复背景: 旧版 calc_size / pyramid_alloc / buy_stock 一律按 LOT_SIZE=100 计算手数,
    EXCLUDE_KCB=False 放开科创板后, 688 候选按100股算出的首批常不足200股,
    最终在 normalize_buy_volume 处被整单拒发(日志还归因为"板块申报规则"),
    当日买入机会报废; 股价>333.33元的科创板更因单票额度66666.66元/200股
    永远算不出合法手数, 结构性无法建仓。"""
    try:
        if is_kcb_code(code):
            return 200
        return int(LOT_SIZE) if LOT_SIZE > 0 else 100
    except Exception:
        return 100

