# ==================== 套牢仓位人工介入(提醒 -> 冻结移交 -> 剔除 -> 释放持仓名额与资金额度) ====================
# 背景: 绝不止损定稿后, 亏损仓位会被长期持有等待回本, 资金与持仓名额被死死占住。
# 本机制负责在"长期亏损且按现有逻辑难以回本"时提醒人工介入, 并把该股踢出策略运作范围,
# 立即释放其占用的持仓名额与资金额度, 供策略重新分配给其它标的。
# 完整流转: 正常持仓 ->(触发阈值)-> 提醒人工 ->(默认自动)冻结移交 -> 剔除出股票池
#          -> 释放名额/额度 -> 只读监控(反弹/解套价再提醒) -> 人工卖出平仓 -> 解除剔除
TRAP_ALERT_ON = True           # 总开关: False=完全关闭套牢提醒与移交
TRAP_LOSS_PCT = 0.15           # 触发阈值①: 浮动亏损比例(现价/成本均价-1)达该值, 即 -15%
TRAP_LOSS_AMT_PCT = 0.03       # 触发阈值②: 浮动亏损金额达基准权益该比例, 即 权益x3%
TRAP_HOLD_TRDAYS = 20          # 触发阈值③: 持有满N个交易日(与①或②组合: 时间+空间双达标才触发)
                               #   ①②任一满足 + ③满足 才触发; 防止短线正常回撤被误判
TRAP_DEEP_LOSS_PCT = 0.25      # 快通道: 浮亏比例达该值(-25%)不看持仓天数, 立即触发(爆雷/深套)
TRAP_DEEP_MIN_TRDAYS = 2       # 快通道的持有交易日下限(避免T+1买入当日暴跌误触发)
TRAP_REBOUND_PCT = 0.08        # 择机提醒: 现价较"持仓期最低价"反弹达该比例(8%)时提示择机解套
TRAP_EXIT_NEAR_PCT = 0.01      # 择机提醒: 现价距"解套价"不足该比例(1%)时提示接近解套
TRAP_ALERT_COOLDOWN_TRDAYS = 5 # 去重: 同一只股票两次提醒之间至少间隔N个交易日(防刷屏)
TRAP_MAX_ALERTS = 3            # 去重: 同一只股票最多提醒N次(0=不限); 达上限后每日只在心跳里一行
TRAP_AUTO_HANDOFF = True       # 提醒后是否自动冻结移交(停止运作+剔除+释放); False=只提醒不移交
TRAP_EXCLUDE_FROM_PNL = True   # 移交仓位是否从策略盈亏口径剔除(其浮亏不再压制基准权益与手数)
TRAP_UNBAN_ON_EXIT = True      # 人工卖出平仓后, 是否自动把该股从黑名单移除(恢复交易范围)
TRAP_NOTIFY_WEBHOOK = True     # 提醒渠道: 是否随 NOTIFY_WEBHOOK 推送到手机(需已配置webhook)
TRAP_TAG = '套牢移交'           # 写入黑名单的原因前缀(解除剔除时只删带该前缀的条目, 不误删人工条目)
