def _prod_of(code=''):
    """零预设独立审计修复(V2.6.80): 按标的代码返回品种键名(显式字符串, 不做对象身份比较)。
    判断顺序与旧版 fee_profile 逐字一致: 港股通(.HK后缀或以HK开头) -> 逆回购(以1318/1319/2040/2041开头)
    -> 可转债(以11x/12x/127/128开头) -> ETF(以5/51/15开头且后缀为.SH/.SZ) -> 默认股票。
    返回 'stock'/'etf'/'hk'/'repo'/'cbond' 之一; 代码为空或无法识别时按 'stock' 处理。
    供 fee_profile/fee_buy/fee_sell 共用, 替代原先脆弱的 "_p is FEE_PROFILE['stock']" 身份比较
    (旧写法依赖 fee_profile 返回字典内同一对象引用, 一旦有人改成返回副本/深拷贝,
    股票会被误判成ETF而漏走 _transfer_rate_for, 沪市过户费口径失效)。"""
    _c = str(code or '').strip().upper()
    if not _c:
        return 'stock'
    _suf = _c.split('.')[-1] if '.' in _c else ''
    _n6 = ''.join(ch for ch in _c.split('.')[0] if ch.isdigit())
    if _suf == 'HK' or _c.startswith('HK'):
        return 'hk'
    if len(_n6) == 6 and _n6[:4] in ('1318', '1319', '2040', '2041'):
        return 'repo'
    if len(_n6) == 6 and _n6[:3] in ('110', '113', '118', '123', '127', '128'):
        return 'cbond'
    # P3(V2.6.83): 补 16x/18x 场内基金(LOF/封基) —— 旧版只认 5x/51/15, 16/18 开头的 LOF
    #   会被当成股票(多算印花税、佣金最低5元), 解套价/净利口径双双偏高。
    if (len(_n6) == 6 and _n6[:2] in ('51', '15', '16', '18')) or _n6[:1] == '5':
        return 'etf'
    return 'stock'

def fee_profile(code=''):
    """V2.6.69新增: 按标的代码返回所属品种的费率配置(从 FEE_PROFILE 取字典)。
    品种识别统一走 _prod_of(code) 返回的显式品种键, 再按键取费率表(V2.6.80改: 不再依赖
    返回字典内对象引用)。代码为空或无法识别时按'stock'处理, 与旧版行为完全一致。"""
    return FEE_PROFILE[_prod_of(code)]

