# P2-2修复(2026-10-19): param_fingerprint 排除清单——非行为型常量(纳入只会因部署
# 环境差异产生误报, 不会产生"行为变了却发现不了"的漏报, 故排除)
_FP_DENY = {
    'BLACKLIST_FILE', 'EMERGENCY_FILE', 'MANUAL_ALERT_FILE', 'PNL_LEDGER_CSV',
    'RUN_LOG_FILE', 'STATE_FILE', 'ST_HIST_FILE',            # 部署路径/文件名
    'CSV_ENCODING', 'LOG_ENCODING', 'LOG_FILE_ENCODING',     # 编码(环境相关)
    'NOTIFY_WEBHOOK', 'NOTIFY_ALLOWED_HOSTS', 'NOTIFY_TIMEOUT',  # 通知基础设施
    'ACCOUNT_ID', 'STRAT_TAG', 'BUY_BLOCK_TAG', 'TRAP_TAG',  # 账户/订单标签
    'ORDER_STATUS_MAP', 'PHASE_NAME',                        # 展示用映射(非决策)
    'SENT_STATE',                                            # 运行时状态(非配置)
    'VERSION',                                              # 版本号(非行为参数): 不参与参数指纹,
                                                            #   改由 code_fingerprint 单独纳入, 见函数说明
    'HISTORY_BARS',                                         # V2.6.150: 数据窗口(取几根日线), 非交易参数
                                                            #   与 VERSION 同一类: 纳入只会因调窗口误报
                                                            #   '参数未经样本外验证', 造成告警疲劳
}

def _fp_keys():
    """P2-2: 自动捕获行为型全局常量——UPPER_CASE、非下划线前缀、非 _FP_DENY、
    取值为标量/容器(int/float/bool/str/tuple/list/dict/None); 排除 G 等对象与函数。
    本函数只被 param_fingerprint 在启动时调用一次, 此时 globals() 已含全部常量
    (含文件后部的 SENT_*), 自动捕获安全。"""
    _T = (int, float, bool, str, tuple, list, dict, type(None))
    _g = globals()
    return [k for k in _g if k.isupper() and not k.startswith('_')
            and k not in _FP_DENY and isinstance(_g[k], _T)]


def _fp_calc(keys):
    # FNV-1a 32位: 返回 (8位十六进制, 原文); 原文用于人工比对哪个参数变了
    _raw = '|'.join('%s=%s' % (k, globals().get(k)) for k in keys)
    _h = 2166136261
    for _c in _raw.encode('utf-8'):
        _h = ((_h ^ _c) * 16777619) & 0xFFFFFFFF
    return '%08x' % _h, _raw


def param_fingerprint():
    """参数指纹(样本内外验证凭据): 只含行为参数, 【不含 VERSION】。
    同指纹 = 同一套参数组合; 任何参数变更后必须在样本外区间复跑并记录结果,
    严禁在全样本上反复调参(详见 README 的样本内外验证纪律)。
    V2.6.85修复: 把 VERSION 从本指纹中剔除 —— V2.6.70 曾将 VERSION 纳入指纹以覆盖
    "不改参数只改代码"的情形, 但副作用是每次升版指纹必变: 用户在状态文件记录
    verified_fp 后, 下次纯文案升版立刻红标"参数未经样本外验证", 反复误报导致告警
    疲劳, 真正改了参数时反而被忽略。现拆为两个指纹: 本函数(参数, 稳定) 供
    verified_fp 比对; code_fingerprint(参数+VERSION) 供"代码是否变更"提示。"""
    # P2-2修复(2026-10-19): 显式列表 -> 自动捕获(机制根治漏参)。原显式列表已三度漏参
    # (V2.6.81 新加的 MARKET_CAP_MIN_YI/MAX_YI、SENT_REGIME_PANIC_LO、
    # SENT_EVT_FRENZY_*/SENT_EVT_PANIC_* 等约40个行为参数未纳入), 指纹失真导致
    # "参数没变但行为变了"无法被发现; 现自动收集全部 UPPER_CASE 模块级常量(标量/
    # 容器), 仅排除与行为无关的路径/URL/编码/账户/展示映射/运行时状态(见 _FP_DENY)。
    # 注意: 本函数只在启动时调用一次, 此时 globals() 已含全部常量(含文件后部 SENT_*)。
    try:
        return _fp_calc(sorted(_fp_keys()))
    except Exception:
        return 'NA', ''


def code_fingerprint():
    """版本指纹 = 参数 + VERSION。
    与 param_fingerprint 分开的意义:
      * 参数指纹不变 + 版本指纹变  -> 只改了代码/文案, 参数本身没动(不红标, 只提示复核)
      * 参数指纹变   + 版本指纹变  -> 参数确实改了(红标 verified_fp 不一致, 须样本外复跑)
    旧版把两者合成一个数, 上述两种情形长得完全一样, 无法区分。"""
    try:
        return _fp_calc(sorted(list(_fp_keys()) + ['VERSION']))
    except Exception:
        return 'NA', ''

def ledger_append(rec):
    """成交明细落账: 状态文件(保留最近PNL_LEDGER_KEEP条) + CSV全量追加; 失败不影响交易"""
    if not PNL_TRACK_ON:
        return
    rec.setdefault('mode', pnl_mode_note())
    try:
        arr = G.state.get('trades')
        if not isinstance(arr, list):
            arr = []
            G.state['trades'] = arr
        arr.append(rec)
        if PNL_LEDGER_KEEP > 0 and len(arr) > PNL_LEDGER_KEEP:
            del arr[:len(arr) - PNL_LEDGER_KEEP]
    except Exception:
        traceback.print_exc()
    if not PNL_LEDGER_CSV:
        return
    try:
        p = ledger_path()
        need = not os.path.exists(p)
        # P2-7修复(2026-10-03): 编码统一走 CSV_ENCODING 常量(GBK), 勿改 UTF-8 BOM(混码)
        with open(p, 'a', newline='', encoding=CSV_ENCODING) as f:
            w = csv.writer(f)
            if need:
                w.writerow(['时间', '模式', '方向', '代码', '名称', '价格', '股数', '成交金额',
                            '费用', '净额', '已实现盈亏', '盈亏比例%', '持仓天数', '该股股数变化',
                            '组合持仓只数变化', '累计已实现盈亏', '原因/信号'])
            w.writerow([rec.get('ts', ''), rec.get('mode', ''), rec.get('dir', ''),
                        rec.get('code', ''), rec.get('name', ''), '%.3f' % _f(rec.get('price')),
                        int(_f(rec.get('vol'))), '%.2f' % _f(rec.get('amount')),
                        '%.2f' % _f(rec.get('fee')), '%.2f' % _f(rec.get('net')),
                        '%.2f' % _f(rec.get('pnl')), '%.2f' % _f(rec.get('pnl_pct')),
                        int(_f(rec.get('hold_days'))),
                        '%d->%d' % (int(_f(rec.get('pos_before'))), int(_f(rec.get('pos_after')))),
                        '%d->%d只' % (int(_f(rec.get('npos_before'))), int(_f(rec.get('npos_after')))),
                        '%.2f' % _f(rec.get('realized_after')), rec.get('reason', '')])
    except Exception:
        traceback.print_exc()

def ledger_buy(s, h, price, vol, reason, npos_before, was_new=True, pos_before=0, fee=None):
    """买入成交记账: 计费用入成本, 记录该股与组合持仓变化; 返回本条明细(调用方再提示开仓)
    V2.6.39b: 区分【首笔开仓】与【分批加仓】—— was_new=False 时组合只数不+1(加仓不新开仓),
    pos_before=该股加仓前已有股数, 展示为 A->B股 而非 0->本笔股数; 默认值保持旧版行为兼容

    V2.6.156: fee 可由调用方传入(实盘成交回报已按委托单归并算好, 见 _order_fee_delta)。
    传 None 时按单笔口径自算, 与旧版完全一致 —— 也避免同一笔成交的费被算两次。"""
    amt = _round2(price * vol)
    if fee is None:
        fee = fee_buy(amt, s)
    st = pnl_stat()
    st['fee'] = _round2(st['fee'] + fee)
    _pb = int(_f(pos_before) or 0)
    rec = {'ts': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
           'mode': pnl_mode_note(), 'dir': '买入', 'code': s, 'name': h.get('name', ''),
           'price': price, 'vol': int(vol), 'amount': amt, 'fee': fee,
           'net': _round2(amt + fee), 'pnl': 0.0, 'pnl_pct': 0.0, 'hold_days': 0,
           'pos_before': _pb, 'pos_after': _pb + int(vol),
           'npos_before': int(npos_before), 'npos_after': int(npos_before) + (1 if was_new else 0),
           'realized_after': st['pnl'], 'reason': reason or ''}
    ledger_append(rec)
    return rec

def ledger_sell(s, h, price, vol, reason, npos_before, order_id=''):
    """卖出成交记账: 按"卖出净收入-持仓成本(含费)"算已实现盈亏并累计胜负统计;
    部分卖出按比例结转成本; 返回明细dict(调用方再提示平仓)"""
    vol = int(vol)
    held = pos_vol(h) or vol
    cost_all = pos_cost(h)
    cost = _round2(cost_all * vol / held) if (held > 0 and vol < held) else cost_all
    amt = _round2(price * vol)
    fee = fee_sell(amt, s, order_id=order_id)
    net = _round2(amt - fee)
    pnl = _round2(net - cost)
    pct = (pnl / cost * 100.0) if cost > 0 else 0.0
    days = held_trd_days(h.get('buy_date', ''))
    st = pnl_stat()
    st['pnl'] = _round2(st['pnl'] + pnl)
    st['fee'] = _round2(st['fee'] + fee)
    st['n'] += 1
    if pnl > 0:
        st['wins'] += 1
        st['gross_win'] = _round2(st['gross_win'] + pnl)
        if pnl > st['best']:
            st['best'] = pnl
    elif pnl < 0:
        st['losses'] += 1
        st['gross_loss'] = _round2(st['gross_loss'] + pnl)
        if pnl < st['worst']:
            st['worst'] = pnl
    else:
        st['flat'] += 1
    closed = 1 if vol >= held else 0        # 全部卖出才算平掉一只
    rec = {'ts': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
           'mode': pnl_mode_note(), 'dir': '卖出', 'code': s, 'name': h.get('name', ''),
           'price': price, 'vol': vol, 'amount': amt, 'fee': fee, 'net': net,
           'pnl': pnl, 'pnl_pct': pct, 'hold_days': days,
           'pos_before': held, 'pos_after': max(0, held - vol),
           'npos_before': int(npos_before), 'npos_after': max(0, int(npos_before) - closed),
           'realized_after': st['pnl'], 'reason': reason or ''}
    ledger_append(rec)
    return rec

def _deal_diag_log(msg):
    """V2.6.53b: DEAL(当日成交明细)取数诊断, 每日最多输出一次, 防刷屏。
    精简 QMT 客户端可能不支持 DEAL 类型查询, 此处只记录现象供人工核对, 不改变任何交易逻辑。"""
    try:
        if getattr(G, 'deal_diag_date', '') == G.today:
            return
        G.deal_diag_date = G.today
        log('[手工卖出诊断] %s' % msg)
    except Exception:
        pass


def _deal_field_sample(d):
    """V2.6.53b: 提取 DEAL 记录的可诊断字段样例(仅用于日志, 不输出实盘敏感值)。"""
    try:
        return ('InstrumentID=%s ExchangeID=%s Price=%r Vol=%r Remark=%r Time=%r Dir=%r Offset=%r' % (
            str(getattr(d, 'm_strInstrumentID', '') or ''),
            str(getattr(d, 'm_strExchangeID', '') or ''),
            getattr(d, 'm_dPrice', ''),
            getattr(d, 'm_nVolume', ''),
            str(getattr(d, 'm_strRemark', '') or ''),
            str(getattr(d, 'm_strTradeTime', '') or getattr(d, 'm_strTime', '') or ''),
            getattr(d, 'm_nDirection', ''),
            getattr(d, 'm_nOffsetFlag', '')))
    except Exception:
        return '(字段不可读)'


def _find_manual_sell_deal(code):
    """V2.6.53b: 在柜台当日成交明细(DEAL)中反查该股的手工卖出真实成交价/量。
    返回 [(price, vol, remark), ...]；查不到或方向无法识别返回 []。
    判据: price>0、vol>0、备注不含 'SELL|' 前缀(策略卖出由成交回报入账, 这里排除防止重复记账)。
    P1-1修复(2026-10-17): 增加买卖方向过滤 —— m_nDirection(23=买/24=卖, 与passorder的
    opType同口径); 买入方向成交(含备注被柜台截断丢失前缀的策略买入)一律排除, 方向无法
    确定的不入账(只记诊断日志, 由调用方降级到估算兜底), 杜绝把策略买入/手工补仓误记成
    "手工卖出"的幽灵账(旧版实例: 策略买入6.33万成交被记成手工卖出6.33万)。
    DEAL 查询失败/返回空表时安全返回 [], 由调用方降级到原估算兜底。
    本函数只用于补记, 绝不触发任何真实卖出委托。"""
    try:
        deals = _api(get_trade_detail_data, G.accid, 'STOCK', 'DEAL') or []
    except Exception as _e:
        _deal_diag_log('DEAL取数异常: %s (该路径已安全降级到估算兜底)' % _e)
        return []
    if not deals:
        _deal_diag_log('DEAL返回空表(客户端可能不支持DEAL或当日无成交, 降级到估算兜底)')
        return []
    out = []
    _uncertain = 0
    for _d in deals:
        try:
            _cd = '%s.%s' % (getattr(_d, 'm_strInstrumentID', ''), getattr(_d, 'm_strExchangeID', ''))
            if _cd != code:
                continue
            _px = _f(getattr(_d, 'm_dPrice', 0.0))
            _vol = int(getattr(_d, 'm_nVolume', 0) or 0)
            _rm = str(getattr(_d, 'm_strRemark', '') or '')
            if 'SELL|' in _rm:
                continue          # 策略卖出: 已由成交回报入账, 排除防重复记账
            # P1-1修复(2026-10-17): 手工成交必须区分买卖方向 —— 旧版只按"备注不含SELL|"
            # 筛选, 策略自己的买入成交(备注BUY|被柜台截断丢失时)也会被当成"手工卖出"混入
            # 加权价, 账本记出"幽灵卖出"(一股没卖却记卖, 成本还被按卖出比例扣减)。
            # 方向字段: m_nDirection(23=买/24=卖, 与passorder的opType同口径)
            _dir = int(getattr(_d, 'm_nDirection', 0) or 0)
            if _dir == 23 or 'BUY|' in _rm:
                continue          # 买入方向成交: 绝不是手工卖出(疑手工补仓, 由reconcile方向C处理)
            if _dir != 24:
                # 方向无法确定: 不自动入账, 记待人工核对(调用方走估算兜底并强告警)
                _uncertain += 1
                continue
            if _px <= 0 or _vol <= 0:
                continue
            out.append((_px, _vol, _rm))
        except Exception:
            continue
    if _uncertain:
        _deal_diag_log('DEAL中%d笔成交方向无法确定(无m_nDirection且备注无方向前缀), 未自动入账, 请人工核对' % _uncertain)
    _deal_diag_log('DEAL总记录%d条, 该股命中%d笔(代码=%s); 字段样例: %s' % (len(deals), len(out), code, _deal_field_sample(deals[0])))
    return out


def estimate_close(s, h, note=''):
    """兜底补记平仓(仅实盘): 持仓记录已消失但账本没有对应卖出明细时, 按最近可得价补一笔,
    避免"每笔交易都有记录"出现缺口。已有成交回报记账过的不重复补记"""
    if not PNL_TRACK_ON:
        return
    try:
        ls = G.state.setdefault('ledger_sold', {})
        now_ts = time.time()
        for k in [x for x, v in ls.items() if now_ts - _f(v) > 7 * 86400]:
            ls.pop(k, None)
        if _f(ls.get(s, 0)) > 0 and now_ts - _f(ls.get(s, 0)) < 7 * 86400:
            return                      # 已有成交回报入账, 不重复补记
        # V2.6.53b: 先精确反查手工卖出成交 —— 策略未运行时用户在券商端手动卖出本策略持仓,
        # 成交回报无 BUY|/SELL| 备注且策略进程不在, deal_callback 不会触发入账, 旧逻辑用 last_px
        # 估算, 真实盈亏与账本存在偏差。现先用柜台当日成交明细(DEAL)反查真实成交价/量,
        # 命中则走 ledger_sell 精确入账并登记 ledger_sold 防重复; 未命中/DEAL不可用降级到原估算兜底。
        try:
            _deals = _find_manual_sell_deal(s)
        except Exception:
            _deals = []
        if _deals:
            _tvol = sum(_v for _p, _v, _r in _deals)
            _tamt = sum(_p * _v for _p, _v, _r in _deals)
            _px = (_tamt / _tvol) if _tvol > 0 else 0.0
            if _px > 0 and _tvol > 0:
                _vcap = min(_tvol, int(pos_vol(h))) if pos_vol(h) > 0 else _tvol
                if _vcap <= 0:
                    _vcap = _tvol
                rec = ledger_sell(s, h, _px, _vcap,
                                  (note or '手工卖出精确反查(DEAL成交明细)') + '(成交价%.2f)' % _px,
                                  mode_pos_count())
                ls[s] = now_ts
                log('[手工卖出] %s 精确入账 | %d股 加权均价@%.2f(DEAL明细%d笔, 首笔remark=%s) | 已实现盈亏=%s'
                    % (disp_code(s, h.get('name', '')), rec['vol'], _px, len(_deals),
                       _deals[0][2] or '(空)', fmt_pnl(rec['pnl'], rec['pnl_pct'])))
                alert_close(rec)
                return
        ctx = (G.state.get('sell_ctx') or {}).get(s)
        if ctx:
            # P1-3修复(2026-10-03): 旧逻辑"委托在途一律等成交回报"存在死锁风险 ——
            # 若成交回报丢失(撤单衔接断线/柜台漏报/进程重启错过回报), sell_ctx 会一直
            # 占位, estimate_close 永不补记, 账本永久缺一笔且持仓记录无法闭环。
            # 现改为: 在途超过 SELL_CTX_SETTLE_GRACE_SEC 仍无成交回报, 且调用方已确认
            # 柜台无仓(pos_total<=0, 见 _run_round_unlocked 两处调用前提)时, 以 sell_ctx
            # 为第二证据兜底补记(股数取本地与ctx较大者); 补记后清除 ctx —— 若回报迟到,
            # deal_callback 会因成本上下文缺失打警告日志提示人工核对, 但不会重复入账。
            if now_ts - _f(ctx.get('ts', 0)) <= SELL_CTX_SETTLE_GRACE_SEC:
                return                      # 正常在途: 等成交回报入账
            lp = _f(h.get('last_px', 0.0)) or _f(h.get('buy_price', 0.0))
            dvol = int(ctx.get('hold_vol') or 0)
            if lp <= 0 or (pos_vol(h) <= 0 and dvol <= 0):
                log(disp(s), '提示: 该笔卖出在途超期且无可用价格/股数, 盈亏账本未记录(请核对柜台成交单)')
                return
            vol = max(pos_vol(h), dvol)
            rec = ledger_sell(s, h, lp, vol,
                              (note or '无成交回报, 依据卖出在途上下文兜底补记') + '(估算价%.2f)' % lp,
                              mode_pos_count())
            ls[s] = now_ts
            # P2修复(2026-10-02): 估算平仓显式记账 —— 防"按最近价伪造盈亏"污染统计且无人察觉
            try:
                _r0 = G.state.get('realized')
                if isinstance(_r0, dict):
                    _r0['estimated_n'] = int(_r0.get('estimated_n', 0) or 0) + 1
                    _r0['estimated_pnl'] = _round2(_f(_r0.get('estimated_pnl', 0.0)) + _f(rec.get('pnl')))
            except Exception:
                pass
            try:
                G.state['sell_ctx'].pop(s, None)
            except Exception:
                pass
            log('[实盘] 平仓补记(在途超期, 依据卖出上下文) | %s | %d股 按最近价@%.2f | 已实现盈亏=%s'
                % (disp_code(s, ctx.get('name', '') or h.get('name', '')), rec['vol'], lp,
                   fmt_pnl(rec['pnl'], rec['pnl_pct'])))
            alert_close(rec)
            return
        lp = _f(h.get('last_px', 0.0)) or _f(h.get('buy_price', 0.0))
        if lp <= 0 or pos_vol(h) <= 0:
            log(disp(s), '提示: 该笔卖出无成交回报且无可用价格, 盈亏账本未记录(请核对柜台成交单)')
            return
        rec = ledger_sell(s, h, lp, pos_vol(h),
                          (note or '无成交回报, 按最近可得价估算') + '(估算价%.2f)' % lp,
                          mode_pos_count())
        ls[s] = now_ts
        # P2修复(2026-10-02): 估算平仓显式记账 —— 防"按最近价伪造盈亏"污染统计且无人察觉
        try:
            _r0 = G.state.get('realized')
            if isinstance(_r0, dict):
                _r0['estimated_n'] = int(_r0.get('estimated_n', 0) or 0) + 1
                _r0['estimated_pnl'] = _round2(_f(_r0.get('estimated_pnl', 0.0)) + _f(rec.get('pnl')))
        except Exception:
            pass
        log('[实盘] 平仓补记(无成交回报) | %s | %d股 按最近价@%.2f | 已实现盈亏=%s'
            % (disp_code(s, h.get('name', '')), rec['vol'], lp, fmt_pnl(rec['pnl'], rec['pnl_pct'])))
        alert_close(rec)
    except Exception:
        traceback.print_exc()

def alert_open(rec, cash_before=0.0, cash_after=0.0):
    """买入提示: 首笔显示开仓, 后续批次显示加仓; 股数与组合只数取账本真实前后值"""
    if not PNL_TRACK_ON:
        return
    vol = int(rec.get('vol') or 0)
    cost = _f(rec.get('net'))
    pos_before = int(_f(rec.get('pos_before', 0)) or 0)
    pos_after = int(_f(rec.get('pos_after', pos_before + vol)) or 0)
    npos_before = int(_f(rec.get('npos_before', 0)) or 0)
    npos_after = int(_f(rec.get('npos_after', npos_before)) or 0)
    action = '开仓' if pos_before <= 0 else '加仓'
    pnl_alert('[盈亏][%s] %s %s | %d股 @%.2f | 成交金额=%.2f 费用=%.2f 本笔成本=%.2f(含费均价%.3f)'
              ' | 持仓变化: 该股 %d->%d股, 组合 %d->%d只 | 信号: %s'
              % (rec.get('mode', ''), action,
                 disp_code(rec.get('code', ''), rec.get('name', '')), vol,
                 _f(rec.get('price')), _f(rec.get('amount')), _f(rec.get('fee')), cost,
                 (cost / vol) if vol > 0 else 0.0, pos_before, pos_after,
                 npos_before, npos_after, rec.get('reason', '')))

def alert_close(rec, cash_before=0.0, cash_after=0.0):
    """平仓提示: 已实现盈亏金额+比例+买卖两侧价格/金额/费用/持仓天数/持仓变化/累计统计(资金变化不输出)"""
    if not PNL_TRACK_ON:
        return
    st = pnl_stat()
    base = pnl_base_asset()
    cum_pct = pnl_pct_of(st['pnl'], base)
    pnl_alert('[盈亏][%s] 平仓 %s | %d股 @%.2f | 卖出金额=%.2f 费用=%.2f 净收入=%.2f '
              '(持仓成本%.2f含费) | 已实现盈亏=%s | 持仓%d个交易日 | 持仓变化: 组合%d->%d只, '
              '该股%d->%d股 | 累计已实现盈亏=%s(胜%d/负%d/平%d, 累计费用%.2f) | 信号: %s'
              % (rec.get('mode', ''), disp_code(rec.get('code', ''), rec.get('name', '')),
                 int(rec.get('vol') or 0), _f(rec.get('price')), _f(rec.get('amount')),
                 _f(rec.get('fee')), _f(rec.get('net')),
                 _round2(_f(rec.get('net')) - _f(rec.get('pnl'))),
                 fmt_pnl(_f(rec.get('pnl')), _f(rec.get('pnl_pct'))),
                 int(rec.get('hold_days') or 0),
                 int(rec.get('npos_before') or 0), int(rec.get('npos_after') or 0),
                 int(rec.get('pos_before') or 0), int(rec.get('pos_after') or 0),
                 fmt_pnl(st['pnl'], cum_pct), st['wins'], st['losses'], st['flat'], st['fee'],
                 rec.get('reason', '')))

def alert_unreal(s, h, lp, mv, unreal, pct, days, kind, level, step):
    """单票浮动盈亏跨档位提示: 成本/现价/市值/浮动盈亏金额与比例/档位/持仓天数/组合浮盈"""
    if not PNL_TRACK_ON:
        return
    vol = pos_vol(h)
    cost = pos_cost(h)
    avg = cost / vol if vol > 0 else 0.0
    tag = '浮盈' if kind == 'win' else '浮亏'
    thr = ('+%.0f%%' if kind == 'win' else '-%.0f%%') % (level * step * 100.0)
    pf = ''
    if G.pnl:
        pf = ' | 组合浮动盈亏=%s(持仓%d只)' % (fmt_money(_f(G.pnl.get('unreal'))),
                                              int(G.pnl.get('n') or 0))
    pnl_alert('[盈亏][%s] 持仓%s %s | %d股 成本均价%.3f(含费) 现价%.2f 市值=%.2f | '
              '浮动盈亏=%s | 跨越%s档位 | 持仓%d个交易日%s'
              % (pnl_mode_note(), tag, disp_code(s, h.get('name', '')), vol, avg, lp, mv,
                 fmt_pnl(unreal, pct), thr, days, pf))

def alert_portfolio(snap, sig, level):
    """组合总收益跨档位提示: 持仓只数/市值/现金/总资产/浮动盈亏/已实现/总收益"""
    if not PNL_TRACK_ON:
        return
    st = pnl_stat()
    base = _f(snap.get('base'))
    ret = _f(snap.get('ret'))
    tag = '累计盈利' if sig > 0 else '累计亏损'
    thr = ('+%.0f%%' if sig > 0 else '-%.0f%%') % (level * PNL_PF_STEP * 100.0)
    # 现金/总资产均为策略自身口径(预算+已实现-持仓成本 / 预算+已实现+浮盈), 不含实盘账户其他资金
    pnl_alert('[盈亏][%s] 组合%s跨越%s档位 | 持仓%d只 市值=%.2f 策略现金=%.2f 策略资产=%.2f | '
              '浮动盈亏=%s 已实现盈亏=%s | 总收益=%s(基准%.2f)'
              % (pnl_mode_note(), tag, thr, int(snap.get('n') or 0), _f(snap.get('mkt')),
                 _f(snap.get('cash')), _f(snap.get('asset')),
                 fmt_pnl(_f(snap.get('unreal')), _f(snap.get('unreal_pct'))),
                 fmt_money(st['pnl']), fmt_pnl(_f(snap.get('asset')) - base, ret), base))

    # [P2-3 FIX 2026-10-16] 统一计数体系说明(避免后续口径漂移):
    # 本代码存在三套并行计数, 各自职责边界:
    #  ① G.buy_cnt / G.sell_cnt       —— 进程内实时计数, 仅实盘运行期间有效, 重启清零;
    #                                    用于日志显示、委托日志频次, 非风控边界
    #  ② daily_buy_state / daily_sell_state —— 按 TRADE_MODE(live/paper) 分离的跨重载计数器,
    #                                    持久化在状态文件, 用于"每日最多X笔"风控闸门;
    #                                    发单前置 daily_buy_done/daily_sell_done 写入
    #  ③ _ledger_today_counts / _ledger_today_pnl —— 账本(trades)持久化统计, 跨重载/跨重启一致;
    #                                    alert_daily_report/状态签名/启动横幅等只读账本统计;
    #  一致性要求: 风控边界(②) ≥ 账本统计(③) ≥ 进程内计数(①)
def _ledger_today_counts():
    """V2.6.50b: 按账本(trades)统计当日买入/卖出笔数。
    用于状态更新与状态签名，替代进程内G.buy_cnt/G.sell_cnt：
    进程重启不会清零，与全天汇总口径一致。失败时退回进程内计数。"""
    d = str(G.today or datetime.datetime.now().strftime('%Y%m%d'))
    nb = ns = 0
    try:
        for _r in (G.state.get('trades') or []):
            _t = str(_r.get('ts', ''))[:10].replace('-', '')
            if _t != d:
                continue
            _dir = str(_r.get('dir', ''))
            if _dir == '买入':
                nb += 1
            elif _dir.startswith('卖出'):
                ns += 1
    except Exception:
        return int(G.buy_cnt or 0), int(G.sell_cnt or 0)
    return nb, ns


def _ledger_today_pnl():
    """V2.6.52b: 按账本(trades)统计当日已实现盈亏(仅卖出方向)。
    与 _ledger_today_counts() 使用同一日期过滤规则(trades.ts 的 YYYYMMDD == G.today)。
    供收盘全天汇总/未来10分钟汇总复用, 失败时返回 0.0 且不中断。"""
    d = str(G.today or datetime.datetime.now().strftime('%Y%m%d'))
    tot = 0.0
    try:
        for _r in (G.state.get('trades') or []):
            _t = str(_r.get('ts', ''))[:10].replace('-', '')
            if _t != d:
                continue
            if str(_r.get('dir', '')).startswith('卖出'):
                tot = _round2(tot + _f(_r.get('pnl')))
    except Exception:
        return 0.0
    return tot


def alert_daily_report(snap):
    """全天盈亏汇总提示(每交易日PNL_DAILY_REPORT_HM一次): 今日成交/今日已实现/持仓浮盈/总收益"""
    if not PNL_TRACK_ON:
        return
    st = pnl_stat()
    d = G.today or datetime.datetime.now().strftime('%Y%m%d')
    nbuy, nsell = _ledger_today_counts()   # V2.6.51b: 当日买卖笔数统一走账本口径(与状态更新同一函数)
    today_pnl = _ledger_today_pnl()   # V2.6.52b: 当日已实现盈亏统一走账本口径(唯一入口)
    base = _f(snap.get('base'))
    stale = ' | 注: 收盘价缺失, 浮动盈亏按最近可得价/成本价估算' if snap.get('stale') else ''
    # 现金/总资产均为策略自身口径(预算+已实现-持仓成本 / 预算+已实现+浮盈), 不含实盘账户其他资金
    pnl_alert('[盈亏][%s] 全天汇总 %s | 今日成交: 买入%d笔 卖出%d笔 | 今日已实现盈亏=%s | '
              '持仓%d只 市值=%.2f 浮动盈亏=%s | 策略现金=%.2f 策略资产=%.2f | 总收益=%s(基准%.2f) | '
              '累计已实现盈亏=%s(已平仓%d笔 胜%d/负%d/平%d, 单笔最佳%s/最差%s, 累计费用%.2f)%s'
              % (pnl_mode_note(), d, nbuy, nsell,
                 fmt_pnl(today_pnl, pnl_pct_of(today_pnl, base)),
                 int(snap.get('n') or 0), _f(snap.get('mkt')),
                 fmt_pnl(_f(snap.get('unreal')), _f(snap.get('unreal_pct'))),
                 _f(snap.get('cash')), _f(snap.get('asset')),
                 fmt_pnl(_f(snap.get('asset')) - base, _f(snap.get('ret'))), base,
                 fmt_money(st['pnl']), st['n'], st['wins'], st['losses'], st['flat'],
                 fmt_money(st['best']), fmt_money(st['worst']), st['fee'], stale))
    # P2修复(2026-10-02): 估算补记显式披露 —— 统计含估算成分时必须让用户看得见
    if int(st.get('estimated_n', 0) or 0) > 0:
        pnl_alert('[盈亏][%s] 估算补记提示 %s | 账本中有%d笔平仓为"无成交回报按最近价估算"(合计%s, '
                  '非真实成交价): 总收益/已实现盈亏含估算成分, 核对请以柜台成交单为准'
                  % (pnl_mode_note(), d, int(st['estimated_n']),
                     fmt_money(_f(st.get('estimated_pnl', 0.0)))))
    # P0修复(2026-10-02): 真实权益口径披露 —— 移交仓浮亏已计入组合熔断/硬约束判定
    if int(snap.get('handoff_n') or 0) > 0:
        pnl_alert('[盈亏][%s] 真实权益口径 %s | 已移交套牢仓%d只(市值%.2f 浮亏%s)已剔出策略账本口径; '
                  '含移交仓的真实总收益=%s(基准%.2f) —— 组合熔断/硬约束按此口径判定'
                  % (pnl_mode_note(), d, int(snap['handoff_n']),
                     _f(snap.get('handoff_mkt')), fmt_money(_f(snap.get('handoff_unreal'))),
                     fmt_pnl(_f(snap.get('asset_all')) - base, _f(snap.get('ret_all'))), base))

def pnl_halfhour_report(snap):
    """每10分钟盈亏汇总(仅交易时段): 持仓逐只浮盈明细 + 累计已清仓 + 当日清仓明细 + 组合总览。
    2026-10-14 用户新增: 30分钟一次; 20261027 按用户要求改为10分钟一次(周期由常量控制)。
    只在交易时段调用(pnl_tick已判定); 距上次输出>=PNL_HALF_HOUR_REPORT_SEC(现900秒)才输出。
    hh_report_ts=0(首次运行)时立即输出一次作为基准, 之后每10分钟一条。"""
    if not PNL_TRACK_ON or PNL_HALF_HOUR_REPORT_SEC <= 0:
        return False
    now = datetime.datetime.now()
    m = pnl_meta()
    last = float(_f(m.get('hh_report_ts', 0.0)) or 0.0)
    if last > 0 and (now - datetime.datetime.fromtimestamp(last)).total_seconds() < PNL_HALF_HOUR_REPORT_SEC:
        return False
    m['hh_report_ts'] = time.time()
    st = pnl_stat()
    base = _f(snap.get('base'))
    d = now.strftime('%Y-%m-%d %H:%M')
    lines = []
    lines.append('持仓盈亏(%d只):' % int(snap.get('n') or 0))
    codes = snap.get('codes') or {}
    for s, cd in sorted(codes.items()):
        h = (G.state.get('hold') or {}).get(s) or {}
        nm = h.get('name', '')
        avg = (cd['cost'] / cd['vol']) if cd['vol'] > 0 else 0.0
        # 20261027 用户要求: 每条持仓同时给出"若现在卖出扣完全部费用后的净利"与"解套价"。
        #   只读展示, 不改任何判定; 计算直接复用卖出闸门同款函数(net_pnl_if_sell /
        #   exit_price_needed), 保证"报表说能卖"与"下单真的放行"是同一套算法, 不会两套口径。
        _sh = str(s).upper().split('.')[-1] != 'SZ'      # 沪市才收过户费; 深市由 _transfer_rate_for 返回0
        _cvol = int(cd['vol'])
        _sell_net = net_pnl_if_sell(h, cd['price'], s, _cvol)
        _xp = exit_price_needed(h, s, _cvol)
        if _sell_net > 0:
            _sell_txt = '可卖(净赚%.2f)' % _sell_net
        else:
            _sell_txt = '不可卖(扣费亏%.2f)' % (-_sell_net if _sell_net < 0 else 0.0)
        if _xp > 0 and cd['price'] > 0:
            _gap = (_xp / cd['price'] - 1.0) * 100.0
            if _gap > 0.005:
                _xp_txt = '解套价%.2f(还需涨%.2f%%, 即%.2f元)' % (_xp, _gap, _xp - cd['price'])
            else:
                _xp_txt = '解套价%.2f(现价已达, 扣费即可净赚)' % (_xp,)
        else:
            _xp_txt = '解套价取不到'
        lines.append('  %s | %d股 成本均价%.3f(含费) 现价%.2f 市值=%.2f | 浮动盈亏=%s | 持仓%d个交易日'
                     % (disp_code(s, nm), int(cd['vol']), avg, cd['price'], cd['mv'],
                        fmt_pnl(cd['unreal'], cd['pct']),
                        held_trd_days(h.get('buy_date', ''))))
        lines.append('      -> 若现在卖出: %s | %s' % (_sell_txt, _xp_txt))
    lines.append('  合计: 市值=%.2f 成本=%.2f 浮动盈亏=%s'
                 % (_f(snap.get('mkt')), _f(snap.get('cost')),
                    fmt_pnl(_f(snap.get('unreal')), _f(snap.get('unreal_pct')))))
    lines.append('已清仓盈亏: 累计已平仓%d笔 胜%d/负%d/平%d 累计已实现盈亏=%s 累计费用=%.2f'
                 % (st['n'], st['wins'], st['losses'], st['flat'], fmt_money(st['pnl']), st['fee']))
    if st['n'] > 0:
        lines.append('  单笔最佳=%s 单笔最差=%s' % (fmt_money(st['best']), fmt_money(st['worst'])))
    # 20261027 用户要求: 清仓明细改为"当日累计全部展开" —— 旧版只看近N分钟窗口,
    #   一笔卖出只在它发生后那一次报表里出现, 错过就再也看不到了。现在每份报表都
    #   把【当日全部清仓单】逐笔列出, 并额外标出"本次新增"(距上次报表之间产生的),
    #   便于盘中随时回看今天卖了什么、每笔赚赔多少。跨自然日自动只留当天。
    #   只改展示口径: 不参与任何盈亏计算, 不影响买卖判据与风控闸门。
    _today_s = str(G.today or '')
    sells = []
    for r in (G.state.get('trades') or []):
        if not str(r.get('dir', '')).startswith('卖出'):
            continue
        _rts_raw = str(r.get('ts', '') or '')
        # 日期部分直接取前10位(YYYY-MM-DD), 解析失败则不按当日处理, 避免脏数据混入
        if _rts_raw[:10] != ('%s-%s-%s' % (_today_s[:4], _today_s[4:6], _today_s[6:8])):
            continue
        sells.append(r)
    # 本次新增 = 距上一次报表时间戳之后产生的(首次运行 last<=0 时全部算新增)
    _new_begin = datetime.datetime.fromtimestamp(last) if last > 0 else None
    _new_items = []
    for r in sells:
        if _new_begin is None:
            _new_items.append(r)
            continue
        try:
            _rts = datetime.datetime.strptime(str(r.get('ts', '')), '%Y-%m-%d %H:%M:%S')
        except Exception:
            continue
        if _rts > _new_begin:
            _new_items.append(r)
    if sells:
        _sum_pnl = sum(_f(r.get('pnl')) for r in sells)
        _sum_txt = ('+%.2f元(盈利)' % _sum_pnl) if _sum_pnl > 0 else                    (('%.2f元(亏损)' % _sum_pnl) if _sum_pnl < 0 else '0.00元(持平)')
        lines.append('  当日清仓(累计%d笔, 合计%s): %s'
                     % (len(sells), _sum_txt,
                        ('本次新增%d笔' % len(_new_items)) if _new_items else '本次无新增'))
        _new_ids = set(id(x) for x in _new_items)
        for r in sells:
            _msg = ('    %s%s 卖出价%.2f %d股 已实现盈亏=%s '
                    % ('[新] ' if id(r) in _new_ids else '',
                       disp_code(r.get('code', ''), r.get('name', '')),
                       _f(r.get('price')), int(_f(r.get('vol'))),
                       fmt_pnl(_f(r.get('pnl')), _f(r.get('pnl_pct')))))
            _why = str(r.get('reason', '') or '')
            if _why:
                _msg += _why
            lines.append(_msg)
    else:
        lines.append('  当日清仓: 无')
    lines.append('组合总览: 策略现金=%.2f 策略资产=%.2f 总收益=%s(基准%.2f)'
                 % (_f(snap.get('cash')), _f(snap.get('asset')),
                    fmt_pnl(_f(snap.get('asset')) - base, _f(snap.get('ret'))), base))
    if int(snap.get('handoff_n') or 0) > 0:
        lines.append('真实权益口径: 已移交套牢仓%d只(市值%.2f 浮亏%s)已剔出策略账本; 含移交仓真实总收益=%s'
                     % (int(snap['handoff_n']), _f(snap.get('handoff_mkt')),
                        fmt_money(_f(snap.get('handoff_unreal'))),
                        fmt_pnl(_f(snap.get('asset_all')) - base, _f(snap.get('ret_all')))))
    if int(st.get('estimated_n', 0) or 0) > 0:
        lines.append('注: 已实现盈亏含%d笔估算补记(合计%s), 核对请以柜台成交单为准'
                     % (int(st['estimated_n']), fmt_money(_f(st.get('estimated_pnl', 0.0)))))
    msg = '[盈亏][%s] 10分钟报 %s\n%s' % (pnl_mode_note(), d, '\n'.join(lines))
    pnl_alert(msg)
    return True

def pnl_brief():
    """一行式盈亏摘要(心跳打点用): 浮动盈亏/已实现盈亏/总收益(总资产不显示)"""
    if not PNL_TRACK_ON:
        return '盈亏统计已关闭'
    st = pnl_stat()
    snap = G.pnl or {}
    base = pnl_base_asset()
    s = '浮动盈亏=%s 已实现盈亏=%s' % (fmt_money(_f(snap.get('unreal'))), fmt_money(st['pnl']))
    if _f(snap.get('asset')) > 0:
        s += ' 总收益=%s(%.2f%%)' % (fmt_money(_f(snap.get('asset')) - base),
                                     pnl_pct_of(_f(snap.get('asset')) - base, base))
    return s


def strategy_status_signature(phase=None):
    """生成策略状态签名；仅业务状态变化才触发状态日志刷新。
    触发字段: 交易日、市场时段、日初始化阶段、账号/状态文件可用性、候选代码及排序、
    自有持仓代码/股数/退出与分批状态、买卖累计笔数、熔断状态、累计已实现盈亏(按分取整)、财务数据源可用性。
    时间戳不进入签名，因此时间流逝、轮询执行不会单独触发刷新。
    【2026-10-02 用户要求: 存活打点改静默】浮动盈亏/总资产(随行情每轮变动)不再进入签名 ——
    旧版把它们按分取整也算作触发字段, 盘中几乎每轮签名都变, 心跳实际退化成"定时打点";
    现在价格类指标仍照常写进日志正文, 只是不再单独触发输出(需按盈亏触发见 HB_PNL_TRIGGER_PCT)。
    P3(V2.6.83): 整个构造过程持 G.state_lock —— state['hold'] 会被成交回报线程同时增删,
    旧版无锁遍历可能抛 "dictionary changed size during iteration" 导致本轮巡检中断;
    RLock 可重入, 已在持锁路径(轮询)内调用时不会死锁。"""
    with G.state_lock:
        state = G.state or {}
        hold_sig = []
        for code, h in sorted((state.get('hold') or {}).items()):
            if not is_own_position(h):
                continue
            if h.get('closed'):
                continue        # V2.6.185: 已全部卖出的仓位不算自有持仓
            hold_sig.append((code, int(h.get('buy_vol') or 0), bool(h.get('exited')),
                             int(h.get('plan_idx') or 0), bool(h.get('plan_done')),
                             int(h.get('pend_vol') or 0), bool(h.get('closed'))))
        cand_sig = tuple(c.get('stock') for c in (G.candidates or []))
        meta = state.get('pnlmeta') or {}
        fuse_sig = (bool(meta.get('fuse_on')), str(meta.get('fuse_until') or ''),
                    bool(meta.get('manual_resume')))
        _d_nb, _d_ns = _ledger_today_counts()   # V2.6.50b: 账本当日笔数(与全天汇总一致)
        return (G.today or '', phase if phase is not None else market_phase(), int(G.dl_phase or 0),
                G.acct_ok, bool(G.state_broken), cand_sig, tuple(hold_sig),
                _d_nb, _d_ns, fuse_sig,
                int(round(_f((state.get('realized') or {}).get('pnl')) * 100)),
                bool(getattr(G, 'loss_data_ok', True)))

def strategy_pnl_value():
    """心跳阈值判据(元): 浮动盈亏 + 总资产相对基准资产的变动。
    仅当 HB_PNL_TRIGGER_PCT > 0 时参与触发判定; 当前设定 0.01(=基准权益1%), 设0=不参与。"""
    snap = G.pnl or {}
    v = _f(snap.get('unreal'))
    if _f(snap.get('asset')) > 0:
        v += _f(snap.get('asset')) - pnl_base_asset()
    return v

def status_log_if_changed(phase=None, force=False):
    """状态变化时输出一条快照；无变化返回False且不刷新日志。
    【2026-10-02 用户要求: 存活打点改静默】触发条件以业务状态签名为准;
    行情驱动的浮动盈亏/总资产只在越过 HB_PNL_TRIGGER_PCT(当前0.01=基准权益1%)阈值时才额外触发。"""
    sig = strategy_status_signature(phase)
    cur = strategy_pnl_value()
    if not force:
        if G.last_status_sig == sig:
            if HB_PNL_TRIGGER_PCT <= 0 or G.last_hb_pnl is None:
                return False
            _base = pnl_base_asset()
            if _base <= 0 or abs(cur - _f(G.last_hb_pnl)) < _base * HB_PNL_TRIGGER_PCT:
                return False
    G.last_status_sig = sig
    G.last_hb_pnl = cur
    _ds = '' if bool(getattr(G, 'loss_data_ok', True)) else ' | 财务数据=【不可用】(缺失股票已保守剔除，待补数重筛)'
    # V2.6.98(1): 这一位原来直接把 dl_phase 的整数印成'初始化阶段', 但它在代码里的含义是
    #   0=阶段机空闲 / 1=下载中 / 2=待加载, 而初始化完成后(5497)恰好把 dl_phase 重置为 0 ——
    #   于是'已完成'被印成 '初始化阶段=0', 字面像'还没开始'。2026-10-20 两份日志正好相反:
    #   00:22:35(下载中)打 =1, 00:47:54(已完成)打 =0, 看日志的人会以为后者没准备好。
    _ph_map = {0: u'已完成', 1: u'下载中', 2: u'待加载'}
    _ph_val = int(sig[2] or 0)
    _ph_txt = _ph_map.get(_ph_val, u'未知%d' % _ph_val)
    log('策略状态更新 | 时段=%s | 数据阶段=%s(dl_phase=%d) | 账号=%s | 状态文件=%s | 持仓%d只 候选%d只 | %s | 账本成交 买入%d笔/卖出%d笔(成交入账口径, 含手工卖出; 策略实发单另见[汇总]行)%s'
        % (PHASE_NAME.get(sig[1], sig[1]), _ph_txt, _ph_val,
           '就绪' if G.acct_ok is not False else '异常',
           '异常' if G.state_broken else '正常', len(sig[6]), len(sig[5]),
           pnl_brief(), sig[7], sig[8], _ds))   # V2.6.50b: 当日买卖笔数(账本口径, sig第7/8位)
    return True

def pnl_startup_note():
    """启动时输出盈亏账本概况: 累计已实现盈亏/胜率/持仓成本合计/基准资产/提示档位配置"""
    if not PNL_TRACK_ON:
        log('盈亏账本与提示: 已关闭(PNL_TRACK_ON=False), 仅输出原有买卖日志')
        return
    try:
        st = pnl_stat()
        base = pnl_base_asset()
        hold = G.state.get('hold') or {}
        mine = [h for h in hold.values() if not h.get('exited') and is_own_position(h)]
        cost_sum = 0.0
        for h in mine:
            cost_sum = _round2(cost_sum + pos_cost(h))
        nrec = len(G.state.get('trades') or [])
        win_rate = (st['wins'] * 100.0 / st['n']) if st['n'] > 0 else 0.0
        log('盈亏账本: 累计已实现盈亏=%s(已平仓%d笔 胜%d/负%d/平%d 胜率%.1f%%, 单笔最佳%s/最差%s, 累计费用%.2f元)'
            % (fmt_money(st['pnl']), st['n'], st['wins'], st['losses'], st['flat'], win_rate,
               fmt_money(st['best']), fmt_money(st['worst']), st['fee']))
        log('盈亏账本: 在持%d只 持仓成本合计=%.2f元(含买入费用; 上方单票金额为不含费口径) | 明细%d笔(CSV=%s, 状态文件保留最近%d笔) | '
            '提示档位: 单票浮盈%.0f%%/浮亏%.0f%%一档, 组合%.0f%%一档, 全天汇总=%s, '
            '10分钟汇总=%s'
            % (len(mine), cost_sum, nrec, PNL_LEDGER_CSV or '未启用', PNL_LEDGER_KEEP,
               PNL_WIN_STEP * 100, PNL_LOSS_STEP * 100, PNL_PF_STEP * 100,
               ('%02d:%02d' % (PNL_DAILY_REPORT_HM // 100, PNL_DAILY_REPORT_HM % 100))
               if PNL_DAILY_REPORT_HM > 0 else '关闭',
               ('每%d秒' % PNL_HALF_HOUR_REPORT_SEC)
               if PNL_HALF_HOUR_REPORT_SEC > 0 else '关闭'))
        if not FEE_ON:
            log('提示: FEE_ON=False, 盈亏为纯价差口径(未计佣金/印花税/过户费)')
    except Exception:
        traceback.print_exc()

def pnl_tick():
    """交易时段每轮: 用最新行情实时计算每只持仓浮动盈亏与组合快照。
    P1-13: 自持锁(可重入) —— 旧版依赖timer_poll外层大锁, 导致全市场取数/下载期间
    全部回调被阻塞; 锁粒度收窄后本函数自行持锁保护G.state读写"""
    if not PNL_TRACK_ON or not G.state:
        return
    if is_trading_day() is not True:
        return
    ticks = None
    if market_phase() == 'trading':
        try:
            with G.state_lock:
                _h = G.state.get('hold') or {}
                _w = [s for s, h in _h.items()
                      if not h.get('exited') and is_own_position(h)]
                # V2.6.73修复(2026-10-19, 用户确认): 候选股也纳入本通道取数 ——
                # 旧版此处只刷持仓, 候选股实时价在本通道恒为0, 导致下方
                # '候选股行情断流'告警每日误报一次(与run_round买入通道不同步);
                # 现把候选股一并取数, 告警口径与实际买入决策一致, 不再误报。
                # 仅影响本通道的可观测性, 不改变任何交易触发逻辑与铁律。
                _ch = [c['stock'] for c in (getattr(G, 'candidates', []) or [])
                       if c.get('stock') and c['stock'] not in _w]
                if _ch:
                    _w = _w + _ch
            if _w:
                ticks = _refresh_ticks(_w)     # V2.6.30 B→C (V2.6.73: 含候选股)
            else:
                ticks = {}
        except Exception:
            ticks = {}
            # P2-9修复: 关键路径(行情取数)异常不得静默 —— 每交易日提示一条
            if getattr(G, 'tick_err_date', '') != G.today:
                G.tick_err_date = G.today
                log('[告警] 持仓行情取数异常(get_full_tick), 本轮按缓存价计算(每交易日提示一次)')
    with G.state_lock:
        _pnl_tick_unlocked(ticks)

def _pnl_tick_unlocked(ticks=None):
    """原pnl_tick主体(P1-13: 由pnl_tick加锁包装调用, 逻辑不变)。
    P1-2修复(2026-10-02): 行情取数改由 pnl_tick 在锁【外】完成后传入(ticks=None 时
    兼容直接调用, 内部自取) —— 旧版持锁调用 get_full_tick, 行情接口慢/超时会阻塞
    deal_callback(需同一把锁)导致成交回报延迟入账。"""
    if not PNL_TRACK_ON or not G.state:
        return
    if is_trading_day() is not True:
        return
    now = datetime.datetime.now()
    live = market_phase() == 'trading'
    hold = G.state.get('hold') or {}
    mine = {}
    ho = {}                     # 已移交人工的冻结仓: 单独统计, 不计入策略盈亏口径
    for s, h in hold.items():
        if h.get('exited'):
            continue
        if h.get('closed'):
            # V2.6.185: 已全部卖出(成交回报已入账)的仓位不计入盈亏快照/市值/浮盈
            continue
        if not is_own_position(h):
            # 对账补录的孤儿仓(其他策略/手工持仓): 不计入本策略盈亏口径, 只做去重防买
            continue
        if TRAP_ALERT_ON and TRAP_EXCLUDE_FROM_PNL and is_handoff(h):
            ho[s] = h
            continue
        mine[s] = h
    _watch = list(mine.keys()) + list(ho.keys())
    # P2-8修复(2026-10-17): 候选股也纳入行情刷新 —— 旧版只刷持仓+移交仓, 候选股断流时
    # 买入侧只有vol_ok闸门静默拦截, 无任何告警, 排障时看不到"候选突然全灭"的原因
    _cand_extra = [c['stock'] for c in (getattr(G, 'candidates', []) or [])
                   if c.get('stock') and c['stock'] not in _watch]
    if _cand_extra:
        _watch = _watch + _cand_extra
    if ticks is None:
        ticks = {}
        if _watch and live:
            try:
                ticks = _refresh_ticks(_watch)   # V2.6.30 B→C
            except Exception:
                ticks = {}
    elif not isinstance(ticks, dict):
        ticks = {}
    snap = {'ts': now.strftime('%Y-%m-%d %H:%M:%S'), 'n': len(mine), 'mkt': 0.0,
            'cost': 0.0, 'unreal': 0.0, 'unreal_pct': 0.0, 'cash': 0.0, 'asset': 0.0,
            'base': 0.0, 'ret': 0.0, 'stale': False, 'stale_n': 0, 'codes': {},
            'handoff_n': len(ho), 'handoff_mkt': 0.0, 'handoff_unreal': 0.0,
            'unreal_all': 0.0, 'asset_all': 0.0, 'ret_all': 0.0}   # P0修复: 真实权益(含移交仓)
    _live_n = 0                 # P0-3修复: 本轮取到有效最新价的在管持仓只数
    rows = []                   # 先算全所有持仓, 组合快照才完整(单票提示要引用当前组合浮盈)
    for s, h in mine.items():
        vol = pos_vol(h)
        cost = pos_cost(h)
        t = ticks.get(s) or {}
        lp = _f(t.get('lastPrice'))
        if lp > 0:
            h['last_px'] = lp
            _live_n += 1
        else:
            lp = _f(h.get('last_px', 0.0)) or _f(h.get('buy_price', 0.0))
            snap['stale'] = True
        if vol <= 0 or cost <= 0 or lp <= 0:
            continue
        mv = _round2(lp * vol)
        unreal = _round2(mv - cost)
        pct = unreal / cost * 100.0
        days = held_trd_days(h.get('buy_date', ''))
        snap['mkt'] = _round2(snap['mkt'] + mv)
        snap['cost'] = _round2(snap['cost'] + cost)
        snap['unreal'] = _round2(snap['unreal'] + unreal)
        snap['codes'][s] = {'price': lp, 'vol': vol, 'mv': mv, 'cost': cost,
                            'unreal': unreal, 'pct': pct}
        rows.append((s, h, lp, mv, unreal, pct, days))
    # P0-3修复(2026-10-02): stale_n 连续轮数 —— 旧版 G.pnl['stale_n'] 被 risk_increase_allowed
    #   读取但全文件无任何写入点(只写布尔 snap['stale']), "持仓行情陈旧即暂停增险"永不生效。
    #   定义: 有在管持仓(mine非空)但本轮一个有效最新价都取不到 = 行情源整体异常, 累计轮数;
    #   一旦取到任一有效价即清零。
    if mine:
        if _live_n > 0:
            G.stale_rounds = 0
        elif live:
            # V2.6.54修复(4处之一): 仅在交易时段累计行情陈旧轮数 —— 午休(11:30-13:00共90分钟≈180轮)
            # /盘前/盘后无tick属正常, 旧版照常+1, 导致13:00开盘瞬间 stale_rounds 仍高企, 误触发
            # '持仓行情连续N轮取不到最新价'告警并暂停价格型卖出判定; 非交易时段清零, 开盘后从0
            # 重新累计真实故障轮数(原告警阈值STALE_BLOCK_ROUNDS不变)。
            G.stale_rounds = int(getattr(G, 'stale_rounds', 0) or 0) + 1
        else:
            G.stale_rounds = 0
    else:
        G.stale_rounds = 0
    snap['stale_n'] = int(getattr(G, 'stale_rounds', 0) or 0)
    # P2-8修复(2026-10-17): 候选股行情断流告警(当日首次一条) —— 旧版stale_n只统计在管持仓股,
    # 候选股断流不计入也无提示; 买入侧另有vol_ok/bar_cnt闸门兜底(不会按残缺数据买入),
    # 此处仅补可观测性, 不改任何闸门行为
    try:
        # V2.6.70修复: 非交易时段(午休/盘前/盘后)tick本来就不更新, 取不到最新价属正常现象,
        # 旧版仍打'候选股行情断流'告警, 2026-10-19 12:06 午休日志即误报。仅交易时段(live)告警。
        _cand_miss = [c['stock'] for c in (getattr(G, 'candidates', []) or [])
                      if c.get('stock') and c['stock'] not in mine
                      and _f((ticks.get(c['stock']) or {}).get('lastPrice')) <= 0] if live else []
        if _cand_miss and getattr(G, 'cand_tick_note_date', '') != G.today:
            G.cand_tick_note_date = G.today
            log('[数据告警] 候选股行情断流: %d只候选取不到最新价(%s), 买入侧已按vol_ok闸门拦截, '
                '持仓卖出不受影响' % (len(_cand_miss), ','.join(_cand_miss[:3])))
    except Exception:
        pass
    # 已移交人工的冻结仓: 只做可见性统计(不进策略盈亏口径, 不压制基准权益与手数)
    for s, h in ho.items():
        vol = pos_vol(h)
        cost = pos_cost(h)
        t = ticks.get(s) or {}
        lp = _f(t.get('lastPrice'))
        if lp > 0:
            h['last_px'] = lp
        else:
            lp = _f(h.get('last_px', 0.0)) or _f(h.get('buy_price', 0.0))
        if vol <= 0 or cost <= 0 or lp <= 0:
            continue
        mv = _round2(lp * vol)
        snap['handoff_mkt'] = _round2(snap['handoff_mkt'] + mv)
        snap['handoff_unreal'] = _round2(snap['handoff_unreal'] + (mv - cost))
    # 策略自身总资产: 策略预算 + 累计已实现盈亏 + 当前浮动盈亏
    # (不用账户全部现金, 否则基准=策略预算时总收益会虚高为账户其他资金)
    st = pnl_stat()
    snap['asset'] = _round2(_f(STRATEGY_CAPITAL) + _f(st['pnl']) + snap['unreal'])
    # 策略口径现金 = 策略资产 - 持仓市值(=预算+已实现-持仓成本)
    # 不取实盘账户可用资金(账户其他资金不属于本策略, 日志不暴露实盘资金)
    snap['cash'] = _round2(snap['asset'] - snap['mkt'])
    snap['unreal_pct'] = (snap['unreal'] / snap['cost'] * 100.0) if snap['cost'] > 0 else 0.0
    base = pnl_base_asset(snap['asset'])
    snap['base'] = base
    snap['ret'] = pnl_pct_of(snap['asset'] - base, base)
    # P0修复(2026-10-02): 真实权益口径 —— 已移交套牢仓的浮亏同样计入。
    #   旧版 TRAP_EXCLUDE_FROM_PNL=True 把移交仓剔出 snap['ret'], 但移交仓浮亏是真实亏损,
    #   剔出后组合熔断在深套时反而失明(越亏越看不见), 手数基准也随之上浮。
    try:
        _b0 = _f(snap.get('base', 0.0))
        snap['asset_all'] = _round2(_f(snap.get('asset', 0.0)) + _f(snap.get('handoff_mkt', 0.0)))
        snap['unreal_all'] = _round2(_f(snap.get('unreal', 0.0)) + _f(snap.get('handoff_unreal', 0.0)))
        snap['ret_all'] = pnl_pct_of(snap['asset_all'] - _b0, _b0)
    except Exception:
        snap['asset_all'] = _f(snap.get('asset', 0.0))
        snap['unreal_all'] = _f(snap.get('unreal', 0.0))
        snap['ret_all'] = _f(snap.get('ret', 0.0))
    G.pnl = snap
    dirty = False
    if live:
        # 单票浮盈/浮亏跨档位提示(同一档位只提示一次, 档位持久化)
        for (s, h, lp, mv, unreal, pct, days) in rows:
            wlv = pnl_level(pct, PNL_WIN_STEP) if pct > 0 else 0
            llv = pnl_level(pct, PNL_LOSS_STEP) if pct < 0 else 0
            if wlv > int(h.get('alert_win', 0) or 0):
                h['alert_win'] = wlv
                h['alert_loss'] = 0
                alert_unreal(s, h, lp, mv, unreal, pct, days, 'win', wlv, PNL_WIN_STEP)
                dirty = True
            elif llv > int(h.get('alert_loss', 0) or 0):
                h['alert_loss'] = llv
                h['alert_win'] = 0
                alert_unreal(s, h, lp, mv, unreal, pct, days, 'loss', llv, PNL_LOSS_STEP)
                dirty = True
        # 组合总收益跨档位提示(档位带符号持久化: 正=盈利档, 负=亏损档; 未跨过第一档不提示)
        if PNL_PF_STEP > 0 and base > 0 and snap['ret'] != 0:
            m = pnl_meta()
            sig = 1 if snap['ret'] > 0 else -1
            lv = pnl_level(snap['ret'], PNL_PF_STEP)
            cur = int(m.get('pf_level', 0) or 0)
            cur_sig = 1 if cur > 0 else (-1 if cur < 0 else 0)
            if lv >= 1 and (cur_sig != sig or lv > abs(cur)):
                m['pf_level'] = sig * lv
                alert_portfolio(snap, sig, lv)
                dirty = True
            elif lv < 1 and cur != 0:
                m['pf_level'] = 0   # 收益回落到第一档以内, 归零等待下次跨越
    # 每交易日一次全天汇总
    if PNL_DAILY_REPORT_HM > 0 and (now.hour * 100 + now.minute) >= PNL_DAILY_REPORT_HM:
        m = pnl_meta()
        if m.get('report_date') != (G.today or ''):
            m['report_date'] = G.today or ''
            alert_daily_report(snap)
            dirty = True
    # 2026-10-14 用户新增; 20261027 改为每10分钟一次持仓+已清仓盈亏汇总(仅交易时段, 午休/盘后静默)
    if live and PNL_HALF_HOUR_REPORT_SEC > 0:
        try:
            if pnl_halfhour_report(snap):
                dirty = True
        except Exception:
            traceback.print_exc()
    if dirty:
        save_state()

# ==================== 资金基准 / 动态手数 / 单仓串行 ====================
def size_equity():
    """手数与风控的基准权益E(元): 起始本金 + 累计已实现盈亏 + 当前浮动盈亏。
    current=复利(盈加亏缩); initial=固定本金; high_water=历史最高权益(回撤时缩仓最激进)。
    极端亏损时用本金的20%作地板, 防止权益趋零导致手数归零、策略彻底停摆。"""
    base = _f(STRATEGY_CAPITAL)
    if base <= 0:
        return 0.0
    if SIZE_EQUITY_MODE == 'initial':
        return base
    try:
        realized = _f(pnl_stat().get('pnl', 0.0))
        unreal = _f((G.pnl or {}).get('unreal', 0.0))
        # P0修复(2026-10-02): 可选把已移交套牢仓浮亏计入手数基准(默认关, 与原行为一致)
        if SIZE_EQUITY_INCLUDE_HANDOFF:
            unreal = _f((G.pnl or {}).get('unreal_all', unreal))
        cur = _round2(base + realized + unreal)
        if SIZE_EQUITY_MODE == 'high_water':
            m = pnl_meta()
            hw = _f(m.get('hw_equity', 0.0))
            if cur > hw:
                m['hw_equity'] = cur
                hw = cur
            return hw if hw > 0 else base
        floor = base * 0.2
        return cur if cur > floor else floor
    except Exception:
        return base

def atr_of(s):
    """单只补拉ATR_BARS根日线算ATR(真实波幅): 返回 (atr, atr_pct, 昨收)。
    只对最终候选调用(全市场拉会把初始化从十几秒推到数分钟), 结果按交易日缓存"""
    key = '%s|%s' % (G.today, s)
    if key in G.atr_cache:
        return G.atr_cache[key]
    out = (0.0, 0.0, 0.0)
    try:
        # P0-1(重审20261005): 按位置传参(旧 stock_code= 必然TypeError被吞, ATR恒0致动态手数全拒)
        d = _api(G.C.get_market_data_ex, [], [s], '1d', '', '', ATR_BARS, 'front', False, False)
        bars = _bars_to_dict(d.get(s) if isinstance(d, dict) else None)
    except Exception as e:
        bars = {}
        if not getattr(G, 'mde_atr_warned', False):
            G.mde_atr_warned = True     # 接口失效必须响亮告警, 禁止静默吞掉
            log('[数据告警] get_market_data_ex(ATR)调用失败, 动态手数将全部被拒:', repr(e)[:160])
    rows = []
    for d in sorted(bars.keys()):
        # P3(V2.6.83): 日期口径统一用 _bardate_loose —— 索引若是 date/datetime, str(d)[:8] 得到
        #   '2026-10-' 永远不等于 '20261019', 当日未走完的K线剔不掉, ATR 混入半截当日数据。
        if G.today and _bardate_loose(d) == G.today:
            continue                      # 剔除当日未走完的K线
        b = bars[d] or {}
        hi, lo, cl = _f(b.get('high')), _f(b.get('low')), _f(b.get('close'))
        if hi <= 0 or lo <= 0 or cl <= 0:
            continue
        rows.append((hi, lo, cl))
    if len(rows) >= ATR_PERIOD + 1:
        trs = []
        for i in range(1, len(rows)):
            hi, lo, cl = rows[i]
            pc = rows[i - 1][2]
            trs.append(max(hi - lo, abs(hi - pc), abs(lo - pc)))
        use = trs[-ATR_PERIOD:]
        atr = sum(use) / float(len(use))
        last = rows[-1][2]
        if last > 0:
            G.prev_close[s] = last
            out = (atr, atr / last, last)
    G.atr_cache[key] = out
    return out

def last_close_of(s):
    """最近一个已完成交易日的收盘(单日急跌判断用): ATR缓存优先, 否则取已加载日线"""
    if s in G.prev_close and _f(G.prev_close[s]) > 0:
        return _f(G.prev_close[s])
    rows = G.hist.get(s) or []
    if not rows:
        return 0.0
    r = rows[-1]
    if r.get('date') == G.today and len(rows) >= 2:
        r = rows[-2]
    return _f(r.get('close'))

def sell_stall_confirmed(s, h, lp, t):
    """卖出侧"滞涨确认"(2026-10-02 借鉴: 高位放量滞涨才是真派发)。
    V2.6.159(用户选方案B): 主判据改为 ②未创新高
           (现价 < 近 STALL_NEWHIGH_DAYS 个【已完成】交易日最高价 x (1-STALL_NEWHIGH_GAP))。
    ①涨幅门槛只在"近高取不到"时兜底。原因: 放量 1.9 倍通常伴随大涨, 与"涨幅<=1%"天然矛盾,
    两条同时要求等于几乎不触发 —— 实盘表现就是策略自本次上线以来从未自动止盈过。
    返回 (是否确认滞涨, 说明串, 是否因数据缺失而降级)。
    数据缺失时返回 (True, '', True) —— 退回纯量能口径, 不因缺数据改变既有卖出行为。"""
    try:
        lastclose = _f(t.get('lastClose')) or last_close_of(s)
        if lastclose <= 0 or lp <= 0:
            return True, '', True
        gain = lp / lastclose - 1.0
        c1 = gain <= STALL_MAX_GAIN_PCT
        c2 = True
        c2_ok = False       # V2.6.159: 近高是否真的取到 —— 取不到才退回看涨幅
        hi_note = '近高不可得'
        n = int(STALL_NEWHIGH_DAYS)
        # 只用【已完成】日线(剔除当日行), 避免盘中未完成数据干扰"是否创新高"
        rows = [r for r in (G.hist.get(s) or []) if str(r.get('date', '')) != str(G.today)]
        if n > 0 and rows:
            hi = max([_f(r.get('high', 0.0)) for r in rows[-n:]])
            if hi > 0:
                c2 = lp < hi * (1 - STALL_NEWHIGH_GAP)
                c2_ok = True
                hi_note = '近%d日最高%.2f' % (min(n, len(rows)), hi)
        # V2.6.159(方案B): 只要近高取到, 就只按"有没有创出近N日新高"判 —— 放量却过不了前高,
        #   无论当日涨了多少都算派发。涨幅门槛仅在近高缺失时兜底, 仍可作最后一道判据。
        if c2_ok:
            if c2:
                return True, ('滞涨确认(放量当日涨%.2f%%, 未创%s)' % (gain * 100, hi_note)), False
            return False, ('已创%s(价在新高, 疑换手后再上攻)' % hi_note), False
        if c1:
            return True, ('滞涨确认(近高不可得, 退用涨幅%.2f%%<=%.2f%%)'
                          % (gain * 100, STALL_MAX_GAIN_PCT * 100)), False
        return False, ('现价较昨收涨%.2f%%>%.2f%%(价还在涨, 疑换手后再上攻; 近高不可得)'
                       % (gain * 100, STALL_MAX_GAIN_PCT * 100)), False
    except Exception as e:
        # [P1-3 FIX 2026-10-16] 异常时保守不放行卖出(原代码静默放行=FAIL-OPEN)
        # 原 except 分支返回(True, "", True) —— 任何异常都让滞涨确认"通过",
        # STALL_CONFIRM_ON=True 时风控垫被静默绕过, 等于悄悄回到纯量能口径
        # 铁律配套: 数据不确定时阻塞卖出比放行更安全
        log('[安全][滞涨确认] sell_stall_confirmed异常, 保守不放行卖出(等下轮充足数据): %s' % repr(e)[:150])
        return False, '滞涨确认数据异常, 保守不放行卖出(等下轮充足数据)', True

def calc_stop_pct(atr_pct):
    """止损距离(2026-10-03 方案A): 仅按 N倍ATR 计算 —— 硬止损底线(HARD_STOP_PCT)已删除,
    该距离只用于手数测算与"跌破止损线"提示, 绝不触发任何实际卖出"""
    return ATR_STOP_MULT * atr_pct

def calc_size(s, price, atr, atr_pct, eq, cash):
    """动态手数: 五级约束取最小值(风险/单票市值/日内波动/现金/组合总市值) ->
    按LOT_SIZE只舍不入 -> 不足一手时降级或跳过。
    返回 (vol, info); vol=0 表示不可买, info['reason'] 为原因"""
    lot = _lot_of(s)   # P1-1(第18轮审计): 科创板200股/主板100股, 与 normalize_buy_volume 同口径
    info = {'stop_pct': 0.0, 'n1': 0.0, 'n2': 0.0, 'n3': 0.0, 'n4': 0.0, 'n5': 0.0,
            'n_raw': 0.0, 'vol': 0, 'amount': 0.0, 'degraded': False, 'reason': ''}
    if price <= 0 or eq <= 0:
        info['reason'] = '价格或基准权益无效'
        return 0, info
    if atr_pct > ATR_PCT_MAX > 0:
        info['reason'] = 'ATR波动%.1f%%超过%.0f%%(高波动剔除)' % (atr_pct * 100, ATR_PCT_MAX * 100)
        return 0, info
    sp = calc_stop_pct(atr_pct)
    info['stop_pct'] = sp
    if sp > ATR_STOP_MAX:
        info['reason'] = '止损距离%.1f%%超过%.0f%%上限(不买)' % (sp * 100, ATR_STOP_MAX * 100)
        return 0, info
    r_amt = eq * RISK_PCT
    n1 = r_amt / (price * sp) if sp > 0 else 0.0
    n2 = min(eq * MAX_POS_VALUE_PCT, MAX_POS_VALUE_ABS) / price   # V2.6.74: 单票额度取相对上限与绝对上限66666.66元较小者
    n3 = (eq * MAX_DAILY_SWING_PCT / atr) if atr > 0 else n2
    # 审计修复I6: cash 已由 eff_cash() 按 STRATEGY_CASH_CAP 收敛为本策略可动用资金边界,
    # 此处直接沿用, 不再与同账户其他策略/手工资金混用
        # Q1修复(2026-10-19 第九轮零预设审计): n4 现金约束改用真实费率 —— 旧版用粗估FEE_RATE_EST(0.15%)
    #   比真实佣金(0.0084%)高约17倍, 边界资金会漏买; 现按 真实佣金率 + 过户费率 计算(n4 只是粗口径上限,
    #   精确的买入费用校验由 buy_stock 用 fee_buy 完成)。低于5元最低佣金的极小单由 MIN_BUY_AMOUNT 另拦。
    _buy_fee_rate = (FEE_COMMISSION_RATE + _transfer_rate_for(s)) if (price > 0 and FEE_ON) else 0.0
    n4 = cash * CASH_USE_PCT / (price * (1.0 + _buy_fee_rate))
# P2-29: 组合总市值上限 —— 单票35%x3只=105%会越界, 以"已投入成本"口径把
    # 组合总仓位收敛到 MAX_TOTAL_VALUE_PCT 内(0=关闭)
    # 2026-10-09第五轮审计修复(用户确认): 绝对资金封顶 STRATEGY_CASH_CAP 不再依赖
    #   MAX_TOTAL_VALUE_PCT 是否>0 —— 旧版把66666.66元封顶挂在"组合市值上限"开关下,
    #   一旦按注释把 MAX_TOTAL_VALUE_PCT 设为0(关闭), 绝对封顶会悄悄失效。
    n5 = 0.0
    _cap_on = (MAX_TOTAL_VALUE_PCT > 0) or (STRATEGY_CASH_CAP > 0)
    if _cap_on:
        # V2.6.75修复(第十一轮零预设审计问题1): 改用 used_capital() 统一口径 ——
        # 旧版此处只累加 pos_cost(不含在途委托 pend_vol), 而 abs_cap_left 同一份持仓却含在途,
        # 两道资金闸门算法打架; n5 虚高时 n_raw=min(...) 取不到真实上限, 分批加仓逐轮多买
        # 可突破 STRATEGY_CASH_CAP(20万)。现与 abs_cap_left 完全同口径, 且仍正确实现
        # 用户保留逻辑: 移交人工的套牢仓不占用股票数额度与资金额度, 且不加回名义额度。
        inv = used_capital()
        # P0-1修复: 删除"+trap_credit_left" —— 移交释放的名义额度不再进入组合上限分子
        # 2026-10-03 用户定稿硬约束: 组合总市值上限受 STRATEGY_CASH_CAP 绝对封顶 ——
        # 复利模式下 eq(基准权益)随浮盈增长, eq*MAX_TOTAL_VALUE_PCT 可能越过
        # 66666.66 元资金边界, 此处 min 兜底, 保证组合规划市值口径同样不可逾越。
        _comb_cap = (eq * MAX_TOTAL_VALUE_PCT) if MAX_TOTAL_VALUE_PCT > 0 else float('inf')
        if STRATEGY_CASH_CAP > 0:
            _comb_cap = min(_comb_cap, STRATEGY_CASH_CAP)
        n5 = max(0.0, (_comb_cap - inv) / price) if price > 0 else 0.0
    n_raw = min(n1, n2, n3, n4, n5) if _cap_on else min(n1, n2, n3, n4)
    _sm = sent_size_mult()   # 情绪模块L4: 过热收缩单仓(未就绪=0.0, 显式拒单; 模块关闭=1.0 不干预)
    n_raw = n_raw * _sm
    if _sm <= 0:
        # P3-4(第18轮审计): 乘数为0必须是显式拒单, 不能静默走到下方"不足一手"分支 ——
        #   否则日志只会说"不足一手", 排查时会往手数/额度方向找, 真正的数据原因被埋掉。
        info['reason'] = ('情绪数据未就绪(模块已开启), 本轮不出仓'
                          if not _SENTIMENT_READY else '情绪处于极度过热区间, 本轮不出仓')
        return 0, info
    info.update({'n1': n1, 'n2': n2, 'n3': n3, 'n4': n4, 'n5': n5, 'n_raw': n_raw})
    n = int(math.floor(n_raw / lot) * lot)
    if n >= lot:
        amt = _round2(n * price)
        # 审计修复G8: 低价股容差 —— 最低买入金额判断改用"含滑点预估成交额"口径
        # (买入限价已上移SLIPPAGE_PCT再夹取, 实付更高), 避免按原始价卡线通过、
        # 夹取后实际成交金额反而跌破MIN_BUY_AMOUNT的边界误判
        # Q6修复(2026-10-19): 最低买入金额改用动态滑点(低价股0.3%), 与主买入发单口径一致(旧版固定0.2%会漏买低价股)
        _slip_calc = _slippage_for(price)
        amt_buy = _round2(n * price * (1.0 + _slip_calc)) if _slip_calc > 0 else amt
        if MIN_BUY_AMOUNT > 0 and amt_buy < MIN_BUY_AMOUNT:
            info['reason'] = ('算出%d股金额%.0f元低于最低买入金额%.0f元(手续费占比过高)'
                              % (n, amt_buy, MIN_BUY_AMOUNT))
            return 0, info
        info['vol'] = n
        info['amount'] = amt
        return n, info
    one = lot * price                       # 最小一手金额
    # 风险预算/日内波动/组合额度是硬上限，任一不足一手都不得向上提升。
    hard_limits = [('风险预算', n1), ('日内波动额度', n3)]
    if _cap_on:
        hard_limits.append(('组合剩余额度', n5))
    for _label, _limit in hard_limits:
        if _limit < lot:
            info['reason'] = '%s仅允许%.0f股，不足最小%d股，按硬上限拒绝' % (_label, _limit, lot)
            return 0, info
    _pos_abs_cap = min(eq * MAX_POS_VALUE_PCT, MAX_POS_VALUE_ABS)   # V2.6.75: 先算出真实生效的单票上限(判断与文案同源)
    if one > _pos_abs_cap:   # V2.6.74: 一手金额超单票绝对额度则拒买
        # V2.6.75修复(第十一轮零预设审计问题3): 文案与判断对齐 —— 旧版判断用 min(PCT, ABS) 却输出 eq*PCT,
        # 权益20万时日志打印"超过单票上限200000元", 而真实上限是66666.66元, 数字对不上会误导排查。
        info['reason'] = ('最小%d股金额%.0f元超过单票上限%.0f元(股价过高, 结构性限制)'
                          % (lot, one, _pos_abs_cap))
        return 0, info
    # 审计修复G8: 同上一处 —— 一手金额按含滑点口径复核, 防边界误杀
        # Q6修复(2026-10-19): 同上, 最小一手金额也按动态滑点复核(与主买入发单口径一致)
    one_buy = _round2(one * (1.0 + _slippage_for(price))) if _slippage_for(price) > 0 else one
    if MIN_BUY_AMOUNT > 0 and one_buy < MIN_BUY_AMOUNT:
        info['reason'] = '最小%d股金额%.0f元低于最低买入金额%.0f元' % (lot, one_buy, MIN_BUY_AMOUNT)
        return 0, info
    if one + fee_buy(one, s) > cash * CASH_USE_PCT:   # V2.6.71: 降级一手现金校验改真实费用fee_buy(旧版粗估0.15%高估)
        info['reason'] = '可用现金不足'
        return 0, info
    # P1-2修复(2026-10-04): 降级买一手前先复核实际单笔风险比, 超过 RISK_PCT*DEGRADE_TOLERANCE
    # 即直接拒买(不再"降级"突破上限)。旧版无条件降级买一手, 使高价股/窄止损标的以超出
    # 1.5%风险预算的口径建仓, 风险预算失真。DEGRADE_TOLERANCE=0 表示完全禁止降级。
    _act_risk = (one * sp / eq) if eq > 0 else 0.0
    _tol = float(DEGRADE_TOLERANCE or 0)
    if _tol > 0 and _act_risk > RISK_PCT * _tol:
        info.update({'vol': 0, 'amount': 0.0, 'degraded': False,
                     'reason': ('降级买最小%d股的实际单笔风险%.2f%%超过容忍上限%.2f%%, '
                                '拒绝买入(风险预算不足)'
                                % (lot, _act_risk * 100.0, RISK_PCT * _tol * 100.0))})
        return 0, info
    info.update({'vol': lot, 'amount': _round2(one), 'degraded': True,
                 'reason': ('风险预算不足%d股(算出%.0f股), 降级买最小%d股; 单笔风险升至%.2f%%'
                            % (lot, n_raw, lot, (one * sp / eq * 100.0) if eq > 0 else 0.0))})
    return lot, info

def lock_state():
    """单仓串行的解锁状态(持久化state.lock): 解锁标记/上次平仓净利/冷静期截止/连亏次数"""
    l = G.state.get('lock')
    if not isinstance(l, dict):
        l = {}
        G.state['lock'] = l
    l.setdefault('unlocked', True)
    l.setdefault('last_pnl', 0.0)
    l.setdefault('last_close_date', '')
    l.setdefault('cooldown_until', '')
    l.setdefault('consec_loss', 0)
    return l

def trd_days_after(ymd, n):
    """从ymd起往后第n个交易日(含当日时n=0); 日历缺失或越界返回空串"""
    if n <= 0 or not G.calendar or ymd not in G.calendar:
        return ''
    j = G.calendar.index(ymd) + n
    return G.calendar[j] if 0 <= j < len(G.calendar) else ''

def pause_until(ymd, n):
    """重审20261005(1-4): 冷静期/连亏长停的截止日。
    旧版直接用 trd_days_after —— 本地日历只覆盖有限窗口, ymd越界/缺失时返回空串,
    空串让 in_pause 恒为 False → 冷静期/长停静默失效(熔断路径有 FUSE_AUTO_RESUME_DAYS
    兜底, 此前冷静期路径没有任何兜底)。交易日推算失败时退回自然日兜底
    (约2倍交易日跨度, 方向上只会多歇不会少歇)。"""
    r = trd_days_after(ymd, n)
    if r:
        return r
    try:
        base = datetime.datetime.strptime(ymd, '%Y%m%d')
        return (base + datetime.timedelta(days=n * 2 + 1)).strftime('%Y%m%d')
    except Exception:
        return ''

def in_pause(until):
    """是否处于截止日until(含)之前的暂停期。
    P2-2: 旧版截止日落在周末/节假日(不在日历)时直接返回False → 熔断提前失效;
    新版对不在日历的截止日退回字符串日期比较, 保证暂停期完整覆盖。"""
    if not until or not G.today:
        return False
    if G.today in G.calendar and until in G.calendar:
        return G.calendar.index(G.today) <= G.calendar.index(until)
    return G.today <= until        # 兜底: 截止日非交易日(周末/节假日)或日历缺失时按自然日比较

def market_tide_check():
    """退潮期判断: 基准指数近N日跌幅>=阈值 -> 退潮期, 暂停新开仓。
    结果按交易日缓存到 G.market_tide, 避免每轮重复请求行情。"""
    if not MARKET_TIDE_CHECK or MARKET_TIDE_DROP_PCT <= 0:
        return False
    if getattr(G, 'market_tide_date', '') == G.today:
        if not bool(getattr(G, 'market_tide', False)):
            return False
        # P1-3修复(2026-10-17): 消费重试窗口 —— 禁买达到 MARKET_TIDE_RETRY_SEC 后清当日缓存
        # 重新取数判定(旧版缓存命中直接返回, 重试时间戳无人读取, 数据故障被当成退潮堵一整天)
        _rts = _f(getattr(G, 'market_tide_retry_ts', 0.0))
        if _rts > 0 and time.time() >= _rts:
            G.market_tide_date = ''
            G.market_tide = False
            G.market_tide_err_n = 0
            G.market_tide_retry_ts = 0.0
            log('[退潮判断] 禁买重试窗口(%d秒)已到, 重新取数判定(数据恢复即自动解除禁买)' % MARKET_TIDE_RETRY_SEC)
        else:
            return bool(getattr(G, 'market_tide', False))
    try:
        n = MARKET_TIDE_LOOKBACK + 1
        d = _api(G.C.get_market_data_ex, [], [MARKET_TIDE_INDEX], '1d', '', '', n + 5, 'none', False, False)
        bars = _bars_to_dict(d.get(MARKET_TIDE_INDEX) if isinstance(d, dict) else None)
        # P2-12修复(2026-10-19): 剔除当日未走完的 K 线再算退潮 —— 盘中当日 K 线是
        # 未完成的, 把它混入退潮计算等于用半个交易日的涨跌幅做判断; 且本函数结果按
        # G.today 全天缓存(首算即定全天), 更必须用已完成交易日口径(退潮是慢变量,
        # 不差当日这一天; 这样盘中首算与收盘后口径一致, 不会日内反复翻转)
        if bars:
            # P3(V2.6.83): 同上, 索引为 date/datetime 时 str()[:8] 无法与 '20261019' 比较,
            #   当日K线剔不掉 -> 退潮判断混入未完成K线(与本块 P2-12 的意图相反)。
            bars = {_k: _v for _k, _v in bars.items() if _bardate_loose(_k) != G.today}
        _cal = getattr(G, 'calendar', []) or []
        if _cal and bars:
            _last_days = [dd for dd in _cal if dd in bars][-n:]
            closes = [_f((bars.get(dd) or {}).get('close')) for dd in _last_days]
        else:
            closes = [_f((bars[k] or {}).get('close')) for k in sorted(bars.keys())[-n:]]
        closes = [c for c in closes if c > 0]
        if len(closes) >= 2:
            drop = (closes[-1] - closes[0]) / closes[0]
            tide = drop <= -MARKET_TIDE_DROP_PCT
            G.market_tide = tide
            G.market_tide_date = G.today
            if tide:
                log('[退潮期] %s 近%d日跌幅%.2f%%>=%.0f%%, 暂停新开仓(亏损仓位仍按亏损禁卖持有)'
                    % (MARKET_TIDE_INDEX, MARKET_TIDE_LOOKBACK, drop * 100, MARKET_TIDE_DROP_PCT * 100))
            else:
                # 第六轮零预设审计修复(2026-10-04): 数据有效但未触发退潮时, 打一条细粒度日志
                # (非刷屏, 仅当日首次), 便于日后排查"为什么没触发退潮"—— 特别是极端行情时
                # 能明确区分"数据有效但没到阈值"和"数据异常"。
                if getattr(G, 'tide_ok_note_date', '') != G.today:
                    G.tide_ok_note_date = G.today
                    log('[退潮判断] 数据有效: %s 近%d日跌幅%.2f%%, 未达退潮阈值%.0f%%, 退潮层通过(仍须过情绪等其它闸门)'
                        % (MARKET_TIDE_INDEX, MARKET_TIDE_LOOKBACK, drop * 100,
                           MARKET_TIDE_DROP_PCT * 100))
            return tide
    except Exception as e:
        # 重审20261005(1-1): 异常≠退潮 —— 接口/数据异常先降级放行并强提醒,
        # 连续 MARKET_TIDE_ERR_BLOCK_N 次异常才保守禁买(当日缓存不再重试, 次日自动复核)。
        # 旧版一有异常就全天禁买: 测试实证(行情桩缺该接口时7项买入断言全灭),
        # 生产中指数数据未下载/接口抖动=白白损失整日开仓机会且只有一条日志极易被忽视。
        _n = int(getattr(G, 'market_tide_err_n', 0) or 0) + 1
        G.market_tide_err_n = _n
        if _n >= MARKET_TIDE_ERR_BLOCK_N:
            log('[安全][退潮判断] 指数行情连续%d次取数异常, 保守视为退潮暂停开仓(当日不再重试, 次日复核): %s'
                % (_n, repr(e)[:200]))
            G.market_tide = True
            G.market_tide_date = G.today
            G.market_tide_retry_ts = time.time() + MARKET_TIDE_RETRY_SEC  # P2-2 FIX: 禁买后1800秒自动重试
            return True
        if getattr(G, 'market_tide_err_note_date', '') != G.today:
            G.market_tide_err_note_date = G.today
            log('[安全][退潮判断] 指数行情取数异常(第%d次), 本轮放行开仓判断; 连续%d次将保守禁买: %s'
                % (_n, MARKET_TIDE_ERR_BLOCK_N, repr(e)[:160]))
        G.market_tide = False
        return False                  # 不置 market_tide_date: 下轮重试
    G.market_tide_err_n = 0
    G.market_tide = False
    G.market_tide_date = G.today
    return False

def pos_limit():
    return 1 if SINGLE_POSITION_MODE else int(MAX_POSITIONS)

def _parse_emergency_text(raw):
    """把应急开关文件内容解析成模式词(2026-10-09第五轮新增)。
    支持 JSON(如 {"mode":"halt"})或纯文本(如 halt); 内容为空/无法识别一律返回 'halt'(保守)。
    识别顺序 only_cancel -> stop_new -> halt -> normal(先匹配更"强"的级别, 避免误读成正常)。"""
    t = str(raw or '').strip().lower()
    if not t:
        return 'halt'
    try:
        obj = json.loads(t)
        if isinstance(obj, dict):
            for k in ('mode', 'emergency_mode', 'emergency', 'state'):
                if k in obj:
                    t = str(obj.get(k) or '').strip().lower()
                    break
        elif isinstance(obj, str):
            t = obj.strip().lower()
    except Exception:
        pass
    for m in ('only_cancel', 'stop_new', 'halt', 'normal'):
        if m in t:
            return m
    return 'halt'

def emergency_mode_effective():
    """当前生效的应急模式(2026-10-09第五轮新增, 缺陷1加固第2层: 秒级开关)。
    优先级: 脚本同目录的应急开关文件(EMERGENCY_FILE) > 代码参数 EMERGENCY_MODE。
      · 开关文件不存在 -> 用 EMERGENCY_MODE(默认 normal 正常交易);
      · 开关文件存在且内容可识别 -> 用文件里的模式(改文件即生效, 无需改代码/重启策略);
      · 开关文件读取失败或内容无法识别 -> 返回 'halt'(保守: 停止一切买入, 只放行卖出), 绝不静默当正常。
    每 EMERGENCY_FILE_REFRESH_SEC 秒最多读一次盘(缓存), 不拖慢轮询。"""
    try:
        now = time.time()
        c = getattr(G, 'emergency_cache', None)
        if not isinstance(c, dict):
            c = {'ts': 0.0, 'mode': None, 'note': ''}
            G.emergency_cache = c
        if c.get('mode') is not None and now - _f(c.get('ts', 0.0)) < max(0.0, _f(EMERGENCY_FILE_REFRESH_SEC)):
            return c['mode']
        mode = str(EMERGENCY_MODE or 'normal').strip().lower()
        src = '参数EMERGENCY_MODE'
        if EMERGENCY_FILE:
            path = _join_base(EMERGENCY_FILE)
            if os.path.exists(path):
                raw = ''
                try:
                    with open(path, 'r', encoding='utf-8', errors='ignore') as fh:
                        raw = fh.read()
                except Exception:
                    raw = ''
                mode = _parse_emergency_text(raw)
                src = '开关文件' + EMERGENCY_FILE
        c['ts'] = now
        c['mode'] = mode
        _note = src + '=' + mode
        if c.get('note') != _note:
            c['note'] = _note
            log('[应急模式] 生效值=%s (来源=%s)' % (mode, src))
        return mode
    except Exception as e:
        log('[应急模式] 读取异常, 保守按 halt 处理(停止一切买入, 只放行卖出): %s' % repr(e)[:150])
        return 'halt'

def emergency_block(side):
    """应急总开关闸门(2026-10-09第五轮零预设审计修复: 原 EMERGENCY_MODE 只在分批加仓处检查, 半接线)。
    side: 'new'=新开仓, 'add'=分批加仓, 'sell'=卖出。返回拒绝原因(空串=放行)。
      normal      = 全部放行;
      stop_new    = 停止【新开仓】; 分批加仓与卖出照常;
      only_cancel = 停止【一切新委托】(买/卖都不发), 仅允许撤单;
      halt        = 停止【一切买入】(新开仓+分批加仓); 卖出照常;
      未知取值    = 保守按 halt 处理(停止一切买入, 只放行卖出)。
    改 EMERGENCY_MODE 参数, 或新建/删除应急开关文件(EMERGENCY_FILE)即可紧急停手, 无需重启策略。"""
    m = str(emergency_mode_effective() or 'normal').strip().lower()
    if m == 'normal':
        return ''
    if m == 'only_cancel':
        return '应急模式=only_cancel(已停止一切新委托, 仅允许撤单)'
    if side == 'sell':
        return ''
    if m == 'stop_new':
        if side == 'new':
            return '应急模式=stop_new(已停止新开仓; 分批加仓与卖出照常)'
        return ''
    return '应急模式=%s(已停止一切买入; 卖出照常)' % m

def can_open_new():
    """是否允许开新仓: 持仓上限 -> 解锁 -> 冷静/长停 -> 组合熔断, 全部通过才返回(True, '')"""
    hold = G.state.get('hold') or {}
    # 已移交人工的套牢仓不占持仓名额(名额已释放, 供策略重新分配);
    # 只统计本策略自身持仓(is_own_position), 账户内其他策略/手工持仓(reconciled孤儿仓)绝不计入上限
    _eb = emergency_block('new')
    if _eb:
        return False, _eb
    # A5修复(2026-10-17 零预设审计): 持仓上限只统计"已真实成交"的本策略持仓 ——
    # 撤单重报期间(fill_vol==0 且 pend_vol>0)不计入, 防一轮废单虚耗 1 个名额。
    # is_own_position 不动(仍供其它调用点判断), 此处用更严格的"真实成交"口径。
    cnt = len([1 for h in hold.values()
               if isinstance(h, dict)
               and not h.get('reconciled')
               and not is_handoff(h)
               and not h.get('closed')      # V2.6.185: 已全部卖出的仓位不占持仓名额
                              # Q2修复(2026-10-19 第九轮零预设审计): 在途委托(pend_vol>0)同样占用持仓名额 ——
               #   旧版只统计已成交(fill_vol>0), 同一轮发多单期间会虚放MAX_POSITIONS名额导致同轮超买
               and (int(_f(h.get('fill_vol', 0)) or 0) > 0
                    or int(_f(h.get('pend_vol', 0)) or 0) > 0)])
    if cnt >= pos_limit():
        return False, '本策略已持仓%d只(持仓上限%d只, 仅计本策略自身持仓), 须先平仓' % (cnt, pos_limit())
    l = lock_state()
    if not l.get('unlocked', True):
        if in_pause(l.get('cooldown_until', '')):
            return False, '上次平仓净利%.2f元未达"赚到手"标准, 冷静期至%s' % (
                _f(l.get('last_pnl', 0.0)), l.get('cooldown_until', ''))
        l['unlocked'] = True          # 冷静期已过, 自动恢复可买
        l['cooldown_until'] = ''
    m = pnl_meta()
    # R2刚性约束: 熔断解除允许 ①人工写入manual_resume ②盈利全平后自动解除
    # ③暂停FUSE_PAUSE_TRDAYS个交易日后自动解除(P2-2统一口径); 绝不因"回撤减小"自动恢复开仓
    if m.get('manual_resume'):
        m['manual_resume'] = False
        m['fuse_until'] = ''
        m['hard_dd_until'] = ''      # P0修复: 人工解除同时放行组合硬约束
        log('组合熔断/硬约束已由人工解除(manual_resume), 恢复开仓')
    if in_pause(m.get('fuse_until', '')):
        return False, '组合熔断暂停开仓(至%s, 人工解除: 状态文件pnl_meta.manual_resume=true%s)' % (
            m.get('fuse_until', ''),
            '; 或暂停期满自动解除' if FUSE_PAUSE_TRDAYS > 0 else '')
    # P0修复(2026-10-02): 组合硬约束(真实权益口径, 不自动解除) —— 弥补熔断2个交易日后
    #   自动恢复在连续下跌中的保护空档; 只能人工解除或盈利平仓解除
    if PORTFOLIO_HARD_DD_PCT > 0 and in_pause(m.get('hard_dd_until', '')):
        return False, ('组合硬约束暂停开仓(真实权益含移交仓浮亏, 回撤已达-%.0f%%, 至%s; '
                       '人工解除: 状态文件pnl_meta.manual_resume=true, 盈利平仓亦自动解除)'
                       % (PORTFOLIO_HARD_DD_PCT * 100.0, m.get('hard_dd_until', '')))
    # P0-2修复(2026-10-02): 新开仓同样过统一数据闸门 —— 旧版本函数完全不检查数据质量,
    #   数据严重缺失时仍能开新仓(与分批加仓口径分裂)。轻度缺失只强提示, 严重缺失才拦。
    _blk, _why, _alert = data_gate()
    if _alert:
        data_quality_alert(_why)
    if _blk:
        return False, _why
    # V2.6.78 P1-1: 情绪+退潮 合并检查(都执行, 原因不丢失)
    # V2.6.151: 情绪侧改用 sent_block_note() 取原因, 日志能区分"真恐慌"与"数据没就绪"
    _sent_note = sent_block_note()
    _sent_ok = not _sent_note
    _tide_ok = not market_tide_check()
    if not _sent_ok and not _tide_ok:
        return False, '%s + 市场退潮期(双重触发), 暂停新开仓' % _sent_note
    if not _tide_ok:
        return False, '市场退潮期, 暂停新开仓'
    if not _sent_ok:
        return False, '%s, 暂停新开仓' % _sent_note
    return True, ''

def settle_pending(pos_total):
    """P1-1修复(2026-10-02): 消费 pending_settlements(旧版只写不读 —— 卖出回报到达时若
    账户查询未知, 登记后永不结算, 该仓永久卡在未解锁状态)。
    卖出回报不再在持锁状态下查柜台, 改由本轮已取到的柜台持仓(pos_total, 锁外查询)确认
    "该代码已清零"后结算, 避免柜台卡顿占住 G.state_lock 阻塞成交回报/OrderID绑定落盘。
    超过 PENDING_SETTLE_MAX_DAYS 天仍无法确认的登记丢弃并响亮告警(绝不静默累积)。"""
    pend = G.state.get('pending_settlements')
    if not isinstance(pend, dict) or not pend:
        return
    for code in list(pend.keys()):
        it = pend.get(code) or {}
        try:
            left = int(pos_total.get(code, 0) or 0)
        except Exception:
            left = 0
        if left <= 0:
            pend.pop(code, None)
            log('[结算] %s 柜台持仓已清零, 累计%d笔/%d股 净利%s 费用%.2f, 统一结算"赚到手"判定' % (disp(code), int(_f(it.get('fills', 1))), int(_f(it.get('vol', 0))), fmt_money(_f(it.get('pnl', 0.0))), _f(it.get('fee', 0.0))))
            settle_after_close(code, _f(it.get('pnl', 0.0)), _f(it.get('fee', 0.0)))
        elif time.time() - _f(it.get('ts', 0)) > PENDING_SETTLE_MAX_DAYS * 86400:
            pend.pop(code, None)
            log('[告警] %s 待结算登记已超过%d天但柜台仍有持仓, 登记已丢弃(请人工核对柜台与盈亏账本)'
                % (disp(code), PENDING_SETTLE_MAX_DAYS))
    if not pend:
        G.state.pop('pending_settlements', None)

def settle_after_close(s, pnl, round_fee):
    """平仓结算: 判定"赚到手" -> 解锁 / 冷静期 / 连亏长停。
    门槛 = max(往返费用 x PROFIT_LOCK_FEE_MULT, 基准权益 x PROFIT_LOCK_MIN_PCT)。
    R2路径a: 盈利全平后自动解除组合熔断(fuse_until清空) —— 绝不因回撤减小自动恢复,
    必须有真实的盈利平仓才解除。"""
    if pnl > 0:
        m = pnl_meta()
        if m.get('fuse_until'):
            m['fuse_until'] = ''
            log('[熔断解除] %s 盈利平仓(净利%s), 组合熔断已自动解除, 恢复开仓' % (s, fmt_money(pnl)))
        # P0修复(2026-10-02): 盈利平仓同时解除组合硬约束(与既有"盈利全平解除熔断"口径一致)
        if m.get('hard_dd_until'):
            m['hard_dd_until'] = ''
            log('[硬约束解除] %s 盈利平仓(净利%s), 组合硬约束已自动解除, 恢复开仓' % (s, fmt_money(pnl)))
    # P0-2修复(20261008): 多仓模式同样执行冷静期/连亏长停(组合级保护) ——
    # 旧版在此提前return, COOLDOWN_TRDAYS/CONSEC_LOSS_PAUSE/LOSS_PAUSE_TRDAYS 多仓下静默失效;
    # can_open_new 统一消费 lock_state 的 cooldown_until/consec_loss, 删除提前return后多仓同样生效
    l = lock_state()
    eq = size_equity()
    thr = max(round_fee * PROFIT_LOCK_FEE_MULT, eq * PROFIT_LOCK_MIN_PCT)
    if pnl > 0 and pnl >= thr:
        l['unlocked'] = True
        l['cooldown_until'] = ''
        l['consec_loss'] = 0
        log('[解锁] %s 本次净利%s(门槛=往返费%.2fx%.1f与权益的%.1f%%取大), '
            '已达"赚到手"标准, 可筛选下一只' % (s, fmt_money(pnl), round_fee,
                                      PROFIT_LOCK_FEE_MULT, PROFIT_LOCK_MIN_PCT * 100))
    elif pnl > 0 and not PROFIT_LOCK_STRICT:
        l['unlocked'] = True
        l['cooldown_until'] = ''
        l['consec_loss'] = 0
        log('[解锁] %s 本次净利%s 未达门槛%.2f元(微利), 按设定仍算赚到手, 可筛选下一只'
            % (s, fmt_money(pnl), thr))
    else:
        l['consec_loss'] = int(l.get('consec_loss', 0) or 0) + 1
        if l['consec_loss'] >= CONSEC_LOSS_PAUSE and CONSEC_LOSS_PAUSE > 0:
            l['cooldown_until'] = pause_until(G.today, LOSS_PAUSE_TRDAYS)   # 重审20261005: 日历越界时自然日兜底
            l['consec_loss'] = 0
            log('[未解锁] %s 本次净利%s(门槛%.2f元), 且已连续亏损%d次, 长停%d个交易日(至%s)'
                % (s, fmt_money(pnl), thr, CONSEC_LOSS_PAUSE, LOSS_PAUSE_TRDAYS,
                   l['cooldown_until'] or '-'))
        else:
            l['cooldown_until'] = pause_until(G.today, COOLDOWN_TRDAYS)   # 重审20261005: 日历越界时自然日兜底
            log('[未解锁] %s 本次净利%s(门槛%.2f元), 未达"赚到手"标准, 冷静%d个交易日(至%s)'
                % (s, fmt_money(pnl), thr, COOLDOWN_TRDAYS, l['cooldown_until'] or '-'))
        l['unlocked'] = False
    l['last_pnl'] = _round2(pnl)
    l['last_close_date'] = G.today
    save_state()

# ==================== 套牢仓位人工介入(提醒/冻结移交/剔除/释放名额与资金额度) ====================
def handoff_records():
    """已移交人工的仓位索引 {代码: {成本/股数/移交日/原因/解套价/提醒次数}}"""
    d = G.state.get('handoff')
    if not isinstance(d, dict):
        d = {}
        G.state['handoff'] = d
    return d

def is_handoff(h):
    """是否已移交人工(冻结): True=策略不再运作该仓位(不加仓/不自动卖出/不占名额)"""
    return bool((h or {}).get('handoff'))

def handoff_credit():
    """已移交人工仓位占用的成本合计(元): 仅用于移交概览日志展示"占用成本"口径(V2.6.58b起),
    不再作为任何资金额度/买入计算的来源"""
    tot = 0.0
    for _s, r in handoff_records().items():
        if isinstance(r, dict):
            tot += _f(r.get('cost', 0.0))
    return _round2(tot)

# V2.6.58b修复(2026-10-17): 删除 trap_credit_left/trap_consume 两个死代码函数 ——
# 旧版"移交释放额度"记账体系已无人读取(释放额度不进入任何资金上限计算/买入路径),
# trap_credit_left 无任何调用者, trap_consume 只写无人读的状态字段 trap_used;
# handoff_credit 保留, 供 trap_sweep 移交概览日志展示"占用成本"口径。

def eff_cash(cash):
    """可用现金: 不放大账户真实现金(仍以柜台可用资金为准, 收敛到STRATEGY_CASH_CAP资金边界)
    (移交释放的是"资金额度": abs_cap_left/calc_size不再把移交仓成本计入已占用,
     移交仓股票与占用成本仍在账户里, 可用现金不会凭空增加 —— 防止按不存在的钱下单/全部废单)
    审计修复I6: STRATEGY_CASH_CAP>0 时把现金收敛到本策略资金边界,
    避免多策略共用同一账户时相互挤占/重复使用同一笔钱下单"""
    c = _f(cash)
    if STRATEGY_CASH_CAP > 0:
        c = min(c, STRATEGY_CASH_CAP)
    return c

def exit_price_needed(h, code='', vol=None):
    """解套价: 以该价全部卖出、扣掉全部摩擦费用后净利刚好转正的最低价格(人工解套的目标价)。
    P3(V2.6.83): 新增 code 参数 —— 旧版固定按股票费率(万0.841/5元起/印花税万5)推算, 持仓若是
    ETF(万0.5/0.1元起/无印花税)或可转债(卖出十万分之5), 解套价会算高或算低: 算高则人工挂单
    永远卖不掉, 算低则按该价卖出扣费后仍亏(违背"扣费后真正赚钱才卖"的铁律)。"""
    _full_vol = pos_vol(h)
    vol = _full_vol if vol is None else min(_full_vol, max(0, int(_f(vol))))
    cost = pos_cost(h) * vol / float(_full_vol) if _full_vol > 0 else 0.0
    if vol <= 0 or cost <= 0:
        return 0.0
    _pit = fee_profile(code) if code else FEE_PROFILE['stock']
    _rate = _f(_pit.get('rate'))
    _min = _f(_pit.get('min'))
    _stamp = _f(_pit.get('stamp'))
    _tr = _f(_pit.get('transfer'))
    if code and _prod_of(code) == 'cbond':
        _rate = FEE_CBOND_SELL_RATE      # 可转债买卖不同价: 解套用卖出档费率
    denom = vol * (1.0 - _stamp - _tr)
    p1 = ((cost + _min) / denom) if denom > 0 else 0.0
    p2 = (cost / (vol * (1.0 - _rate - _stamp - _tr))) if vol > 0 else 0.0
    px = max(p1, p2)
    if px <= 0:
        return 0.0
    # Q8修复(2026-10-19 第九轮零预设审计): 解套价迭代上限 30->300 次 —— 旧版30次(每次+0.2%)在极端费用
    #   情形下算出的价可能远高于涨停价, 被当委托价发单后必废单并耗尽重发次数(giveup), 卖出永久停摆
    _px_cap = px * 1.05   # S5(2026-10-24): 上探价封顶 <= 起始价×1.05, 防给出离谱目标价(如>涨停)
    for _i in range(300):
        px = math.ceil(px * 100) / 100.0
        if px > _px_cap:
            break
        if net_pnl_if_sell(h, px, code, vol) > 0:
            return _round2(px)
        px = px * 1.002
    return _round2(px)

def trap_metrics(s, h, lp):
    """套牢判定所需的全部度量: 股数/成本/单位成本/持有交易日/浮亏金额与比例/基准权益"""
    vol = pos_vol(h)
    cost = pos_cost(h)
    cost_u = (cost / vol) if vol > 0 else 0.0
    days = held_trd_days(h.get('buy_date', ''))
    unreal = ((lp - cost_u) * vol) if (vol > 0 and cost_u > 0 and lp > 0) else 0.0
    loss_pct = ((lp / cost_u) - 1.0) if (cost_u > 0 and lp > 0) else 0.0
    return {'vol': vol, 'cost': cost, 'cost_u': cost_u, 'days': days,
            'loss_amt': _round2(unreal), 'loss_pct': loss_pct, 'eq': size_equity()}

def trap_gap_ok(last_date, n):
    """去重/冷却: 距上次提醒是否已满N个交易日(日历缺失退回自然日)"""
    if n <= 0 or not last_date:
        return True
    if not G.today:
        return False
    try:
        if last_date in G.calendar and G.today in G.calendar:
            return (G.calendar.index(G.today) - G.calendar.index(last_date)) >= n
    except Exception:
        pass
    try:
        b = datetime.datetime.strptime(str(last_date), '%Y%m%d')
        t = datetime.datetime.strptime(str(G.today), '%Y%m%d')
        return (t - b).days >= n
    except Exception:
        return True

def manual_alert_path():
    """人工介入待办清单路径(带账号隔离后缀): 与状态文件同目录, 仅允许纯文件名, 禁止穿越"""
    stem, ext = _split_name(MANUAL_ALERT_FILE)
    return _join_base(stem + _account_suffix() + ext)

def write_manual_todo():
    """把"待人工处理"的套牢仓位写入待办清单(原子写): 人工可打开文件直接看, 处理后自动清空"""
    if not MANUAL_ALERT_FILE:
        return
    try:
        items = []
        for s, h in list((G.state.get('hold') or {}).items()):
            if not is_handoff(h):
                continue
            r = handoff_records().get(s) or {}
            lp = _f(h.get('last_px', 0.0)) or _f(h.get('buy_price', 0.0))
            m = trap_metrics(s, h, lp)
            xp = _f(h.get('trap_exit_price', 0.0)) or exit_price_needed(h, s)
            items.append({
                'code': s, 'name': h.get('name', ''), 'status': '待人工处理',
                'since': r.get('date', h.get('handoff_date', '')),
                'reason': r.get('reason', h.get('handoff_reason', '')),
                'vol': m['vol'], 'cost_total': _round2(m['cost']),
                'cost_avg': _round2(m['cost_u']), 'last_price': _round2(lp),
                'loss_pct': _round2(m['loss_pct'] * 100.0),
                'loss_amt': _round2(m['loss_amt']),
                'exit_price': _round2(xp),
                'low_since_buy': _round2(_f(h.get('trap_low', 0.0))),
                'held_trd_days': m['days'], 'alerts': int(h.get('trap_n', 0) or 0),
                'last_alert': h.get('trap_last_date', '')})
        data = {'updated': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                'note': '套牢仓位人工介入待办清单(策略自动生成, 人工卖出后自动移除)',
                'count': len(items), 'items': items}
        p = manual_alert_path()
        tmp = p + '.tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, p)
    except Exception:
        traceback.print_exc()
        log('人工介入待办清单写入失败(不影响交易, 提醒已输出到日志窗)')

def fire_trap_alert(s, h, lp, kind, reason):
    """套牢提醒(唯一出口): 冷却去重 + 次数上限 + 日志窗 + webhook + 待办清单。
    返回 True 表示本次确实提醒了(供调用方决定是否执行移交)"""
    if not TRAP_ALERT_ON:
        return False
    last = str(h.get('trap_last_date', '') or '')
    n = int(h.get('trap_n', 0) or 0)
    if not trap_gap_ok(last, TRAP_ALERT_COOLDOWN_TRDAYS):
        return False
    if TRAP_MAX_ALERTS > 0 and n >= TRAP_MAX_ALERTS:
        if h.get('trap_silent_date') != G.today:
            h['trap_silent_date'] = G.today
            log(disp(s), '套牢提醒已达上限%d次(上次%s), 不再重复提醒, 等待人工处理(待办清单: %s)'
                % (n, last or '-', MANUAL_ALERT_FILE or '未启用'))
        return False
    m = trap_metrics(s, h, lp)
    xp = exit_price_needed(h, s)
    h['trap_last_date'] = G.today
    h['trap_n'] = n + 1
    h['trap_exit_price'] = _round2(xp)
    kind_cn = {'trap': '套牢提醒', 'rebound': '反弹择机', 'near': '接近解套',
               'exit': '已达解套价'}.get(kind, '套牢提醒')
    text = ('[人工介入][%s] %s | 持有%d个交易日 | %d股 成本均价%.2f(含费) 现价%.2f | '
            '浮动盈亏=%s | 解套价=%.2f(扣费后净利转正价) | 触发: %s | 第%d/%s次提醒'
            % (kind_cn, disp_code(s, h.get('name', '')), m['days'], m['vol'], m['cost_u'], lp,
               fmt_pnl(m['loss_amt'], m['loss_pct'] * 100.0), xp, reason, n + 1,
               ('%d' % TRAP_MAX_ALERTS) if TRAP_MAX_ALERTS > 0 else '不限'))
    try:
        log(text)
    except Exception:
        pass
    try:
        if TRAP_NOTIFY_WEBHOOK and NOTIFY_WEBHOOK:
            notify_enqueue(text)      # P1-11: 推送入队, 锁外统一发送
    except Exception:
        pass
    write_manual_todo()
    save_state()
    return True

def blacklist_add(s, reason):
    """剔除出交易范围: 写入人工风险黑名单文件(原子写)并刷新当日缓存;
    写入失败只告警 —— 内存黑名单同步生效, 选股层仍能剔除"""
    bl = load_blacklist()
    if not isinstance(bl, dict):
        bl = {}
    bl[s] = reason
    G.blacklist = bl
    G.blacklist_date = G.today
    try:
        p = blacklist_path()
        data = {}
        try:
            # 重审20261005(1-3): 读取对象可能是UTF-8内容(黑名单文件/外部脚本写的状态文件)
            with open(p, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if not isinstance(data, dict):
                raise ValueError('黑名单顶层不是JSON对象')
        except FileNotFoundError:
            data = {}              # 文件确实不存在，允许首次创建
        except Exception as e:
            # D8：文件存在但读不了时绝不覆盖；本轮内存黑名单已生效，等待人工修复原文件。
            log('[安全][告警] 黑名单文件存在但读取失败(%s)，为保护原有条目已禁止覆盖: %s'
                % (e, p))
            try:
                pnl_alert('[安全][告警] 人工黑名单读取失败，已保留原文件不覆盖；'
                          '本轮新增剔除仅在内存生效，请人工修复文件后补写')
            except Exception:
                pass
            return False
        codes = data.get('codes')
        if isinstance(codes, dict):
            pass
        elif isinstance(codes, list):
            codes = dict((str(k), '人工标记') for k in codes)
        else:
            codes = {}
        codes[str(s)] = reason
        data['codes'] = codes
        tmp = p + '.tmp'
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, p)
        return True
    except Exception:
        traceback.print_exc()
        log(disp(s), '黑名单文件写入失败, 已用内存黑名单兜底(本次运行内仍能剔除, 重启后需手动补写)')
        return False

def blacklist_remove_tagged(s):
    """解除剔除: 只删除带 TRAP_TAG 前缀的条目, 人工自己写的黑名单条目一律不动"""
    try:
        p = blacklist_path()
        data = {}
        try:
            # 重审20261005(1-3): 读取对象可能是UTF-8内容(黑名单文件/外部脚本写的状态文件)
            with open(p, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except Exception:
            return
        if not isinstance(data, dict):
            return
        codes = data.get('codes')
        if isinstance(codes, dict):
            v = str(codes.get(s, '') or '')
            if v.startswith(TRAP_TAG):
                codes.pop(s, None)
                data['codes'] = codes
                tmp = p + '.tmp'
                with open(tmp, 'w', encoding='utf-8') as f:
                    json.dump(data, f, ensure_ascii=False, indent=1)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(tmp, p)
    except Exception:
        traceback.print_exc()
    bl = G.blacklist if isinstance(G.blacklist, dict) else {}
    if str(bl.get(s, '') or '').startswith(TRAP_TAG):
        bl.pop(s, None)

def handoff_position(s, h, lp, reason):
    """冻结移交: 停止仓位运作 -> 剔除出股票池 -> 释放名额与资金额度 -> 写待办清单"""
    if is_handoff(h):
        return False
    m = trap_metrics(s, h, lp)
    xp = exit_price_needed(h, s)
    h['handoff'] = True
    h['handoff_date'] = G.today
    h['handoff_reason'] = reason
    low = _f(h.get('trap_low', 0.0))
    h['trap_low'] = _round2(min(low, lp) if low > 0 else lp)
    h['trap_exit_price'] = _round2(xp)
    # 停止运作: 清掉分批建仓计划, 后续批次不再续买
    for k in ('plan_batches', 'plan_vol', 'plan_idx', 'batch_ts', 'batch_date',
              'batch_today_n'):
        h.pop(k, None)
    h['plan_done'] = True
    # P2-1(2026-10-24 第18轮零预设独立审计): 移交时撤掉在途买入委托 ——
    #   旧版只清分批计划, 不清 pend_vol 也不撤挂单: 第二批次还在柜台上排队时票被套牢移交,
    #   此后该挂单永远不进 handle_unfilled_buy 管理分支(移交仓 pos_total>0 走只读监控),
    #   挂到收盘自动废; 同时 used_capital 已把它的占用算成"已释放",
    #   同轮其它标的额度偏高, 而挂单真成交时现金真的被扣掉。
    #   危害例: 已成交3000股、在途3000股, 浮亏-18%触发移交 -> 在途单无人管理 ->
    #   尾盘成交则实际多投入3万元, 策略账上该票却"零占用", 组合投入超设计边界。
    if int(_f(h.get('pend_vol', 0) or 0)) > 0:
        try:
            _bo = buy_order_obj(s)
            if _bo and _bo != '_ERR' \
                    and int(getattr(_bo, 'm_nOrderStatus', -1)) in ACTIVE_ORDER_STATUS:
                if cancel_buy_order(s, _bo):
                    log('[人工介入] %s 移交时发现仍有在途买入委托, 已发出撤单指令(防成交后脱离额度管理)'
                        % disp_code(s, h.get('name', '')))
                else:
                    log('[人工介入][注意] %s 移交时有在途买入委托且撤单指令发送失败, 请人工撤销挂单'
                        '(该票资金额度已释放, 若挂单成交将不计入本策略额度)'
                        % disp_code(s, h.get('name', '')))
            else:
                log('[人工介入] %s 移交时有在途买入量登记(%d股)但柜台已无活动委托, 按已终结处理'
                    % (disp_code(s, h.get('name', '')), int(_f(h.get('pend_vol', 0) or 0))))
        except Exception:
            traceback.print_exc()
        # 移交后不再自动续买: 清掉在途量登记, 交由人工处理
        h['pend_vol'] = 0
    handoff_records()[s] = {'code': s, 'name': h.get('name', ''), 'date': G.today,
                            'cost': _round2(m['cost']), 'vol': m['vol'], 'reason': reason,
                            'exit_price': _round2(xp),
                            'loss_pct': _round2(m['loss_pct'] * 100.0),
                            'loss_amt': _round2(m['loss_amt']),
                            'alerts': int(h.get('trap_n', 0) or 0),
                            'last_alert': h.get('trap_last_date', '')}
    blacklist_add(s, '%s(%s)' % (TRAP_TAG, reason))
    log('[人工介入] %s 已冻结移交: 停止加仓与自动卖出, 已剔出选股池(黑名单), '
        '该股票从本策略选股池剔除, 同时不再占用本策略的股票数额度与资金额度'
        '(即"额度回赠": 该笔资金不再计入 used_capital/abs_cap_left, 但股票与本金'
        '仍在账户里冻结着, 需人工择机卖出; 股票占用的资金额度一旦释放, 仍不产生可用现金), '
        '本条仅告知, 不构成任何交易动作 | 待人工择机解套(解套价%.2f)'
        % (disp_code(s, h.get('name', '')), xp))
    write_manual_todo()
    save_state()
    return True

def monitor_handoff(s, h, lp):
    """移交后只读监控: 维护持仓期最低价, 在"反弹到位/接近解套/已达解套价"时再提醒人工择机卖出"""
    if not TRAP_ALERT_ON or lp <= 0:
        return
    low = _f(h.get('trap_low', 0.0))
    if low <= 0 or lp < low:
        h['trap_low'] = _round2(lp)
        low = lp
    xp = _f(h.get('trap_exit_price', 0.0)) or exit_price_needed(h, s)
    h['trap_exit_price'] = _round2(xp)
    if xp <= 0 or low <= 0:
        return
    if lp >= xp:
        fire_trap_alert(s, h, lp, 'exit',
                        '现价%.2f已达解套价%.2f, 扣费后净利转正, 可人工卖出解套' % (lp, xp))
    elif TRAP_EXIT_NEAR_PCT > 0 and lp >= xp * (1 - TRAP_EXIT_NEAR_PCT):
        fire_trap_alert(s, h, lp, 'near',
                        '现价%.2f距解套价%.2f仅差%.2f%%, 接近解套' % (lp, xp, (1 - lp / xp) * 100))
    elif TRAP_REBOUND_PCT > 0 and lp >= low * (1 + TRAP_REBOUND_PCT):
        fire_trap_alert(s, h, lp, 'rebound',
                        '自持仓期最低价%.2f反弹%.2f%%(达%.0f%%阈值), 反弹到位可择机解套'
                        % (low, (lp / low - 1) * 100, TRAP_REBOUND_PCT * 100))

def check_trap(s, h, lp):
    """套牢判定: 时间+空间双达标 或 深度亏损快通道 -> 提醒(并按配置自动冻结移交)"""
    if not TRAP_ALERT_ON or is_handoff(h) or lp <= 0:
        return
    m = trap_metrics(s, h, lp)
    if m['vol'] <= 0 or m['cost_u'] <= 0:
        return
    days = m['days']
    if days < 1:
        return                                   # 当日买入(T+1)不判定
    deep = (TRAP_DEEP_LOSS_PCT > 0 and m['loss_pct'] <= -TRAP_DEEP_LOSS_PCT
            and days >= TRAP_DEEP_MIN_TRDAYS)
    bits = []
    if TRAP_LOSS_PCT > 0 and m['loss_pct'] <= -TRAP_LOSS_PCT:
        bits.append('浮亏%.2f%%达%.0f%%阈值' % (-m['loss_pct'] * 100, TRAP_LOSS_PCT * 100))
    if TRAP_LOSS_AMT_PCT > 0 and m['eq'] > 0 and m['loss_amt'] <= -m['eq'] * TRAP_LOSS_AMT_PCT:
        bits.append('浮亏达基准权益%.0f%%' % (TRAP_LOSS_AMT_PCT * 100))
    normal = bool(bits) and days >= TRAP_HOLD_TRDAYS
    if not (deep or normal):
        return
    if deep:
        reason = ('深度亏损快通道: 浮亏%.2f%%已达%.0f%%(持有%d个交易日, 不看时间阈值)'
                  % (-m['loss_pct'] * 100, TRAP_DEEP_LOSS_PCT * 100, days))
    else:
        reason = ('长期套牢: 持有%d个交易日(阈值%d)且%s'
                  % (days, TRAP_HOLD_TRDAYS, '、'.join(bits)))
    fired = fire_trap_alert(s, h, lp, 'trap', reason)
    if TRAP_AUTO_HANDOFF and (fired or int(h.get('trap_n', 0) or 0) > 0):
        handoff_position(s, h, lp, reason)

def clear_handoff(s, note=''):
    """解除移交: 人工/系统卖出后清掉索引, 回收释放额度, 按配置恢复其交易范围"""
    r = handoff_records().pop(s, None)
    if r is None:
        return False
    _hh = (G.state.get('hold') or {}).get(s)
    if isinstance(_hh, dict):
        _hh['handoff'] = False      # 持仓记录仍在时同步解冻(避免待办清单里重复出现)
        for _k in ('handoff_date', 'handoff_reason'):
            _hh.pop(_k, None)
    if TRAP_UNBAN_ON_EXIT:
        blacklist_remove_tagged(s)
    log('[人工介入] %s 套牢仓位已平仓(%s), 解除冻结: 持仓名额已回收, %s'
        % (s, note or '人工/系统平仓',
           '已恢复其交易范围(移出黑名单)' if TRAP_UNBAN_ON_EXIT
           else '仍保留在黑名单(TRAP_UNBAN_ON_EXIT=False)'))
    write_manual_todo()
    save_state()
    return True

def trap_sweep():
    """每日巡检: 持仓记录已消失的移交条目自动解除; 输出一次移交概览(心跳)"""
    if not TRAP_ALERT_ON:
        return
    hold = G.state.get('hold') or {}
    for s in list(handoff_records().keys()):
        if s not in hold:
            clear_handoff(s, '持仓记录已消失(已平仓)')
    recs = handoff_records()
    if not recs:
        return
    if G.trap_note_date == G.today:
        return
    G.trap_note_date = G.today
    tot_cost = handoff_credit()
    log('套牢移交概览: 已移交%d只(占用成本%.2f元), 均不占持仓名额与策略盈亏口径 '
        '(资金仍在持仓中, 由人工管理, 不存在额外可动用资金) | 待人工处理清单: %s'
        % (len(recs), tot_cost, MANUAL_ALERT_FILE or '未启用'))
    # V2.6.166(修复B): 移交额度循环监控改为实时检查(见 _hc_alert_realtime, 由 timer_poll
    #   每轮驱动一次), 不再等到 trap_sweep 每日一次才提醒, 避免一天里额度被反复借出
    #   而无人察觉; 本段【只观测与提醒, 不改变任何下单/额度计算】, 用户保留逻辑一字未动。
    for s, r in recs.items():
        log('  · %s | 移交于%s | 成本%.2f元/%d股 | 当前%s | 解套价%.2f | 已提醒%d次'
            % (disp_code(s, r.get('name', '')), r.get('date', '-'), _f(r.get('cost', 0.0)),
               int(r.get('vol', 0) or 0),
               ('浮亏%.2f元' % _f(r.get('loss_amt', 0.0))) if _f(r.get('loss_amt', 0.0)) < 0
               else '已回本', _f(r.get('exit_price', 0.0)), int(r.get('alerts', 0) or 0)))

def _hc_alert_realtime():
    """V2.6.166(修复B): 移交额度循环监控改为实时检查 ——

    HANDOFF_CREDIT_ALERT(默认20万元)只是这条监控的提醒阈值, 不参与任何额度计算。
    背景: 移交人工后该仓成本不再计入 used_capital()(用户保留逻辑: 同时释放股票数额度
    与资金额度), 配合 TRAP_AUTO_HANDOFF=True 的套牢自动移交, STRATEGY_CASH_CAP 会从
    "本策略累计投入总额"退化为"同时在运作的金额上限"; 账户真实现金是唯一天然刹车,
    现金多于 STRATEGY_CASH_CAP 时策略在账户里累积的持仓金额没有天花板(额度还回,
    但钱并未回来)。例如: 账户趴50万 -> 买3只x6.6万=20万 -> 全部套牢自动移交 ->
    额度还回但钱没回 -> 再买3只 -> 账户里变成6只 -> 再移交再买, 如此循环。

    本函数只做三件事, 全是观测与提醒, 一字不改任何交易逻辑或额度计算:
      1) 移交仓累计占用成本首次达到/超过阈值时, 推一次手机提醒并置位
         G._hc_alert_fired 作为去重标志(同一轮只提醒一次, 不做盯盘式刷屏);
      2) 占用成本回落到阈值以下时自动复位, 之后再次越过阈值可再次提醒;
      3) 取不到移交记录或 HANDOFF_CREDIT_ALERT<=0(关闭提醒)时直接返回, 什么都不做。

    原 trap_sweep 里的阈值判断(每日概览时提醒)已移除, 由本函数实时接管。"""
    try:
        if HANDOFF_CREDIT_ALERT <= 0:
            return
        recs = handoff_records()
        if not recs:
            return
        tot = handoff_credit()
        if tot >= HANDOFF_CREDIT_ALERT:
            if getattr(G, '_hc_alert_fired', False):
                return
            G._hc_alert_fired = True
            _hc_n = len(recs)
            _hc_txt = (
                '[资金额度循环监控·实时] 已移交人工仓位%d只, 占用成本合计%.2f元, 已达提醒阈值%.2f元。\n'
                '  说明: 移交后该仓不再占用股票数额度与资金额度(您的保留逻辑), 但股票与本金仍在账户里冻结着。\n'
                '  因此 STRATEGY_CASH_CAP=%.2f元 约束的是"同时在运作的金额", 不是"历史累计投入总额"。\n'
                '  真实天花板是您的账户可用现金: 账户现金越多, 本策略可累积的持仓越多。\n'
                '  本条仅提醒, 未改变任何交易逻辑或额度计算。如需硬性累计上限, 请另行确认。')
            notify_enqueue(_hc_txt % (_hc_n, tot, HANDOFF_CREDIT_ALERT,
                                      STRATEGY_CASH_CAP))
            log('[资金额度循环监控·实时] 移交仓%d只/占用成本%.2f元, 已达阈值%.2f元'
                '(STRATEGY_CASH_CAP=%.2f元; 该上限约束的是同时在运作金额, 非累计投入)'
                % (_hc_n, tot, HANDOFF_CREDIT_ALERT, STRATEGY_CASH_CAP))
        else:
            G._hc_alert_fired = False
    except Exception:
        pass


# ==================== 买入去重层 ====================
def mark_sold(s):
    """记录卖出日期(持久化到state.sold): 买入去重依据之一,
    卖出后需间隔超过REBUY_GAP_TRDAYS个交易日才允许再次买入"""
    G.state.setdefault('sold', {})[s] = G.today

def rebuy_blocked(s, t0=''):
    """买入去重: 返回跳过原因(空串=允许买入)。判断依据按序:
    ①当前持仓中 -> 跳过(单票仅一笔在途持仓)
    ②同一轮涨停周期已操作过(done按T0涨停日记录) -> 跳过(防同周期反复进出)
    ③卖出后间隔未超过REBUY_GAP_TRDAYS个交易日 -> 跳过(防卖飞后立刻追回)
    首次入选(无持仓/无done记录/无卖出记录)一律放行"""
    if s in G.state['hold']:
        return '当前持仓中'
    if t0 and G.state['done'].get(s) == t0:
        return '本轮涨停周期(T0=%s)已操作过' % t0
    sd = (G.state.get('sold') or {}).get(s)
    if sd and G.today:
        gap = held_trd_days(sd)
        if gap <= REBUY_GAP_TRDAYS:
            return '卖出(%s)后仅%d个交易日, 间隔需大于%d日' % (sd, gap, REBUY_GAP_TRDAYS)
    return ''

ORDER_STATUS_MAP = {48: '未报', 49: '待报', 50: '已报', 51: '已报待撤',
                    52: '部成待撤', 53: '部撤', 54: '已撤', 55: '部成',
                    56: '已成', 57: '废单'}

# ---- 每日买卖笔数上限(纸面/实盘完全分离) ----
def _mode_buckets():
    """返回 (state['buys'], state['sells']) 两套独立桶(live/paper)的引用;
    首次调用时把旧版扁平 buys 迁移进 live 桶, sells 初始化为空桶。幂等, 可重复调用。"""
    for k in ('buys', 'sells'):
        d = G.state.get(k)
        if not isinstance(d, dict) or 'live' not in d or 'paper' not in d:
            old = d if isinstance(d, dict) else {}
            G.state[k] = {'live': {}, 'paper': {}}
            if k == 'buys':
                # 旧版 {date,n,codes} -> 归入 live 桶, 保证历史计数不丢
                G.state[k]['live'] = {kk: old[kk] for kk in ('date', 'n', 'codes') if kk in old}
    return G.state['buys'], G.state['sells']

def daily_buy_cap(mode=None):
    """该模式的每日买入笔数硬上限(0=不限制)。
    P1-2修复(2026-10-03): 默认参数不可绑定TRADE_MODE —— Python在函数定义时求值
    默认参数, 若TRADE_MODE运行中被切换或另作参数传入, 旧写法(mode=TRADE_MODE)
    会锁死定义时的值(陷阱); 改为None+运行时取值, 与调用侧动态传参语义一致。"""
    if mode is None:
        mode = TRADE_MODE
    return MAX_DAILY_BUYS_LIVE if mode == 'live' else MAX_DAILY_BUYS_PAPER

def daily_sell_cap(mode=None):
    """该模式的每日卖出笔数硬上限(0=不限制)"""
    if mode is None:
        mode = TRADE_MODE
    return MAX_DAILY_SELLS_LIVE if mode == 'live' else MAX_DAILY_SELLS_PAPER

def daily_buy_state(mode=None):
    """当日买入计数读写入口(按模式独立桶): 存状态文件, 跨重载/补选股/重启都算数;
    日期不是当日的自动归零(含codes明细)"""
    if mode is None:
        mode = TRADE_MODE
    buys, _ = _mode_buckets()
    b = buys.get(mode)
    if not isinstance(b, dict):
        b = {}
        buys[mode] = b
    if b.get('date') != G.today:
        b['date'] = G.today
        b['n'] = 0
        b['codes'] = []
    b['n'] = int(b.get('n', 0) or 0)
    if not isinstance(b.get('codes'), list):
        b['codes'] = []
    return b

def daily_sell_state(mode=None):
    """当日卖出计数读写入口(按模式独立桶)"""
    if mode is None:
        mode = TRADE_MODE
    _, sells = _mode_buckets()
    s = sells.get(mode)
    if not isinstance(s, dict):
        s = {}
        sells[mode] = s
    if s.get('date') != G.today:
        s['date'] = G.today
        s['n'] = 0
        s['codes'] = []
    s['n'] = int(s.get('n', 0) or 0)
    if not isinstance(s.get('codes'), list):
        s['codes'] = []
    return s

def daily_buy_blocked(mode=None):
    """P1修复(2026-10-02): 识别外部手工封锁标记(set_daily_buys.py MODE='BLOCK' 写入 codes 的
    '手工封锁'): 返回 (是否封锁, 原因)。该标记优先于笔数上限 —— 旧版 BLOCK 只把 buys.n 写到
    DAILY_CAP, 而 MAX_DAILY_BUYS_*=0(默认不限制)时 daily_buy_left() 恒为 9999, 封锁完全不生效。
    标记随当日日期失效(次日自动放开)。"""
    if mode is None:
        mode = TRADE_MODE
    try:
        b = daily_buy_state(mode)
        if BUY_BLOCK_TAG and BUY_BLOCK_TAG in (b.get('codes') or []):
            return True, '外部手工封锁(set_daily_buys.py MODE=BLOCK)'
    except Exception:
        return False, ''
    return False, ''

def daily_buy_left(mode=None):
    """当日还可新买几笔; 上限<=0 表示不限制; 手工封锁时恒为0"""
    if mode is None:
        mode = TRADE_MODE
    if daily_buy_blocked(mode)[0]:
        return 0
    cap = daily_buy_cap(mode)
    if cap <= 0:
        return 9999
    return max(0, cap - daily_buy_state(mode)['n'])

def daily_sell_left(mode=None):
    """当日还可新卖几笔; 上限<=0 表示不限制"""
    if mode is None:
        mode = TRADE_MODE
    cap = daily_sell_cap(mode)
    if cap <= 0:
        return 9999
    return max(0, cap - daily_sell_state(mode)['n'])

def daily_buy_done(s, mode=None):
    """买入成功后登记当日买入笔数(仅计入所属模式的桶, 不影响另一模式)"""
    if mode is None:
        mode = TRADE_MODE
    b = daily_buy_state(mode)
    b['n'] += 1
    if s not in b['codes']:
        b['codes'].append(s)

def daily_sell_done(s, mode=None):
    """卖出委托发出后登记当日卖出笔数(仅计入所属模式的桶, 不影响另一模式)"""
    if mode is None:
        mode = TRADE_MODE
    s_ = daily_sell_state(mode)
    s_['n'] += 1
    if s not in s_['codes']:
        s_['codes'].append(s)

def daily_add_state(mode=None):
    """P2-27: 当日分批加仓笔数(独立桶, 不占"新开仓"额度, 但如实记账对齐文档口径)"""
    if mode is None:
        mode = TRADE_MODE
    adds = G.state.get('adds')
    if not isinstance(adds, dict):
        adds = {}
        G.state['adds'] = adds
    a = adds.get(mode)
    if not isinstance(a, dict):
        a = {}
        adds[mode] = a
    if a.get('date') != G.today:
        a['date'] = G.today
        a['n'] = 0
        a['codes'] = []
    a['n'] = int(a.get('n', 0) or 0)
    if not isinstance(a.get('codes'), list):
        a['codes'] = []
    return a

def daily_add_done(s, mode=None):
    """P2-27: 分批加仓发单后登记当日加仓笔数(如实记账, 不影响每日买入上限语义)"""
    if mode is None:
        mode = TRADE_MODE
    a = daily_add_state(mode)
    a['n'] += 1
    if s not in a['codes']:
        a['codes'].append(s)

def query_order_status(s, ords_snap=None):
    """查询柜台侧本策略对s的买入委托状态(诊断用): 返回描述串, 查不到返回空。
    P1-01: ords_snap=run_round锁外预取的委托快照, 传入则不再锁内重复查柜台"""
    try:
        ords = ords_snap if ords_snap is not None \
            else (_api(get_trade_detail_data, G.accid, 'STOCK', 'ORDER') or [])
        mine = []
        for o in ords:
            code = '%s.%s' % (getattr(o, 'm_strInstrumentID', ''), getattr(o, 'm_strExchangeID', ''))
            rm = str(getattr(o, 'm_strRemark', '') or '')
            if code == s and 'BUY' in rm:
                st = getattr(o, 'm_nOrderStatus', -1)
                mine.append('@%.2f %s' % (_f(getattr(o, 'm_dPrice', 0)),
                            ORDER_STATUS_MAP.get(st, '未知状态(%s)' % st)))
        return '; '.join(mine)
    except Exception:
        return ''

def note_order_id(code, rm, oid):
    """P1-3加固: 委托回报里记录本策略对每只票最新一笔委托的OrderID(按BUY|/SELL|分侧),
    供buy_order_obj/sell_order_obj查柜台时精确匹配, 不再依赖OrderID字符串序猜"最新"。
    存状态文件, 跨重启仍可对上当日委托"""
    try:
        code = str(code or '').strip()
        oid = str(oid or '').strip()
        if not code or not oid or oid == '-1':
            return
        rm = str(rm or '')
        side = 'buy' if rm.startswith('BUY|') else ('sell' if rm.startswith('SELL|') else '')
        if not side:
            return
        d = G.state.get('ordids')
        if not isinstance(d, dict):
            d = {}
            G.state['ordids'] = d
        # V2.6.159: 按方向分开存 —— 旧结构 d[code] 只留最后一条, 买入登记会被卖出覆盖,
        #   备注缺失时按方向兜底就查到反方向的单号(轻微: 柜台正常回传备注时不触发)。
        _cur = d.get(code)
        if isinstance(_cur, dict) and (isinstance(_cur.get('buy'), dict)
                                       or isinstance(_cur.get('sell'), dict)):
            _slot = _cur
        else:
            _slot = {'buy': {}, 'sell': {}}
            if isinstance(_cur, dict) and str(_cur.get('side', '')) in ('buy', 'sell') \
                    and str(_cur.get('id', '') or ''):
                _slot[str(_cur['side'])] = {'id': str(_cur['id']),
                                            'ts': _f(_cur.get('ts', 0.0))}
        _slot[side] = {'id': oid, 'ts': time.time()}
        d[code] = _slot
        # P3-3(2026-10-24 第18轮零预设独立审计): 订单号登记表时效清理 —— 旧版只写不清,
        #   随交易标的数单调增长并全量落盘(按日均3笔、每票2条估算一年约1500条/150KB,
        #   不会炸但属可预见的长跑膨胀)。现按 3 天时效清理已终结登记(与 buy_ctx/sell_ctx
        #   同口径), 每自然日最多执行一次(节流, 不影响当日委托匹配)。
        if G.state.get('ordids_prune_date') != G.today:
            G.state['ordids_prune_date'] = G.today
            try:
                _cut = time.time() - 3 * 86400.0
                for _c in list(d.keys()):
                    _v = d.get(_c)
                    if not isinstance(_v, dict):
                        d.pop(_c, None)
                        continue
                    _alive = False
                    for _sd in ('buy', 'sell'):
                        _sl = _v.get(_sd)
                        if isinstance(_sl, dict) and _f(_sl.get('ts', 0.0)) >= _cut:
                            _alive = True
                    if not _alive:
                        d.pop(_c, None)
            except Exception:
                traceback.print_exc()
    except Exception:
        # P2-8: ordids是撤单精确匹配与防重复发单的关键凭证, 写失败必须留痕
        log('[警告] 委托ID登记失败(ordids), 撤单匹配将退化为ID排序猜最新')
        traceback.print_exc()

def _oid_rec(s, side):
    """V2.6.159: 取某只票【指定方向】的委托登记。
    兼容 V2.6.158 及以前的单条结构 {'side','id','ts'} —— 那种结构每只票只留最后一条,
    买与卖互相覆盖, 备注缺失时按方向兜底就会拿到反方向的单号。新结构 {'buy':{},'sell':{}}。"""
    d = G.state.get('ordids') or {}
    v = d.get(s) if isinstance(d, dict) else None
    if not isinstance(v, dict):
        return {}
    _slot = v.get(side)
    if isinstance(_slot, dict):
        return _slot
    if str(v.get('side', '')) == side:
        return v
    return {}


def _oid_side_of(s, oid):
    """V2.6.159: 按委托号反查方向(成交回报备注丢失时的兜底)。返回 'buy'/'sell'/''。"""
    oid = str(oid or '')
    if not oid:
        return ''
    d = G.state.get('ordids') or {}
    v = d.get(s) if isinstance(d, dict) else None
    if not isinstance(v, dict):
        return ''
    for _sd in ('buy', 'sell'):
        _slot = v.get(_sd)
        if isinstance(_slot, dict) and str(_slot.get('id', '') or '') == oid:
            return _sd
    if str(v.get('id', '') or '') == oid:
        return str(v.get('side', '') or '')
    return ''


def _oid_known(s, oid):
    """V2.6.159: 该委托号是否登记在本策略该股的任一方向(对账撤遗留单用, 只判存在)。"""
    return bool(_oid_side_of(s, oid))


def _oid_sort_key(oid):
    """委托ID排序键: 纯数字按数值序(避免'9'>'100'的字符串序误判), 非数字退回字符串序"""
    oid = str(oid or '')
    try:
        return (0, float(oid))
    except Exception:
        return (1, oid)

def _code_with_suffix(code):
    """P2-1加固: orderError回报的代码可能不带交易所后缀, 按代码前缀补齐
    (持仓记录键形如002142.SZ; 6/5/9开头为沪市, 其余按深市处理)"""
    code = str(code or '').strip()
    if not code or '.' in code:
        return code
    return code + ('.SH' if code[0] in ('5', '6', '9') else '.SZ')

def disp_code(s, name=''):
    """交易标的展示: 代码(不带交易所后缀) + 名称, 如 '600519 贵州茅台'。
    名称优先用调用方给的, 其次持仓记录/名称缓存, 查不到显示'?'"""
    s = str(s or '')
    code = s.split('.')[0]
    if not name:
        h = (G.state.get('hold') or {}).get(s) or {}
        name = h.get('name', '')
    if not name:
        name = (G.state.get('names') or {}).get(s, '')
    if not name:
        try:
            name = inst_name(s)
        except Exception:
            name = ''
    return '%s %s' % (code, name or '?')

def disp(s):
    """单参数版展示(从持仓/缓存查名称)"""
    return disp_code(s)

def buy_scope_ok(s):
    """交易铁律: 买入仅允许 当日候选池 或 本策略分批计划中的股票"""
    if any(c.get('stock') == s for c in (G.candidates or [])):
        return True
    h = (G.state.get('hold') or {}).get(s)
    return bool(h and h.get('plan_batches') and not h.get('plan_done'))

def sell_scope_ok(s):
    """交易铁律: 卖出/重报 仅允许 本策略持仓记录中的股票"""
    return s in (G.state.get('hold') or {})

def is_strategy_target(code):
    """判断一个股票代码是否属于【本策略交易标的】, 用于策略日志过滤:
    仅候选池 / 本策略持仓 / 本策略买卖上下文(buy_ctx, sell_ctx, ordids) / 分批计划 / 历史done记录
    中的标的视为策略标的; 其他(柜台手工持仓、其他策略、纯外部成交回报)一律视为非策略标的,
    其买卖信息不写入策略日志。仅影响日志输出, 不影响任何下单/持仓/风控决策。"""
    try:
        if not code:
            return False
        if any(c.get('stock') == code for c in (G.candidates or [])):
            return True
        st = G.state or {}
        if code in (st.get('hold') or {}):
            return True
        if code in (st.get('buy_ctx') or {}):
            return True
        if code in (st.get('sell_ctx') or {}):
            return True
        if code in (st.get('ordids') or {}):
            return True
        if code in (st.get('done') or {}):
            return True
        h = (st.get('hold') or {}).get(code)
        if h and h.get('plan_batches') and not h.get('plan_done'):
            return True
        return False
    except Exception:
        # 判定异常时保守返回 True: 宁可多打印本策略标的, 也不遗漏策略内买卖回报
        return True

def scope_refuse(s, side):
    """铁律拦截: 拒绝对非策略标的执行买卖, 日志+推送双告警(绝不发单)"""
    # 2026-10-04: 用结构化触发日志输出, 明确"触发类型/动作/依据/参数", 便于核对调试
    try:
        trigger_log('铁律拦截-非策略标的', side, '该标的不在策略允许的买卖范围内, 拒绝发单',
                    code=disp(s), in_candidates=(s in [c.get('stock') for c in (G.candidates or [])]),
                    in_hold=(s in (G.state.get('hold') or {})), action='拒绝')
    except Exception:
        pass
    try:
        log('[铁律拦截] 拒绝对非策略标的执行%s: %s' % (side, disp(s)))
    except Exception:
        pass
    try:
        pnl_alert('[盈亏][异常] 铁律拦截: %s请求被拒绝(非策略交易标的) %s' % (side, disp(s)))
    except Exception:
        pass
def _clock_session_note():
    """按墙钟判定当前是否处于交易时段(不依赖日历, 供提示文案使用):
    明确回答'目前是交易时间还是非交易时间'"""
    now = datetime.datetime.now()
    v = now.hour * 100 + now.minute
    if (SESSION1_START <= v < SESSION1_END) or (SESSION2_START <= v < SESSION2_END):
        return '当前为交易时段(现%02d:%02d, 时段=09:30-11:30/13:00-15:00)' % (v // 100, v % 100)
    return '当前为非交易时段(现%02d:%02d, 时段=09:30-11:30/13:00-15:00)' % (v // 100, v % 100)

def _today_has_bars(ymd):
    """探测当日是否已有分钟行情(日历滞后时确认今日开市的兜底信号)。
    加固(2026-10-02): 探测前先补下载000001.SH当日1分钟数据(内置全局download_history_data),
    消除"客户端本地无该股1分钟数据 -> 真实交易日被误判待确认而暂停一整天"的隐患;
    补数据失败/无该接口(聚宽)只跳过, 不影响原有探测路径。"""
    try:
        try:
            _api(download_history_data, '000001.SH', '1m', ymd, ymd)   # 先补当日1分钟数据再探测
        except NameError:
            pass                          # 环境无download接口(聚宽兼容层已替换为no-op)
        except Exception:
            pass                          # 补数据失败不阻塞探测(维持原行为)
        # P0-1(重审20261005): 按位置传参(旧 stock_code= 必然TypeError, 日历滞后日整天误判待确认)
        d = _api(G.C.get_market_data_ex, ['volume'], ['000001.SH'], '1m', '', '', 10, 'front', False, False)
        bars = _bars_to_dict(d.get('000001.SH') if isinstance(d, dict) else None)
        for k, row in bars.items():
            if str(k).startswith(ymd):
                v = row.get('volume', 0) if isinstance(row, dict) else 0
                if v:
                    return True
        # P2-11修复(2026-10-17): 探测源加宽 —— 日线源(000001.SH当日日线bar)也作为开市证据。
        # 旧版只探测1m: 1m当日不落盘/取数异常时, 真实交易日可能整天"待确认"而暂停开平仓
        d2 = _api(G.C.get_market_data_ex, ['volume'], ['000001.SH'], '1d', '', '', 5, 'front', False, False)
        b2 = _bars_to_dict(d2.get('000001.SH') if isinstance(d2, dict) else None)
        if ymd in b2:
            return True
    except Exception as e:
        if not getattr(G, 'mde_probe_warned', False):
            G.mde_probe_warned = True   # 探测失效必须留痕, 禁止静默吞掉
            log('[数据告警] 当日分钟行情探测失败(日历滞后日可能整天待确认):', repr(e)[:160])
    return False

def load_local_calendar():
    """从多个候选位置装载交易日历 trading_calendar.json(由 download_trading_calendar.py 生成)。
    不依赖 QMT/网络, 可在 QMT 未启动/接口异常时独立提供日历; QMT 客户端常常把策略代码拷到
    自己的策略目录里运行(与项目目录分离), 故搜索多个候选位置, 命中第一个即返回。

    搜索顺序(找到就用, 跳过不存在的):
      1) 环境变量 TRADING_CALENDAR_PATH 指定的路径(强制指定)
      2) 策略脚本同目录(__file__ 所在)
      3) 当前工作目录(os.getcwd())
      4) 用户主目录(os.path.expanduser('~'))

    成功: 返回 (sorted_days_list, meta_dict); 全部候选都失败: 返回 (None, None)。
    meta 字段: source / last_update / first_date / last_date / count / _path(命中位置)。"""
    candidates = []
    env_path = os.environ.get('TRADING_CALENDAR_PATH')
    if env_path:
        candidates.append(env_path)
    try:
        here = os.path.dirname(os.path.abspath(__file__))
        candidates.append(os.path.join(here, 'trading_calendar.json'))
    except Exception:
        pass
    try:
        candidates.append(os.path.join(os.getcwd(), 'trading_calendar.json'))
    except Exception:
        pass
    try:
        candidates.append(os.path.join(os.path.expanduser('~'), 'trading_calendar.json'))
    except Exception:
        pass

    for path in candidates:
        try:
            if not path or not os.path.exists(path):
                continue
            with open(path, 'r', encoding='utf-8') as f:
                j = json.load(f)
            days = j.get('trading_days')
            if not isinstance(days, list) or len(days) < 100:
                continue
            out = []
            for x in days:
                s = str(x)[:8]
                if len(s) == 8 and s.isdigit():
                    out.append(s)
            if len(out) < 100:
                continue
            meta = {
                'source': str(j.get('source') or 'local'),
                'last_update': str(j.get('last_update') or ''),
                'first_date': out[0],
                'last_date': out[-1],
                'count': len(out),
                '_path': path,
            }
            return sorted(set(out)), meta
        except Exception:
            continue
    return None, None

_WD_CN = ('周一', '周二', '周三', '周四', '周五', '周六', '周日')

def log_day_phase_banner(force=False):
    """输出交易日/时段横幅；相同业务状态不重复打印。

    状态签名刻意不含当前小时/分钟：时间只用于展示，不能让每分钟都变成新状态。
    启动可用 force=True 强制输出一次；常规日历复核使用 force=False。
    """
    now = datetime.datetime.now()
    today = now.strftime('%Y%m%d')
    tday = is_trading_day(today)
    if tday is True:
        day_label = '交易日'
    elif tday is False:
        day_label = '非交易日'
    else:
        day_label = '日历未就绪'
    v = now.hour * 100 + now.minute
    if (SESSION1_START <= v < SESSION1_END) or (SESSION2_START <= v < SESSION2_END):
        # V2.6.64(F2): 旧文案硬编码"开平仓正常", 非交易日在时段内也这么打, 与次行
        # "今日暂停开平仓"自相矛盾; 按当日历判定(tday)分流, 墙钟时段与可交易权限分开表述。
        if tday is True:
            clk_label = '交易时段(开平仓正常)'
        elif tday is False:
            clk_label = '交易时段(今日非交易日, 暂停开平仓)'
        else:
            clk_label = '交易时段(日历未就绪, 待确认)'
    else:
        clk_label = '非交易时段(盘前/午休/盘后, 静默)'
    src = G.calendar_source or '(本地无缓存, QMT 日历接口失败)'
    upd = G.calendar_last_update or '(从未更新)'
    wd = _WD_CN[now.weekday()] if 0 <= now.weekday() < 7 else '?'
    state_key = (today, day_label, clk_label, src, upd)
    if not force and G.last_day_phase_key == state_key:
        return False
    msg = ('交易日状态 | 今日 %s (%s) = %s | 当前 %02d:%02d = %s | 日历源=%s 缓存更新=%s'
           % (today, wd, day_label, now.hour, now.minute, clk_label, src, upd))
    # P3(V2.6.83): 删死字段 banner_note_date(去重已由 last_day_phase_key 完成)
    G.last_day_phase_key = state_key
    log(msg)
    return True


def refresh_calendar():
    """每天刷新交易日历: 三级优先级 1) 本地缓存 trading_calendar.json  2) C.get_trading_dates  3) 上证指数日线。
    日历滞后修正: 盘中官方日历可能尚未包含当日(数据延迟), 此时用当日分钟行情探测确认;
    无法确认前保持待确认(暂停开平仓, 按CAL_RETRY_SEC静默复核), 绝不把交易日误锁成休市整天。"""
    now = datetime.datetime.now()
    ymd = now.strftime('%Y%m%d')
    if G.refresh_date == ymd:
        if G.today:
            return                                  # 今日已确认为交易日
        if now.weekday() >= 5:
            return                                  # 今日已确认为周末休市
        if (time.time() - G.cal_retry_ts) < CAL_RETRY_SEC:
            return                                  # 待确认状态, 按节流自动复核
    G.refresh_date = ymd
    G.cal_retry_ts = time.time()
    cal = []
    cal_source_tag = ''

    # ---- 优先级 1: 本地缓存 trading_calendar.json (download_trading_calendar.py 生成) ----
    _stale_cal = False   # P2-3修复(20261008): 本地日历缓存是否跨年陈旧(缓存最后日期年份<当前年)
    _not_cover_today = False  # V2.6.70: 本地日历缓存最后日期是否未覆盖今天(停更)
    try:
        local_days, local_meta = load_local_calendar()
        # P2-3修复(20261008): 跨年陈旧缓存检测 —— 日历缓存最后日期年份早于当前年即视为陈旧
        # (新年头几个交易日/调休日历未更新), 跳过本地缓存优先, 强制走 QMT 官方接口刷新。
        try:
            _lastd = str((local_days or [''])[-1] or '')
            if _lastd[:4].isdigit() and int(_lastd[:4]) < now.year:
                _stale_cal = True
        except Exception:
            _stale_cal = False
        # V2.6.70修复: 除跨年陈旧外, 再查缓存是否已覆盖今天 —— 本地缓存 last_date < 今天
        # 说明日历文件停更(例: 2026-10-19实盘日志显示缓存更新=2026-10-02且未覆盖今天),
        # 旧版仍采信本地缓存, 遇临时调休/新年度新增休市会误判交易日。此时跳过本地缓存
        # 强制走 QMT 官方接口刷新; QMT 也失败时再走当日行情探测兜底(不误锁休市)。
        _not_cover_today = False
        try:
            _ld_last = str((local_days or [''])[-1] or '')
            if _ld_last[:8].isdigit() and _ld_last[:8] < ymd:
                _not_cover_today = True
        except Exception:
            _not_cover_today = False
        if local_days and len(local_days) >= 100 and not _stale_cal and not _not_cover_today:
            cal = local_days
            base_src = local_meta.get('source') or 'local'
            cal_source_tag = 'local:%s' % base_src
            G.calendar_last_update = local_meta.get('last_update') or ''
            # 日志透明化: 打一条告诉用户本地缓存是从哪个具体路径装载的(QMT 拷贝策略到
            # 自己的目录运行时, __file__ 已不再指向项目目录, 此日志便于排查)
            _lp = local_meta.get('_path') or '?'
            if _lp and _lp != os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                            'trading_calendar.json'):
                log('[日历] 本地缓存命中非默认位置: %s(由 TRADING_CALENDAR_PATH/'
                    '工作目录/用户主目录候选之一载入)' % _lp)
            # ---- D2(2026-10-03): 每年【第一次运行本策略】提示下载当年度最新交易日/非交易日列表 ----
            # 原版在"每年首个交易日"才提示: 若用户当年首批交易日没有启动策略(或假期才启动),
            # 整年都不会提示, 节假日变更/新增休市信息无法及时刷新缓存导致日历失准。
            # 新口径: 每年第一次运行即检查本地日历是否已覆盖当年; 未覆盖则提示一次(年内不重复)。
            try:
                if getattr(G, 'year_prompt', '') != str(now.year):
                    G.year_prompt = str(now.year)
                    if not any(str(d).startswith(str(now.year)) for d in local_days):
                        log('[日历] %d年度交易日/非交易日列表尚未下载(本地缓存最后更新=%s)。'
                            '请运行 python download_trading_calendar.py 下载当年度'
                            '最新列表, 确保节假日/调休判定准确; 本提示每年仅提醒一次'
                            % (now.year, local_meta.get('last_update') or '?'))
            except Exception:
                pass
    except Exception:
        pass
    if not cal:
        # 本地缓存完全找不到时给一条明确提示(只在每天首次刷新时打一次, 不刷屏)
        if _stale_cal:
            # P2-3修复(20261008): 跨年陈旧场景说明为强制刷新(不是"缓存找不到")
            if G.cal_warn_ts == 0.0 or (time.time() - G.cal_warn_ts) > 3600:
                G.cal_warn_ts = time.time()
                log('[日历] 本地缓存为跨年陈旧数据, 已强制走 QMT 官方接口刷新 %d 年度 '
                    '交易日/节假日口径(若 QMT 接口同时失败, 见上方告警)' % now.year)
        elif _not_cover_today:
            # V2.6.70: 本地缓存存在但已不覆盖今天(停更), 单列提示便于排障
            if G.cal_warn_ts == 0.0 or (time.time() - G.cal_warn_ts) > 3600:
                G.cal_warn_ts = time.time()
                log('[日历] 本地缓存 trading_calendar.json 最后日期=%s 未覆盖今天%s, '
                    '已强制走 QMT 官方接口刷新(缓存可能停更, 建议运行 '
                    'download_trading_calendar.py 刷新)'
                    % (_ld_last, ymd))
        elif G.cal_warn_ts == 0.0 or (time.time() - G.cal_warn_ts) > 3600:
            G.cal_warn_ts = time.time()
            log('[日历] 本地缓存 trading_calendar.json 找不到, 已回退到 QMT '
                'C.get_trading_dates(可能被节假日数据滞后影响)。建议: ①把 trading_calendar.json '
                '放到 QMT 策略目录同层; ②或设置系统环境变量 TRADING_CALENDAR_PATH 指向 JSON 路径; '
                '③或运行 python download_trading_calendar.py 定时刷新项目目录的 JSON')

    # ---- 优先级 2: QMT C.get_trading_dates(官方接口) ----
    if len(cal) < 20:
        start = (now - datetime.timedelta(days=90)).strftime('%Y%m%d')
        end2 = (now + datetime.timedelta(days=15)).strftime('%Y%m%d')   # 部分客户端end需晚于当日才返回当日
        try:
            cal = list(_api(G.C.get_trading_dates, '000001.SH', start, end2, -1, '1d'))
        except Exception:
            cal = []
        if len(cal) < 20:
            try:
                cal = list(_api(G.C.get_trading_dates, '000001.SH', start, ymd, -1, '1d'))
            except Exception:
                cal = []
        if len(cal) >= 20:
            cal_source_tag = 'qmt:get_trading_dates'
            G.calendar_last_update = now.strftime('%Y-%m-%d %H:%M:%S')

    # ---- 优先级 3: 上证指数日线兜底(指数有bar就有交易日) ----
    if len(cal) < 20:
        try:
            # P0-1(重审20261005): 按位置传参(旧 stock_code= 必然TypeError被吞, 兜底成死分支)
            d = _api(G.C.get_market_data_ex, [], ['000001.SH'], '1d', '', '', 90, 'front', True, False)
            cal = sorted(_bars_to_dict(d.get('000001.SH') if isinstance(d, dict) else None).keys())
        except Exception as e:
            if not getattr(G, 'mde_cal_warned', False):
                G.mde_cal_warned = True   # 日历兜底失效必须留痕, 禁止静默吞掉
                log('[数据告警] 指数日线日历兜底失效:', repr(e)[:160])
        if len(cal) >= 20:
            cal_source_tag = 'qmt:sse_index_bars (fallback)'
            G.calendar_last_update = now.strftime('%Y-%m-%d %H:%M:%S')

    if len(cal) < 20:
        cal = []
    G.calendar = [str(x) for x in cal]
    if cal_source_tag:
        G.calendar_source = cal_source_tag
    # 日历复核可能每60秒执行；仅在交易日/时段/数据源状态变化时刷新横幅，避免刷屏。
    log_day_phase_banner(force=False)
    if ymd in G.calendar:
        G.today = ymd
        return
    # 本地日历完整覆盖今天(last_date >= today) 且 今天不在日历里
    #   → 权威判定: 今天就是非交易日(法定节假日落在工作日上)
    #   → 不再走 "待确认 + 60秒复核" 的悲观路径, 直接按休市处理
    # 注意: 仅在本地缓存源(local:*)下生效; QMT 接口源覆盖不全时仍走原路径, 防误锁
    if G.calendar and G.calendar[-1] >= ymd and cal_source_tag.startswith('local:'):
        G.today = ''
        if G.cal_note_date != ymd:
            G.cal_note_date = ymd
            # V2.6.64(F1): 该分支对周末同样生效(日历覆盖全年时周末必入此分支),
            # 旧文案把周末误标为法定节假日; 按星期几分流, 周末与节假日分别表述。
            if now.weekday() >= 5:
                log(ymd, '今日判定: 非交易日(周末, 本地日历确认) |',
                    _clock_session_note(),
                    '| 今日暂停开平仓')
            else:
                log(ymd, '今日判定: 非交易日(本地日历权威确认, 工作日但非交易日 = 法定节假日) |',
                    _clock_session_note(),
                    '| 今日暂停开平仓')
        return
    if now.weekday() >= 5:
        G.today = ''
        if G.cal_note_date != ymd:
            G.cal_note_date = ymd
            log(ymd, '今日判定: 非交易日(周末, 日历确认) |', _clock_session_note(),
                '| 今日暂停开平仓')
        return
    if _today_has_bars(ymd):
        G.calendar = sorted(set(G.calendar + [ymd]))            # 日历滞后: 行情确认开市, 补入日历
        G.today = ymd
        log(ymd, '今日判定: 交易日(日历滞后, 当日分钟行情已确认开市) |', _clock_session_note(),
            '| 恢复正常运行')
        return
    # P2-11修复(2026-10-17): 行情探测无果时, 用静态交易日历(trading_calendar.json)兜底确认 ——
    # 旧版直接"待确认"并每CAL_RETRY_SEC秒复核, 若1m/日线取数持续失败(调休日/数据缺失),
    # 会隐式禁买至15:00(整日无开平仓); 静态日历含今日即判定开市, 不含才维持待确认
    try:
        _ld11, _lm11 = load_local_calendar()
    except Exception:
        _ld11 = []
    if ymd in (_ld11 or []):
        G.calendar = sorted(set(G.calendar + [ymd]))
        G.today = ymd
        log(ymd, '今日判定: 交易日(行情探测无果, 静态交易日历确认开市) |', _clock_session_note(),
            '| 恢复正常运行')
        return
    G.today = ''
    G.refresh_date = ''      # 清除按日标记, 允许按CAL_RETRY_SEC自动复核(确认开市后自动恢复)
    if G.cal_note_date != ymd:
        G.cal_note_date = ymd
        log(ymd, '今日判定: 待确认(工作日, 日历源=%s 未含今日, 节假日或日历数据滞后) |'
            % G.calendar_source,
            _clock_session_note(),
            '| 确认开市前暂停开平仓, 每%d秒自动复核; 当日分钟行情确认开市后将自动恢复交易日处理'
            % CAL_RETRY_SEC)

def is_trading_day(ymd=''):
    """交易日判定(独立封装, 供任意模块复用)。依据官方交易日历, 自动覆盖
    周末/法定节假日/调休, 与沪深市场保持一致。须先调用refresh_calendar()刷新。
    返回: True=交易日; False=非交易日; None=日历不可用(调用方应保守按休市处理)"""
    if not G.calendar:
        return None
    d = ymd or datetime.datetime.now().strftime('%Y%m%d')
    return d in G.calendar

def market_phase(ymd='', hm=None):
    """市场时段判定(独立封装, 与is_trading_day同源可复用)。须先refresh_calendar()。
    返回: 'trading'=交易时段(开平仓正常, 打点逐次输出);
          'off_hours'=交易日非交易时段(盘前/午休/盘后, 静默);
          'closed_day'=非交易日(周末/法定节假日, 静默);
          'unknown'=日历不可用(保守按非交易处理)"""
    d = ymd or datetime.datetime.now().strftime('%Y%m%d')
    tday = is_trading_day(d)
    if tday is not True:
        return 'closed_day' if tday is False else 'unknown'
    now = datetime.datetime.now()
    v = (now.hour * 100 + now.minute) if hm is None else hm
    if (SESSION1_START <= v < SESSION1_END) or (SESSION2_START <= v < SESSION2_END):
        return 'trading'
    return 'off_hours'

def load_universe():
    """获取沪深A股列表: 依次尝试多种板块名与调用形式, 兼容不同客户端版本/板块数据缺失"""
    attempts = [('沪深A股', True), ('沪深A股', None), ('A股', None)]
    last_err = None
    for name, extra in attempts:
        try:
            lst = (_api(G.C.get_stock_list_in_sector, name, extra) if extra is not None
                   else _api(G.C.get_stock_list_in_sector, name)) or []
            if lst:
                log('股票列表获取成功: 板块=%r 形式=%s 股票数=%d'
                    % (name, '带第二参数' if extra is not None else '单参数', len(lst)))
                return list(lst)
        except Exception as e:
            last_err = e
            continue
    if last_err is not None:
        log('板块列表获取异常:', last_err)
    return []

def step_day_init():
    """每交易日初始化, 按策略状态分步执行避免阻塞框架:
    阶段1分批download_history_data -> 阶段2加载历史+对账+选股"""
    if not G.today or G.state['last_init_date'] == G.today:
        return
    now = datetime.datetime.now()
    if time.time() - G.last_init_try < 300 and G.dl_phase == 0:
        return
    if G.dl_phase == 0:
        G.last_init_try = time.time()
        if G.state['last_dl_date'] == G.today:
            G.dl_phase = 2          # 今日已下载过, 直接进加载
            return
        G.universe = load_universe()
        if not G.universe:
            log('股票列表为空(板块数据未下载或行情未连接), 5分钟后重试')
            G.last_init_try = time.time()
            return
        G.dl_i = 0
        G.dl_phase = 1
        G.dl_mark = -1      # V2.6.95: 新一轮重新计桶, 保证首轮就打印进度(不再静默10分钟)
        # V2.6.97(3): 下载起始时刻。写成 G 属性而非模块级常量, 否则 _fp_keys() 会把它
        #   收进参数指纹, 改日志而已指纹却漂了。
        G.dl_t0 = time.time()
        start = (now - datetime.timedelta(days=DOWNLOAD_START_DAYS)).strftime('%Y%m%d')
        G.dl_start = start
        log('====== 交易日初始化', G.today, '====== 开始下载日线, 股票数:', len(G.universe))
        return
    if G.dl_phase == 1:
        start = G.dl_start
        end = G.today
        _u_tot = len(G.universe)
        # P1-3修复(2026-10-02): 单轮下载加时间预算 —— 旧版固定400只/轮, 单只下载慢时本轮会
        #   长时间占用轮询线程(成交回报回调被延迟)。超预算即让出线程, 下一轮从 G.dl_i 续下。
        # V2.6.96(3): 块大小 x5(400 -> 2000/块), 且"一块下完预算还有剩就接着切下一块"。
        #   旧版每轮只切一块 400 只, 不管 8 秒预算还剩多少都退出等下一个 30 秒节拍 ——
        #   2026-10-20 00:23 实测: 情绪取数并发抢接口, 8 秒只下 153 只, 余下约 22 秒纯空转,
        #   5226 只被拖成 17 分钟。现在把"时间预算"当成唯一上限: 8 秒内能下多少下多少,
        #   下完就停, 单轮对轮询线程的占用仍严格受 DOWNLOAD_TIME_BUDGET_SEC 约束, 不多占 1 毫秒。
        #   块大小写成局部算式 DOWNLOAD_CHUNK*5 而不是改常量: DOWNLOAD_CHUNK 是大写模块级
        #   常量, 改动会让参数指纹漂移, 使状态文件 verified_fp 的比对凭空失效。
        _chunk_n = DOWNLOAD_CHUNK * 5
        _t0 = time.time()
        _n = 0
        while G.dl_i < _u_tot and not G.no_download:
            if DOWNLOAD_TIME_BUDGET_SEC > 0 and (time.time() - _t0) >= DOWNLOAD_TIME_BUDGET_SEC:
                break           # 预算用完: 让出轮询线程, 下一轮从 G.dl_i 续下
            _chunk = G.universe[G.dl_i:G.dl_i + _chunk_n]
            if not _chunk:
                break
            _got = 0
            for s in _chunk:
                if G.no_download:
                    break
                if DOWNLOAD_TIME_BUDGET_SEC > 0 and (time.time() - _t0) >= DOWNLOAD_TIME_BUDGET_SEC:
                    break
                try:
                    _api(download_history_data, s, '1d', start, end)
                except NameError:
                    G.no_download = True
                    break
                except Exception:
                    pass
                _n += 1
                _got += 1
            G.dl_i += _got
            if G.no_download:
                break           # 交给下面的 no_download 分支处置(dl_i 不再推进, 保住"是否首轮"的判断)
            if _got <= 0:
                G.dl_i += 1     # 单只下载即超预算: 至少推进一只, 保证不死循环
                break
            if _got < len(_chunk):
                break           # 预算在本块内用完
            if DOWNLOAD_TIME_BUDGET_SEC <= 0:
                break           # 预算关闭(0=不限)时保持旧行为: 一轮只下一块, 不长时间占用轮询线程
        if G.no_download:
            if G.dl_i == 0:
                log('本QMT无download_history_data接口: 请在客户端手动批量下载沪深A股'
                    '日线历史数据(数据管理/历史数据下载), 否则无数据可选股')
            G.dl_i = len(G.universe)   # 跳过下载阶段, 直接读取本地已有数据
            # V2.6.144: 额外给上证指数也下载日线(1个代码,不影响节流),
            #   让 load_history() 能把成交额维度注入 G.hist,
            #   _sent_fetch_from_cache() 缓存聚合就能拿到三维数据了
            try:
                _api(download_history_data, SENT_INDEX_SYMBOL, '1d', start, end)
                log('[下载] 上证指数(%s)日线也下载完毕(额外1个)' % SENT_INDEX_SYMBOL)
            except Exception as _e144:
                log('[下载] 上证指数(%s)日线下载失败(不影响A股,仅情绪少成交额维度): %s'
                    % (SENT_INDEX_SYMBOL, repr(_e144)[:100]))

            G.state['last_dl_date'] = G.today
            save_state()
            G.dl_phase = 2
            return
        _bucket = G.dl_i // 2000      # V2.6.95(2): 千位桶号 —— 旧判定要求进度恰好踩在
        #   2000 的整数倍上, 但每轮实际只推进约 250 只(8秒预算被并发的情绪取数拖住), 于是
        #   250/500/750/1000... 永远踩不到 2000, 整场只在结束时打一行, 甚至一行都没有
        #   (2026-10-20 00:07 那次启动, 5226 只下完约10分钟里日志一个字都没打)。
        #   改成跨桶即打: 首轮就出进度, 之后每跨过 2000 只一行, 末尾补一行终值。
        if _bucket != getattr(G, 'dl_mark', -1) or G.dl_i >= _u_tot:
            G.dl_mark = _bucket
            # V2.6.97(3): 完成那行补总耗时与均速。旧版只有“下载进度 5226 / 5226”,
            #   2026-10-20 00:22:33->00:35:39 这轮下了 786 秒(5226 只 / 6.6 只每秒,
            #   当时情绪取数在并发抢接口), 但日志里没有任何时间账可对;
            #   明天验证 V2.6.96 串行化到底省了多少, 没有基线就说不出口。
            if G.dl_i >= _u_tot:
                _dl_el = time.time() - _f(getattr(G, 'dl_t0', 0.0))
                _dl_sp = (float(min(G.dl_i, _u_tot)) / _dl_el) if _dl_el > 0 else 0.0
                log('下载进度', min(G.dl_i, _u_tot), '/', _u_tot,
                    '(完成, 耗时%d秒 均速%.1f只/秒)' % (int(_dl_el), _dl_sp))
            else:
                log('下载进度', min(G.dl_i, _u_tot), '/', _u_tot)
        if G.dl_i >= _u_tot:
            G.state['last_dl_date'] = G.today
            save_state()
            G.dl_phase = 2
        return
    # 阶段2: 加载历史 + 选股(对账已由init阶段reconcile_positions全量双向完成, 此处仅处理正常清算)
# V2.6.146 Phase2 自动排雷调用块 (独立文件, 直接以 GBK 字节嵌入)
    # V2.6.160: 移除策略内自动抓取(约80秒外部HTTP), 改为仅读取本地缓存清单
    #   原 _auto_risk_exclude() 连接东方财富/新浪财经外部接口, 触发QMT"非法IP"安全拦截
    #   排雷清单在QMT外部生成后放入脚本同目录, 策略仅读取本地JSON(策略内不抓取外部接口)
    if G.risk_ex_date != G.today and RISK_EXCLUDE_ON:
        try:
            load_risk_exclude()
        except Exception as _e160:
            log('[排雷] 清单装载异常: %r (后续用旧清单)' % repr(_e160)[:120])
        log('[排雷] 排雷清单为本地JSON(与脚本同目录); 更新请在QMT外部生成后替换该文件, 策略内不做外部抓取(防非法IP拦截)')

    load_history()
    load_hot_sectors()   # 方案A一期: 刷新当日热门板块集合(依赖G.hist, 在选股前)
    if G.today not in G.calendar:
        dates = set()
        for rows in G.hist.values():
            dates.update(r['date'] for r in rows)
        G.calendar = sorted(dates)
    pt, pa, cash = query_account()
    if pt is None:
        # P0-1: 对账查询失败(空表/异常)时清算必须跳过 —— 此处旧版连None都不检查,
        # 柜台断连返回空表会把全部持仓当已平仓删除(mark_sold+伪造已实现盈亏)
        log('[安全] 日初始化对账查询失败, 今日清算跳过(绝不基于空数据清理持仓)')
    else:
        with G.state_lock:
            for s in list(G.state['hold'].keys()):
                h = G.state['hold'][s]
                if not is_own_position(h):
                    # 对账补录的孤儿仓(其他策略/手工持仓): 不在此处当作本策略平仓处理, 其清理归 reconcile_positions
                    continue
                if pt.get(s, 0) <= 0:
                    # reconcile_positions 已清掉脏记录(px<=0等), 此处处理正常清算(真持有过然后没了)
                    if h.get('fill_vol', 0) > 0 or h.get('exited'):
                        log(disp(s), '对账: 已无持仓, 本轮结束')
                        mark_sold(s)      # 真实持有过才计入卖出间隔(防误锁10日)
                    else:
                        log(disp(s), '对账: 昨日买入未成交, 回到观察(不计卖出间隔)')
                        G.state['done'].pop(s, None)
                    del G.state['hold'][s]
            manual = [x for x in pt if x not in G.state['hold']]
            if manual:
                # 日志过滤: 不输出实盘账户非本策略持仓的只数与明细(账户级信息不写入策略日志)
                log('提示: 账户内检测到非本策略持仓, 本策略绝不碰它们(明细不输出)')
            if len(G.state['done']) > 500:
                items = sorted(G.state['done'].items(), key=lambda kv: kv[1], reverse=True)[:200]
                G.state['done'] = dict(items)
            sold = G.state.get('sold') or {}
            if len(sold) > 300 and G.today in G.calendar:
                t_idx = G.calendar.index(G.today)
                keep = {}
                for k, v in sold.items():
                    try:
                        if t_idx - G.calendar.index(v) <= 60:
                            keep[k] = v
                    except Exception:
                        keep[k] = v
                G.state['sold'] = keep
    screen_candidates()
    G.state['last_init_date'] = G.today
    G.dl_phase = 0
    save_state()

# V2.6.171: 非交易日预选 —— 周末/法定节假日也刷新候选池(只选股, 绝不开平仓)。
#   参考日 ref = 交易日历中<=今天的最后交易日(周末=上周五, 节假日=之前最后交易日);
#   日历取不到则退回上一自然日。数据来源: load_history 只读QMT本地已下载日线
#   (get_market_data_ex, 不触发重新下载全市场) —— 非交易日本地数据即参考日数据,
#   无需重复下载; 本地无数据时打一行日志跳过, 下一个交易日初始化自动补齐(不重试不刷屏)。
def prescreen_offday():
    """非交易日预选(V2.6.171): 只刷新候选池, 绝不开平仓。
    调用点: timer_poll 中 G.today 为空的分支(非交易日/日历未就绪)。
    节流: 每个自然日只完整执行一次(G.prescreen_date, 进程重启即重新计时)。
    保险: 是交易日则直接返回(交易日选股由 step_day_init 驱动, 绝不经本路径)。"""
    if is_trading_day() is True:
        return      # 保险: 交易日绝不走预选路径
    ymd = datetime.datetime.now().strftime('%Y%m%d')
    if getattr(G, 'prescreen_date', '') == ymd:
        return
    G.prescreen_date = ymd
    ref = ''
    for _d in reversed(G.calendar or []):
        if _d <= ymd:
            ref = _d
            break
    if not ref:
        ref = (datetime.datetime.now() - datetime.timedelta(days=1)).strftime('%Y%m%d')
    log('====== 非交易日预选', ymd, '====== 参考交易日', ref, '(只刷新候选池, 绝不开平仓)')
    if not G.universe:
        try:
            G.universe = load_universe()
        except Exception:
            pass
    # P3-X-N1(2026-10-29 修复)：非交易日预选必须【每次重载】日线。
    #   原实现只在 G.hist 为空时才 load_history()；周末 QMT 保持登录时 G.hist 还是上一个
    #   交易日的旧切片，于是直接拿旧数据选股 —— 正是 V2.6.180 声称修掉的「陈旧基准」。
    #   旧池会写进日志并下发到 QMT 板块，盘前看到的是过期名单。
    try:
        load_history()
    except Exception as _e_xn1:
        log('[非交易日预选] 日线重载异常(继续用现有缓存):', _e_xn1)
    if not G.hist:
        log('[非交易日预选] 本地无日线数据(QMT数据目录未下载或行情未连接), 本次预选跳过; '
            '候选池将在下一个交易日初始化时自动构建')
        return
    try:
        load_hot_sectors()
        screen_candidates(ref)
        log('[非交易日预选] 完成: 候选池', len(G.candidates), '只(参考交易日', ref,
            '); 下一个交易日的日初始化会按当日数据重新筛选, 本池仅作盘前参考')
    except Exception:
        log('[非交易日预选] 选股异常(不影响交易, 下一个交易日初始化会自动重建候选池):')
        traceback.print_exc()

def detect_volume_unit(d1, sample_cap=300):
    """拍板2(重审20261005): 从批量日线的原始bar探测volume单位(手/股)。
    原理: bar自带 amount(成交额,元), ratio = amount/(close*volume):
      ratio~100 -> volume是"手"(返回100); ratio~1 -> 是"股"(返回1);
      样本不足/口径异常返回 None(调用方沿用现值并告警)。
    只采样前sample_cap个有效bar, 全市场批量数据下开销可忽略。
    兼容聚宽版: jq口径成交额字段为 money。"""
    ratios = []
    cnt = 0
    for s, rows in (d1 or {}).items():
        if rows is None:
            continue
        if hasattr(rows, 'to_dict'):
            try:
                rows = _df_to_rows(rows)
            except Exception:
                continue
        if not isinstance(rows, dict) or not rows:
            continue
        for dt, b in rows.items():
            if not isinstance(b, dict):
                continue
            close = _f(b.get('close', 0))
            vol = _f(b.get('volume', 0))
            amt = _f(b.get('amount', 0)) or _f(b.get('money', 0))
            if close <= 0 or vol <= 0 or amt <= 0:
                continue
            ratios.append(amt / (close * vol))
            cnt += 1
            if cnt >= sample_cap:
                break
        if cnt >= sample_cap:
            break
    if not ratios:
        return None
    med = sorted(ratios)[len(ratios) // 2]
    if med >= 50:
        return 100
    if med <= 2:
        return 1
    # 重审20261006(P1-C/问题5): 模糊区间[2,50]不得直接返回None回退陈旧全局值 ——
    # A股股价一般>=0.5元: ratio在[2,50]说明"若是股则股价2-50元(合理), 若是手则股价0.02-0.5元(不合理)",
    # 故几乎必为"股"(返回1)。为彻底稳健, 用样本内收盘价中位数做交叉校验:
    # 若 median(close) 落在 [1, 500] 元正常区间, 判定为股(ratio~close/unit); 否则沿用保守返回None。
    # 这消除了旧版"探测失败→回退陈旧DAILY_VOL_UNIT→流动性过滤错100倍"的隐患。
    _closes = []
    _c2 = 0
    for s, rows in (d1 or {}).items():
        if rows is None:
            continue
        if hasattr(rows, 'to_dict'):
            try:
                rows = _df_to_rows(rows)
            except Exception:
                continue
        if not isinstance(rows, dict) or not rows:
            continue
        for dt, b in rows.items():
            if not isinstance(b, dict):
                continue
            _cl = _f(b.get('close', 0))
            if _cl > 0:
                _closes.append(_cl)
                _c2 += 1
            if _c2 >= sample_cap:
                break
        if _c2 >= sample_cap:
            break
    if _closes:
        _med_close = sorted(_closes)[len(_closes) // 2]
        if 1.0 <= _med_close <= 500.0:
            # 股价落在正常A股区间, ratio[2,50]对应"股"口径(close=2~50元), 判定为股
            return 1
    # 股价异常(数据质量存疑): 保守返回None, 由调用方走保守流动性过滤(见screen_candidates)
    return None


def detect_tick_volume_unit(stocks, sample_cap=200):
    """P0-1修复(20261008): 实测tick快照volume单位(手/股) —— ratio=amount/(lastPrice*volume),
    与日线 detect_volume_unit 同法: ratio~100->手(100), ~1->股(1), 模糊区间用lastPrice交叉校验;
    样本不足/异常返回None(调用方按与日线同单位处理并提示)。"""
    ratios = []
    px_list = []
    cnt = 0
    try:
        ticks = _api(G.C.get_full_tick, stocks[:sample_cap]) or {}
    except Exception:
        return None
    for _s, _t in (ticks or {}).items():
        if not isinstance(_t, dict):
            continue
        _px = _f(_t.get('lastPrice'))
        _vol = _f(_t.get('volume'))
        _amt = _f(_t.get('amount'))
        if _px <= 0 or _vol <= 0 or _amt <= 0:
            continue
        ratios.append(_amt / (_px * _vol))
        px_list.append(_px)
        cnt += 1
        if cnt >= sample_cap:
            break
    # 20261027: 样本门槛由固定20改为按观察只数折算(六成, 下限 TICK_UNIT_MIN_SAMPLES, 上限20)。
    #   旧版 watch 常态只有持仓+候选约3~6只, 永远凑不满20, 于是每个交易日开盘第一次核对
    #   必然失败, 被调用方记成"异常1天", 连续3天就把买入拉闸。本函数结果只用于核对口径,
    #   不参与量能计算(G.tick_vol_unit 恒按手=100), 故降门槛不影响任何交易数值。
    _n_watch = len(stocks or [])
    _need_n = min(20, max(TICK_UNIT_MIN_SAMPLES, (6 * _n_watch + 9) // 10))
    if len(ratios) < _need_n:
        return None
    med = sorted(ratios)[len(ratios) // 2]
    if med >= 50:
        return 100
    if med <= 2:
        return 1
    _mp = sorted(px_list)[len(px_list) // 2]
    if 1.0 <= _mp <= 500.0:
        return 1
    return None


def _tick_unit_blocked():
    """第6条修复(2026-10-17): tick量单位异常拉闸状态 —— 返回True表示"tick量单位疑似股(与手冲突)
    已连续多个交易日异常、已强制暂停买入", 需人工确认行情源正常(tick_unit_ack 或 TICK_UNIT_ACK)后才解除。
    买入主路径(buy_stock)与分批加仓(run_pyramid_adds)在发单前都先查本函数。"""
    try:
        return bool(G.state.get('tick_unit_blocked'))
    except Exception:
        return False


def _px_is_stale(t):
    """P3-5(2026-10-24 第18轮零预设独立审计): 判断某票当前 tick 价格是否为"陈旧价"。
    陈旧价 = _refresh_ticks 在"当日1m无任何bar"时写入的【上一交易日收盘价】
    (src=old_bar_px_only, volume=0, vol_ok=False) —— 该价格只应用于只读监控,
    不能作为价格型交易决策(止盈/到期卖出/T+1执行)的依据。
    危害例: 成本10.00、昨日收10.50(浮盈5%), 今日1m缺失被判陈旧价10.50, 恰逢
    MAX_HOLD_TRDAYS 到期 -> 按10.48挂限价卖; 若今日真实价已跌到9.80, 卖单高于市价
    成交不了(错失卖点); 若真实价涨到11.00, 则10.48立即成交, 少赚约0.52元/股
    (1万股≈5200元)。"""
    try:
        return bool(t) and str(t.get('src') or '') == 'old_bar_px_only' \
            and t.get('vol_ok') is False
    except Exception:
        return False


def _tick_to_daily_scale():
    """V2.6.35b修正注释(行为不变): tick快照 volume -> 日线基准量 同单位换算系数。本策略已锁定 tick_vol_unit=100 且 DAILY_VOL_UNIT=100, 故恒返回 1.0(手=手, 无需换算)。原注释称"支持 TICK_VOL_UNIT=1 按股处理", 与真实行为不符, 已更正。"""
    _t = int(getattr(G, 'tick_vol_unit', 0) or 0)
    _d = int(DAILY_VOL_UNIT or 1)
    if _t > 0 and _d > 0:
        return float(_t) / float(_d)
    return 1.0

def load_history():
    """一次性批量读取全市场近HISTORY_BARS根日线, 并按前收盘计算每日涨停标记"""
    global DAILY_VOL_UNIT
    G.hist = {}
    stocks = G.universe
    try:
        # P0-1(重审20261005): 本接口必须按位置传参(官方签名: 字段列表,股票列表,周期,开始,
        # 结束,根数,复权,填充,订阅) —— 旧版关键字 stock_code= 必然TypeError且被吞,
        # 导致 G.hist 恒空、策略每天静默空转(最危险失效形态)
        d1 = _api(G.C.get_market_data_ex, [], stocks, '1d', '', '', HISTORY_BARS, 'front', False, False)
    except Exception as e:
        d1 = {}
        log('[数据告警] get_market_data_ex(批量历史)调用失败, 选股将无数据可用:', repr(e)[:160])
    # 拍板2(重审20261005): 自动探测日线volume单位, 覆盖 DAILY_VOL_UNIT 全局 ——
    #   MIN_DAILY_AMOUNT 流动性过滤的成交额口径依赖它, 单位错100倍过滤即失效
    # V2.6.17 口径锁定: 成交量单位已确认为"手"(tick/分时/日K 同口径), 此处只做核对, 不再改判 ——
    #   原逻辑在探测到"股"口径时会把 DAILY_VOL_UNIT 改成 1, 使成交额与量能口径整体错100倍(流动性过滤失效)。
    if AUTO_VOL_UNIT:
        log('[单位校准] 口径确认: tick快照/分时/日K 成交量单位均为手(1手=100股), DAILY_VOL_UNIT=%d' % DAILY_VOL_UNIT)
        try:
            det = detect_volume_unit(d1)
            if det is None:
                # P3(V2.6.83): 删死字段 vol_unit_confirmed(全文件只写不读, 核对结论已由日志表达)
                if int(DAILY_VOL_UNIT or 1) != 100:
                    DAILY_VOL_UNIT = 100
                log('[单位校准] 日线volume核对: 样本无amount/money或口径异常, 无法核对; '
                    '按已确认口径保持 DAILY_VOL_UNIT=%d(手)' % DAILY_VOL_UNIT)
            elif det == 100:
                # P3(V2.6.83): 删死字段 vol_unit_confirmed(全文件只写不读, 核对结论已由日志表达)
                log('[单位校准] 日线volume核对: amount/(close*volume)中位比值判定为手(100股/手), 与已确认口径一致')
            else:
                # P3(V2.6.83): 删死字段 vol_unit_confirmed(全文件只写不读, 核对结论已由日志表达)
                log('[风控][告警] 日线volume核对不一致: 探测判定为股(1), 与已确认口径(手)冲突! '
                    '按已确认口径保持 DAILY_VOL_UNIT=%d 不变(改判为1会让成交额与量能口径整体错100倍); '
                    '如确实更换过行情源, 请人工确认后再决定' % DAILY_VOL_UNIT)
                # V2.6.35b(D4修复): 量纲异常是策略静默跑偏的高危场景, 仅写日志量大的时候容易漏看;
                # 升级为状态文件标记 + 每日一次强推送, 确保人工可感知。
                G.state['vol_unit_conflict'] = {'date': G.today, 'DAILY_VOL_UNIT': DAILY_VOL_UNIT}
                if getattr(G, 'vol_unit_conflict_note', '') != G.today:
                    G.vol_unit_conflict_note = G.today
                    try:
                        notify_enqueue('[风控][紧急] 日线成交量口径异常: 探测判定为股(1), 已确认口径为手(100)。'
                                       '量能预估将整体错100倍, 缩量买/放量卖信号全部失真。请核对行情源, '
                                       '若确认已更换数据源请人工修改 DAILY_VOL_UNIT')
                    except Exception:
                        pass
        except Exception as e:
                # P3(V2.6.83): 删死字段 vol_unit_confirmed(全文件只写不读, 核对结论已由日志表达)
            log('[单位校准] 核对异常, 按已确认口径保持 DAILY_VOL_UNIT=%d(手):' % DAILY_VOL_UNIT, repr(e)[:120])
    for s in stocks:
        bars = _bars_to_dict(d1.get(s) if isinstance(d1, dict) else None)
        rows = []
        prev_close = 0.0
        for d in sorted(bars.keys()):
            # 第六轮零预设审计修复(2026-10-04): 过滤未来日期bar, 防止数据源异常时
            # 使用"未来数据"做决策(未来函数会导致回测虚高、实盘亏钱)
            if isinstance(d, str) and G.today and d > G.today:
                continue
            # Q4修复(2026-10-19 第九轮零预设审计): 显式剔除当日未走完的K线 —— 旧版只过滤未来日期,
            #   若数据源在盘中返回当日bar, 会把「今日涨停」当成历史信号(未来函数); 现强制只用已完成交易日
            if isinstance(d, str) and G.today and d == G.today:
                continue
            c = _f((bars[d] or {}).get('close'))
            if c <= 0:
                continue
            v = _f((bars[d] or {}).get('volume'))
            lo = _f((bars[d] or {}).get('low'))
            o_px = _f((bars[d] or {}).get('open'))
            hi_px = _f((bars[d] or {}).get('high'))
            # 非法/填充日不进入量价因子：有限值、成交量和OHLC关系必须成立。
            if v <= 0 or lo <= 0 or o_px <= 0 or hi_px <= 0 or hi_px < lo \
                    or c < lo or c > hi_px or o_px < lo or o_px > hi_px:
                continue
            zt = False
            if prev_close > 0:
                # 重审20261006(P1-A/问题3): 历史ST状态无数据源, _zt_coef 回退当前名称判定,
                # 对"当前ST但历史非ST/当前非ST但历史ST"的股票可能存在误判(以日志醒目标注, 宁漏检不误检)
                limit = _round2(prev_close * _zt_coef(s, d))
                zt = c >= limit - 0.005
            _tv = _f((bars[d] or {}).get('turnover'))
            if _tv <= 0:
                _tv = _f((bars[d] or {}).get('turnover_ratio'))
            if _tv > 1.0:
                # 第六轮零预设审计修复(2026-10-04): 换手率单位归一化 —— 原逻辑对
                # "接口已返回小数形式但值>1.0(如1.5=150%换手率)"的股票误除以100变0.015(错150倍)。
                # 修复: 先按值域判断是百分比还是小数形式 —— 若除以100后仍>1.0说明原本就是小数形式(不除);
                # 若原值>100(如150)且除以100后落在(0,1]区间, 说明原值以百分数给出, 转小数。
                # 新增判定: 原值在(1.0, 100.0] 且除以100后 < 1.0, 属于"小数形式但>1.0"的极端情形,
                # 视为原本已是小数形式(如1.5=150%), 不再误除。
                if _tv >= 100.0:
                    # 明确百分数形式(如150.0=150%): 直接转小数
                    _tv = _tv / 100.0
                elif _tv > 1.0:
                    _tv_tmp = _tv / 100.0
                    if _tv <= 2.0:
                        # 新修复: 原值在(1.0, 2.0] 且除以100后<1.0, 属"小数形式但>1.0"的极端情形
                        # (如1.5=150%换手率), 视为原本已是小数形式, 保持原值
                        pass
                    else:
                        # 正常: 百分比(如5.0=5%)转小数(0.05)存储
                        _tv = _tv_tmp
            rows.append({'date': d, 'close': c, 'open': o_px, 'high': hi_px,
                         'volume': v, 'low': lo, 'zt': zt, 'turnover': _tv})
            prev_close = c
        if len(rows) >= MIN_HISTORY_BARS:
            G.hist[s] = rows
    # V2.6.144: 单独给上证指数注入日线(含成交额字段)到 G.hist,
    #   这样 _sent_fetch_from_cache() 就能拿到三维情绪数据(涨跌广度/涨停比例/成交额)
    #   注意: 不塞进 G.universe, 否则指数会出现在选股候选里产生荒谬信号
    try:
        _idx = _api(G.C.get_market_data_ex, [], [SENT_INDEX_SYMBOL], '1d',
                    '', '', HISTORY_BARS, 'front', True, False)
        _idx_bars = _bars_to_dict(_idx.get(SENT_INDEX_SYMBOL) if isinstance(_idx, dict) else None)
        _idx_rows = []
        _idx_prev_c = 0.0
        for _d in sorted(_idx_bars.keys()):
            if isinstance(_d, str) and G.today and _d >= G.today:
                continue
            _b = _idx_bars.get(_d) or {}
            _c = _f(_b.get('close'))
            if _c <= 0:
                continue
            _idx_rows.append({
                'date': _d, 'close': _c,
                'open': _f(_b.get('open')), 'high': _f(_b.get('high')),
                'low': _f(_b.get('low')), 'volume': _f(_b.get('volume')),
                'zt': False, 'turnover': _f(_b.get('turnover')),
                'amount': _f(_b.get('amount')),
            })
            _idx_prev_c = _c
        if len(_idx_rows) >= MIN_HISTORY_BARS:
            G.hist[SENT_INDEX_SYMBOL] = _idx_rows
            log('[情绪] 上证指数(%s)日线注入 G.hist 成功, %d个交易日(含成交额)'
                % (SENT_INDEX_SYMBOL, len(_idx_rows)))
        else:
            log('[情绪] 上证指数(%s)日线不足MIN_HISTORY_BARS=%d,跳过(情绪退化为两维)'
                % (SENT_INDEX_SYMBOL, MIN_HISTORY_BARS))
    except Exception as _e144b:
        log('[情绪] 上证指数(%s)日线注入失败(情绪退化为两维): %s'
            % (SENT_INDEX_SYMBOL, repr(_e144b)[:120]))

    log('历史数据加载完成, 有效股票数:', len(G.hist),
        '(涨停价=前收盘x系数四舍五入; 除权除息日可能个别误判, 属可接受的近似)')
    flush_st_coef_note()   # V2.6.18: [口径提示] 汇总一条(原为逐票打日志, 启动时刷屏)
    if len(G.hist) < MIN_UNIVERSE_FOR_SCREEN:
        G.data_ready = False
        # P2-9: 残缺股票池必须显式告警 —— 在残缺全市场里做"缩量优选排序"并下单, 排序基准失真
        log('[数据告警] 本地日线数据严重不足(仅%d只, A股常态5000+只, 阈值%d): '
            '选股排序基准不完整, 请在客户端数据管理中批量下载沪深A股日线后重启策略'
            % (len(G.hist), MIN_UNIVERSE_FOR_SCREEN))
    # P2修复(2026-10-02): 环比口径 —— 固定阈值2000有盲区: 本地只下载到3000只(>2000不告警),
    #   但优选排序已在残缺全市场上进行。以"有效历史数/股票池数"做环比体检, 缺失超阈值即告警。
    try:
        _pool = len(getattr(G, 'universe', None) or [])
        if _pool > 0:
            _ratio = len(G.hist) / float(_pool)
            G.data_ready = (len(G.hist) >= MIN_UNIVERSE_FOR_SCREEN and _ratio >= MIN_UNIVERSE_RATIO)
            if _ratio < MIN_UNIVERSE_RATIO:
                log('[数据告警] 日线数据完整性不足: 股票池%d只中仅%d只有效历史(占比%.1f%%, '
                    '阈值%.0f%%), 优选排序基准残缺, 建议补齐日线数据后重启策略'
                    % (_pool, len(G.hist), _ratio * 100.0, MIN_UNIVERSE_RATIO * 100.0))
    except Exception as e:
        log('[警告][load_history] data_ready计算异常: %s' % repr(e)[:200])

# ==================== 避雷风险排查层 ====================
def blacklist_path():
    """黑名单文件路径(带账号隔离后缀): 与状态文件同目录, 仅允许纯文件名, 禁止穿越"""
    stem, ext = _split_name(BLACKLIST_FILE)
    return _join_base(stem + _account_suffix() + ext)

def load_blacklist(force=False):
    """每日加载一次人工风险黑名单, 格式: {"codes": {"600000.SH": "证监会立案"}}
    codes 也可为纯列表。
    P1-7: 读取失败绝不当成"名单为空" —— 文件任何格式瑕疵都不能让黑名单防护静默失效:
    沿用上一次名单兜底, 不置当日刷新标记(下轮自动重试), 并持续节流告警。
    P3-6(2026-10-24 第18轮零预设独立审计): 新增 force=True —— 供发单前"即时复核"使用。
    旧版按日缓存, 盘中用户新写入的条目要等次日选股才生效:
      危害例: 用户10:00得知利空把300001.SZ写进黑名单文件, 而策略09:31选出的候选池里
      已含它 -> 10:05仍以约20万元买入, 该条目要到次日才生效。
    force=True 时忽略当日缓存强制重读文件(读失败仍沿用上次名单兜底, 语义与旧版一致),
    并按 BLACKLIST_RECHECK_SEC 节流, 避免每候选每轮都做文件IO。"""
    if not force and G.blacklist is not None and G.blacklist_date == G.today:
        return G.blacklist
    if force:
        # 节流: 窗口内沿用最近一次读到的名单(缓存命中路径零IO)
        _now_b = time.time()
        if getattr(G, 'blacklist_force_ts', 0.0) \
                and (_now_b - _f(G.blacklist_force_ts)) < BLACKLIST_RECHECK_SEC:
            return G.blacklist if isinstance(G.blacklist, dict) else {}
        G.blacklist_force_ts = _now_b
    bl = {}
    try:
        # 重审20261005(1-3): 黑名单文件是UTF-8(已实证), 不指定编码会按本地GBK读必然失败
        # → 人工黑名单防护静默降级; 读写统一显式 encoding='utf-8'
        with open(blacklist_path(), 'r', encoding='utf-8') as f:
            data = json.load(f)
        codes = data.get('codes', {}) if isinstance(data, dict) else {}
        if isinstance(codes, dict):
            bl = dict((str(k), str(v)) for k, v in codes.items())
        elif isinstance(codes, list):
            bl = dict((str(k), '人工标记') for k in codes)
        if bl:
            log('已加载人工风险黑名单%d只' % len(bl))
        else:
            log('人工风险黑名单为空(文件存在但无条目, 如需人工避雷请按README格式写入): %s' % blacklist_path())
        G.blacklist = bl
        G.blacklist_date = G.today
    except FileNotFoundError:
        # 名单文件不存在=未配置名单, 属正常场景(与"读取失败"区分, 不告警)
        if G.blacklist is None:
            log('人工风险黑名单未配置(文件不存在), 如需人工避雷请创建: %s (实际读取路径带账号后缀, 以本行路径为准)' % blacklist_path())
        G.blacklist = {}
        G.blacklist_date = G.today
    except Exception as e:
        prev = G.blacklist if isinstance(G.blacklist, dict) else {}
        if prev:
            log('[风控][告警] 黑名单读取失败(%s), 沿用上次名单%d只兜底, 稍后自动重试' % (e, len(prev)))
            bl = dict(prev)
        else:
            log('[风控][告警] 黑名单读取失败(%s)且无历史名单可用, 本次选股黑名单防护不可用! '
                '请检查 %s 的JSON格式/编码(文件被占用/BOM/非UTF-8均会失败)' % (e, blacklist_path()))
        if time.time() - _f(G.blacklist_warn_ts) > 300:
            G.blacklist_warn_ts = time.time()
            try:
                pnl_alert('[风控][告警] 人工黑名单读取失败(%s), 请立即检查文件 %s' % (e, blacklist_path()))
            except Exception:
                pass
        # 不置 blacklist_date → 下一轮自动重试
        G.blacklist = bl if bl else prev
    return G.blacklist if isinstance(G.blacklist, dict) else bl

def st_hist_path():
    """历史曾用名含ST清单文件路径(带账号隔离后缀): 与状态文件同目录, 仅允许纯文件名, 禁止穿越"""
    stem, ext = _split_name(ST_HIST_FILE)
    return _join_base(stem + _account_suffix() + ext)

def load_st_hist():
    """每日加载一次历史曾用名含ST清单(曾用名含ST或曾被ST的股票), 格式:
    {"codes": {"600000.SH": "曾用名*STxx"}} 或 {"codes": ["600000.SH", ...]} 或纯列表。
    用户定稿(2026-10-08): 历史ST与当前ST均不入选优选股。
    读取失败绝不当成"清单为空": 沿用上次清单兜底, 不置当日刷新标记(下轮自动重试), 并节流告警。"""
    if G.st_hist is not None and G.st_hist_date == G.today:
        return G.st_hist
    sh = set()
    try:
        # 清单文件是UTF-8(与blacklist同规则), 显式 encoding='utf-8' 读取
        with open(st_hist_path(), 'r', encoding='utf-8') as f:
            data = json.load(f)
        codes = data.get('codes', {}) if isinstance(data, dict) else {}
        if isinstance(codes, dict):
            sh = set(str(k).split('.')[0] for k in codes)
        elif isinstance(codes, list):
            sh = set(str(k).split('.')[0] for k in codes)
        if sh:
            log('已加载历史曾用名含ST清单%d只(历史ST不入优选股)' % len(sh))
        else:
            log('历史ST清单为空(文件存在但无条目, 历史ST过滤不生效, 请检查 %s)' % st_hist_path())
        G.st_hist = sh
        G.st_hist_date = G.today
    except FileNotFoundError:
        # 清单文件不存在=未配置, 属正常场景(与读取失败区分, 不告警)
        if G.st_hist is None:
            log('历史ST清单未配置(文件不存在), 如需启用历史ST剔除请创建: %s (实际读取路径带账号后缀, 以本行路径为准)' % st_hist_path())
            # P3(V2.6.83): 清单缺失 = 历史ST过滤整体不生效, 仅写本地日志极易被忽略;
            #   每次加载失败只推一次(该分支每交易日最多进一次), 补一条手机强提醒。
            try:
                pnl_alert('[风控][提示] 历史ST清单未配置(文件不存在), 历史ST剔除未生效。如需启用请创建: %s'
                          % st_hist_path())
            except Exception:
                pass
        G.st_hist = set()
        G.st_hist_date = G.today
    except Exception as e:
        prev = G.st_hist if isinstance(G.st_hist, set) else set()
        if prev:
            log('[风控][告警] 历史ST清单读取失败(%s), 沿用上次清单%d只兜底, 稍后自动重试' % (e, len(prev)))
            sh = set(prev)
        else:
            log('[风控][告警] 历史ST清单读取失败(%s)且无历史清单可用, 历史ST过滤本轮不可用! '
                '请检查 %s 的JSON格式/编码(文件被占用/BOM/非UTF-8均会失败)' % (e, st_hist_path()))
        if time.time() - _f(G.st_hist_warn_ts) > 300:
            G.st_hist_warn_ts = time.time()
            try:
                pnl_alert('[风控][告警] 历史ST清单读取失败(%s), 请立即检查文件 %s' % (e, st_hist_path()))
            except Exception:
                pass
        # 不置 st_hist_date → 下一轮自动重试
        G.st_hist = sh if sh else prev
    return G.st_hist if isinstance(G.st_hist, set) else set()

def _risk_ex_sig_of(path):
    """V2.6.92新增: 清单文件指纹 (路径, mtime整秒, 字节数); 取不到返回 None。
    用途: "当日已装载"不再等于"当天不再看文件" —— 工具随时可以重跑, 指纹变了就重装。"""
    try:
        _st = os.stat(path)
        return (str(path), int(_st.st_mtime), int(_st.st_size))
    except Exception:
        return None


def _risk_ex_cur_sig():
    """V2.6.92新增: 按 candidates 顺序取第一个存在文件的指纹(与装载顺序保持一致)。"""
    for _c in _risk_exclude_candidates():
        _sg = _risk_ex_sig_of(_c)
        if _sg is not None:
            return _sg
    return None


def risk_exclude_path():
    """V2.6.83: 排雷清单路径(带账号后缀) —— 与状态文件同目录, 仅允许纯文件名, 禁止穿越"""
    stem, ext = _split_name(RISK_EXCLUDE_FILE)
    return _join_base(stem + _account_suffix() + ext)

def _risk_exclude_candidates():
    """优先账号后缀文件, 再回退无后缀主文件(工具默认输出名)"""
    p1 = risk_exclude_path()
    p2 = _join_base(RISK_EXCLUDE_FILE)
    return [p1] if p1 == p2 else [p1, p2]

def _risk_src_err_short(e):
    # V2.6.93(1): 数据源异常压成一行可读文本。旧写法统一取 err 前 40 字符, 于是
    #   RemoteDisconnected('Remote end closed connection without response') 被切成
    #   "RemoteDisconnected('Remote end closed co" —— 引号不闭合, 日志里像乱码, 也看不出
    #   到底是哪类异常(连接被对端关闭 / 超时 / 解析失败)。现在优先取异常类名, 只有拿不到
    #   类名(纯文本报错)时才按 40 字符截断并加 "...", 保证读者一眼能分类。
    try:
        _s = str(e or '').strip()
    except Exception:
        return '失败'
    if not _s:
        return '失败'
    _cls = _s.split('(')[0].strip()
    if _cls and _cls != _s and len(_cls) <= 40:
        return _cls
    if len(_s) > 40:
        return _s[:40] + '...'
    return _s


def load_risk_exclude():
    """V2.6.83新增: 每日装载一次提前排雷清单(本地JSON, 与脚本同目录; 在QMT外部生成)。
    返回 {代码: {'tags': [...], 'reasons': [...]}}。
    容错口径(用户定稿"误报偏紧"): 文件缺失=不阻断(此时仍有 ST/亏损/解禁等实时闸门),
    但必须留痕; 结构损坏或清单过期=仍然使用已解析部分并每日强提醒一次(宁可多排, 不可漏排)。"""
    if not RISK_EXCLUDE_ON:
        return {}
    _prev = G.risk_ex if isinstance(getattr(G, 'risk_ex', None), dict) else {}
    _reload = False      # V2.6.92: 本次是否为"当日清单文件更新后的重载"(失败时保留旧表)
    if not getattr(G, 'risk_ex', None) and \
            (time.time() - _f(getattr(G, 'risk_ex_try_ts', 0.0))) < 60.0:
        return {}      # 清单尚未就绪: 60秒内不重复读盘(避免选股循环高频IO), 到点自动重试
    if G.risk_ex_date == G.today:
        # V2.6.92: 旧版此处直接返回当日缓存 —— 当天重跑工具生成的新清单不会生效, 只能等次日
        #   或重启, 与"生成后自动装载, 无需重启"自相矛盾(实测 23:31 重跑后策略仍读 23:24 那份)。
        #   现比对 (路径, mtime, 大小) 指纹: 变了就当日重载; 指纹比对本身 60 秒节流, 不拖慢选股。
        if time.time() - _f(getattr(G, 'risk_ex_stat_ts', 0.0)) < 60.0:
            return G.risk_ex if isinstance(G.risk_ex, dict) else {}
        G.risk_ex_stat_ts = time.time()
        _cur_sig = _risk_ex_cur_sig()
        if _cur_sig is None or _cur_sig == getattr(G, 'risk_ex_sig', None):
            return G.risk_ex if isinstance(G.risk_ex, dict) else {}
        log('[排雷] 清单文件已更新(%s), 当日重新装载'
            % (os.path.basename(_cur_sig[0]) if _cur_sig[0] else '?'))
        _reload = True
        G.risk_ex_date = ''      # 放行到下方装载流程; 重载失败则由 _prev 兜底
    data, used, err = {}, '', ''
    _found = False     # V2.6.84: 是否找到并成功解析清单文件(用于区分"文件不存在"与"清单为空")
    _src, _src_errs, _wd_decl = {}, [], 0    # V2.6.92: 生成端的数据源健康信息
    for cand in _risk_exclude_candidates():
        try:
            if not os.path.exists(cand):
                continue
            with open(cand, 'r', encoding='utf-8') as f:
                j = json.load(f)
            if not isinstance(j, dict) or not isinstance(j.get('stocks'), dict):
                err = '结构不符(缺 stocks 字典): %s' % os.path.basename(cand)
                continue
            _found = True      # V2.6.84: 文件已成功打开且解析出 stocks 字典(内容可能为空)
            # V2.6.92: 记下生成端写的数据源健康信息(旧版只读 stocks, 这几项被整体忽略)
            _sj = j.get('sources')
            if isinstance(_sj, dict):
                _src = _sj
            _se = j.get('errors')
            if isinstance(_se, list):
                _src_errs = [str(x)[:80] for x in _se[:5]]
            try:
                _wd_decl = int(j.get('window_days') or 0)
            except Exception:
                _wd_decl = 0
            for _k, _v in j['stocks'].items():
                if not isinstance(_v, dict):
                    continue
                _rs = _v.get('reasons')
                _tg = _v.get('tags')
                data[str(_k)] = {
                    'reasons': [str(x) for x in _rs][:6] if isinstance(_rs, list) else [],
                    'tags': [str(x) for x in _tg][:6] if isinstance(_tg, list) else [],
                }
            used = cand
            G.risk_ex_sig = _risk_ex_sig_of(cand)      # V2.6.92: 记账, 供下次指纹比对
            _asof = str(j.get('asof') or '')
            if RISK_EXCLUDE_MAX_AGE_DAYS > 0 and len(_asof) == 8:
                try:
                    _d = datetime.datetime.strptime(_asof, '%Y%m%d').date()
                    _age = (datetime.date.today() - _d).days
                    if _age > RISK_EXCLUDE_MAX_AGE_DAYS:
                        err = '清单已过期%d天(asof=%s)' % (_age, _asof)
                except Exception:
                    pass
            break
        except Exception as e:
            err = '%s(%r)' % (os.path.basename(cand), e)
            continue
    # V2.6.92: 当日重载失败(文件更新后损坏)绝不能用空表覆盖已生效的旧表 —— 否则排雷静默失效
    if _reload and not data and _prev and (err or not _found):
        data = dict(_prev)
        err = (err + '; ' if err else '') + '清单更新后解析失败, 沿用更新前旧表'
    G.risk_ex = data
    if data:
        G.risk_ex_date = G.today      # 只有真正装载到清单才锁定当日
    else:
        # V2.6.83: 装载失败不锁定当日 —— 实盘常见顺序是"先启策略、后跑排雷工具",
        #   旧写法会把当日标记置上, 导致当天工具生成的清单要等次日才生效(空窗一整天)。
        G.risk_ex_date = ''
        G.risk_ex_try_ts = time.time()
    if data:
        _cnt = {}
        for _v in data.values():
            for _t in _v.get('tags', []):
                _cnt[_t] = _cnt.get(_t, 0) + 1
        # V2.6.94(3): st 口径说清 —— st 源失败时这个数字不是"市场ST总数", 而是"公告扫描
        #   窗口内发过公告的ST票"(20页=35只 / 60页=80只, 随 --ann-pages 线性变), 与本地
        #   真名单(zt_shrink_st_coef_note, 实测145只)无关。2026-10-19 两轮日志都只打
        #   st=35 / st=80, 极易被读成"覆盖率达标"。工具侧已加本地清单兜底(同批改动),
        #   兜底成功时这里直接报兜底只数, 兜底失败才提示"仅为公告兜底"。
        _sti = _src.get('st') if isinstance(_src, dict) else None
        _stfb = 0
        if isinstance(_sti, dict):
            try:
                _stfb = int(_sti.get('fallback_n') or 0)
            except Exception:
                _stfb = 0
        _st_tot = _cnt.get('st', 0)     # V2.6.95(5): 清单里 st 标签的实际只数(本地兜底+公告独有)
        _st_ann_only = (_st_tot - _stfb) if _st_tot > _stfb else 0
        if _stfb > 0:
            _st_note = (u' [st类=%d只 = 本地清单兜底%d + 公告简称独有%d(生成端st源失败); '
                        u'本地清单只含名称带ST的票, 不含"退"字票(退市由实时名称闸门拦)]'
                        % (max(_st_tot, _stfb), _stfb, _st_ann_only))
        elif isinstance(_sti, dict) and _sti.get('ok') is False:
            _st_note = (u' [st类仅为公告简称兜底, 数量随--ann-pages波动, '
                        u'不等于市场ST总数, 需重跑工具补全]')
        else:
            _st_note = u''
        _overlap = max(0, sum(_cnt.values()) - len(data))   # V2.6.100(4): 标签重叠只数(一只票命中多标签, 分项之和>清单总数即重叠)
        log('[排雷] 已装载提前排雷清单%d只(%s, 标签重叠%d只) 文件=%s%s'
            % (len(data), ', '.join('%s=%d' % (k, v) for k, v in sorted(_cnt.items())) or '-',
               _overlap, os.path.basename(used) if used else u'(沿用旧表)', _st_note))
        # V2.6.92: 数据源健康 —— 生成端只把失败写进 JSON 的 sources/errors, 策略旧版压根不读,
        #   于是"st 源挂了、st=35 只来自公告简称兜底"在策略日志里完全看不出来, 看着像 ST 全覆盖。
        _bad = [k for k, v in _src.items() if isinstance(v, dict) and v.get('ok') is False]
        if _bad:
            # V2.6.93(1): 两处文案修复。①截断: 旧写法取 err 前 40 字符, 把
            #   RemoteDisconnected 的整句切在半个单词上, 引号还不闭合; 现在走
            #   _risk_src_err_short(优先异常类名)。②重复: 下面 pnl_alert 与本行内容
            #   几乎一致, 而 pnl_alert 也写同一份 run.log —— 2026-10-19 23:44 的日志里
            #   两条告警紧挨着, 像"生成清单失败 + 装载清单失败"两次故障, 实际只有一次。
            _bdet = ', '.join('%s:%s' % (k, _risk_src_err_short((_src.get(k) or {}).get('err')))
                              for k in _bad)
            log('[排雷][告警] 清单生成时%d类数据源失败: %s —— 这些类别覆盖不全, 不等于'
                '"该类无风险"; 请在QMT外部按schema=1重新生成清单' % (len(_bad), _bdet))
            if getattr(G, 'risk_ex_src_warn_date', '') != G.today:
                G.risk_ex_src_warn_date = G.today
                try:
                    pnl_alert('[排雷][告警] 清单生成时%d类数据源失败(%s), 覆盖不全; '
                              '本条是上一行日志的推送副本, 不是第二次故障'
                              % (len(_bad), ','.join(_bad)))
                except Exception:
                    pass
        elif _src_errs:
            log('[排雷][告警] 清单生成端报错: %s' % ('; '.join(_src_errs))[:160])
        _annc = _src.get('ann') if isinstance(_src, dict) else None
        if isinstance(_annc, dict) and _annc.get('cover_from') and _annc.get('cover_to') \
                and _wd_decl > 0:
            try:
                _cfrom = datetime.datetime.strptime(str(_annc['cover_from']), '%Y-%m-%d').date()
                _cto = datetime.datetime.strptime(str(_annc['cover_to']), '%Y-%m-%d').date()
                _cdays = (_cto - _cfrom).days + 1
                if _cdays < _wd_decl:
                    # V2.6.97(4): 旧文案只说“仅7天”, 不给数量级 —— 2026-10-20 00:36 那次
                    #   ann=22 只 / 实扫 7 天, 单看这行很像“ann 类本来就少”,
                    #   实际按同比推算 45 天应有约 141 只, 缺了约 119 只的拦截。
                    _ann_n = _cnt.get('ann', 0)
                    if _ann_n > 0 and _cdays > 0:
                        _ann_est = int(round(float(_ann_n) * _wd_decl / float(_cdays)))
                        _ann_txt = ('ann类%d只; 同比推算%d天满覆盖约%d只, 缺约%d只'
                                    % (_ann_n, _wd_decl, _ann_est,
                                       max(_ann_est - _ann_n, 0)))
                    else:
                        # V2.6.97(4b): ann 类 0 只时同比算式会打出“满覆盖约0只, 缺约0只”,
                        #   读起来像“没有风险”, 实际是“这一类根本没采到”。
                        #   方向必须说清, 否则这条日志比不打还误导。
                        _ann_txt = 'ann类0只(该类可能完全未采到, 不等于无风险)'
                    log('[排雷][提示] 公告实扫仅%d天(%s~%s, 仅覆盖%d天窗口的%.0f%%), %s —— '
                        '立案/处罚/退市风险警示可能漏检, 需加大 --ann-pages'
                        % (_cdays, _annc['cover_from'], _annc['cover_to'], _wd_decl,
                           _cdays * 100.0 / _wd_decl, _ann_txt))
            except Exception:
                pass
        if err:
            log('[排雷][告警] %s —— 仍按现有清单拦截(偏紧), 请在QMT外部更新本地清单文件' % err)
            try:
                pnl_alert('[排雷][告警] %s, 请在QMT外部更新本地清单文件(策略内不抓取外部接口)' % err)
            except Exception:
                pass
    elif err:
        log('[排雷][告警] 排雷清单不可用: %s —— 仍依赖实时闸门(ST/财务亏损/仙股/退潮等)' % err)
        try:
            pnl_alert('[排雷][告警] 排雷清单不可用: %s' % err)
        except Exception:
            pass
    elif _found:
        # V2.6.84: 文件存在但清单为空 —— 旧版误并入"未发现文件"分支, 提示方向跑偏
        if getattr(G, 'risk_ex_note_date', '') != G.today:
            G.risk_ex_note_date = G.today
            log('[排雷][提示] 清单文件存在但内容为空(0只): %s —— 今日无提前排雷拦截对象;'
                ' 若刚更新过清单请确认工具输出是否正常' % os.path.basename(used))
    else:
        # V2.6.84: 旧版说"可选功能"但 RISK_EXCLUDE_ON 实为 True, 会让人以为未启用而不去补清单;
        #   且未说明生成后自动装载(无需重启), 用户会误以为要等次日。改为醒目待办 + 明确生效方式。
        #   每日一次, 避免 60 秒重试装载时反复刷屏(重试本身不变, 清单随时生成仍当轮生效)。
        if getattr(G, 'risk_ex_note_date', '') != G.today:
            G.risk_ex_note_date = G.today
            log('[排雷][待办] 排雷功能已开启(RISK_EXCLUDE_ON=True)但清单文件不存在: %s'
                % ', '.join(os.path.basename(x) for x in _risk_exclude_candidates()))
            log('[排雷][待办] 今日仅依赖实时闸门(ST/财务亏损/仙股/退潮等), 无提前排雷(解禁/减持/立案/预亏)拦截;'
                ' 请在QMT外部按schema=1生成清单并放入脚本同目录 —— 放入后自动装载, 无需重启策略')
    # V2.6.158: 旧版走完这条真正的读盘分支后直接到函数结尾, 没有把读到的内容交回调用方 ——
    #   调用方拿到空值, 一律判"未命中", 于是每个装载周期里第一只被检查的候选必然漏检。
    return data if isinstance(data, dict) else {}
# V2.6.161(第14轮审计-死代码清理): 原 V2.6.146 内嵌的"策略内自动排雷抓取"整块已删除
#   (含 5 个外部抓取函数/聚合类/_http_risk/_suffix_risk/_norm_risk/_iso_risk,
#    以及 _ssl_excl/_uparse_excl/_urequest_excl 三个导入与 _RISK_* 系列常量, 约360行)。
#   删除原因: ① _auto_risk_exclude 自 V2.6.160 起零调用点(纯死代码);
#   ② 其内部经东方财富/新浪的外部 HTTP 抓取, 正是触发 QMT「非法IP」安全拦截强退事故的根因
#      (V2.6.160 已移除调用); 排雷清单改为仅本地 JSON 后, 该块永无恢复必要。
#   ★ 教训: 绝不在策略进程内直接抓取外部行情接口 —— 会触发 QMT IP 安全拦截强退。

def risk_excluded(s):
    """V2.6.83: 查询排雷清单。命中返回原因文本, 未命中返回 ''。
    异常一律按"未命中"处理(排雷是增强项, 不能因清单损坏而误伤全部交易);
    真正的实时风险闸门(risk_blocked/excluded)不受本函数影响。"""
    if not RISK_EXCLUDE_ON:
        return ''
    try:
        d = load_risk_exclude()
        it = d.get(str(s)) if isinstance(d, dict) else None
        if not isinstance(it, dict):
            return ''
        _rs = it.get('reasons') or []
        if _rs:
            return '排雷命中: ' + '/'.join(str(x) for x in _rs[:3])
        _tg = it.get('tags') or []
        if _tg:
            return '排雷命中: ' + ','.join(str(x) for x in _tg[:3])
        return '排雷命中(清单内)'
    except Exception as e:
        log('[排雷][告警] 清单查询异常(按未命中处理): %r' % (e,))
        return ''


def get_recent_net_profit(s):
    """返回最近一期已披露归母净利润记录, 取不到返回None。
    标准: value<0为亏损、=0为盈亏平衡、>0为盈利; 单位统一为元。
    时间范围: 报告期<=策略日的最新一期季报/中报/年报, 不读取未来报告期。
    字段: QMT Profit.np/net_profit/NET_PROFIT / QMT内置接口 C.get_financial_data /
          聚宽 indicator.net_profit。
    返回: {'value': 数值, 'report_date': YYYYMMDD或'未知', 'field': 字段名, 'source': 数据源}。"""
    try:
        code = s.split('.')[0]
        today = G.today or datetime.datetime.now().strftime('%Y%m%d')
        _errs = []           # 2026-10-08 v2: 记录各层取数失败原因(限频日志)
        def _date_field(r, keys):
            for k in keys:
                if r.get(k):
                    v = str(r[k]).replace('-', '')[:8]
                    if len(v) == 8 and v.isdigit():
                        return v
            return ''
        def _report_date(r):
            return _date_field(r, ('report_date', 'report_time', 'm_time', 'time'))
        def _announce_date(r):
            return _date_field(r, ('declareDate', 'declare_date', 'announce_date', 'pub_date'))
        # ===== 优先: QMT 内置策略接口 (2026-10-08 v2, 按迅投文档修正) =====
        # v1(09:35) 误用 xtdata 表名签名 C.get_financial_data(['Profit'],[code]):
        # 缺 startDate/endDate 必填、'Profit' 非合法 fieldList -> TypeError 被吞 -> 财务全缺失候选0。
        # 文档(thinktrader 股票数据-获取单季度/年度财务数据):
        #   用法1  get_financial_data(fieldList, stockList, startDate, endDate,
        #                             report_type='announce_time')
        #   原始   get_raw_financial_data(fieldList, stockList, startDate, endDate,
        #                             report_type='announce_time')  # 不填充交易日, 天然已披露序列
        #   fieldList 如 ['ASHAREINCOME.net_profit_excl_min_int_inc'](归母净利润),
        #   stockList 需带市场后缀(如 '600000.SH')。
        try:
            C = getattr(G, 'C', None)
            if C is not None:
                _fin_alias = ['ASHAREINCOME.net_profit_excl_min_int_inc',
                              '利润表.归母净利润', '利润表.净利润']
                # 首选: get_raw_financial_data(原始公告序列, 不填充交易日)
                if hasattr(C, 'get_raw_financial_data'):
                    try:
                        cfd = _api(C.get_raw_financial_data, _fin_alias, [s], '20000101', today,
                                                             report_type='announce_time')
                        rows = _extract_fin_rows(cfd, s, None) or _extract_fin_rows(cfd, code, None)
                        if rows:
                            _r = _pick_latest_fin_row(rows, _report_date, _announce_date, today)
                            if _r and _r.get('value') is not None:
                                return {'value': float(_r['value']),
                                        'report_date': _r['report_date'],
                                        'announce_date': _r['announce_date'],
                                        'field': _r['field'],
                                        'source': 'QMT内置 C.get_raw_financial_data'}
                    except Exception as _e:
                        _errs.append('get_raw_financial_data: %s' % _e)
                # 次选: get_financial_data 用法1(按交易日填充)
                if hasattr(C, 'get_financial_data'):
                    try:
                        cfd = _api(C.get_financial_data, _fin_alias, [s], '20000101', today,
                                                         report_type='announce_time')
                        rows = _extract_fin_rows(cfd, s, None) or _extract_fin_rows(cfd, code, None)
                        if rows:
                            _r = _pick_latest_fin_row(rows, _report_date, _announce_date, today)
                            if _r and _r.get('value') is not None:
                                return {'value': float(_r['value']),
                                        'report_date': _r['report_date'],
                                        'announce_date': _r['announce_date'],
                                        'field': _r['field'],
                                        'source': 'QMT内置 C.get_financial_data(用法1)'}
                    except Exception as _e:
                        _errs.append('get_financial_data用法1: %s' % _e)
                # 兜底: get_financial_data 用法2(单值; 需 barpos)
                try:
                    if hasattr(C, 'get_financial_data') and hasattr(C, 'barpos'):
                        _mkt = 'SH' if s.endswith(('.SH', '.XSHG')) else 'SZ'
                        for _args in (
                            ('ASHAREINCOME', 'net_profit_excl_min_int_inc', _mkt, code,
                             'announce_time', C.barpos),
                            ('ASHAREINCOME', 'net_profit_excl_min_int_inc', _mkt, code, C.barpos),
                        ):
                            try:
                                _v = _api(C.get_financial_data, *_args)
                                if isinstance(_v, (int, float)) and _v == _v:
                                    return {'value': float(_v), 'report_date': '未知',
                                            'announce_date': today,
                                            'field': 'get_financial_data(用法2)',
                                            'source': 'QMT内置 C.get_financial_data(用法2)'}
                            except Exception:
                                continue
                    else:
                        _errs.append('get_financial_data用法2: 无barpos不可用')
                except Exception as _e:
                    _errs.append('get_financial_data用法2: %s' % _e)
            else:
                _errs.append('G.C 为 None')
        except Exception as _e:
            _errs.append('C接口: %s' % _e)
        # X2(2026-10-17 V2.6.62): 删除 xtdata 财务兜底分支(用户铁律: 禁用xtquant/xtdata函数);
        #   财务数据仅保留: 内置C接口主通道(上方) + jqdata聚宽同步通道(下方)
        try:
            from jqdata import get_fundamentals, query, indicator
            q = query(indicator).filter(indicator.code == code)
            df = get_fundamentals(q, date=today)
            if df is not None and not df.empty and 'net_profit' in df.columns:
                row = df.iloc[-1]
                report_date = '未知'
                for field in ('statDate', 'stat_date', 'report_date'):
                    if field in df.columns and row[field] is not None:
                        report_date = str(row[field]).replace('-', '')[:8]
                        break
                return {'value': float(row['net_profit']), 'report_date': report_date,
                        'field': 'indicator.net_profit', 'source': 'JoinQuant indicator'}
        except ImportError:
            _errs.append('jqdata: ImportError')
        except Exception as _e:
            _errs.append('jqdata: %s' % _e)
    except Exception as _e:
        _errs.append('get_recent_net_profit: %s' % _e)
    # 2026-10-08 v2: 三层全失败时限频打印根因(每60秒最多1条, 避免选股循环刷屏)
    if _errs:
        _now = time.time()
        if getattr(G, '_fin_diag_ts', 0) + 60 < _now:
            G._fin_diag_ts = _now
            log('[财务数据] %s 三层取数均失败: %s' % (s, ' | '.join(_errs[-4:])))
    return None


def _float_market_cap_yi(stock):
    """V2.6.81零预设审计修复: 只按【流通市值】口径取数, 不再用总股本冒充流通市值。
    依据迅投官方文档: 流通股本标准字段名为 FloatVolume, 【部分低等级客户端中为 FloatVolumn(少一个e)】,
    故 CirculatingVolume / FloatVolume / FloatVolumn 三种拼写全部尝试, 不猜客户端等级。
    取价顺序: LastPrice -> Price -> PreClose -> _last_close_of(G.hist)。
    三种拼写均取不到流通股本时返回 None, 由调用方按 MARKET_CAP_DEGRADE 降级放行(不误剔)。
    缓存 MARKET_CAP_CACHE_SEC 秒, 降低接口压力。只在 MARKET_CAP_FILTER_ON 开启时才调用。"""
    try:
        _cache = getattr(G, '_mcap_cache', None)
        if not isinstance(_cache, dict):
            _cache = {}
            G._mcap_cache = _cache
        now = time.time()
        # V2.6.81: 记录【实际命中的字段名】(取代 V2.6.35 笼统的circ/total 计数),
        #   启动日志可直接看出某券商客户端用的是哪种拼写, 不用猜。
        _src = getattr(G, '_mcap_src', None)
        if not isinstance(_src, dict) or 'hits' not in _src:
            _src = {'hits': {}, 'none': 0}
            G._mcap_src = _src

        def _mcap_bump(_key):
            if _key == 'none':
                _src['none'] = int(_src.get('none', 0) or 0) + 1
            else:
                _h = _src.setdefault('hits', {})
                _h[_key] = int(_h.get(_key, 0) or 0) + 1

        hit = _cache.get(stock)
        if isinstance(hit, dict) and (now - float(hit.get('ts', 0))) < MARKET_CAP_CACHE_SEC:
            _mcap_bump(str(hit.get('src', 'none')))
            return hit.get('v')
        val = None
        _which = 'none'
        C = getattr(G, 'C', None)
        # 方案1(唯一口径): get_instrument_detail 流通股本 x 当日价 = 流通市值
        try:
            if C is not None and hasattr(C, 'get_instrument_detail'):
                det = _api(C.get_instrument_detail, stock) or {}
                # V2.6.81: 流通股本三种拼写全试 —— CirculatingVolume(旧版兼容)/
                #   FloatVolume(迅投标准字段)/FloatVolumn(官方注明的"部分低等级客户端"拼写, 少一个e)
                _sh = 0.0
                _hit_fld = ''
                for _fld in ('CirculatingVolume', 'FloatVolume', 'FloatVolumn'):
                    _v = _f(det.get(_fld) or 0)
                    if _v > 0:
                        _sh = _v
                        _hit_fld = _fld
                        break
                if _sh > 0:
                    # V2.6.81: 取价补 PreClose(官方字段); LastPrice/Price 非官方字段, 实际恒取不到
                    _px = _f(det.get('LastPrice') or det.get('Price') or det.get('PreClose') or 0)
                    if _px <= 0:
                        _px = _last_close_of(stock)
                    if _px > 0:
                        val = _sh * _px / 1e8
                        _which = _hit_fld
        except Exception:
            pass
        # V2.6.81: 原"方案2 总股本兜底"已整段删除(用户确认方案A) ——
        #   总股本含限售股(大股东/定增/股权激励), 算出的总市值系统性高于流通市值,
        #   使"按流通市值30~150亿筛选"名不副实: 流通市值合适但总股本庞大的中小盘会被误剔
        #   (例: 总股本100亿股/流通30亿股/股价5元 -> 流通市值150亿刚好保留, 总市值500亿却被剔除)。
        #   现拿不到流通股本即返回 None, 由调用方按 MARKET_CAP_DEGRADE 降级放行。
        _cache[stock] = {'v': val, 'ts': now, 'src': _which}
        _mcap_bump(_which)
        return val
    except Exception:
        return None


def _last_close_of(stock):
    """取股票最后一日收盘价(从 G.hist 缓存中读), 失败返回 0"""
    try:
        rows = (G.hist or {}).get(stock)
        if rows and rows[-1]:
            return _f(rows[-1].get('close'))
    except Exception:
        pass
    return 0.0


def _float_share(stock):
    """V2.6.88: 取流通股本(股) —— 供换手率自算使用。
    动机: QMT get_market_data_ex 日线不返回 turnover/turnover_ratio 列, load_history 里取到的
      换手率恒为 0, 使 ZT_TURNOVER_MIN=0.05 / ZT_TURNOVER_MAX=0.20 自上线起从未生效
      (20261019 实盘: 121 只进入换手率判定, 121 只全部"字段缺失"), 一字板与过热出货全被放行。
    算法: 换手率(小数) = 成交量(手) x DAILY_VOL_UNIT(股/手) / 流通股本(股)。
    字段拼写与 _float_market_cap_yi 一致(CirculatingVolume / FloatVolume / FloatVolumn),
      不猜客户端等级。
    缓存 1 小时(流通股本日内不变); 取不到返回 0, 调用方按"缺失放行"处理, 绝不误杀。"""
    try:
        _c = getattr(G, '_fshare_cache', None)
        if not isinstance(_c, dict):
            _c = {}
            G._fshare_cache = _c
        _now = time.time()
        _hit = _c.get(stock)
        if isinstance(_hit, tuple) and len(_hit) == 2 and (_now - _f(_hit[0])) < 3600.0:
            return _f(_hit[1])
        _sh = 0.0
        _C = getattr(G, 'C', None)
        if _C is not None and hasattr(_C, 'get_instrument_detail'):
            _det = _api(_C.get_instrument_detail, stock) or {}
            if isinstance(_det, dict):
                for _fld in ('CirculatingVolume', 'FloatVolume', 'FloatVolumn'):
                    _v = _f(_det.get(_fld) or 0)
                    if _v > 0:
                        _sh = _v
                        break
        _c[stock] = (_now, _sh)
        return _sh
    except Exception as _e:
        # V2.6.89: 原来裸 except 直接 return 0.0, 于是"接口抛异常"和"这只票确实没有流通股本字段"
        #   在日志上完全一样(都是 0 -> 走"缺失放行"), 排查时只能靠猜 ——
        #   与 V2.6.87 的 _f 遮蔽、V2.6.88 的心跳静默属同一类"异常被吞"的坑。节流 30 分钟提示一次。
        try:
            if (time.time() - _f(getattr(G, '_fshare_err_ts', 0) or 0)) >= 1800:
                G._fshare_err_ts = time.time()
                log('[提示] 流通股本取数异常(该票换手率退化为"缺失放行", 不误杀也不过滤): %s'
                    % _exc_text(_e))
        except Exception:
            pass
        return 0.0


def get_recent_net_profit_cached(s):
    """P1-3修复(20261008): 当日内存缓存 —— risk_blocked 与 screen_candidates 对同一票
    各查一次财务(全市场5000+只接口调用翻倍, 拖慢选股)。缓存仅当日有效, 次日自动失效。"""
    _c = getattr(G, '_fin_cache', None)
    if not isinstance(_c, dict):
        _c = {}
        G._fin_cache = _c
    _k = (s, G.today)
    if _k in _c:
        return _c[_k]
    v = get_recent_net_profit(s)
    _c[_k] = v
    return v


def _ts_to_date(t):
    """QMT 财务时间(毫秒/秒时间戳或 YYYYMMDD 字符串) -> YYYYMMDD; 失败返回''。"""
    try:
        if isinstance(t, str) and t.strip().isdigit():
            t = int(t.strip())
        if isinstance(t, (int, float)) and not isinstance(t, bool):
            # V2.6.158: 八位整数形态(19000101~29991231)本身就是年月日, 不是 1970 年起的秒数。
            #   旧版一律按秒换算, 20260930 会被解成 1970 年 8 月 23 日, 报告期被判严重滞后,
            #   财务数据被整批过滤掉且日志只写过滤正常。
            if 19000101 <= t <= 29991231 and float(t) == int(t):
                return str(int(t))
            ts = t / 1000.0 if t > 10 ** 12 else float(t)   # 毫秒 vs 秒
            d = datetime.datetime.fromtimestamp(ts).strftime('%Y%m%d')
            return d if len(d) == 8 and d.isdigit() else ''
        v = str(t).replace('-', '')[:8]
        return v if len(v) == 8 and v.isdigit() else ''
    except Exception:
        return ''


def _fin_short(k):
    """字段名短化: 'ASHAREINCOME.net_profit_excl_min_int_inc' -> 'net_profit_excl_min_int_inc'"""
    k = str(k)
    return k.split('.')[-1] if '.' in k else k


def _extract_fin_rows(cfd, code, table):
    """把 C.get_financial_data / get_raw_financial_data 返回结构统一解析为行 dict 列表。
    get_raw_financial_data: {stock: {field: {毫秒时间戳: 值}}} -> 行含 time/m_time(公告或报告期);
    get_financial_data 用法1: dict{stock:{table:DataFrame}} / DataFrame(时间索引,字段列) /
    Series / Panel 等; 统一做字段短名规整供 _pick_latest_fin_row 容错。"""
    if cfd is None:
        return []
    rows = []
    try:
        if isinstance(cfd, dict):
            node = cfd.get(code)
            if node is None and len(cfd) == 1:
                node = list(cfd.values())[0]
            # raw 接口形态: {stock: {field: {ts: value}}}
            if isinstance(node, dict) and node and all(isinstance(v, dict) for v in node.values()):
                _by_time = {}
                for _f, _tv in node.items():
                    if not isinstance(_tv, dict):
                        continue
                    _short = _fin_short(_f).lower()
                    for _t, _v in _tv.items():
                        if isinstance(_v, (dict, list, tuple)) or _v is None:
                            continue
                        try:
                            _fv = float(_v)
                        except Exception:
                            continue
                        if _fv != _fv:      # NaN
                            continue
                        _d = _ts_to_date(_t)
                        if not _d:
                            continue
                        _row = _by_time.setdefault(_d, {'time': _d, 'm_time': _d, 'announce_date': _d})
                        _row[_short] = _fv
                        _row['field'] = _short
                rows = list(_by_time.values())
                if rows:
                    return rows
            # 普通形态: dict{stock:{table:DataFrame}} 等
            if isinstance(node, dict):
                node = node.get(table, node)
            if isinstance(node, dict):
                for k in ('data', 'Data', 'rows', 'list'):
                    if isinstance(node.get(k), (list, tuple)):
                        rows = [r for r in node[k] if isinstance(r, dict)]
                        break
                if not rows:
                    try:
                        records = node.to_dict('records') if hasattr(node, 'to_dict') else []
                        rows = [r for r in records if isinstance(r, dict)]
                    except Exception:
                        rows = []
            elif hasattr(node, 'to_dict'):
                try:
                    rows = [r for r in node.to_dict('records') if isinstance(r, dict)]
                except Exception:
                    rows = []
        elif hasattr(cfd, 'to_dict'):
            try:
                rec = cfd.to_dict('records')
                if isinstance(rec, list):
                    rows = [r for r in rec if isinstance(r, dict)]
            except Exception:
                rows = []
    except Exception:
        rows = []
    # 字段短名规整: 带表名前缀的列 -> 去掉前缀, 供 _pick_latest_fin_row 容错
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        nr = dict(r)
        for k, v in list(nr.items()):
            if '.' in str(k):
                nr.setdefault(_fin_short(k), v)
        out.append(nr)
    return out


def _pick_latest_fin_row(rows, _report_date, _announce_date, today):
    """从财务行 dict 列表中选最近一期已披露记录, 提取归母净利润。
    归母净利润字段按 QMT 多版本容错: Income.net_profit_excl_min_int_inc /
    Profit.np / net_profit / NET_PROFIT。"""
    visible = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        rd = _report_date(r)
        ad = _announce_date(r)
        # 第六轮零预设审计修复(2026-10-04): 除公告日期(ad)校验外, 补一层报告期(rd)校验,
        # 防止数据源异常时返回未来报告期的财报数据(未来函数)
        # P3(V2.6.83): 单侧日期缺失容错 —— 旧版要求报告期与公告日同时存在, 任一为空时整条
        #   记录被丢弃(数据源只给其中一个字段), 明明有净利润却判"取不到"-> 亏损过滤失效。
        #   现用另一侧兜底, 两侧都缺才跳过; 未来日期仍严格禁止(防未来函数)。
        _rd_c = rd or ad
        _ad_c = ad or rd
        if _rd_c and _ad_c and _rd_c <= today and _ad_c <= today:
            visible.append((_rd_c, _ad_c, r))
    if not visible:
        return None
    rd, ad, best = max(visible, key=lambda x: (x[0], x[1]))
    for field in ('net_profit_excl_min_int_inc', 'np', 'net_profit', 'NET_PROFIT'):
        if best.get(field) is not None:
            try:
                return {'value': float(best[field]), 'report_date': rd,
                        'announce_date': ad, 'field': field}
            except Exception:
                continue
    return None


def _download_qmt_financial_data(stocks):
    """2026-10-08 P1修复: 某券商QMT内置Python无xtdata, 改为C接口直取验证式补数。
    对候选逐票调用 get_recent_net_profit (raw->用法1->用法2 三层C接口) 验证取数可达,
    覆盖率达标即视为数据可用, 返回(success, detail)。"""
    if not RISK_LOSS_AUTO_DOWNLOAD:
        return False, '自动下载开关已关闭'
    codes = [str(s).split('.')[0] for s in (stocks or []) if s]
    if not codes:
        return False, '无票可验证'
    sample = list(codes)[:300]
    ok = 0
    failed = []
    # 第六轮零预设审计修复(2026-10-04): 增加时间预算 —— 全市场逐票C接口直取可能长时间
    # 占用轮询线程, 阻塞成交回报回调(买卖时机被延迟)。每轮处理最多 FIN_TIME_BUDGET_SEC 秒,
    # 超时即让出线程, 下一轮继续处理剩余股票(数据完整性不受影响, 只是分次取数)。
    _fin_deadline = time.time() + float(getattr(G, '_fin_time_budget_sec', 5.0) or 5.0)
    for i, s in enumerate(sample, 1):
        # 时间预算检查: 每处理20只检查一次(避免每只都调time.time()微开销)
        if i % 20 == 0 and time.time() > _fin_deadline:
            log('[财务数据] 时间预算已到(本批%d/%d只), 让出线程, 剩余下轮继续' % (i - 1, len(sample)))
            break
        try:
            if get_recent_net_profit_cached(s) is not None:
                ok += 1
            else:
                failed.append(s)
        except Exception:
            failed.append(s)
        if i % 50 == 0:
            log('[财务数据] C接口直取验证进度 %d/%d, 成功%d只' % (i, len(sample), ok))
    min_ok = max(1, int(math.ceil(len(sample) * 0.8)))
    if ok >= min_ok:
        return True, 'C接口直取验证通过 %d/%d只(纯内置接口)' % (ok, len(sample))
    tail = ', '.join(failed[:3]) if failed else '全部失败'
    return False, 'C接口取数覆盖不足 %d/%d(<%d), 失败示例: %s' % (ok, len(sample), min_ok, tail)
def _probe_financial_data(stocks):
    return sum(1 for s in (stocks or []) if get_recent_net_profit_cached(s) is not None)

def ensure_financial_data(stocks):
    """筛选前探测财务数据；全缺失时自动下载，并以重新读取结果确认是否恢复。"""
    probe = list(stocks or [])[:max(0, int(RISK_LOSS_PROBE_N))]
    if not probe:
        return True, '无探测样本'
    got = _probe_financial_data(probe)
    min_ok = max(1, int(math.ceil(len(probe) * 0.8)))
    if got >= min_ok:
        return True, '首次探测%d/%d只有数据(覆盖达标)' % (got, len(probe))
    log('[财务数据] 抽样%d只均缺失，正在自动下载Profit表并复检...' % len(probe))
    started, detail = _download_qmt_financial_data(list(stocks or []))
    if started:
        log('[财务数据] 已触发自动下载: %s' % detail)
        got = _probe_financial_data(probe)
        if got >= min_ok:
            log('[财务数据] 自动下载成功，复检%d/%d只有数据，覆盖率达标' % (got, len(probe)))
            return True, '自动下载后复检成功%d/%d' % (got, len(probe))
        return False, '已调用%s，但复检仍为0/%d（可能下载失败、尚未落盘或无字段权限）' % (detail, len(probe))
    return False, '无法启动自动下载: %s' % detail

def _mark_loss_degraded():
    """2026-10-08用户确认: 财务数据缺失时的退桥方案标记。
    在 risk_blocked 中被命中(财务数据无法获取且 RISK_LOSS_MISSING_DEGRADE=True)时调用,
    每个交易日最多推送一条强提醒，提醒当前处于降级模式（缺失股不为跨行为。"""
    try:
        if getattr(G, 'loss_degrade_date', '') != G.today:
            G.loss_degrade_date = G.today
            trigger_log('财务数据降级放行', '选股',
                        '财务数据无法获取，已启用降级放行（缺失股不为跨剔除），请尽快补数',
                        mode=TRADE_MODE)
            log('【降级模式】财务数据缺失，跳过缺失股的跨剔除但无法匹配利润负股风险，'
                '请尽快在 QMT、客户端财务数据中下载 Profit 表（本日仅提醒一次）')
    except Exception:
        pass


def _mark_mcap_degraded(n_degrade=0, n_checked=0):
    """审计P1-2修复(第十四轮, 2026-10-19): 流通市值降级放行占比过高时每日一条强提醒。
    与 _mark_loss_degraded 同规格(每日守卫+trigger_log); 只提醒不改筛选行为
    (MARKET_CAP_DEGRADE=True 仍放行不误剔), 提醒运维尽快排查数据源。"""
    try:
        if getattr(G, 'mcap_degrade_date', '') != G.today:
            G.mcap_degrade_date = G.today
            _pct = (n_degrade * 100.0 / n_checked) if n_checked > 0 else 0.0
            trigger_log('流通市值筛选降级过半', '选股',
                        '本轮%d只候选中%d只取不到流通股本被降级放行(占比%.0f%%), '
                        '市值筛选名义开启实则大半失效, 请检查 get_instrument_detail '
                        '字段拼写(CirculatingVolume/FloatVolume/FloatVolumn)与数据权限'
                        % (int(n_checked), int(n_degrade), _pct),
                        mode=TRADE_MODE)
            log('【降级模式】流通市值筛选: %d/%d只取不到流通股本已降级放行(占比%.0f%%), '
                '30~150亿筛选大半失效, 请尽快检查数据源(本日仅提醒一次)'
                % (int(n_degrade), int(n_checked), _pct))
    except Exception:
        pass


def _fin_unknown_rd():
    """P2-11修复(2026-10-19): 业绩报告期未知→保守剔除的每日守卫+计数(与
    _mark_mcap_degraded 同一模式: 每日首次 trigger_log 强提示, 后续仅计数不刷屏)"""
    try:
        if getattr(G, 'fin_unknown_rd_date', '') != G.today:
            G.fin_unknown_rd_date = G.today
            G.fin_unknown_rd_n = 0
        G.fin_unknown_rd_n = int(getattr(G, 'fin_unknown_rd_n', 0) or 0) + 1
        if G.fin_unknown_rd_n == 1:
            trigger_log('业绩报告期未知-保守剔除', '选股',
                        '数据源只返回净利润数值、未返回报告期(无法验证15个月时效), '
                        '按保守规则剔除(与业绩数据缺失=剔除同家风); 若批量出现, '
                        '请检查 QMT 财务接口字段是否变更',
                        mode=TRADE_MODE)
            log('保守剔除: 业绩报告报告期未知(无法做15个月时效校验), 当日首次已强提示, 后续仅计数')
    except Exception:
        pass


def risk_blocked(s, comp):
    """避雷排查: 返回风险原因(空串=通过)。
    自动规则覆盖QMT内置框架可取到的信号; 财报/公告/质押类靠人工核查后写入黑名单"""
    if not RISK_CHECK_ON:
        return ''
    name = inst_name(s)
    # 审计P1-1: 名称取数失败=身份不明, 与选股层 excluded() 同口径保守剔除
    if not (name and str(name).strip()):
        return '名称取数失败(身份不明,按保守规则剔除)'
    if '退' in name:
        return '名称含退(退市/退市整理期风险)'
    if is_st_name(name):          # 重审20261006(P3-B/问题10): 改用公共函数统一口径(startswith/前3字符口径已废弃)
        return 'ST/*ST(连续亏损/退市风险警示)'
    bl = load_blacklist()
    if s in bl:
        return '人工黑名单(%s)' % bl[s]
    if len(comp) >= 2:
        if RISK_MIN_PRICE > 0 and comp[-1]['close'] < RISK_MIN_PRICE:
            return '收盘%.2f低于%.1f元(仙股/面值退市风险)' % (comp[-1]['close'], RISK_MIN_PRICE)
        if RISK_MAX_DROP_7D < 1:
            recent = comp[-7:]
            if len(recent) >= 2 and recent[0]['close'] > 0:
                drop = 1.0 - recent[-1]['close'] / recent[0]['close']
                if drop > RISK_MAX_DROP_7D:
                    return '近%d日累计跌%.1f%%超%.0f%%(疑似爆雷出逃)' % (
                        len(recent), drop * 100, RISK_MAX_DROP_7D * 100)
        # 严重亏损过滤1: 近3个交易日累计跌幅超阈值
        if RISK_MAX_DROP_3D < 1:
            recent3 = comp[-3:]
            if len(recent3) >= 2 and recent3[0]['close'] > 0:
                drop3 = 1.0 - recent3[-1]['close'] / recent3[0]['close']
                if drop3 > RISK_MAX_DROP_3D:
                    return '近3日累计跌%.1f%%超%.0f%%(短期急跌, 疑似业绩暴雷)' % (
                        drop3 * 100, RISK_MAX_DROP_3D * 100)
        # 严重亏损过滤2: 近5个交易日累计跌幅超阈值
        if RISK_MAX_DROP_5D < 1:
            recent5 = comp[-5:]
            if len(recent5) >= 2 and recent5[0]['close'] > 0:
                drop5 = 1.0 - recent5[-1]['close'] / recent5[0]['close']
                if drop5 > RISK_MAX_DROP_5D:
                    return '近5日累计跌%.1f%%超%.0f%%(中期弱势, 疑似业绩承压)' % (
                        drop5 * 100, RISK_MAX_DROP_5D * 100)
        # 严重亏损过滤3: 财报净利润亏损或数据缺失均剔除(保守口径)
        # (旧"跌破250日均线"过滤已删除: HISTORY_BARS<=15时条件恒假, 属假开关 —— P1-16)
    if RISK_LOSS_CHECK:
        try:
            profit = get_recent_net_profit_cached(s)
            if profit is None:
                # 2026-10-08用户确认: 财务数据缺失时的退桥方案
                #   False=保守剔除(缺失即剔除, 保持原行为);
                #   True=降级放行(跳过跨剔除但每日一次强提醒, 避免筛选空转)
                if RISK_LOSS_MISSING_DEGRADE:
                    _mark_loss_degraded()
                    return ''
                return ('归母净利润数据缺失或查询异常 | 报告期=未知 | 字段=net_profit_excl_min_int_inc | 数值=未知 | '
                        '数据源=QMT Profit/JoinQuant indicator | 按保守规则剔除')
            # P2-10修复(2026-10-17): 报告期时效校验 —— 最新可见报告期距当前超过15个月
            # (如现在10月, 最新报告期还是去年Q1)说明财务数据源严重滞后/停更, 按"数据缺失"
            # 保守剔除; 旧版只判数值不管时效, 1月发上年年报与数据源停更两种情形混在一起
            _td10 = str(G.today or '')
            _ny = int(_td10[:4]) if _td10[:4].isdigit() else 0
            _nm = int(_td10[4:6]) if _td10[4:6].isdigit() else 0
            _rd10 = str(profit.get('report_date', '') or '')
            _rd_ok = bool(_rd10[:4].isdigit() and _rd10[4:6].isdigit())
            if _ny > 0 and _nm > 0 and not _rd_ok:
                # P2-11修复(2026-10-19): 报告期未知=保守剔除。原逻辑只在 report_date
                # 为8位数字时才做15个月时效校验, 而 get_financial_data 用法2(barpos 取值)
                # 与 jqdata 兜底分支会返回 report_date=未知, 陈旧校验被静默跳过——一份
                # 可能是年前的旧报告会被当成有效数据放行; 遵循本文件"取数未知=保守剔除"
                # 的一贯家风(与 RISK_LOSS_MISSING_DEGRADE=False 同思路), 未知报告期
                # 一律剔除并计数告警(每日首次强提示, 后续仅计数不刷屏)
                _fin_unknown_rd()
                return ('最新一期业绩报告报告期未知(数据源仅返回值未返回报告期, 无法验证15个月时效) | '
                        '字段=%s | 取值=%.2f万元 | 数据源=%s | 按保守规则剔除'
                        % (profit.get('field', ''), profit.get('value', 0.0) / 10000.0,
                           profit.get('source', '')))
            if _ny > 0 and _nm > 0 and _rd_ok:
                _months10 = (_ny * 12 + _nm) - (int(_rd10[:4]) * 12 + int(_rd10[4:6]))
                if _months10 > 15:
                    return ('最近一期归母净利润报告期严重滞后 | 报告期=%s(距今约%d个月) | '
                            '数据源=%s | 按保守规则剔除' % (_rd10, _months10, profit.get('source', '')))
            if profit['value'] < 0:
                return ('最近一期归母净利润<0 | 报告期=%s | 字段=%s | 数值=%.2f万元 | 数据源=%s'
                        % (profit['report_date'], profit['field'], profit['value'] / 10000.0,
                           profit['source']))
        except Exception as e:
            log('[财务数据][强提醒] %s 查询/解析异常: %s，按保守规则剔除' % (disp(s), e))
            return '归母净利润查询异常 | 按保守规则剔除'
    return ''

# ==================== 趋势结构过滤(方案A一期: 10日线不破) ====================
def ma10_held_after_zt(comp, p):
    """方案A一期: 涨停后回调期间不跌破10日均线(趋势结构完好, 主力未出逃)。
    comp: 该股已完成日线列表(每条含date/close/low/zt); p: 涨停日T0在comp中的索引。
    返回: ''=通过(全程未跌破); 非空=剔除原因。
    检查范围: T0+MA10_HOLD_FROM 到 comp末尾(最近已完成交易日)的每个交易日,
    当日MA10 = 此前10日(含当日)收盘均价, 当日基准(收盘或最低)须不低于MA10。"""
    if not MA10_HOLD_ON:
        return ''
    if len(comp) < MA10_MIN_BARS:
        return ''    # 数据不足不误判(交由其他规则处理)
    start = p + MA10_HOLD_FROM
    if start < 1:
        start = 1
    for i in range(start, len(comp)):
        if i < 9:    # MA10需索引0..i共10根, i>=9才够
            continue
        ma10 = sum(comp[j]['close'] for j in range(i - 9, i + 1)) / 10.0
        if ma10 <= 0:
            continue
        if MA10_HOLD_BENCH == 'low':
            bench = comp[i].get('low', 0.0) or comp[i]['close']
        else:
            bench = comp[i]['close']
        if bench < ma10:
            return 'T0+%d日(%s)%s%.2f跌破MA10=%.2f(趋势结构破位)' % (
                i - p, comp[i]['date'], '最低' if MA10_HOLD_BENCH == 'low' else '收盘', bench, ma10)
    return ''

# ==================== 战法借鉴增强(判定函数) ====================
def zt_low_held(comp, p):
    """战法借鉴①(缩倍阴锁仓/三阴洗盘公共内核): 涨停后回调期间任一已完成交易日
    最低价跌破涨停日最低价 -> 返回剔除原因; 全程不破返回''(纯收紧选股, 不改买点)。"""
    if not ZT_LOW_HOLD_ON:
        return ''
    t0_low = _f(comp[p].get('low', 0.0))
    if t0_low <= 0:
        return ''                       # 涨停日低点缺失(老数据)不误杀
    for i in range(p + 1, len(comp)):
        lo = _f(comp[i].get('low', 0.0))
        if lo > 0 and lo < t0_low:
            return 'T0+%d日(%s)最低%.2f跌破涨停日低点%.2f(回调不破涨停低点过滤)' % (
                i - p, comp[i]['date'], lo, t0_low)
    return ''

def ma5_of_comp(comp):
    """最近5根已完成收盘均线(不足5根或含无效价返回0)"""
    if len(comp) < 5:
        return 0.0
    closes = [_f(comp[j].get('close', 0.0)) for j in range(len(comp) - 5, len(comp))]
    if min(closes) <= 0:
        return 0.0
    return sum(closes) / 5.0

def detect_confirm_entry(comp, p):
    """战法借鉴②(缩倍阴锁仓): 在已完成K线中从最近往回找"缩倍量阴线"(阴线量<=前一日量x
    CONFIRM_YIN_VOL_RATIO), 且 ①其后尚无收盘突破阴线高点(信号未消耗) ②仍在
    CONFIRM_BREAK_MAX_DAYS窗口内。命中返回 {yin_high, yin_vol, yin_date}, 否则None。
    盘中触发(放量中阳突破阴线高点)在 run_round 买入循环判定。"""
    if not CONFIRM_ENTRY_ON or p + 1 >= len(comp):
        return None
    L = len(comp) - 1
    for i in range(L, p, -1):
        b = comp[i]
        o_px, c_px = _f(b.get('open', 0.0)), _f(b.get('close', 0.0))
        hi = _f(b.get('high', 0.0))
        prev_v = _f(comp[i - 1].get('volume', 0.0)) if i >= 1 else 0.0
        if o_px <= 0 or c_px <= 0 or hi <= 0 or c_px >= o_px:
            continue                    # 数据缺失或非阴线
        if prev_v > 0 and _f(b.get('volume', 0.0)) > prev_v * CONFIRM_YIN_VOL_RATIO:
            continue                    # 量未缩到倍量标准
        if L - i >= CONFIRM_BREAK_MAX_DAYS:
            break                       # P3(V2.6.83): i 递减 => L-i 单调增, 超窗后再往前必然更超, 直接结束
        if any(_f(comp[j].get('close', 0.0)) > hi for j in range(i + 1, L + 1)):
            continue                    # 其后已有收盘突破 -> 信号已消耗
        return {'yin_high': hi, 'yin_vol': _f(b.get('volume', 0.0)), 'yin_date': b['date']}
    return None

def detect_ma5_break(comp, p, base_vol):
    """战法借鉴③(五日线战法): T0后存在"缩量跌破5日线"(破位日量<=基准量x
    MA5_RECLAIM_SHRINK_RATIO), 且破位后每日收盘仍在5日线下方(未收复)、破位距今
    未超MA5_RECLAIM_MAX_DAYS(短暂破位) -> True。盘中触发(放量涨停收复5日线)在
    run_round 买入循环判定。"""
    if not MA5_RECLAIM_ON or p + 1 >= len(comp):
        return False
    L = len(comp) - 1
    for i in range(L, p, -1):
        ma5_i = ma5_of_comp(comp[:i + 1])
        b = comp[i]
        if ma5_i <= 0 or _f(b.get('close', 0.0)) >= ma5_i:
            continue                    # 未破位
        if base_vol > 0 and _f(b.get('volume', 0.0)) > base_vol * MA5_RECLAIM_SHRINK_RATIO:
            continue                    # 破位但未缩量(放量破位是出货, 不适用)
        if L - i >= MA5_RECLAIM_MAX_DAYS:
            break                       # P3(V2.6.83): 同上, 破位过久后续必然更久, 省掉无意义遍历
        if all(_f(comp[j].get('close', 0.0)) < ma5_of_comp(comp[:j + 1])
               for j in range(i + 1, L + 1)):
            return True                 # 其后未收复: 今日涨停即首日收复
    return False

# ==================== 热门板块过滤(方案A一期: 仅买当日热门板块) ====================
def _norm_code(s):
    """归一化股票代码为前6位代码(去交易所后缀), 便于跨平台板块成分股匹配"""
    return (s or '').split('.')[0]

def _fetch_sector_members():
    """取板块列表+板块成分(跨平台: 聚宽 jqdata / QMT内置C接口板块列表)
    返回: {板块名: [成分股代码...]}, 空值=取数失败。"""
    sector_members = {}
    if not sector_members:
        try:
            from jqdata import get_industries, get_industry_stocks
            inds = get_industries(name='sw_l1')    # 申万一级行业
            if inds:
                for code, info in inds.items():
                    try:
                        members = get_industry_stocks(code) or []
                        if members:
                            nm = getattr(info, 'name', None) or code
                            sector_members[nm] = list(members)
                    except Exception:
                        continue
        except ImportError:
            pass
        except Exception as e:
            log('热门板块: 聚宽行业接口异常:', e)
    if not sector_members:
        try:
            if hasattr(G.C, 'get_sector_list'):
                sl = _api(G.C.get_sector_list)
                for name in (sl or []):
                    try:
                        members = _api(G.C.get_stock_list_in_sector, name) or []
                        if members:
                            sector_members[name] = list(members)
                    except Exception:
                        continue
        except Exception as e:
            log('热门板块: 板块列表接口异常:', e)
    return sector_members

def _autofix_sector_data():
    """接口失败时重取板块数据再取数(避免客户端未下载板块数据的凌晨卡死)
    X3(2026-10-17 V2.6.62): 删除 xtdata.download_sector_data 刷新体(用户铁律: 禁用xtquant函数);
       某券商QMT内置客户端无板块数据刷新接口, 降级为直接重试一次, 仍失败按原逻辑走。
    返回 sector_members(None=autofix也失败)"""
    log('热门板块autofix: 内置客户端无板块数据刷新接口, 直接重试取数')
    return _fetch_sector_members()

def load_hot_sectors():
    """方案A一期: 加载当日热门板块集合到 G.hot_sectors / G.hot_stock_set。
    口径: 最近已完成交易日涨停股数量TopN的板块, 且涨停数>=HOT_SECTOR_ZT_MIN。
    接口失败时: 先 autofix(下载板块数据+重试), 仍失败按 HOT_SECTOR_FAIL_HARD 处理。"""
    if not HOT_SECTOR_ON:
        G.hot_sectors_ok = True     # 关闭即视为"通过"(不过滤)
        return
    if G.hot_sectors_date == G.today and G.hot_sectors is not None:
        return    # 当日已加载, 命中缓存(含空dict=当日无热门/已autofix失败, 不重复)
    G.hot_sectors = None
    G.hot_stock_set = None
    G.hot_sectors_ok = False
    # 1) 取最近已完成交易日的涨停股集合(归一化代码, 跨平台匹配)
    zt_stocks = set()
    ref_date = ''
    for s, rows in G.hist.items():
        if not rows:
            continue
        comp = rows[:-1] if rows[-1]['date'] == G.today else rows
        if not comp:
            continue
        last = comp[-1]
        if last.get('zt') and last.get('close', 0) > 0:
            zt_stocks.add(_norm_code(s))
            ref_date = last['date']
    if not zt_stocks:
        log('热门板块: 最近已完成交易日无涨停股, 热门集合为空(当日所有股票按非热门处理)')
        G.hot_sectors = {}          # 空dict触发节流(当日不重复加载)
        G.hot_stock_set = set()
        G.hot_sectors_ok = True     # 接口正常, 只是结果为空
        G.hot_sectors_date = G.today
        return
    # 2) 取板块列表+成分股(首次尝试)
    sector_members = _fetch_sector_members()
    # 2b) 首次取数失败 -> autofix: 告警 + 下载板块数据 + 重试
    if not sector_members and HOT_SECTOR_AUTOFIX_ON_FAIL:
        log('热门板块告警: 板块接口首次取数失败(券商版本/数据未下载), 触发autofix(下载板块数据+重试)')
        sector_members = _autofix_sector_data()
    if not sector_members:
        # autofix后仍失败: 按HOT_SECTOR_FAIL_HARD处理(默认降级放过, 绝不整天不出手)
        log('热门板块告警: autofix后仍无法获取板块数据。按 HOT_SECTOR_FAIL_HARD=%s 处理'
            % ('硬拒绝(当日不买非热门)' if HOT_SECTOR_FAIL_HARD else '降级放过(不误杀好票, 不整天不出手)'))
        G.hot_sectors = {}          # 空dict触发节流(当日不重复autofix, 次日再试)
        G.hot_stock_set = set()
        if HOT_SECTOR_FAIL_HARD:
            G.hot_sectors_ok = False   # 硬模式: 选股时非热门即拒
        else:
            G.hot_sectors_ok = False   # 降级: 选股时见ok=False即放过
        G.hot_sectors_date = G.today
        return
    # 3) 统计每个板块的涨停股数量(归一化代码后取交集)
    sector_zt = {}
    for name, members in sector_members.items():
        cnt = sum(1 for m in members if _norm_code(m) in zt_stocks)
        if cnt > 0:
            sector_zt[name] = cnt
    if not sector_zt:
        log('热门板块: 板块成分股与涨停股无交集(板块口径不匹配), 降级放过')
        G.hot_sectors = {}
        G.hot_stock_set = set()
        G.hot_sectors_ok = False
        G.hot_sectors_date = G.today
        return
    # 4) 取涨停数TopN且>=HOT_SECTOR_ZT_MIN
    ranked = sorted(sector_zt.items(), key=lambda kv: kv[1], reverse=True)
    top = ranked[:HOT_SECTOR_TOPN]
    hot = dict((n, c) for n, c in top if c >= HOT_SECTOR_ZT_MIN)
    if not hot:
        log('热门板块: Top%d板块涨停数均不足%d, 无热门板块, 降级放过'
            % (HOT_SECTOR_TOPN, HOT_SECTOR_ZT_MIN))
        G.hot_sectors = {}
        G.hot_stock_set = set()
        G.hot_sectors_ok = False
        G.hot_sectors_date = G.today
        return
    # 5) 合并热门板块成分股为反查集合(归一化代码)
    stock_set = set()
    for n in hot:
        for m in sector_members.get(n, []):
            stock_set.add(_norm_code(m))
    G.hot_sectors = hot
    G.hot_stock_set = stock_set
    G.hot_sectors_ok = True
    G.hot_sectors_date = G.today
    log('热门板块加载完成(基准日=%s 涨停股%d只): 热门%d板块 -> 成分股%d只: %s'
        % (ref_date, len(zt_stocks), len(hot), len(stock_set),
           '; '.join('%s(%d)' % (n, c) for n, c in list(hot.items())[:8])))

def stock_in_hot_sector(s):
    """方案A一期: 判断股票是否属于当日热门板块。返回: ''=通过; 非空=剔除原因。"""
    if not HOT_SECTOR_ON:
        return ''
    if not G.hot_sectors_ok:
        # 接口失败: 降级放过; 硬模式(空集)下非热门即拒
        if HOT_SECTOR_FAIL_HARD and G.hot_stock_set is not None:
            if _norm_code(s) not in G.hot_stock_set:
                return '非当日热门板块(接口失败硬模式, 当日拒绝买入)'
        return ''
    if G.hot_stock_set is None:
        return ''    # 未加载放过(load_hot_sectors应在选股前调用)
    if _norm_code(s) not in G.hot_stock_set:
        return '非当日热门板块(热门%d板块, 成分股%d只)' % (
            len(G.hot_sectors or {}), len(G.hot_stock_set))
    return ''

# ==================== 选股层(规则1+规则2窗口) ====================
def financial_data_recheck():
    """P2-7修复(2026-10-02): 财务数据自动下载后的跨轮次复检。
    旧版在同一次调用里"下载->立即复检", 而QMT下载是异步落盘, 复检必然为0, 导致当天永久
    判为"财务数据不可用"(候选被保守剔除, 且需等次日重筛)。现改为登记待复检时间戳,
    由轮询线程按 RISK_LOSS_RECHECK_SEC 间隔复检, 恢复后自动重新筛选并补推"已恢复"。"""
    ts = _f(getattr(G, 'loss_pending_ts', 0.0))
    if ts <= 0 or bool(getattr(G, 'loss_data_ok', True)):
        return
    if time.time() - ts < RISK_LOSS_RECHECK_SEC:
        return
    G.loss_pending_ts = 0.0
    try:
        _probe = list((getattr(G, 'hist', None) or {}).keys())[:int(RISK_LOSS_PROBE_N)]
        if not _probe:
            return
        _ok, _detail = ensure_financial_data(list((G.hist or {}).keys()))
        if _ok:
            G.loss_data_ok = True
            log('[财务数据] 跨轮次复检通过: %s, 已恢复亏损过滤并重新筛选候选' % _detail)
            loss_data_source_alert(True)
            try:
                screen_candidates()
                G.last_status_sig = None      # 强制刷新一条状态快照(候选集已变化)
            except Exception:
                log('[财务数据] 恢复后重新筛选异常, 下轮重试')
                traceback.print_exc()
        else:
            G.loss_pending_ts = time.time()
            log('[财务数据] 跨轮次复检仍未就绪: %s (每%d秒重试)' % (_detail, RISK_LOSS_RECHECK_SEC))
    except Exception:
        G.loss_pending_ts = time.time()
        traceback.print_exc()

def _sync_sector():
    """V2.6.175: 同步策略关注股票到交易端专属板块(本地板块, 不走券商柜台)。
    板块内容 = 当日候选 并 当前持仓, 整表替换(reset)避免历史候选无限累积, 持仓不丢。
    调用时机: screen_candidates 末尾(交易日/非交易日预选/rescreen 三路径均经此)。"""
    try:
        if 'create_sector' not in globals() or 'reset_sector_stock_list' not in globals():
            return   # 非QMT运行环境(本地编译/冒烟)无全局函数, 安全跳过
        _sector = '涨停缩量策略'
        try:
            create_sector('', _sector, True)   # True=已存在则跳过, 复用同名板块(避免数字后缀漂移)
        except Exception:
            pass
        _seen = set(); _codes = []
        for _c in (G.candidates or []):
            if not isinstance(_c, dict):
                continue
            _sc = _c.get('stock')
            if _sc and _sc not in _seen:
                _seen.add(_sc); _codes.append(_sc)
        for _s in ((G.state or {}).get('hold') or {}).keys():
            if _s and _s not in _seen:
                _seen.add(_s); _codes.append(_s)
        reset_sector_stock_list(_sector, _codes)
        log('[板块同步] 已同步 %d 只到专属板块[%s](候选%d+持仓%d)' % (
            len(_codes), _sector, len(G.candidates or []), len(G.state.get('hold') or {})))
    except Exception:
        log('[板块同步] 异常(忽略):')
        traceback.print_exc()


def _add_to_sector(code):
    """V2.6.175: 买入成交即时加单只到专属板块(盘中可见); 重复添加幂等。"""
    try:
        if 'add_stock_to_sector' not in globals():
            return
        add_stock_to_sector('涨停缩量策略', code)
    except Exception:
        pass


def screen_candidates(ref_day=''):
    """筛出: 近7个交易日恰好1个涨停(多个涨停剔除, 且该涨停日放量),
    今日处于涨停后第3~7天、基准量已形成的候选"""
    # 构建纪律(重审20261005修正注释与代码一致): 本函数与买卖决策段同在策略线程串行执行,
    #   无并发读者 —— 先整表置空([]), 再 append 逐个填充, 排序后整表截断替换,
    #   过程中读者只能看到 旧表/空表/新表 三种状态。
    #   若未来改为并发构建(与持锁轮询并行), 必须改成局部列表一次性整体替换(防"半构建"中间态)。
    # V2.6.171: ref_day 非空=非交易日预选的参考交易日(日历中<=今天的最后交易日);
    #   为空=交易日正常选股(用 G.today), 与旧版行为逐字节等价。
    _ref = ref_day or G.today
    G.candidates = []
    blocked = []
    loss_excluded = []
    loss_checked = []
    loss_missing_codes = []   # 20261008: 财务数据不完整(缺失/查询异常)股票, 供带序号清单与末尾汇总
    dedup = []
    mcap_excluded = []          # V2.6.22: 市值过滤剔除清单
    st_mcap_low = st_mcap_high = st_mcap_miss = st_mcap_degrade = 0   # V2.6.22: 市值过滤统计; degrade=V2.6.81取不到流通股本而降级放行只数

    if MARKET_CAP_FILTER_ON:

        G._mcap_src = {'hits': {}, 'none': 0}   # V2.6.81: 本轮实际命中的流通股本字段名计数(供日志核对)
    # P1-4修复(2026-10-02): 选股在锁【外】执行(含全市场遍历/名称缓存/财务探测等重IO),
    #   旧版直接读 G.state['hold']/['done'] —— 与 deal_callback/order_callback 并发改写时
    #   可能触发"dictionary changed size during iteration"使选股中断(候选残缺), 或读到中途值。
    #   此处一次性快照, 循环内判定只用快照(其余 .get() 读取为原子操作, 不需快照)。
    with G.state_lock:
        hold = dict(G.state.get('hold') or {})
        _done_snap = dict(G.state.get('done') or {})
    # 漏斗统计: 记录各条件实际剔除数量(纯观测, 不参与任何交易判断)
    # st_vol_t0 = T0涨停日未放量(量<前5日均量x1.2); st_vol_base = T0+1基准量日未达T0量x0.5
    st_held = st_nozt = st_multi = st_zt_month = st_done = st_win = st_vol_t0 = st_vol_base = st_turnover = st_excl = st_sthist = st_ma10 = st_hot = st_lowhold = 0
    st_namefail = st_turnover_missing = st_turnover_calc = 0   # 审计P1-1/P1-2: 名称取数失败保守剔除数 / 换手率字段缺失数(不再静默跳过) / V2.6.88 换手率自算成功只数
    st_turn_lo = st_turn_hi = 0   # V2.6.89: 换手率不符拆两向(低于下限=一字板/流动性不足, 高于上限=过热出货) —— 只给总数看不出闸门卡在哪一侧, 调阈值时无从下手
    # V2.6.94(1): 拆解"板块或名称排除" —— 旧版这一个计数混装 ST/板块/排雷清单三种原因,
    #   导致"提前排雷清单到底拦了几只"从 V2.6.83 上线起无法从日志看出(2026-10-19 两轮
    #   实盘都只能靠猜, 且我先误判成"命中0")。以下四个计数器之和恒等于 st_excl。
    st_excl_risk = st_excl_st = st_excl_board = st_excl_oth = 0
    risk_ex_hits = []   # V2.6.94(2): 排雷命中明细(纯日志, 不进账目/不参与筛选)
    st_rise = 0                       # V2.6.181: 价格位置护栏剔除计数(仅优选阶段末尾不复权精筛-2%)

    # V2.6.35零预设审计: 原 st_skip 一个计数器混装5种'数据不足'原因, 现拆成具名计数(仅日志口径, 不参与筛选)

    st_short = st_t0cal = st_nobase = st_base0 = st_amt = st_susp = 0

    st_risk = st_dedup = 0
    st_loss_missing = 0     # 因财务数据缺失被保守剔除的候选数
    # 财务数据保障：首次探测全缺失时自动下载Profit表并复检；失败后强提醒且仍保守剔除。
    G.loss_data_ok = True
    if RISK_LOSS_CHECK and RISK_LOSS_PROBE_N > 0:
        _probe = list(G.hist.keys())[:int(RISK_LOSS_PROBE_N)]
        try:
            if _probe:
                G.loss_data_ok, _finance_detail = ensure_financial_data(list(G.hist.keys()))
                if not G.loss_data_ok:
                    log('[数据告警][强提醒] 财务数据自动下载/复检失败: %s | '
                        '数据源=QMT Profit | 缺失=报告期/归母净利润字段 | '
                        '结果影响=缺失股票按保守规则剔除，不进入候选。请补数后重新筛选。' % _finance_detail)
                    loss_data_source_alert(False, len(_probe), _finance_detail)
                    G.loss_pending_ts = time.time()   # P2-7修复: 登记待复检, 由轮询线程跨轮次复检
                else:
                    loss_data_source_alert(True)
        except Exception as e:
            G.loss_data_ok = False
            _finance_detail = '财务数据保障流程异常:%s' % e
            log('[数据告警][强提醒] %s | 结果影响=缺失股票按保守规则剔除，不进入候选。' % _finance_detail)
            loss_data_source_alert(False, len(_probe), _finance_detail)
    if _ref not in G.calendar:
        return
    t_idx = G.calendar.index(_ref)
    for s, rows in G.hist.items():
        if s in hold:
            st_held += 1
            continue
        dates = [r['date'] for r in rows]
        # 剔除当日未走完的K线, 只用已完成交易日判断涨停
        # V2.6.180: 原条件 dates[-1] == _ref 在非交易日预选下误切参考日K线 ——
        #   prescreen_offday 传的 _ref 是最近已完成交易日(如周五), 该日K线已完结,
        #   并非当日未走完, 原条件却仍命中 -> comp[-1] 退化为前一交易日,
        #   涨停天数判断/昨收基准/粗筛pullback 全部基于过期数据;
        #   改为 dates[-1] == G.today(与 load_hot_sectors 内既有写法一致):
        #   仅数据末bar就是今天(盘中未走完)才切, 非交易日整表保留, 交易日行为不变。
        comp = rows[:-1] if dates[-1] == G.today else rows
        if len(comp) < 2:
            st_short += 1
            continue
        recent = comp[-LOOKBACK_TRDAYS:]
        # 统计近N个已完成交易日的涨停天数: 要求恰好1个, 无涨停或多个涨停都剔除
        limit_days = [r for r in recent if r['zt']]
        if not limit_days:
            st_nozt += 1
            continue
        if ONLY_SINGLE_ZT and len(limit_days) != 1:
            st_multi += 1
            continue
        # 规则1.1 V2.6.182: 月内涨停过滤 —— 近MONTHLY_SPAN(默认22)交易日涨停数> MONTHLY_ZT_MAX(默认1) → 剔除
        #   语义: 只抓"第一次涨停"后的第一波回调, 老妖股第二波/第三波(月内多涨停)拦下; 复用 comp 数组, 零API成本
        if MONTHLY_ZT_MAX >= 0 and len(comp) > LOOKBACK_TRDAYS:
            _month_end = max(0, len(comp) - MONTHLY_SPAN)
            _month_zt = [r for r in comp[_month_end:] if r['zt']]
            if len(_month_zt) > MONTHLY_ZT_MAX:
                st_zt_month += 1
                continue
        t0row = limit_days[-1]
        if _done_snap.get(s) == t0row['date']:
            st_done += 1
            continue    # 本轮涨停周期已做过, 防重复进出
        if t0row['date'] not in G.calendar:
            st_t0cal += 1
            continue
        offset = t_idx - G.calendar.index(t0row['date'])
        if offset < BUY_WINDOW_START or offset > BUY_WINDOW_END:
            st_win += 1
            continue    # 不在第3~7天窗口内
        p = dates.index(t0row['date'])
        if p + 1 >= len(comp):
            st_nobase += 1
            continue    # 涨停次日基准量尚未形成
        # 放量涨停校验: T0当日量能须达到此前5日均量的ZT_VOL_RATIO_MIN倍。
        # 缩量涨停/一字板往往无资金实质介入, 回踩容易直接破位(设0关闭)
        if ZT_VOL_RATIO_MIN > 0:
            pre = comp[max(0, p - 5):p]
            if len(pre) >= 3:
                avg_v = sum(x['volume'] for x in pre) / float(len(pre))
                if avg_v > 0 and t0row['volume'] < avg_v * ZT_VOL_RATIO_MIN:
                    st_vol_t0 += 1
                    continue
        base = comp[p + 1]
        if base['volume'] <= 0:
            st_base0 += 1
            continue
        # 审计修复1: T0+1基准量日须达到T0量的BASE_VOL_RATIO_MIN倍, 防止极端缩量日作为基准
        # 导致缩量买入阈值过低(易误买)和放量卖出阈值过低(易早卖)
        if BASE_VOL_RATIO_MIN > 0 and t0row['volume'] > 0:
            if base['volume'] < t0row['volume'] * BASE_VOL_RATIO_MIN:
                st_vol_base += 1
                continue
        # 审计修复P2-5: 基准量日成交额下限(0=不限制), 过滤流动性不足标的(成交额=收盘价x量)
        # 换手率过滤(涨停日): 5%-20%为合理, 剔除一字板(<5%)和过热(>20%)
        _to = 0.0   # V2.6.89: 先兜底 —— 下方"候选 dict 带上涨停日换手率"要读它,
        #   闸门两个阈值都为 0(关闭)时原代码不会给 _to 赋值, 直接引用会 NameError 打断整轮选股
        if ZT_TURNOVER_MIN > 0 or ZT_TURNOVER_MAX > 0:
            # 重审20261005(P2-5/P2-6): load_history 已做百分数→小数归一, 此处不重复再除;
            # 删除无写入点的死标记 turnover_api_unavailable(换手率取不到=0, 由 _to>0 放行不误杀)
            _to = _f(t0row.get('turnover'))
            if _to <= 0:
                # V2.6.88(2026-10-19 实盘日志取证): QMT get_market_data_ex 的日线结果里
                #   根本没有 turnover / turnover_ratio 两列, load_history 写进去的恒为 0 ->
                #   旧版走到了下面"缺失即放行"分支, ZT_TURNOVER_MIN=0.05 / MAX=0.20 自上线起
                #   一次都没生效过(实测: 121 只进入换手率判定, 121 只全部"字段缺失",
                #   换手率不符恒为 0; 一字板与过热出货全被放行进候选)。
                #   现改按流通股本自算: 换手率 = 成交量(手) x 每股股数 / 流通股本(股)。
                #   口径说明: 流通股本取"当前"值, 历史增发/解禁会带偏差, 属可接受近似
                #   (只用于区间过滤, 不参与估值; 偏差远小于不做过滤的后果)。
                _sh_t = _float_share(s)
                _v_t0 = _f(t0row.get('volume'))
                if _sh_t > 0 and _v_t0 > 0:
                    _to = _v_t0 * float(DAILY_VOL_UNIT) / _sh_t
                    if _to > 0:
                        st_turnover_calc += 1
            if _to > 0:
                if ZT_TURNOVER_MIN > 0 and _to < ZT_TURNOVER_MIN:
                    st_turn_lo += 1
                    st_turnover += 1
                    continue
                if ZT_TURNOVER_MAX > 0 and _to > ZT_TURNOVER_MAX:
                    st_turn_hi += 1
                    st_turnover += 1
                    continue
            else:
                # 审计P1-2: 换手率字段缺失不再静默跳过整条过滤(旧逻辑全市场悄悄
                # 失效且漏斗无计数, 运维看到"过滤正常"假象); 计入缺失数并在汇总明示
                # V2.6.88: 只有"接口没给 + 自算也拿不到流通股本"才落到这里(放行不误杀)
                st_turnover_missing += 1
        # 重审20261006(P1-C/问题5)+20261008零预设审计定稿: 流动性过滤单位口径 ——
        # 某券商QMT行情技术口径=手(100): 探测失败时 DAILY_VOL_UNIT 已兜底为100(手),
        # 成交额按"手"口径(真实成交额)。旧"降为股(1)"逻辑会把成交额低估100倍,
        # 1000万流动性过滤误杀正常票(买入被不恰当堵塞), 已废除; 此处仅做非法值防御。
        _unit_flt = DAILY_VOL_UNIT
        if int(_unit_flt or 1) not in (1, 100):
            # 非法值防御: 兜底按手(100)
            _unit_flt = 100
        _amt_base = _f(base.get('close', 0)) * base['volume'] * _unit_flt
        _last_row = comp[-1] if isinstance(comp, list) and comp else None
        _amt_last = (_f(_last_row.get('close', 0)) * _f(_last_row.get('volume', 0)) * _unit_flt) \
                    if (_last_row and _last_row.get('volume')) else _amt_base
        _amt_flt = min(_amt_base, _amt_last) if _amt_last > 0 else _amt_base
        if MIN_DAILY_AMOUNT > 0 and _amt_flt < MIN_DAILY_AMOUNT:
            st_amt += 1
            continue
        _exr = excluded(s)
        if _exr:
            # V2.6.94(1): 按 excluded() 的返回原因分类计数, 四项之和恒等于 st_excl
            if _exr.startswith('名称取数失败'):
                st_namefail += 1
            elif _exr.startswith('排雷命中'):
                st_excl_risk += 1
                if len(risk_ex_hits) < 40:      # 上限40条, 防清单异常时日志爆量
                    risk_ex_hits.append('%s | %s | %s' % (s, inst_name(s), _exr))
            elif _exr == 'ST':
                st_excl_st += 1
            elif _exr in ('KCB', 'CYB'):
                st_excl_board += 1
            else:
                st_excl_oth += 1                # 未预期原因单独计数, 绝不并入其它档
            st_excl += 1
            continue
        # 用户定稿(2026-10-08): 历史曾用名含ST/曾被ST的股票也不入选优选股
        # (当前ST由上方excluded按当前名称剔除; 本处按本地清单剔除历史ST, 单点覆盖所有候选入口)
        if EXCLUDE_ST_HIST and (s.split('.')[0] in load_st_hist()):
            st_sthist += 1
            continue
        rb = risk_blocked(s, comp)
        if rb:
            st_risk += 1

            row = '%s | %s | %s' % (s, inst_name(s), rb)
            blocked.append(row)
            if rb.startswith('最近一期归母净利润<0'):
                loss_excluded.append(row)
            elif rb.startswith('归母净利润数据缺失') or rb.startswith('归母净利润查询异常'):
                loss_excluded.append(row)
                st_loss_missing += 1     # P1修复: 单独计数(20261008起含查询异常), 供口径日志与数据源健康判断
                loss_missing_codes.append(s)   # 20261008: 记录财务数据不完整股票
            continue
        if RISK_LOSS_CHECK:
            profit = get_recent_net_profit_cached(s)
            if profit is not None:
                # V2.6.70: 展示用公告日期(数据源返回的report_date实为披露日), 口径语义更准
                _ad4 = profit.get('announce_date') or profit.get('report_date') or '未知'
                loss_checked.append('%s | %s | %s | %s=%.2f万元 | 保留' %
                                    (s, inst_name(s), _ad4, profit['field'],
                                     profit['value'] / 10000.0))
        # 方案A一期: 涨停后回调不破10日线(趋势结构过滤)
        ma10 = ma10_held_after_zt(comp, p)
        if ma10:
            blocked.append('%s %s: %s' % (s, inst_name(s), ma10))
            st_ma10 += 1
            continue
        # 战法借鉴①: 回调不破涨停日最低点(公共内核, 纯收紧)
        lh = zt_low_held(comp, p)
        if lh:
            blocked.append('%s %s: %s' % (s, inst_name(s), lh))
            st_lowhold += 1
            continue
        # 方案A一期: 仅买当日热门板块内股票
        hs = stock_in_hot_sector(s)
        if hs:
            blocked.append('%s %s: %s' % (s, inst_name(s), hs))
            st_hot += 1
            continue
        db = rebuy_blocked(s, t0row['date'])
        if db:
            st_dedup += 1

            dedup.append('%s %s: %s' % (s, inst_name(s), db))
            continue
        # V2.6.22(2026-10-12): 市值过滤 —— 默认关闭, 开启后按流通市值区间剔除
        if MARKET_CAP_FILTER_ON:
            _mcap = _float_market_cap_yi(s)
            if _mcap is None:
                if MARKET_CAP_DEGRADE:
                    st_mcap_degrade += 1
                    log('[市值过滤][降级] %s %s 取不到流通股本, 降级放行(不误剔)' %
                        (s, inst_name(s)))
                else:
                    st_mcap_miss += 1
                    continue
            elif _mcap < MARKET_CAP_MIN_YI:
                st_mcap_low += 1
                mcap_excluded.append('%s %s | 流通市值%.1f亿 < 下限%.1f亿' %
                                     (s, inst_name(s), _mcap, MARKET_CAP_MIN_YI))
                continue
            elif _mcap > MARKET_CAP_MAX_YI:
                st_mcap_high += 1
                mcap_excluded.append('%s %s | 流通市值%.1f亿 > 上限%.1f亿' %
                                     (s, inst_name(s), _mcap, MARKET_CAP_MAX_YI))
                continue
        yst = comp[-1]    # 昨日(最近已完成交易日), 用于候选优选排序
        # 审计修复2: 停牌日(量=0)过滤 —— 停牌会被误判为"极度缩量", 导致shrink_rank=0而优先入选
        if yst['volume'] <= 0:
            st_susp += 1
            continue
        G.candidates.append({'stock': s, 'name': inst_name(s), 't0': t0row['date'],
                             'turn_t0': _to,   # V2.6.89: 涨停日换手率(小数, 0=字段缺失已放行) —— 供优选项日志审计, 不参与任何买卖判定
                             'base_vol': base['volume'], 'zt_close': t0row['close'],
                             'offset': offset, 'last_vol': yst['volume'],
                             'last_close': yst['close'],
                             'confirm': detect_confirm_entry(comp, p),
                             'ma5_break': detect_ma5_break(comp, p, base['volume']),
                             'ma5': ma5_of_comp(comp)})
    # P3-9(2026-10-24 第18轮零预设独立审计): 补取"不复权"收盘价, 供回撤/追高比价使用。
    #   背景: comp 来自 dividend_type='front'(前复权) 序列, zt_close/last_close 都是复权价;
    #   而买入循环里比较的对象 lp 是实时真实价。区间内若无除权除息, 前复权最新一根锚定
    #   真实价, 两者一致; 但若 T0(3~7个交易日前)到今日之间发生分红送股, 前复权 zt_close
    #   被下调而 lp 不调 -> 回撤/追高算错。
    #   危害例: T0真实涨停收10.00, 期间10派5(复权因子≈0.95) -> 前复权zt_close=9.50;
    #   今日真实价9.60, 判定"回撤+1.05%"(在追高检查3%内放行), 而相对真实T0价实际回撤4%。
    #   修法: 对候选池做一次批量"不复权"取数(1次API调用, 只取20根), 存 zt_close_raw/
    #   last_close_raw; 比价时优先用不复权口径, 取不到才回退前复权值(向后兼容,
    #   无除权情形下两者相等, 行为逐字节等价)。
    if G.candidates:
        try:
            _raw9 = _api(G.C.get_market_data_ex, [],
                         [c['stock'] for c in G.candidates], '1d',
                         '', '', 20, 'none', False, False)
            for c in G.candidates:
                try:
                    _bars9 = _bars_to_dict(_raw9.get(c['stock']) if isinstance(_raw9, dict) else None)
                    _zt_raw = 0.0
                    _lc_raw = 0.0
                    _t0s = str(c.get('t0') or '')
                    for _d9 in sorted(_bars9.keys()):
                        _b9 = _bars9.get(_d9) or {}
                        if _t0s and _d9 == _t0s:
                            _zt_raw = _f(_b9.get('close'))
                        if isinstance(_d9, str) and G.today and _d9 >= G.today:
                            continue
                        _lc_raw = _f(_b9.get('close'))
                    if _zt_raw > 0:
                        c['zt_close_raw'] = _zt_raw
                    if _lc_raw > 0:
                        c['last_close_raw'] = _lc_raw
                except Exception:
                    continue
        except Exception as e:
            log('[数据告警] 不复权收盘价补取失败, 回撤/追高比价回退前复权口径:', repr(e)[:160])
    # 候选优选(多于MAX_DAILY_PICKS只时):
    #   主条件: 昨日量/基准量, 比值越小越优先(缩量越充分, 抛压越轻)
    #   次条件: 昨收距涨停收盘的回撤, 越浅越优先(走势更强)
    for c in G.candidates:
        c['shrink_rank'] = c['last_vol'] / c['base_vol'] if c['base_vol'] > 0 else 9.99
        # P3-9(第18轮审计): 优先用不复权口径算回撤(前复权与真实价混算会在窗口内除权时算错);
        #   取不到不复权值时回退前复权值(无除权情形两者相等)。
        _ztc_r = _f(c.get('zt_close_raw', 0.0)) or _f(c.get('zt_close', 0.0))
        _lc_r = _f(c.get('last_close_raw', 0.0)) or _f(c.get('last_close', 0.0))
        c['pullback'] = 1.0 - _lc_r / _ztc_r if _ztc_r > 0 else 9.99
    G.candidates.sort(key=lambda c: (round(c['shrink_rank'], 4), round(c['pullback'], 4),
                                     c['stock']))   # P2-4: 兜底键=代码, 同分排序不再依赖数据源返回顺序
    # V2.6.177/V2.6.181: 优选阶段末尾精筛(不复权, -2%) 价格位置护栏(涨停后回调); V2.6.181 已移除早期排雷前的宽阈值前复权粗筛(-8%);
    #   价格筛选逻辑现统一收敛到优选阶段内(切片 G.candidates[:MAX_DAILY_PICKS] 之前); st_rise 计数仅含此精筛剔除(无双计)。
    _rise_rej = []
    _kept = []
    for c in G.candidates:
        if c['pullback'] < -MIN_PULLBACK_FROM_ZT:
            st_rise += 1
            _rise_rej.append(c)
        else:
            _kept.append(c)
    G.candidates = _kept
    total = len(G.candidates)
    if total > MAX_DAILY_PICKS:
        # V2.6.97(2): 截断留痕。旧写法直接切片, 被剔的票在日志里查无此人 ——
        #   2026-10-20 00:36 那次: “候选4只 优选保留2只”只列出 001299(0.48)/002549(0.51)
        #   两条, 另 2 只叫什么、量比多少、为什么排后面, 日志一个字没有。
        #   若排序键写错把更好的剔了, 用户从日志完全无法发现。
        #   注: 必须在切片前打, 切片后对象就没了。
        # V2.6.98(4): 这里只把落选者存进局部 _rej, 打印挪到优选行之后(见本函数末尾)。
        #   旧版在切片前就地打印, 日志顺序成了 落选 -> 漏斗'候选4只' -> ... -> 优选。
        _rej = list(G.candidates[MAX_DAILY_PICKS:])
        # P2-6: 构建纪律 —— 整表截断替换(原子引用换新列表), 不局部删改
        G.candidates = G.candidates[:MAX_DAILY_PICKS]
    else:
        _rej = []                   # V2.6.98(4): 未触发截断时也要有名字, 末尾循环统一处理
    # 漏斗各项顺序互斥(每股只计入第一个命中的条件), 各项与避雷/去重相加 = 全市场有效只数
    # V2.6.35零预设审计: 漏斗口径与代码检查顺序对齐, 原'按数据不足剔除'拆成6项具名原因(仅改日志)

    log('选股漏斗(顺序与代码一致): 有效%d只 -> 持仓中%d / 日线不足2根%d / 无涨停%d / 多涨停%d / '

        '月内多涨停%d / 同周期已做%d / 涨停日不在日历%d / 窗口外%d / 基准量未形成%d / T0未放量%d / '

        '基准量<=0 %d / 基准量不足 %d'

        % (len(G.hist), st_held, st_short, st_nozt, st_multi, st_zt_month, st_done, st_t0cal, st_win,

           st_nobase, st_vol_t0, st_base0, st_vol_base))

    log('           -> 换手率不符%d(剔除:过低%d/过高%d; 旁注:自算%d/缺失放行%d) / 成交额不足%d / '
        '价格位置护栏%d / '
        '板块或名称排除%d(排雷清单%d/ST %d/板块 %d/名称取数失败%d%s) / 历史ST%d / 避雷风险%d / '
        'MA10破位%d / 低点破位%d / 非热门板块%d / 去重%d / 停牌日%d / 市值不符%d -> 候选%d只'
        % (st_turnover, st_turn_lo, st_turn_hi, st_turnover_calc, st_turnover_missing, st_amt, st_rise,
           st_excl, st_excl_risk, st_excl_st, st_excl_board, st_namefail,
           (u'/其它%d' % st_excl_oth) if st_excl_oth else u'',
           st_sthist, st_risk, st_ma10, st_lowhold, st_hot,

           st_dedup, st_susp, (st_mcap_low + st_mcap_high + st_mcap_miss), total))
    if MARKET_CAP_FILTER_ON:
        log('市值过滤(流通市值 %.0f~%.0f亿): 低市值剔除%d / 高市值剔除%d / 数据缺失剔除%d / 降级放行%d'

            % (MARKET_CAP_MIN_YI, MARKET_CAP_MAX_YI, st_mcap_low, st_mcap_high,
               st_mcap_miss, st_mcap_degrade))
        # 审计P1-2: 降级放行占比过高(>=50%)时按财务降级同规格每日一条强提醒
        _mcap_checked8 = st_mcap_low + st_mcap_high + st_mcap_miss + st_mcap_degrade
        if _mcap_checked8 > 0 and st_mcap_degrade * 2 >= _mcap_checked8:
            _mark_mcap_degraded(st_mcap_degrade, _mcap_checked8)

        # V2.6.81: 口径核对 —— 打印实际命中的流通股本字段名与取不到只数,
        #   一眼看出某券商客户端用的是 FloatVolume 还是 FloatVolumn, 不用猜。

        _ms = getattr(G, '_mcap_src', None) or {}

        _hits = _ms.get('hits') or {}

        if _hits:

            _hd = ' / '.join('%s=%d只' % (_k, int(_v or 0)) for _k, _v in

                             sorted(_hits.items(), key=lambda _kv: -int(_kv[1] or 0)))

        else:

            _hd = '(无命中)'

        log('市值过滤口径核对(V2.6.81起只认流通市值, 不再用总股本兜底): 命中字段 %s / 取不到流通股本=%d只'

            % (_hd, int(_ms.get('none', 0) or 0)))
    # 审计P1-1: 名称取数失败强提醒(每日至多一条由 _mark 系列同规格, 此处为日志明示)
    if st_namefail > 0:
        log('[数据告警][强提醒] 本轮%d只股票名称取数失败(身份不明), 已按保守规则剔除; '
            '若多个轮次持续出现, 请检查行情接口 get_instrument_detail 可用性'
            % st_namefail)
    if blocked:
        log('按避雷/结构过滤剔除%d只(风险信号/MA10破位/非热门板块)' % len(blocked))
    # V2.6.94(2): 排雷清单命中明细 —— 旧版命中被 excluded() 吞进"板块或名称排除",
    #   拦了谁、为什么拦, 日志里一个字都没有(2026-10-19 两轮实盘都只能靠猜)。
    if risk_ex_hits:
        log('排雷清单命中%d只(已计入上方"板块或名称排除", 不重复计入"避雷风险"), 明细:'
            % len(risk_ex_hits))
        for _rxr in risk_ex_hits:
            log('  %s' % _rxr)
    if RISK_LOSS_CHECK:
        limit = RISK_LOSS_OUTPUT_LIMIT if RISK_LOSS_OUTPUT_LIMIT > 0 else None
        _miss_how = '自动下载后仍缺失则按保守规则剔除'
        if G.loss_data_ok:
            log('亏损筛选口径 | 指标=最近一期已披露归母净利润 | 判定=<0剔除, >=0保留 | '
                '时间范围=报告期<=策略日%s的最新一期 | QMT字段=ASHAREINCOME.net_profit_excl_min_int_inc'
                '(归母净利润, 别名 np/net_profit/NET_PROFIT) | '
                '聚宽字段=indicator.net_profit | 缺失数据=%s | 本轮因数据缺失剔除%d只'
                % (_ref, _miss_how, st_loss_missing))
        else:
            log('[数据告警][强提醒] 亏损筛选口径 | 财务数据自动下载/复检失败 | '
                '缺失数据=%s | 本轮因数据缺失保守剔除%d只 | 请补数后重新筛选'
                % (_miss_how, st_loss_missing))
        if RISK_LOSS_KEEP_RECORDS:
            _n_neg = len(loss_excluded) - len(loss_missing_codes)
            log('其中财务亏损剔除%d只(归母净利润<0 %d只, 数据缺失/查询异常 %d只; 已计入上方漏斗"避雷风险", 不重复扣除)'
                % (len(loss_excluded), _n_neg, len(loss_missing_codes)))
        log('亏损筛选剩余表(通过风险过滤的中间层, 尚未经MA10/低点/市值过滤, 非最终候选) | 代码 | 名称 | 公告日期 | 字段/数值 | 结果')
        for row in loss_checked[:limit]:
            log('  ' + row)
        if not loss_checked:
            log('  (无)')
        # 20261008: 财务数据不完整股票带序号清单 + 末尾汇总
        if loss_missing_codes:
            log('按财务数据缺失(保守规则)剔除%d只' % len(loss_missing_codes))
    if dedup:
        log('按去重规则跳过%d只(持仓中/同周期已做/卖出间隔不足)' % len(dedup))
    log('今日低吸候选共%d只(近7日恰好1个涨停且处于T0+3~T0+7窗口), 优选保留%d只:' %
        (total, len(G.candidates)))
    if total > len(G.candidates):
        # V2.6.98(3): 两个数口径不同必须点明 —— 漏斗那行打的是截断前计数 total,
        #   状态行'候选N只'打的是 len(G.candidates)(已截断)。2026-10-20 00:48 的日志里
        #   同时出现 '候选4只' 和 '候选2只', 不说明会误判成丢股。
        log('  注: 上方漏斗"候选%d只"为截断前计数, 状态行"候选N只"只统计实际入库的%d只; '
            '差出的%d只已按每日优选上限落选(明细见下方"落选"行)' %
            (total, len(G.candidates), total - len(G.candidates)))
    if st_rise > 0:
        log('[价格位置护栏] 涨停后继续大涨(昨收高于涨停收盘%.0f%%)剔除%d只(非缩量低吸, 与战法②确认进场冲突; '
            'V2.6.181移除早期排雷前的宽阈值前复权粗筛, 此处记录优选阶段精筛剔除):'
            % (MIN_PULLBACK_FROM_ZT * 100, st_rise))
        for _rc in _rise_rej:
            _rp = _rc['pullback'] * 100.0
            log('  %s %s 昨收高于涨停收盘%.1f%% (昨量/基准量=%.2f; 灰区不复权精筛, 阈值%.0f%%)'
                % (_rc['stock'], _rc.get('name', u'(名称缺失)'), -_rp, _rc['shrink_rank'], MIN_PULLBACK_FROM_ZT * 100))
    for i, c in enumerate(G.candidates):
        _pf = get_recent_net_profit_cached(c['stock'])
        if _pf and _pf.get('value') is not None:
            _fin_txt = '公告日期=%s | 净利润=%.2f万元' % (
                (_pf.get('announce_date') or _pf.get('report_date') or '未知'),
                _pf['value'] / 10000.0)
        else:
            _fin_txt = '公告日期=未知 | 净利润=数据缺失'
        # V2.6.89: 把涨停日换手率打进优选项。V2.6.88 首日实跑(20261019)证明闸门确实生效了
        #   (换手率不符50 / 自算121 / 缺失放行0), 但日志只有"总数+自算只数", 候选各自算出来多少看不到,
        #   复核时只能从"它过了闸"倒推 —— 当时据此把 603466 估成约30%属误判, 真实值必须能直接读出来。
        _tt = _f(c.get('turn_t0') or 0)
        _tt_txt = ('涨停日换手=%.1f%%' % (_tt * 100)) if _tt > 0 else '涨停日换手=缺失(已放行)'
        # V2.6.98(5): 回撤为负 = 昨收高于涨停收盘(即昨收涨), 旧版印成 '昨收回撤=-1.9%',
        #   读着别扭还容易被当成数据错误; 负数直接换算成上涨幅度, 不用读者在脑子里翻符号。
        _pb_raw = c['pullback'] * 100.0
        _pb_txt = (u'昨收上涨%.1f%%' % (-_pb_raw)) if _pb_raw < 0 else (u'%.1f%%' % _pb_raw)
        log('  第%d优先 %s %s T0=%s 基准量=%.0f 昨量/基准量=%.2f 昨收回撤=%s 涨停收盘=%.2f 第%d天 %s | %s' %
            (i + 1, c['stock'], c['name'], c['t0'], c['base_vol'], c['shrink_rank'],
             _pb_txt, c['zt_close'], c['offset'], _tt_txt, _fin_txt))
    # V2.6.98(4): 落选明细移到优选行之后 —— 旧顺序是 落选 -> 漏斗'候选4只' -> 市值 -> 亏损表
    #   -> 优选, 先看落选再看候选总数, 读起来是反的。列表在切片前存进 _rej, 此处才打印。
    for _rlc in _rej:
        _rb_raw = _rlc['pullback'] * 100.0
        _rb_txt = (u'昨收上涨%.1f%%' % (-_rb_raw)) if _rb_raw < 0 else (u'%.1f%%' % _rb_raw)
        log('  落选(超出每日优选上限%d只, 按量比升序越小越优) %s %s '
            '昨量/基准量=%.2f 昨收回撤=%s 第%d天'
            % (MAX_DAILY_PICKS, _rlc['stock'], _rlc.get('name') or u'(名称缺失)',
               _rlc['shrink_rank'], _rb_txt, _rlc['offset']))

    _sync_sector()

def rescreen_if_needed():
    """补选股: 交易日初始化已完成但当时历史数据未就绪(有效股票数不足)时,
    按RESCREEN_INTERVAL间隔重试加载日线并重新选股;
    候选为空属正常选股结果, 不触发补选股; 有效数据补齐后自动停止重试"""
    if not G.today or G.state['last_init_date'] != G.today:
        return
    if len(G.hist) >= MIN_UNIVERSE_FOR_SCREEN:
        return
    now = time.time()
    if now - G.last_rescreen_ts < RESCREEN_INTERVAL:
        return
    G.last_rescreen_ts = now
    log('补选股: 当前有效历史仅%d只(<%d), 重试加载日线并选股'
        % (len(G.hist), MIN_UNIVERSE_FOR_SCREEN))
    uni = load_universe()
    if uni:
        G.universe = uni
    load_history()
    load_hot_sectors()   # 方案A一期: 补选股场景同步刷新热门板块
    if len(G.hist) >= MIN_UNIVERSE_FOR_SCREEN:
        screen_candidates()
        log('补选股完成, 有效股票数:', len(G.hist))
        G.rescreen_tries = 0        # V2.6.98(2): 补齐即清零, 下次再残缺时重新从 0 计数
        return
    # V2.6.98(2) 修复: 旧版到这里就结束了 —— 只 load_history() 读本地缓存, 从不下载。
    #   load_history() 走 get_market_data_ex(纯读), 本地没有的股票它永远返回空;
    #   而 stage2 在 5496 行无条件写 last_init_date=today, 之后每轮 step_day_init 在 5344
    #   行直接 return —— 于是'某天首轮只读到 500 只'会变成: 当天不重下、每 300 秒纯读重试、
    #   永远补不上, 整天空仓, 日志里只留一条重复的'补选股: 当前有效历史仅N只'。
    #   修法: 连续 3 次(约 15 分钟)仍不足, 就清空 last_dl_date/last_init_date 并重置阶段机,
    #   让 step_day_init 下一轮按正常流程重下 —— 复用既有下载段(8 秒预算/跨桶进度/耗时/串行化),
    #   不另写一套下载。重置次数上限 2 次, 防止接口真坏时整天反复下 5226 只。
    _tries = int(getattr(G, 'rescreen_tries', 0)) + 1
    G.rescreen_tries = _tries
    if _tries < 3:
        return
    if G.no_download:
        log('[数据告警] 补选股连续%d次不足%d只, 且本机无 download_history_data 接口; '
            '请手动下载沪深A股日线(数据管理/历史数据下载), 否则本日无候选' %
            (_tries, MIN_UNIVERSE_FOR_SCREEN))
        return
    _rs_n = int(getattr(G, 'rsdl_reset_n', 0))
    if _rs_n >= 2:
        log('[数据告警] 补选股连续%d次不足%d只, 已重置下载%d次仍未补齐; 本日不再自动重下, '
            '请人工检查行情连接与数据目录' % (_tries, MIN_UNIVERSE_FOR_SCREEN, _rs_n))
        return
    G.rsdl_reset_n = _rs_n + 1
    G.rescreen_tries = 0
    G.state['last_dl_date'] = ''
    G.state['last_init_date'] = ''
    G.dl_phase = 0
    G.dl_i = 0
    G.dl_mark = -1
    save_state()
    log('[数据告警] 补选股连续%d次加载不足%d只(实际仅%d只), 判定本地日线缓存残缺 -> '
        '重置下载状态机, 下一轮重新下载全市场日线(第%d/2次); 期间无候选属预期' %
        (_tries, MIN_UNIVERSE_FOR_SCREEN, len(G.hist), G.rsdl_reset_n))

# ==================== 账户层 ====================
def dry_cash_delta(d):
    """审计修复P1-5: DRY_RUN模拟盘资金增减(买入扣款/卖出回款)。
    首次使用时以状态文件'状态资金'为初始资金; 资金不落到0以下。"""
    cur = _f(G.state.get('dry_cash', _f(G.state.get('状态资金', 0))))
    G.state['dry_cash'] = max(0.0, cur + d)
    return G.state['dry_cash']

def _own_hold_count():
    """状态文件里本策略自身持仓只数(供空持仓表确认用; 不含孤儿仓与已离场仓)"""
    try:
        return len([1 for h in (G.state.get('hold') or {}).values()
                    if is_own_position(h) and not h.get('exited')])
    except Exception:
        return 0

def query_account():
    """返回 (总持仓dict, 可用持仓dict, 可用资金); 统一走实盘柜台查询。
    安全加固: 柜台查询异常时返回 (None,None,None) 哨兵, 调用方(run_round)必须据此
    跳过本轮开平仓 —— 绝不基于"空持仓"误删真实持仓记录(一次短暂断连就清仓是致命的)。
    审计修复P1-5: DRY_RUN模式下由状态文件构造账户层 —— 模拟持仓=hold记录,
    可用量按T+1规则(当日买入不可卖), 资金=dry_cash(买卖实时增减)。
    避免"模拟持仓在真实柜台不存在"被误判为已无持仓而次日强制清仓。"""
    if DRY_RUN:
        hold = G.state.get('hold') or {}
        pt, pa = {}, {}
        for s, h in hold.items():
            if h.get('exited'):
                continue               # 已发出卖出(模拟成交已完成), 不再计为可卖持仓
            v = int(pos_vol(h))
            if v > 0:
                pt[s] = v
                pa[s] = v if h.get('buy_date') != G.today else 0   # 模拟T+1: 当日买入不可卖
        cash = _f(G.state.get('dry_cash', _f(G.state.get('状态资金', 0))))
        return pt, pa, cash
    try:
        acc = _api(get_trade_detail_data, G.accid, 'STOCK', 'ACCOUNT')
        if not acc:
            # P0-1: 账户查询返回空表(未登录/策略界面未选账号/柜台未就绪的常见形态,
            # 与"抛异常"等价) —— 返回哨兵让调用方跳过本轮。
            # 绝不把"查不到"当成"无持仓": 空表会让所有持仓命中 pt.get(s,0)<=0,
            # 被当作已平仓删除并伪造已实现盈亏(持仓永久失管+组合按假数据决策)。
            log('账户查询返回空表(账号未登录/未就绪), 本轮跳过开平仓(绝不基于空数据误删持仓)')
            return None, None, None
        cash = _f(acc[0].m_dAvailable)
        pos = _api(get_trade_detail_data, G.accid, 'STOCK', 'POSITION')
        if pos is None:
            return None, None, None
        pt, pa = {}, {}
        for i in pos:
            code = '%s.%s' % (i.m_strInstrumentID, i.m_strExchangeID)
            pt[code] = int(i.m_nVolume)
            pa[code] = int(i.m_nCanUseVolume)
        # P0修复(2026-10-02): POSITION 返回空表(非异常)必须与"抛异常"同等对待 ——
        #   旧版只拦 ACCOUNT 空表, POSITION 空表会返回"空持仓", 调用方据此把全部持仓
        #   当已平仓删除(estimate_close 按 last_px 伪造盈亏 + mark_sold 误锁10日 + 释放名额)。
        #   但账户确实无持仓时 POSITION 也为空, 二者不可区分, 故仅在"状态文件仍有本策略持仓"
        #   时进入保守确认: 连续 POS_EMPTY_CONFIRM_ROUNDS 轮为空才认定已清仓。
        if not pt:
            own = _own_hold_count()
            if own <= 0:
                # 状态文件本身也空: 空表可信, 计数归零(内存+落盘一致)
                with G.state_lock:
                    G.state['pos_empty_n'] = 0
                    G.pos_empty_n = 0
                return pt, pa, cash
            # 第3条修复(2026-10-17): 计数读写统一走持久化状态 G.state['pos_empty_n'] ——
            # 旧版只存内存 G.pos_empty_n, 策略一重启就归零, "断连确认"被重启重置,
            # 永远凑不满 POS_EMPTY_CONFIRM_ROUNDS 轮(每次重启都当"第一次空表"处理)。
            with G.state_lock:
                G.pos_empty_n = int(G.state.get('pos_empty_n', 0) or 0) + 1
                G.state['pos_empty_n'] = G.pos_empty_n
            if G.pos_empty_n < POS_EMPTY_CONFIRM_ROUNDS:
                log('账户查询返回空持仓表, 但状态文件仍有%d只本策略持仓 —— 判为柜台未就绪/断连, '
                    '本轮跳过开平仓(第%d/%d次确认; 连续%d次为空才认定已清仓)'
                    % (own, G.pos_empty_n, POS_EMPTY_CONFIRM_ROUNDS, POS_EMPTY_CONFIRM_ROUNDS))
                # 第3条修复: 计数立即落盘 —— 本分支上层会提前return不触发常规落盘, 必须主动存
                save_state()
                return None, None, None
            log('[安全][告警] 连续%d轮查询柜台持仓均为空, 而状态文件仍有%d只本策略持仓 —— '
                '按"已清仓"处理; 若属柜台断连请立即检查账户与状态文件!'
                % (G.pos_empty_n, own))
        else:
            with G.state_lock:
                G.state['pos_empty_n'] = 0
                G.pos_empty_n = 0
        return pt, pa, cash
    except Exception:
        log('查询账户异常, 本轮跳过开平仓(等待柜台恢复, 绝不基于空数据误删持仓)')
        return None, None, None

# ==================== 分批建仓(金字塔低吸) ====================
def _estimate_base_vol(code):
    """重审20261005(1-6): 补录持仓基准量兜底估算。
    buy_ctx 缺失/超期(>3天)或其中无 base_vol 时, 补录持仓的 base_vol 会是 0 ——
    而 base_vol=0 的持仓在卖出判定中 "base>0 且预估量达基准1.9倍" 永假,
    MAX_HOLD_TRDAYS=33(2026-10-09第五轮审计启用)时"持有到期且已盈利"出口生效, 亏损仓位仍只剩套牢移交一条自动出口。
    现按已加载日线最近一个【已完成】交易日的成交量估算(标注为估算值)。
    返回 (估算量, 是否估算); 无可用日线返回 (0, False)。"""
    rows = G.hist.get(code) or []
    comp = [r for r in rows if str(r.get('date', '')) != str(G.today)]
    if comp:
        v = int(_f(comp[-1].get('volume', 0)))
        if v > 0:
            return v, True
    return 0, False

def reconcile_positions():
    """全量双向对账(仅实盘):
    方向A — 柜台有、状态文件没有 → 若存在该股的新鲜 buy_ctx(3日内本策略买入上下文, 即
            状态文件丢失场景)则按柜台值补录接管; 其余(手工/其他策略持仓)仅记录, 不写入
            状态文件(保持状态文件仅含本策略标的); 防重复买入由 run_round 买入循环直接
            检查 pos_total(柜台持仓)实现
    方向A2 — 柜台有未成交在途买单、状态文件没有 → 补录为在途持仓(P1-2: 状态丢失+在途
            委托场景下, 不补录会同一标的再买一单 —— 唯一确认可重复开仓的路径)
    方向B — 状态文件有、柜台没有 → 清理遗留/脏记录(含buy_price异常负数等)
    方向C — 两边都有但状态文件字段脏(buy_price<=0/buy_date空) → 用柜台值覆盖修正;
            除权除息导致股数变化时同步调整buy_price成本基准(P1-5), 防除权后永久禁卖"""
    # P2-1修复(2026-10-02): 柜台查询(POSITION/ORDER, 网络IO)全部移到锁【外】——
    #   旧版持 G.state_lock 调 get_trade_detail_data, 柜台卡顿会阻塞 deal_callback(成交回报)
    #   与 order_callback(OrderID绑定落盘)数秒。此处先取数(失败即冻结交易), 再持锁决策。
    try:
        pos = _api(get_trade_detail_data, G.accid, 'STOCK', 'POSITION') or []
    except Exception:
        log('[安全] 对账异常: 柜台POSITION查询失败, 已暂时禁止下单(每60秒自动复核, 恢复后重新对账)')
        G.acct_ok = False
        G.acct_probe_ts = time.time()
        return
    try:
        ords = _api(get_trade_detail_data, G.accid, 'STOCK', 'ORDER') or []
    except Exception:
        log('[安全] 启动对账ORDER查询失败, 已冻结新增风险；待订单与持仓均可信后恢复')
        G.acct_ok = False
        G.acct_probe_ts = time.time()
        return
    with G.state_lock:
        hold = G.state.get('hold')
        if not isinstance(hold, dict):
            hold = {}
            G.state['hold'] = hold
        # 一次性迁移: 旧版把柜台持仓补录为 reconciled=True(孤儿仓), 其中既可能是本策略
        # 程序化买入的(状态丢失), 也可能是手工/其他策略买入的。按"状态文件仅含本策略
        # 实际买卖标的"的要求, 统一清理: 柜台有但无策略买入记录的一律不进状态文件,
        # 手工持仓由用户自行管理止盈/止损, 策略不碰。
        _legacy = [c for c, h in hold.items() if h.get('reconciled')]
        for c in _legacy:
            del hold[c]
        if _legacy:
            log('[安全] 迁移: 清理旧版补录的非策略持仓记录%d条(状态文件仅保留本策略买卖标的; 手工持仓由用户自行管理)' % len(_legacy))
            save_state()
        orphans = []
        bad_fixed = []
        removed = []
        # P2-1修复: POSITION 已在上方锁外查询(pos), 此处只做纯计算
        # 先构建柜台持仓字典(code -> volume)
        pt = {}
        for i in pos:
            try:
                code = '%s.%s' % (i.m_strInstrumentID, i.m_strExchangeID)
                vol = int(i.m_nVolume or 0)
                if vol > 0:
                    pt[code] = (vol, i)
            except Exception:
                continue
        log('[安全] 对账启动: 状态文件持仓%d只(本策略自身标的)' % len(hold))
        # 方向C量变化修正标志: 除权/手工加减仓修正后需要落盘
        _recon_changed = False
        # 方向B+C: 先处理状态文件里的每条记录
        for code in list(hold.keys()):
            h = hold[code]
            s_px_raw = h.get('buy_price', None)
            s_vol_raw = h.get('buy_vol', None)
            s_px = _f(s_px_raw)
            s_vol = int(s_vol_raw or 0) if s_vol_raw is not None else 0
            # hard_bad: 严重脏数据, 必须修正或清理(精确到具体条件)
            cond_px_neg = s_px <= 0
            cond_px_huge = abs(s_px) > 100000
            cond_vol_zero = s_vol <= 0
            hard_bad = cond_px_neg or cond_px_huge or cond_vol_zero
            # soft_bad: 轻微缺项(buy_date空/name空), 不拦截, 后续流程自然填上
            buy_date_missing = not h.get('buy_date')
            if code not in pt:
                # 柜台没有: 严重脏直接清(不计卖出间隔); 轻微缺不拦正常清算
                if hard_bad and not (h.get('fill_vol', 0) > 0 or h.get('exited')):
                    log(disp(code), '对账B: 实盘无此持仓且buy_price/buy_vol严重脏(px=%.2f vol=%d), 直接清理' % (s_px, s_vol))
                    G.state['done'].pop(code, None)
                    del hold[code]
                    removed.append(code)
                continue
            # 方向C: 两边都有但状态文件脏, 用柜台值修正
            c_vol, ci = pt[code]
            c_px = _f(getattr(ci, 'm_dOpenPrice', 0.0))
            c_cur = _f(getattr(ci, 'm_dLastPrice', 0.0))
            # 柜台开仓价也脏时, 用当前价
            if c_px <= 0 or c_px > 100000 or c_px < -1000:
                c_px = c_cur if c_cur > 0 else 0.01
            if hard_bad:
                # 精确诊断: 哪些条件命中了
                reasons = []
                if cond_px_neg: reasons.append('px<=0(%.2f)' % s_px)
                if cond_px_huge: reasons.append('px>10w(%.2f)' % s_px)
                if cond_vol_zero: reasons.append('vol<=0(%d)' % s_vol)
                old_px, old_vol = s_px, s_vol
                # 只有 old != new 才真正修正和记录
                need_change = (old_px != c_px) or (old_vol != c_vol)
                if need_change:
                    h['buy_price'] = c_px
                    h['buy_vol'] = c_vol
                    h['cost_total'] = _round2(c_px * c_vol + _f(h.get('fee', 0.0)))
                    h['fill_sum'] = c_px * c_vol
                    h['fill_vol'] = c_vol
                    bad_fixed.append('%s: buy_price %.2f→%.2f, buy_vol %d→%d (原因: %s)'
                                     % (code, old_px, c_px, old_vol, c_vol, '|'.join(reasons)))
                # 诊断日志: 不输出实盘原始值, 只记录策略侧修正前后的值(修正后值即写入状态文件的本策略数据)
                log('[诊断] %s hard_bad命中: %s | 原值px=%s(%r) vol=%s(%r) | 修正后px=%.2f vol=%d | 是否需修正=%s'
                    % (code, '|'.join(reasons), s_px, s_px_raw, s_vol, s_vol_raw, c_px, c_vol, need_change))
            # 同步柜台最新量(除权除息/手工加仓/手工减仓导致量变化)
            # 2026-10-03 审计修复: 旧逻辑把一切量变化当"除权除息"无条件用柜台开仓价覆盖
            # buy_price/cost_total, 含费口径被破坏, 手工加仓/减仓后成本基准失真(亏损禁卖/
            # 净利为正判断失真)。现按守恒校验区分"除权除息"与"手工加仓", 手工增减仓
            # 坚持"不覆盖成本基准": 有登记按登记校准, 无登记只同步股数并醒目标记提示。
            elif s_vol != c_vol:
                _fee0 = _f(h.get('fee', 0.0))
                _oc = pos_cost(h)                 # 原含费总成本(cost_total优先, 旧记录折算)
                _pb = _f(h.get('buy_price', 0.0))
                if c_vol > s_vol:
                    # 除权除息(送转/分红): 股数增、总市值≈原含费总成本(市值守恒)
                    if _oc > 0 and abs(c_px * c_vol - _oc) <= max(_oc * 0.02, 1.0):
                        # 守恒命中 -> 按除权口径摊薄: 均价取"(原含费总成本-累计费用)÷新量",
                        # cost_total 保持原含费总成本不变, fee 不变, 维持 fill_sum+fee=cost_total 恒等
                        _npx = (_round2((_oc - _fee0) / c_vol)
                                if (c_vol > 0 and _oc - _fee0 > 0) else _round2(_oc / float(c_vol)))
                        h['buy_vol'] = c_vol
                        h['fill_vol'] = c_vol
                        h['buy_price'] = _npx
                        h['fill_sum'] = _round2(_npx * c_vol)
                        # cost_total 保持 _oc 不变(市值守恒, 防除权后亏损禁卖误判)
                        _recon_changed = True
                        log('[安全] %s 除权除息对账(守恒: 柜台市值%.2f≈含费总成本%.2f): '
                            '股数%d→%d, 均价%.2f→%.2f, 含费总成本不变=%.2f' % (
                                code, c_px * c_vol, _oc, s_vol, c_vol,
                                _f(s_px_raw) if s_px_raw else 0.0, _npx, _oc))
                    else:
                        # 非守恒股数增 -> 视为手工加仓, 坚决不覆盖成本基准
                        _mf = (G.state.get('manual_fill') or {}).get(code)
                        _mac = (G.state.get('manual_avg_cost') or {}).get(code)
                        _nsum = _round2(_oc - _fee0) if _oc > 0 else _round2(_pb * s_vol)
                        if _mf and isinstance(_mf, dict) and _f(_mf.get('price', 0.0)) > 0 \
                                and int(_mf.get('vol', 0) or 0) > 0:
                            # manual_fill 登记: {code:{"price","vol","fee"}} 加权合并真实手工成本
                            _mx = _f(_mf.get('price')); _my = int(_mf.get('vol'))
                            _mz = _f(_mf.get('fee', 0.0))
                            _nsum2 = _nsum + _mx * _my          # 不含费累计金额
                            _fee1 = _fee0 + _mz                 # 费用累计
                            _npx2 = _round2(_nsum2 / float(c_vol))
                            h['buy_vol'] = c_vol
                            h['fill_vol'] = c_vol
                            h['buy_price'] = _npx2
                            h['fee'] = _round2(_fee1)
                            h['fill_sum'] = _round2(_nsum2)
                            h['cost_total'] = _round2(_nsum2 + _fee1)
                            (G.state.get('manual_fill') or {}).pop(code, None)
                            _recon_changed = True
                            log('[安全] %s 手工加仓对账(manual_fill已登记): 股数%d→%d, '
                                '均价%.2f→%.2f, 含费总成本%.2f→%.2f(登记价%.2f×%d股+费%.2f)' % (
                                    code, s_vol, c_vol,
                                    _f(s_px_raw) if s_px_raw else 0.0,
                                    _npx2, _oc, _round2(_nsum2 + _fee1), _mx, _my, _mz))
                        elif _mac and _f(_mac) > 0:
                            # manual_avg_cost 快捷登记: {code: 6.50} 直接指定新均价(不含费口径)
                            _na = _f(_mac)
                            h['buy_vol'] = c_vol
                            h['fill_vol'] = c_vol
                            h['buy_price'] = _na
                            h['fill_sum'] = _round2(_na * c_vol)
                            h['cost_total'] = _round2(_na * c_vol + _fee0)
                            (G.state.get('manual_avg_cost') or {}).pop(code, None)
                            h.pop('unreg_manual_add', None)   # P1-2: 登记后成本已校准, 解除卖出暂停
                            _recon_changed = True
                            log('[安全] %s 手工加仓对账(manual_avg_cost已登记): 股数%d→%d, '
                                '均价按登记值%.2f, 含费总成本%.2f' % (
                                    code, s_vol, c_vol, _na, _round2(_na * c_vol + _fee0)))
                        else:
                            # 无登记: 只同步股数, 保留原成本基准(fill_sum/fee/cost_total/buy_price
                            # 全部不动, 维持 fill_sum+fee=cost_total 恒等), 醒目标记提示登记
                            # P1-2修复(2026-10-17): 成本基准此时已不可信(手工加仓真实成本未知),
                            #   旧版仅打日志 —— 每股成本被稀释后, is_at_loss/net_pnl_if_sell 按偏低的
                            #   假成本放行卖出, 可能卖出"实际亏损"的单子(违反不赚钱不卖铁律)。
                            #   现置未登记标记: 该股一切自动卖出暂停, 人工登记后才恢复。
                            h['buy_vol'] = c_vol
                            h['fill_vol'] = c_vol
                            h['unreg_manual_add'] = {'date': G.today, 'from': s_vol, 'to': c_vol}
                            _recon_changed = True
                            log('[安全][注意] %s 柜台股数增加%d→%d(疑手工加仓), '
                                '无 manual_fill/manual_avg_cost 登记, 仅同步股数、不覆盖成本基准 '
                                '(均价%.2f/含费总成本%.2f保留); 如需校准请在状态文件登记 '
                                'manual_fill 或 manual_avg_cost' % (code, s_vol, c_vol, _pb, _oc))
                            try:
                                notify_enqueue('[安全][注意] %s 检测到未登记手工加仓(股数%d→%d), '
                                               '成本基准不可信, 已【暂停该股自动卖出】; 请在状态文件登记 '
                                               'manual_fill/manual_avg_cost 后恢复(登记前策略只持有不卖出)'
                                               % (disp(code), s_vol, c_vol))
                            except Exception as _e_nt:
                                # 20261027审计: 原为静默 pass —— 推送失败本身不影响交易,
                                #   但这意味着"已暂停该股自动卖出"的提醒用户收不到, 需留痕。
                                log('[警告] 未登记手工加仓提醒推送失败(该股已暂停自动卖出): %s'
                                    % repr(_e_nt)[:120])
                else:
                    # 手工减仓(或柜台部分卖出状态未跟上): 均价不变, 成本按比例缩减
                    _ratio = c_vol / float(s_vol) if s_vol > 0 else 0.0
                    _ncost = _round2(_oc * _ratio)
                    h['buy_vol'] = c_vol
                    h['fill_vol'] = c_vol
                    h['cost_total'] = _ncost
                    h['fee'] = _round2(_fee0 * _ratio)
                    h['fill_sum'] = _round2(_f(h.get('fill_sum', 0.0)) * _ratio)
                    _recon_changed = True
                    log('[安全] %s 手工减仓对账: 股数%d→%d, 均价%.2f不变, '
                        '含费总成本%.2f→%.2f(按比例%.0f%%缩减)' % (
                            code, s_vol, c_vol, _pb, _oc, _ncost, _ratio * 100))
        # 方向E(2026-10-19 V2.6.72, 用户确认修复): 存量持仓费用口径校准 —— V2.6.71前买入的
        # 持仓沿用旧版粗估FEE_RATE_EST(0.15%)记账, 比真实佣金(股票万0.841/最低5元)高约17倍,
        # 导致 cost_total 虚高(实测两只持仓合计虚高约21元), 抬高了"扣费净利为正才卖"的门槛,
        # 可能造成该卖不卖。此处按真实费率 fee_buy 重算 fee 与 cost_total, 保持
        # fill_sum+fee=cost_total 恒等; 只改成本记录、不触发任何交易; 幂等(与实际一致则不改)。
        # 含已移交仓 —— 使组合熔断"真实权益(含已移交套牢仓浮亏)"口径更准确。
        _fee_fixed = []
        _fee_fix_sum = 0.0
        _fee_keep = []
        for _code, _h in list(hold.items()):
            if not is_own_position(_h):
                continue
            _ev = int(_f(_h.get('fill_vol', 0)) or 0)
            if _ev <= 0:
                _ev = int(pos_vol(_h))
            if _ev <= 0:
                continue
            _fs = _f(_h.get('fill_sum', 0.0))
            if _fs <= 0:
                _fs = _f(_h.get('buy_price', 0.0)) * _ev
            if _fs <= 0:
                continue
            _fe_old = _f(_h.get('fee', 0.0))
            # V2.6.157: 只校准「真正的 0.15% 粗估」记录。这段校准的本意是修 V2.6.71 之前
            # 用 FEE_RATE_EST(0.15%) 粗估费率记账的老持仓; 而「成交回报逐笔累加」出来的 fee
            # 是当时的真实记录(一张委托拆多笔成交时每笔各触发起收, 只会偏高, 方向保守),
            # 不应当被二次改写。2026-10-21 实测: 601595 上海电影两张委托累计 25.45 元被按
            # 一张重算成 5.45 元, 低估 5.00 元 —— 方向与铁律二(扣完费用净利为正才卖)相反。
            # 判据: 原 fee 与「成交金额 x 0.0015」吻合(容差 max(1.0, 2%)) → 认定是粗估形态
            # → 才重算; 明显偏离则保留原值不改, 宁可偏高不可偏低。
            _fe_est = _round2(_fs * 0.0015)
            _est_tol = max(1.0, _fe_est * 0.02)
            if abs(_fe_old - _fe_est) > _est_tol:
                _fee_keep.append('%s: fee=%.2f(粗估形态应为%.2f, 偏离%+.2f)'
                                 % (_code, _fe_old, _fe_est, _fe_old - _fe_est))
                continue
            # V2.6.156: 按该仓买过的委托单张数估算起收, 防把多张委托的起收又抹回一张;
            # 旧记录无 order_cnt 字段时默认 1 张, 与 V2.6.72 原口径完全一致
            _n_ord = max(1, int(_f(_h.get('order_cnt', 0)) or 0))
            _fe_new = fee_buy(_round2(_fs), _code, n_order=_n_ord)
            if abs(_fe_new - _fe_old) > 0.005:
                _ct_old = _f(_h.get('cost_total', 0.0))
                _h['fee'] = _round2(_fe_new)
                _h['cost_total'] = _round2(_fs + _fe_new)
                _recon_changed = True
                _fee_fixed.append('%s: fee %.2f->%.2f, cost_total %.2f->%.2f'
                                  % (_code, _fe_old, _fe_new, _ct_old, _h['cost_total']))
                _fee_fix_sum += (_ct_old - _f(_h.get('cost_total', 0.0)))
        if _fee_fixed:
            log('[安全] 存量持仓费用口径校准(V2.6.72): 重算%d只, 旧粗估0.15%%->真实费率, 合计成本调整%.2f元 | %s'
                % (len(_fee_fixed), _fee_fix_sum, '; '.join(_fee_fixed)))
        if _fee_keep:
            log('[安全] 存量持仓费用校准跳过%d只(非0.15%%粗估形态, 按成交回报真实记录原样保留; 偏离见各票, 不影响交易与对账)'
                ' | %s'
                % (len(_fee_keep), '; '.join(_fee_keep)))
        # 方向A2: 在途买单补录(P1-2) —— 状态文件丢失/损坏重启时, 柜台可能恰有一笔
        # 未成交的本策略买单(POSITION查不到、hold为空): 不补录则同一标的可再发一单,
        # 双倍占资且突破单票/持仓上限。
        # P2-1修复: ORDER 已在上方锁外查询(ords)
        now_ts = time.time()
        for o in ords:
            try:
                st = int(getattr(o, 'm_nOrderStatus', -1))
                rm = str(getattr(o, 'm_strRemark', '') or '')
                if st not in ACTIVE_ORDER_STATUS or not rm.startswith('BUY|'):
                    continue
                ocode = '%s.%s' % (getattr(o, 'm_strInstrumentID', ''),
                                   getattr(o, 'm_strExchangeID', ''))
                if ocode in hold or ocode in pt:
                    continue
                opend = int(getattr(o, 'm_nVolume', 0) or 0)
                otrd = int(getattr(o, 'm_nVolumeTraded', 0) or 0)
                pend = opend - otrd
                if pend <= 0:
                    continue
                bctx = (G.state.get('buy_ctx') or {}).get(ocode) or {}
                _bv, _bv_est = int(bctx.get('base_vol', 0) or 0), False
                if _bv <= 0:            # 重审20261005(1-6): base_vol兜底估算, 防补录仓永无自动卖出出口
                    _bv, _bv_est = _estimate_base_vol(ocode)
                hold[ocode] = {'t0': bctx.get('t0', ''), 'base_vol': _bv,
                               'zt_close': _f(bctx.get('zt_close', 0.0)), 'name': bctx.get('name', ''),
                               'buy_date': G.today or datetime.datetime.fromtimestamp(now_ts).strftime('%Y%m%d'),
                               'buy_price': _f(bctx.get('price', 0.0)), 'buy_vol': 0,
                               'paper': DRY_RUN, 'managed': True, 'fill_sum': 0.0, 'fill_vol': 0,
                               'exited': False, 'fee': 0.0, 'cost_total': 0.0, 'last_px': 0.0,
                               'open_ts': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                               'alert_win': 0, 'alert_loss': 0, 'order_ts': now_ts,
                               'order_retries': 0, 'cancel_sent': False, 'pend_vol': int(pend),
                               'recovered_pending': True}
                log('[安全] 对账A2: 补录在途买单 %s %d股(状态文件曾丢失, 防同一标的重复开仓), '
                    '后续由成交回报/超时撤单链路接管%s'
                    % (ocode, pend, ('; 基准量ctx缺失, 已按最近完成日量估算=%d(卖出量能口径恢复)' % _bv)
                       if _bv_est else ''))
            except Exception:
                continue
        # 方向D(P3-4拍板2026-10-08): 遗留单兜底扫描 —— 柜台存在本策略(BUY|/SELL| 前缀)存活
        # 委托, 但 ordids 未登记该 OrderID(登记丢失/状态文件落盘失败/撤单重报后旧单未撤净)时,
        # 正常撤单链路(精确 OrderID 匹配)永远够不到它, 会一直挂单并可能继续成交形成无主持仓。
        # 规则: 存活状态 + 本策略备注 + ordids 登记的该股id != 该委托id -> 遗留单, 启动对账
        # 顺手撤除(只撤不重发, 重发由正常买入/卖出链路决定); ordids 精确登记或状态文件在管
        # (hold 有该股, 含方向A2刚补录的)委托一律不动。
        if not DRY_RUN:
            try:
                _legacy_canceled = 0
                for o in ords:
                    try:
                        st = int(getattr(o, 'm_nOrderStatus', -1))
                        rm = str(getattr(o, 'm_strRemark', '') or '')
                        if st not in ACTIVE_ORDER_STATUS:
                            continue
                        if not (rm.startswith('BUY|') or rm.startswith('SELL|')):
                            continue
                        oid = str(getattr(o, 'm_strOrderID', '') or '')
                        ocode = '%s.%s' % (getattr(o, 'm_strInstrumentID', ''),
                                           getattr(o, 'm_strExchangeID', ''))
                        if not oid or oid == '-1' or ocode in hold:
                            continue
                        # V2.6.159: 任一方向登记过就算正常在途(此处不区分方向, 只判存在)
                        if _oid_known(ocode, oid):
                            continue          # ordids 精确登记: 正常在途, 不动
                        if _api(can_cancel_order, oid, G.accid, 'STOCK')                                 and _api(cancel, oid, G.accid, 'STOCK', G.C) is not False:
                            _legacy_canceled += 1
                            log('[安全] 对账D: 撤除遗留单 %s OrderID=%s(状态%s, 备注%s): '
                                'ordids未登记该ID, 防挂单继续成交成无主持仓'
                                % (ocode, oid, st, rm[:40]))
                        else:
                            log('[安全] 对账D: 遗留单撤单被拒 %s OrderID=%s(状态%s), 下轮对账重试'
                                % (ocode, oid, st))
                    except Exception:
                        continue
                if _legacy_canceled:
                    log('[安全] 对账D完成: 本轮共撤除遗留单%d笔(只撤不重发)' % _legacy_canceled)
            except Exception:
                log('[安全] 对账D异常: 遗留单扫描失败, 下轮对账重试')
                traceback.print_exc()
        # 方向A: 实盘有、状态文件没有 → 仅当存在新鲜buy_ctx(3日内本策略买入上下文)时补录
        # (P1-19: 状态文件丢失场景下, 柜台里确属本策略买入的持仓必须重新接管,
        #  否则成为永久孤儿仓: 不卖出/不占名额/不计盈亏); 其余不写入状态文件,
        #  防重复买入由 run_round 买入循环直接检查 pos_total(实盘持仓)实现
        for code in list(pt.keys()):
            if code in hold:
                continue
            bctx = (G.state.get('buy_ctx') or {}).get(code) or {}
            if not bctx or now_ts - _f(bctx.get('ts', 0)) > 3 * 86400:
                continue      # 无本策略买入痕迹: 视为手工/其他策略持仓, 不碰
            c_vol, ci = pt[code]
            c_px = _f(getattr(ci, 'm_dOpenPrice', 0.0)) or _f(bctx.get('price', 0.0))
            _bv, _bv_est = int(bctx.get('base_vol', 0) or 0), False
            if _bv <= 0:            # 重审20261005(1-6): base_vol兜底估算, 防补录仓永无自动卖出出口
                _bv, _bv_est = _estimate_base_vol(code)
            hold[code] = {'t0': bctx.get('t0', ''), 'base_vol': _bv,
                          'zt_close': _f(bctx.get('zt_close', 0.0)), 'name': bctx.get('name', ''),
                          'buy_date': G.today or datetime.datetime.fromtimestamp(now_ts).strftime('%Y%m%d'),
                          'buy_price': c_px, 'buy_vol': int(c_vol), 'paper': DRY_RUN,
                          'managed': True, 'fill_sum': c_px * int(c_vol), 'fill_vol': int(c_vol),
                          'exited': False, 'fee': 0.0,
                          'cost_total': _round2(c_px * int(c_vol) + fee_buy(c_px * int(c_vol), code)), 'last_px': 0.0,
                          'open_ts': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                          'alert_win': 0, 'alert_loss': 0, 'order_ts': 0.0,
                          'order_retries': 0, 'cancel_sent': False, 'recovered': True}
            log('[安全] 对账A: 补录本策略持仓 %s %d股(存在新鲜买入上下文, 状态文件曾丢失, '
                '已重新接管管理)%s'
                % (code, int(c_vol), ('; 基准量ctx缺失, 已按最近完成日量估算=%d' % _bv)
                   if _bv_est else ''))
        orphans = [code for code in pt if code not in hold]
        # P1-7修复(2026-10-02): 孤儿仓可见化 + 人工一键接管(用户定稿: 不自动接管)。
        #   现状: 状态文件丢失且超过3天 -> 柜台持仓无新鲜buy_ctx -> 既不接管也不卖出, 成为
        #   永久孤儿仓(策略不卖/不占名额/不计盈亏, 用户无从知晓)。现登记到状态文件并响亮提示;
        #   人工确认后把代码写入状态文件 "orphan_adopt": ["600000.SH", ...] 即由策略按柜台
        #   成本一键接管(下一轮对账生效), 接管后按正常持仓管理(绝不亏损卖出铁律同样适用)。
        _adopt = G.state.get('orphan_adopt')
        if not isinstance(_adopt, list):
            _adopt = []
        _adopted = []
        for code in list(orphans):
            if code not in _adopt:
                continue
            try:
                c_vol, ci = pt[code]
            except Exception:
                continue
            c_px = _f(getattr(ci, 'm_dOpenPrice', 0.0))
            bctx = (G.state.get('buy_ctx') or {}).get(code) or {}
            _bp = c_px if c_px > 0 else _f(bctx.get('price', 0.0))
            hold[code] = {'t0': bctx.get('t0', ''), 'base_vol': int(bctx.get('base_vol', 0) or 0),
                          'zt_close': _f(bctx.get('zt_close', 0.0)), 'name': bctx.get('name', ''),
                          'buy_date': G.today or datetime.datetime.fromtimestamp(now_ts).strftime('%Y%m%d'),
                          'buy_price': _bp, 'buy_vol': int(c_vol), 'paper': DRY_RUN, 'managed': True,
                          'fill_sum': _round2(_bp * int(c_vol)), 'fill_vol': int(c_vol),
                          'exited': False, 'fee': fee_buy(_bp * int(c_vol), code), 'cost_total': _round2(_bp * int(c_vol) + fee_buy(_bp * int(c_vol), code)),
                          'last_px': 0.0,
                          'open_ts': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                          'alert_win': 0, 'alert_loss': 0, 'order_ts': 0.0,
                          'order_retries': 0, 'cancel_sent': False, 'adopted_manual': True}
            _adopted.append(code)
            log('[安全] 对账A3(人工一键接管): %s %d股 按柜台成本%.2f纳入策略管理'
                % (code, int(c_vol), _bp))
        if _adopted:
            G.state['orphan_adopt'] = [c for c in _adopt if c not in _adopted]
            log('[安全] 人工接管完成%d只, 已从 orphan_adopt 清单移除' % len(_adopted))
        _orphan_left = sorted([c for c in orphans if c not in hold])
        if _orphan_left:
            G.state['orphans'] = {'date': G.today, 'codes': _orphan_left}
            # 20261008 用户定稿: 非策略股票买卖信息不进策略日志 —— 人工待办只提示数量,
            # 不列出非策略持仓代码(明细写入状态文件 orphans 供人工核对, 不打印到日志/推送)。
            log('[安全][人工待办] 柜台另有非本策略持仓%d只(无本策略买入记录, 状态文件丢失超3天或他方持仓)'
                ' —— 策略不卖/不占名额/不计盈亏。明细不输出到策略日志, 已存状态文件 orphans 字段。'
                '若确认属本策略标的, 请在状态文件 orphan_adopt 写入 [代码...] 后等待下轮对账自动接管'
                '(也可在券商端自行处理)' % len(_orphan_left))
        # 汇总日志: 只报本策略自身标的对账结果, 不输出实盘账户非本策略持仓只数(账户级信息不写入策略日志)
        own_n = len(hold)
        log('[安全] 对账完成: B清脏%d只 C修正%d只 | 状态文件持仓%d只(全部为本策略自身标的) | 实盘另有非本策略持仓(不写入状态文件, 买入循环直接检查实盘持仓防重复)'
            % (len(removed), len(bad_fixed), own_n))
        if bad_fixed:
            log('[安全] 对账C详情: %s' % '; '.join(bad_fixed))
        if removed:
            log('[安全] 对账B: 清理脏记录%d条(明细不输出)' % len(removed))
        if orphans or bad_fixed or removed or _recon_changed:
            save_state()

def day_pos(tick, lp):
    """当前价在当日(最低~最高)区间中的相对位置: 0=当日最低, 1=当日最高。
    取 tick 的 high/low; 数据缺失或无振幅时返回 None(视为无法判断, 不拦)"""
    hi = _f((tick or {}).get('high'))
    lo = _f((tick or {}).get('low'))
    if hi <= 0 or lo <= 0 or hi < lo:
        return None
    if hi - lo <= 1e-9:
        return 0.5
    p = (lp - lo) / (hi - lo)
    return 0.0 if p < 0 else (1.0 if p > 1 else p)


def in_high_zone(pos):
    """是否处在当日振幅的高位区(前 PYRAMID_HIGH_ZONE_PCT), 是则不执行本批"""
    if pos is None:
        return False
    return pos >= (1.0 - PYRAMID_HIGH_ZONE_PCT)


def pyramid_alloc(plan_vol, code=''):
    """把计划总股数按 PYRAMID_RATIOS 拆成各批股数: 按该板块最小申报单位只舍不入,
    余数按最大余额法分配, 保证各批之和 == plan_vol(总仓位与一次性买入完全一致,
    资金/仓位/费用口径不变)。
    P1-1(第18轮审计): 新增 code 形参 —— 旧版恒按100股拆, 科创板(688)首批常不足200股
    而被 normalize_buy_volume 整单拒发; 现按 _lot_of(code) 取步长(科创板200股)。"""
    lot = _lot_of(code)   # P1-1(第18轮审计): 按板块取最小申报单位
    n = int(PYRAMID_SPLITS) if PYRAMID_SPLITS > 0 else 1
    plan_vol = int(plan_vol)
    if n <= 1 or plan_vol < lot:
        return [int(plan_vol // lot * lot)]
    r = list(PYRAMID_RATIOS) if PYRAMID_RATIOS else [1.0]
    if len(r) < n:
        r = r + [1.0] * (n - len(r))
    r = r[:n]
    tot = sum(r) or 1.0
    hands = int(plan_vol // lot)               # 总手数(plan_vol 已是 lot 的整数倍)
    if hands <= 0:
        return []
    n = min(n, hands)                          # 手数不够分时自动减少批次, 保证每批 >= 1手
    r = r[:n]
    tot = sum(r) or 1.0
    raw = [hands * x / tot for x in r]         # 最大余额法: 先取整数手, 余数按小数部分从大到小分配
    base = [int(x // 1) for x in raw]
    rest = hands - sum(base)
    order = sorted(range(n), key=lambda i: raw[i] - base[i], reverse=True)
    for k in range(rest):
        base[order[k % n]] += 1
    return [int(b * lot) for b in base]


def pyramid_remain(h):
    """该票还有多少股没买(计划总股数 - 已买股数); 无分批计划的返回0"""
    try:
        plan_vol = int(h.get('plan_vol', 0) or 0)
    except Exception:
        plan_vol = 0
    if plan_vol <= 0 or h.get('plan_done'):
        return 0
    return max(0, plan_vol - pos_vol(h))


def _set_buy_ctx(code, ctx):
    """P0-2修复(2026-10-04): 统一买入上下文(buy_ctx)写入, 供 buy_stock/重报/pyramid_add 三处共用。
    背景: 旧版只在 buy_stock 主路径写 buy_ctx, 重报与分批加仓成交后若本地 hold 被清理,
    补录建仓找不到新鲜 buy_ctx(3天失效)而退化成 base_vol=0, 留下"柜台有仓、策略无记录"敞口。
    ctx 需含: name/t0/base_vol/zt_close/vol/price; 内部做 3 天时效清理 + setdefault。
    返回写入是否成功(布尔)。"""
    try:
        if not code:
            return False
        bctx = G.state.setdefault('buy_ctx', {})
        if not isinstance(bctx, dict):
            bctx = {}
            G.state['buy_ctx'] = bctx
        now_ts = time.time()
        for k in [x for x, v in bctx.items()
                  if isinstance(v, dict) and now_ts - _f(v.get('ts', 0)) > 3 * 86400]:
            bctx.pop(k, None)
        ctx = dict(ctx or {})
        ctx['ts'] = now_ts
        bctx[code] = ctx
        return True
    except Exception:
        log('[警告] 买入委托上下文(buy_ctx)保存失败, 成交回报补录可能失效')
        traceback.print_exc()
        return False


def pyramid_add(s, h, lp, vol, batch_idx, batch_total, reason, tick=None):
    """分批加仓: 实盘委托发出, 成交后由deal_callback自动校准fill_vol/成本均价等字段。
    P0-2加固: 委托发出时不再预累加buy_vol, 股数与成本全部由成交回报(fill_vol/fill_sum)校准
    重审20261005(P2-1): 返回值由True/False改为实际委托价px(滑点+夹取后)/0.0 ——
    调用方按实际委托价扣减现金, 与买入主路径口径一致, 旧版按lp扣减会低估占用。"""
    vol = normalize_buy_volume(s, vol)
    if vol <= 0:
        return 0.0

    # V2.6.82修复(2026-10-19): 原校验(V2.6.78 P2-2)引用了从未定义的PYRAMID_BATCHES ——
    #   凡vol>=100的加仓调用必抛NameError, 经 run_pyramid_adds -> _run_round_unlocked 冒泡,
    #   使整轮轮询在卖出完成后崩溃(新买入与分批加仓永久被堵, 每轮刷异常日志)。
    #   现改为与该票"实际分批计划"的长度比对: 调用方传入的 batch_total 本就取自
    #   len(h['plan_batches']), 不相等即为真bug; 手数不足自动缩批(长度<PYRAMID_SPLITS)
    #   属正常行为, 不再误告警。
    _bn_plan = len(h.get('plan_batches') or [])
    if _bn_plan > 0 and batch_total != _bn_plan:
        log(disp(s), '[参数一致性告警] 分批加仓批数不一致: 传入%d批 != 本票计划%d批, 日志批次显示可能有误'
            % (batch_total, _bn_plan))
    _eb = emergency_block('add')
    if _eb:
        log(disp(s), '分批加仓暂缓: %s' % _eb)
        return 0.0
    if not buy_scope_ok(s):
        # 交易铁律: 非策略标的(候选池外/无分批计划)一律拒绝买入
        scope_refuse(s, '买入(分批加仓)')
        return 0.0
    # V2.6.83: 发单前复核排雷清单(选股后清单可能已更新; 只拦新增买入, 不影响卖出)
    _rx = risk_excluded(s)
    if _rx:
        log(disp(s), '分批加仓拒绝: %s(发单前复核)' % _rx)
        return 0.0
    # P3-6(第18轮审计): 与 buy_stock 同口径 —— 人工黑名单盘中即时复核 + ST冠名复核。
    #   加仓也是买入动作, 旧版同样只依赖选股层那一次查询, 盘中新增避雷条目不生效。
    _bl = load_blacklist(force=True)
    if s in _bl:
        log(disp(s), '分批加仓拒绝: 人工黑名单(%s)(发单前即时复核)' % (_bl.get(s) or '人工标记'))
        return 0.0
    if EXCLUDE_ST:
        _nm_now = inst_name(s)
        if _nm_now and is_st_name(_nm_now):
            log(disp(s), '分批加仓拒绝: 已冠名ST/*ST(%s)(发单前复核)' % _nm_now)
            return 0.0
    # P1-2(2026-10-24 第18轮零预设独立审计): 分批加仓同样纳入硬双实例防护 ——
    #   旧版只有 buy_stock 新建买入有 _live_peer_exists() 拦截, 加仓/重报/卖出三处发单
    #   路径没有: 双实例误操作时两边各自评估各自发(各自内存里 plan_idx 都是同一批)。
    #   危害例: 计划9000股分3批, 实例A发第2批3000股、实例B也发第2批3000股,
    #   合计6000股, 单票上限66666.66元被突破且成本/费用/账本双记错乱。
    if _live_peer_exists():
        log('[安全][P1-2] 检测到存活的其它策略实例, 本轮回避分批加仓(防重复下单)')
        return 0.0
    amt = _round2(lp * vol)
    # P3(V2.6.83): 删除死变量 fee —— 本函数后续发单/扣款一律用 fee_buy(vol*px, s) 重算,
    #   该变量赋值后全函数零引用(白算一次费用)。
    if not can_trade():
        log(disp(s), '交易未就绪, 分批加仓暂缓等待下轮重试')
        return 0.0
    # 审计修复I2: 加仓限价同样上移滑点; I4: 保护带宽度按标的自适应
    # 第1条修复(2026-10-17): 与买入主路径统一用动态滑点 _slippage_for(lp) ——
    # 旧版用写死 SLIPPAGE_PCT(0.2%), 低价股(5元以下)主买入按0.3%算滑点、加仓仍按0.2%,
    # 同一票两套发单价口径不一致; 现按当前股价计算滑点, 与主买入完全一致。
    px = clamp_order_price(_round2(lp * (1.0 + _slippage_for(lp))), tick, True, s)
    if px <= 0:
        return 0.0
    # V2.6.168: 加仓侧与买入侧同口径卡帽子(单票绝对额度 / 组合剩余额度)
    #   上游算出的加仓数量是按"估算价格"折算额度的, 而真正下发的委托价已经过
    #   clamp_order_price() 夹过滑点(低价股滑点0.3%), 于是 used_capital() 扣的是实时价、
    #   额度却按旧价算, 加仓数量可能一次性把单票额度或组合额度顶穿。
    _amts_a168 = []
    if MAX_POS_VALUE_ABS and MAX_POS_VALUE_ABS > 0:
        _amts_a168.append(max(0.0, float(MAX_POS_VALUE_ABS) - _f(pos_cost(h))))
    _la168 = abs_cap_left(px)
    if _la168 is not None:
        _amts_a168.append(max(0.0, _f(_la168) * _f(px)))
    # P3-C-N3(2026-10-29 修复)：按标的真实最小申报单位裁量。
    #   原实现 lot 传 None -> cap_fit_volume 退回默认 100 股步长，科创板(688/689)首笔
    #   至少 200 股，裁剪后可能算出 100 股这种非法数量，发出必被柜台拒的委托，
    #   还白白消耗重试次数与当日买入机会。
    _lot_a168 = _lot_of(s)
    vol = cap_fit_volume(s, vol, px, _lot_a168, _amts_a168, '分批加仓')
    if vol > 0:
        try:
            vol = normalize_buy_volume(s, vol)   # 二次规范化，确保满足板块申报规则
        except Exception:
            pass
    if vol <= 0:
        log(disp(s), '分批加仓被拦下: 委托价%.2f元下, 实际买入会顶穿单票/组合额度或不足最小申报量' % _f(px))
        return 0.0
    # P3-C-N3：科创板当日已被拒过单的标的直接跳过加仓，防整日反复废单
    try:
        if is_kcb_code(s) and (G.kcb_reject_date or {}).get(s) == G.today:
            log(disp(s), '科创板当日已被柜台拒单，分批加仓跳过(防重复废单)')
            return 0.0
    except Exception:
        pass
    if DRY_RUN:          # 审计修复I7: 模拟盘不真发单, 构造成交回报走deal_callback记账
        h['pend_vol'] = int(vol)
        h['order_ts'] = time.time()
        try:
            if not _sim_deal('BUY|' + s, px, vol):
                # P2-01: 模拟成交未命中: 清在途标记, 由run_pyramid_adds下轮重新评估
                log(disp(s), '模拟盘分批加仓未成交(成交概率%.0f%%), 本轮暂缓' % (SIM_FILL_PROB * 100))
                h['pend_vol'] = 0
                h['order_ts'] = 0.0
                return 0.0
        except Exception:
            log(disp(s), '模拟盘分批加仓构造成交回报异常')
            traceback.print_exc()
            return 0.0
        G.buy_cnt += 1
        dry_cash_delta(-_round2(vol * px + fee_buy(vol * px, s)))   # V2.6.71修复: 模拟盘加仓扣款改用真实费用fee_buy(旧版粗估FEE_RATE_EST 0.15%高估, 模拟现金被过度扣减致少买/加仓堵塞)
        log('[模拟盘] 分批加仓成交 | %s | 第%d/%d批 %d股 限价@%.2f | 金额约=%.2f元 | %s'
            % (disp_code(s, h.get('name', '')), batch_idx, batch_total, vol, px, amt, reason))
        save_state()
        return px
    try:
        if limit_gate_reject(s, px, True, '分批加仓'):
            return 0.0
        # P0-2: 在途量必须在passorder之前设置, 否则同步成交回报无法核销,
        # 导致run_pyramid_adds误判"仍有在途委托"而跳过下一批
        h['pend_vol'] = int(vol)
        h['order_ts'] = time.time()      # 在途委托时间戳(供run_pyramid_adds等待/超时判定)
        # 审计修复P1-1: 发单前先把在途标记(hold/pend_vol/order_ts)落盘 ——
        # 否则"passorder成功 -> save_state"之间崩溃重启后状态文件无该笔记录,
        # 柜台未成交委托又不在POSITION查询内, 下一轮会重复下单
        if not save_state(critical=True):
            log(disp(s), '[关键告警][状态落盘失败取消发单] 交易关键状态无法落盘, 已取消本次分批加仓发单')
            return 0.0
        log('[应急闸门][通过] 分批加仓 | %s | mode=%s | 第%d/%d批%d股'
            % (disp_code(s, h.get('name', '')), emergency_mode_effective(), batch_idx, batch_total, vol))
        _api(passorder, 23, 1101, G.accid, s, 11, px, vol,
                  STRAT_TAG, 2, 'BUY|' + s + '|ADD', G.C)   # 重审20261006(P0-B/问题2): 加仓单备注加|ADD后缀区分新建仓
        G.buy_cnt += 1
        # P0-2: 只登记在途量, 不动buy_vol/成本 —— 股数与成本由成交回报校准
        # P0-2修复(2026-10-04): 加仓同样写buy_ctx兜底 —— 成交回报晚于hold被清理时可凭此补录建仓
        _set_buy_ctx(s, {'name': h.get('name', ''), 't0': h.get('t0', ''),
                         'base_vol': h.get('base_vol', 0), 'zt_close': h.get('zt_close', 0.0),
                         'vol': int(vol), 'price': _round2(px)})
        log('[实盘] 分批加仓委托已发 | %s | 第%d/%d批 %d股 限价@%.2f | 金额约=%.2f元 | %s'
            % (disp_code(s, h.get('name', '')), batch_idx, batch_total, vol, px, amt, reason))
        daily_add_done(s)      # P2-27: 加仓笔数如实记账(独立桶, 不占新开仓额度)
        save_state()
        return px
    except Exception:
        # P0-2修复(2026-10-04): passorder异常不代表委托未送达柜台 —— 标记"提交未知",
        # 保留在途量并补写buy_ctx, 下一轮先查柜台ORDER确认无在途委托再决定是否重试,
        # 防止"实际已成交但仅返回异常"导致重复加仓(对齐buy_stock主路径处置口径)
        log(disp(s), '分批加仓下单异常, 下轮先查柜台确认委托状态再重试(标记提交未知, 不直接重发)')
        traceback.print_exc()
        h['buy_submit_unknown'] = True
        h['pend_vol'] = int(vol)
        h['order_ts'] = h.get('order_ts') or time.time()
        _set_buy_ctx(s, {'name': h.get('name', ''), 't0': h.get('t0', ''),
                         'base_vol': h.get('base_vol', 0), 'zt_close': h.get('zt_close', 0.0),
                         'vol': int(vol), 'price': _round2(px)})
        try:
            save_state(critical=True)
        except Exception:
            traceback.print_exc()
        return 0.0


def risk_increase_allowed():
    """统一增险门禁：状态、账户、数据、手工封锁及组合熔断任一异常即拒绝。"""
    _eb = emergency_block('add')
    if _eb:
        return False, _eb
    if not can_trade():
        return False, '交易/状态未就绪'
    # P0-2/P0-3修复(2026-10-02): 与新开仓共用同一数据闸门(强提示 + 严重缺失才收紧) ——
    #   旧版此处按 data_ready(<80%) 与 loss_data_ok 硬拦, 而新开仓完全不检查, 口径分裂;
    #   轻度缺失(60%~80%)现只强提示不拦, 严重缺失(<60%/财务完全不可用/行情连续不可用)才拦。
    _blk, _why, _alert = data_gate()
    if _alert:
        data_quality_alert(_why)
    if _blk:
        return False, _why
    if daily_buy_blocked()[0]:
        return False, '外部手工封锁'
    fm = pnl_meta()
    if fm.get('hard_dd_until'):
        return False, '组合硬回撤约束生效'
    until = str(fm.get('fuse_until', '') or '')
    if until and (until == '99991231' or not G.today or G.today <= until):
        return False, '组合熔断生效'
    if (G.pnl or {}).get('stale_n', 0):
        return False, '持仓行情陈旧(%d轮无有效最新价)' % int((G.pnl or {}).get('stale_n', 0))
    # [P0-1/P0-2 FIX 2026-10-16] 闸门口径对齐: 退潮期也暂停分批加仓(与can_open_new同口径)
    # 原risk_increase_allowed()完全没有market_tide_check()调用, 大盘暴跌时加仓继续买入
    # 导致增险闸门口径分裂(新开仓和加仓风控不一致)
    if market_tide_check():
        return False, "市场退潮期(%s近%d日跌幅超%.0f%%), 暂停分批加仓" % (
            MARKET_TIDE_INDEX, MARKET_TIDE_LOOKBACK, MARKET_TIDE_DROP_PCT * 100)
    # 情绪模块L1: 恐慌/狂热/极端事件闸门
    # V2.6.151: 数据未就绪同样拦截(与 can_open_new 同口径), 原因分开打
    _sent_note2 = sent_block_note()
    if _sent_note2:
        return False, '%s, 暂停分批加仓' % _sent_note2
    return True, ''

def run_pyramid_adds(ticks, cash, ords_snap=None):
    """分批建仓的后续批次: 逐只检查已开仓但未买满的票, 按价格位置决定是否继续低吸。
    规则(集中可调): 不在当日高位区 -> 不高于首笔价x(1+ADD_MAX_UP_PCT) -> 间隔>=MIN_GAP_MIN分钟
    -> 当日批次<MAX_PER_DAY -> 现金足够; 当日不满足则顺延到后续交易日, 超过
    MAX_WAIT_TRDAYS 后按 EXPIRE_MODE 放弃剩余(keep)或不看价位补足(fill)。返回剩余现金。
    P1-01: ords_snap=锁外预取的委托快照, 透传buy_order_obj避免锁内重复柜台查询"""
    # 第6条修复(2026-10-17): tick量单位异常拉闸时, 分批加仓同样强制拦截(与主买入buy_stock一致)
    if _tick_unit_blocked():
        log('分批加仓暂停: tick量单位异常已拉闸(连续多日疑似"股"而非"手"), 暂停买入等待人工确认行情源')
        return cash
    _ok, _why = risk_increase_allowed()
    if not _ok:
        log('分批加仓暂停: %s' % _why)
        return cash
    for s, h in list((G.state.get('hold') or {}).items()):
        if not PYRAMID_ON:
            break
        if h.get('plan_done') or not h.get('plan_batches'):
            continue                                  # 老状态/一次性建仓的票: 不补买
        if h.get('exited'):
            continue
        # P3-C-N5(2026-10-29 修复)：正在卖出/放弃卖出的标的绝不能再续买。
        #   原实现只挡 exited，卖单在途或 sell_giveup 期间仍会走加仓通道 ——
        #   报告实测：卖出后又在同一天把票买回来，绕过 REBUY_GAP 与当日买入上限。
        if h.get('sell_giveup') or (G.state.get('sell_ctx') or {}).get(s) \
                or _f(h.get('sell_ts', 0.0)) > 0:
            continue                                  # 卖出流程中: 不再加仓
        if is_handoff(h):
            continue                                  # 已移交人工: 不再续买后续批次
        if int(_f(h.get('fill_vol', 0) or 0)) <= 0:
            # P1-6加固: 首笔未成交前绝不发后续批次(否则首笔+批次并存, 撤单重报会超配)
            continue
        # 重审20261006(P0-A/问题1): 消费 pyramid_add 异常路径残留的"提交未知"标记 ——
        # 旧版此处只查 pend_vol, 不消费 buy_submit_unknown; 一旦柜台查询失败(_ERR)直接
        # continue, 标记永久残留, 之后该票进入 handle_unfilled_buy 主买入通道时会被误当作
        # "在途主买单"按残留 pend_vol 重发, 导致同一批股数被买两次(重复下单)。
        # 现于加仓通道内主动消费: 先查柜台确认该笔加仓单是否送达, 再决定等待/撤单/清标记。
        if h.get('buy_submit_unknown'):
            _o_unk = buy_order_obj(s, ords_snap)      # P1-01: 用锁外预取快照
            if _o_unk == '_ERR':                      # 查询失败: 保留标记等下轮复核, 绝不重发
                log(disp(s), '分批加仓提交未知标记复核: 柜台查询失败, 保留标记等下轮复核(不重发)')
                save_state()
                continue
            _st_unk = int(getattr(_o_unk, 'm_nOrderStatus', -1)) if _o_unk else -1
            if _o_unk is not None and _st_unk in ACTIVE_ORDER_STATUS:
                # 加仓单其实已送达柜台且在途: 正常等待成交, 绝不重发
                h['buy_submit_unknown'] = False
                h['order_ts'] = time.time()
                log(disp(s), '分批加仓提交未知标记复核: 委托已送达柜台且在途(状态%s), 正常等待成交'
                    % ORDER_STATUS_MAP.get(_st_unk, '未知状态(%s)' % _st_unk))
                save_state()
                continue
            if _o_unk is not None and _st_unk == 56:
                # 加仓单实际已成: 由 deal_callback 接管记账, 只清标记与在途量
                h['buy_submit_unknown'] = False
                h['pend_vol'] = 0
                log(disp(s), '分批加仓提交未知标记复核: 委托已成交(状态%s), 由成交回报接管记账, 清在途标记'
                    % ORDER_STATUS_MAP.get(_st_unk, '未知状态(%s)' % _st_unk))
                save_state()
                continue
            # 委托确未送达或已终结: 安全清掉标记与在途量, 下轮按剩余计划重新评估
            h['buy_submit_unknown'] = False
            h['pend_vol'] = 0
            h['cancel_sent'] = False
            log(disp(s), '分批加仓提交未知标记复核: 柜台无该加仓在途单, 已安全清除标记与在途量(防重复下单), 下轮按剩余计划重估')
            save_state()
            continue
        if int(_f(h.get('pend_vol', 0) or 0)) > 0:
# P0-2配套: 上一笔买入委托仍在途, 先等它落地(成交回报会更新fill_vol并清pend_vol);
            # 超时则查柜台: 仍存活先撤再等下一轮, 已终结直接清掉在途标记
            _o = buy_order_obj(s, ords_snap)      # P1-01: 用锁外预取快照
            if _o == '_ERR':                 # 风险2修复: 查询失败不清 pend_vol, 等下轮复核
                continue
            _st = int(getattr(_o, 'm_nOrderStatus', -1)) if _o else -1
            if _o and _st in ACTIVE_ORDER_STATUS:
                if time.time() - _f(h.get('order_ts', 0.0)) > BUY_ORDER_TIMEOUT_SEC \
                        and not h.get('cancel_sent'):
                    if cancel_buy_order(s, _o):
                        h['cancel_sent'] = True
                        log(disp(s), '分批加仓委托超时未成交, 已发撤单(确认后按剩余计划重估)')
                        save_state()
                continue
            h['pend_vol'] = 0
            h['cancel_sent'] = False
            # P2-22: 委托已终结(撤单成功/废单)且该批未买满时回退批次号 ——
            # 旧逻辑批次号在发单时已前移且撤单后不补发, 该批永久丢失导致仓位<计划。
            # 回退后下一轮按 remain(=plan_vol-pos_vol)重新执行该批, 永远不会超配。
            if pyramid_remain(h) > 0 and int(h.get('plan_idx', 0) or 0) > 0 \
                    and int(_f(h.get('fill_vol', 0) or 0)) > 0:
                h['plan_idx'] = int(h.get('plan_idx', 0) or 0) - 1
                log(disp(s), '分批批次未完成(委托已终结), 回退批次号重估(第%d批)' % (int(h.get('plan_idx', 0)) + 1))
            save_state()
            continue
        t = (ticks or {}).get(s) or {}
        lp = _f(t.get('lastPrice'))
        if lp <= 0:
            continue
        batches = [int(x) for x in (h.get('plan_batches') or [])]
        idx = int(h.get('plan_idx', 0) or 0)          # 已提交/已成交批次数（最终完成由成交回报确认）
        _day_min = int(elapsed_trading_minutes(datetime.datetime.now()))
        _bar_cnt = int(_f(t.get('bar_cnt', 0)) or 0)
        if _day_min < PYRAMID_MIN_DAY_MINUTES or _bar_cnt < PYRAMID_MIN_DAY_BARS:
            if h.get('pyr_mature_note_date') != G.today:
                h['pyr_mature_note_date'] = G.today
                log(disp(s), '分批加仓暂缓: 当日价格区间样本未成熟(已开盘%d分钟, 1m样本%d根; 要求>=%d分钟且>=%d根), 防首分钟高位区误判'
                    % (_day_min, _bar_cnt, PYRAMID_MIN_DAY_MINUTES, PYRAMID_MIN_DAY_BARS))
            continue
        if idx >= len(batches):
            h['plan_done'] = True
            continue
        remain = pyramid_remain(h)
        if remain <= 0:
            h['plan_done'] = True
            continue
        # ---- 到期处理: 超出最长等待 ----
        waited = held_trd_days(h.get('plan_date', ''))
        # ---- [2026-10-20 V2.6.102] 到期分级: 赢家给机会(延长等待), 输家不补仓 ----
        #  老毛病: 到期不分好坏一视同仁 —— 还在赚钱的票(只是这几天一直没回调到低位)
        #  被硬砍掉剩余仓位, 亏钱的票反而可能被 fill 一次性补齐(越亏越补, 仓位越重越难翻身)
        #  改法: 浮盈(现价 > 持仓成本) -> 等待期 +3 个交易日, 多给几次回调机会;
        #          浮亏(现价 <= 持仓成本) -> 到期就作废剩余计划, 且绕开 fill(绝不补仓)。
        #  只决定"还等不等 / 补不补", 不碰卖出判据、不碰止损。
        _ex_cvol = pos_vol(h)
        _ex_cost = (pos_cost(h) / _ex_cvol) if _ex_cvol > 0 else _f(h.get('buy_price', 0) or 0)
        _ex_win = _ex_cost > 0 and lp > _ex_cost
        _ex_wait = (PYRAMID_MAX_WAIT_TRDAYS + 3) if _ex_win else PYRAMID_MAX_WAIT_TRDAYS
        if PYRAMID_MAX_WAIT_TRDAYS > 0 and waited > _ex_wait:
            if not _ex_win:
                # 输家: 到期立即放弃, 不补仓(fill 路线也绕开)
                if h.get('pyr_note_date') != G.today:
                    h['pyr_note_date'] = G.today
                    log(disp(s), '加仓到期放弃(输家): 已等%d个交易日, 现价%.2f<=成本%.2f(浮亏), '
                           '剩余%d股不再补仓, 剩余计划作废(票继续持有, 绝不止损)'
                           % (waited, lp, _ex_cost, int(remain)))
                h['plan_done'] = True
                continue
            if PYRAMID_EXPIRE_MODE == 'fill' and remain >= 100:
                # [P1-2 FIX 2026-10-16] 超期fill路径补齐三重闸门(原只检查现金)
                # 原fill路径: 超过PYRAMID_MAX_WAIT_TRDAYS后不看价位一次性补足,
                # 只验证了现金够不够, 跳过了正常路径的
                #   ①单票市值上限(MAX_POS_VALUE_PCT)
                #   ②组合绝对资金封顶(STRATEGY_CASH_CAP)
                # 导致超期补足时可能突破单票上限(MAX_POS_VALUE_ABS)/组合20万(STRATEGY_CASH_CAP)硬约束
                _fill_vol = remain
                _eq_now = size_equity()
                # ①单票市值上限复核(与正常路径一致)
                if MAX_POS_VALUE_PCT > 0 and MAX_POS_VALUE_ABS > 0 and _eq_now >= 0 and lp > 0:   # V2.6.78 P0-1: eq_now=0时也走闸门检查(=0会自动cap到0股)   # V2.6.74: 超期补足单票额度复核同时受相对与绝对上限约束
                    _cap = int((min(_eq_now * MAX_POS_VALUE_PCT, MAX_POS_VALUE_ABS) - lp * pos_vol(h)) / lp / 100) * 100
                    if _cap < _fill_vol and _cap >= 100:
                        _fill_vol = _cap
                        log(disp(s), "[超期补足] 按当前权益单票额度上限%.0f元砍掉补足量到%d股" % (MAX_POS_VALUE_ABS, _fill_vol))
                    elif _cap < 100:
                        log(disp(s), "[超期补足] 当前权益下单票额度已达上限%.0f元(全超限), 放弃fill顺延" % (MAX_POS_VALUE_ABS))
                        h["plan_done"] = True
                        continue
                # ②绝对资金封顶复核(与正常路径一致)
                _cap_abs = abs_cap_left(lp)
                if _cap_abs is not None:
                    _vol_cap = int(math.floor(_cap_abs / 100.0)) * 100
                    if _vol_cap < _fill_vol and _vol_cap >= 100:
                        _fill_vol = _vol_cap
                        log(disp(s), "[超期补足] 绝对资金封顶约束下砍掉补足量到%d股" % _fill_vol)
                    elif _vol_cap < 100:
                        log(disp(s), "[超期补足] 绝对资金封顶约束下剩余额度<100股, 放弃fill")
                        h["plan_done"] = True
                        continue
                # ③现金检查(原路径就有)
                _fill_vol = min(int(_fill_vol), int(remain // 100 * 100))
                if _fill_vol >= 100 and lp * _fill_vol + fee_buy(lp * _fill_vol, s) <= cash:   # V2.6.71: 现金校验改真实费用
                    _px = pyramid_add(s, h, lp, _fill_vol, idx + 1, len(batches),
                                      "分批等待超%d个交易日, 按设定不看价位一次性补足剩余%d股"
                                      % (PYRAMID_MAX_WAIT_TRDAYS, _fill_vol), t)
                    if _px > 0:
                        cash -= _round2(_px * _fill_vol + fee_buy(_px * _fill_vol, s))   # V2.6.71: 按实际委托价+真实费用扣减
                        idx += 1
                        h["plan_idx"] = idx
                elif _fill_vol >= 100:
                    log(disp(s), "[超期补足] 可用资金不足, 放弃fill(%d股, 需%.0f元)" % (_fill_vol, lp * _fill_vol))
            if h.get('pyr_note_date') != G.today:
                h['pyr_note_date'] = G.today
                if PYRAMID_EXPIRE_MODE != 'fill' or remain < 100:
                    log(disp(s), '分批等待超%d个交易日(已%d日), 放弃剩余%d股(计划%d股/已买%d股), '
                           '已买部分继续按原规则持有'
                           % (_ex_wait, waited, remain,
                              int(h.get('plan_vol', 0) or 0), pos_vol(h)))
            h['plan_done'] = True
            continue
        elif (PYRAMID_MAX_WAIT_TRDAYS > 0 and _ex_win and waited > PYRAMID_MAX_WAIT_TRDAYS
              and h.get('pyr_ext_note_date') != G.today):
            # 赢家: 已过原等待期但尚在延长期内, 每天提醒一次
            h['pyr_ext_note_date'] = G.today
            log(disp(s), '加仓等待延长(赢家): 已等%d个交易日, 现价%.2f>成本%.2f(浮盈), '
                   '等待期延至%d个交易日继续等回调(未回调则不补仓)'
                   % (waited, lp, _ex_cost, _ex_wait))
        # ---- 常规批次: 价格位置 + 追高 + 间隔 + 当日批次 + 现金 ----
        pos = day_pos(t, lp)
        note = h.get('pyr_note_date')
        # ---- [2026-10-20 V2.6.101] 加仓 <-> 卖出 互锁: 加仓前先看离"卖出"还有多远 ----
        #  老毛病: 加仓只看"价格位置/追高/间隔", 卖出只看"放量/换手/到期", 两边互不通气,
        #  于是会出现"刚加完一批, 下一轮就被放量止盈卖掉": 白付一趟佣金+过户费+印花税,
        #  还把成本抬高(成本一高, 止盈线又跟着抬高, 反而更难卖)。此处用卖出侧同一把尺子
        #  (与卖出循环 est = vol * _tick_to_daily_scale() / k 完全同口径) 先量一次距离。
        #  只做两件事: 离卖出太近 -> 今天不加(明天量缩还能加); 已经能赚钱卖 -> 末批作废。
        #  绝不触发任何卖出、也绝不是止损(NEVER_STOP_LOSS 未动, 全程无止损单逻辑)。
        _il_vol = _f(t.get('volume'))
        _il_k = _proj_vol_ratio(float(_day_min))
        _il_est = (_il_vol * _tick_to_daily_scale() / _il_k) if _il_k > 0 else 0.0
        _il_base = _f(h.get('base_vol', 0) or 0)
        _il_line = sent_param('EXPAND_SELL_RATIO', EXPAND_SELL_RATIO) * SELL_TOL * (
            EARLY_SELL_VOL_MULT if _day_min < EARLY_SELL_END_MIN else 1.0)
        _il_ratio = (_il_est / _il_base) if _il_base > 0 else 0.0
        # ① 离放量止盈只差 15% 以内(=线 x 0.85, 早盘同理乘 1.5) -> 今天不再加仓
        if (_il_base > 0 and _day_min >= EARLY_SELL_BLOCK_MIN
                and _il_ratio >= _il_line * 0.85):
            if note != G.today:
                h['pyr_note_date'] = G.today
                log(disp(s), '加仓%d/%d批暂缓: 预估全日量已达基准%.2f倍(放量止盈线%.2f倍, 已到%.0f%%), '
                       '离卖出很近, 今天不再加仓(非止损, 量缩后可再补)'
                       % (idx + 1, len(batches), _il_ratio, _il_line,
                          (_il_ratio / _il_line * 100) if _il_line > 0 else 0.0))
            continue
        # ② 末批与止盈联动: 只剩最后一批时, 若已能扣费净赚卖出 -> 末批作废, 不再补
        _il_cvol = pos_vol(h)
        _il_cost = (pos_cost(h) / _il_cvol) if _il_cvol > 0 else _f(h.get('buy_price', 0) or 0)
        if (len(batches) >= 2 and idx >= len(batches) - 1 and _il_cost > 0
                and lp > _il_cost * (1 + min_profit_pct(h, s))
                and net_pnl_if_sell(h, lp, s) > 0):
            if note != G.today:
                h['pyr_note_date'] = G.today
                log(disp(s), '加仓末批(第%d/%d批)取消: 现价%.2f已高于成本%.2f且扣费后仍净赚, '
                       '随时可能止盈, 剩余计划作废(不再补仓)'
                       % (idx + 1, len(batches), lp, _il_cost))
            h['plan_done'] = True
            continue
        if in_high_zone(pos):
            if note != G.today:
                h['pyr_note_date'] = G.today
                log(disp(s), '分批第%d/%d批暂缓: 现价%.2f处于当日振幅前%.0f%%高位区(位置%.0f%%, '
                       '区间%.2f~%.2f), 等回落或后续交易日'
                       % (idx + 1, len(batches), lp, PYRAMID_HIGH_ZONE_PCT * 100,
                          (pos or 0) * 100, _f(t.get('low')), _f(t.get('high'))))
            continue
        first_px = _f(h.get('first_price', 0.0))
        if PYRAMID_ADD_MAX_UP_PCT > 0 and first_px > 0 and lp > first_px * (1 + PYRAMID_ADD_MAX_UP_PCT):
            if note != G.today:
                h['pyr_note_date'] = G.today
                log(disp(s), '分批第%d/%d批暂缓: 现价%.2f高于首笔成交价%.2f的%.1f%%(上限%.1f%%), 等回调'
                       % (idx + 1, len(batches), lp, first_px,
                          (lp / first_px - 1) * 100, PYRAMID_ADD_MAX_UP_PCT * 100))
            continue
        if h.get('batch_date') == G.today and PYRAMID_MIN_GAP_MIN > 0:
            gap = time.time() - _f(h.get('batch_ts', 0.0))
            if 0 < gap < PYRAMID_MIN_GAP_MIN * 60:
                continue                              # 同一交易日内间隔不足(跨交易日自动放行)
        if (h.get('batch_date') == G.today and PYRAMID_MAX_PER_DAY > 0
                and int(h.get('batch_today_n', 0) or 0) >= PYRAMID_MAX_PER_DAY):
            if note != G.today:
                h['pyr_note_date'] = G.today
                log(disp(s), '分批第%d/%d批暂缓: 当日已成交%d批(上限%d批), 顺延到后续交易日'
                       % (idx + 1, len(batches), int(h.get('batch_today_n', 0) or 0),
                          PYRAMID_MAX_PER_DAY))
            continue
        vol = min(int(batches[idx]), int(remain // 100 * 100))
        if vol < 100:
            vol = int(remain // 100 * 100)
        if vol < 100:
            h['plan_done'] = True
            continue
        # P2-31: 加仓批次按"当前权益"复核单票市值上限 —— plan_batches是建仓日按当时
        # 权益算出的股数常量, 权益深度回撤后仍按原计划买满会把单票买到当前权益100%以上,
        # 与复利缩仓意图相悖(超限部分砍掉, 全部超限则顺延)
        _eq_now = size_equity()
        if MAX_POS_VALUE_PCT > 0 and MAX_POS_VALUE_ABS > 0 and _eq_now >= 0 and lp > 0:   # V2.6.79 P0-1: 与fill路径口径统一; 权益为0时也走检查(会自动cap到0股)
            _cap = int((min(_eq_now * MAX_POS_VALUE_PCT, MAX_POS_VALUE_ABS) - lp * pos_vol(h)) / lp / 100) * 100
            if _cap < vol:
                if _cap < 100:
                    if note != G.today:
                        h['pyr_note_date'] = G.today
                        log(disp(s), '分批第%d/%d批暂缓: 当前权益下单票额度已达上限%.0f元(权益收缩), 顺延'
                            % (idx + 1, len(batches), MAX_POS_VALUE_ABS))
                    continue
                vol = _cap
        # 第2条修复(2026-10-17): 现金校验改在"真正算出发单价"之后 —— 先按 动态滑点+涨跌停/笼子夹取
        #   算出实际委托价(与下方 pyramid_add 内部同一套口径), 再用 实际委托价x股数+精确手续费 判断;
        #   旧版用最新价 lp 估算(只乘FEE_RATE_EST预留), 与实发价不一致时边界资金会"校验通过但柜台拒单",
        #   白浪费当日买入机会(与 buy_stock 主路径 P2-15 同口径对齐)。
        _px_pyr = clamp_order_price(_round2(lp * (1.0 + _slippage_for(lp))), t, True, s)
        if _px_pyr <= 0:
            _px_pyr = _round2(lp)
        _need_pyr = vol * _px_pyr + fee_buy(vol * _px_pyr, s)
        if _need_pyr > cash:
            if note != G.today:
                h['pyr_note_date'] = G.today
                log(disp(s), '分批第%d/%d批暂缓: 可用资金不足(按实际委托价%.2f x %d股 + 手续费约%.2f = %.2f元, 现金%.2f)'
                       % (idx + 1, len(batches), _px_pyr, vol, fee_buy(vol * _px_pyr, s), _need_pyr, cash))
            continue
        # 2026-10-09第五轮审计修复: 分批加仓同样受"绝对资金封顶"约束(旧版只受现金与单票上限约束,
        #   账户现金远大于200000元时, 逐轮加仓可把组合总投入推过 STRATEGY_CASH_CAP)
        _cap_abs = abs_cap_left(lp)
        if _cap_abs is not None:
            _vol_cap = int(math.floor(_cap_abs / 100.0)) * 100
            if _vol_cap < vol:
                if _vol_cap < 100:
                    if note != G.today:
                        h['pyr_note_date'] = G.today
                        log(disp(s), '分批第%d/%d批暂缓: 本策略绝对资金封顶%.2f元已用满, 顺延'
                            % (idx + 1, len(batches), STRATEGY_CASH_CAP))
                    continue
                vol = _vol_cap
        _px = pyramid_add(s, h, lp, vol, idx + 1, len(batches),
                          '分批低吸第%d/%d批: 现价%.2f位于当日区间%.0f%%(非高位区), '
                          '首笔价%.2f, 累计%d/%d股'
                          % (idx + 1, len(batches), lp, (pos or 0) * 100, first_px,
                             pos_vol(h) + vol, int(h.get('plan_vol', 0) or 0)), t)
        if _px > 0:
            # 重审20261005(P2-1): 按实际委托价(滑点+夹取)扣减, 不再按lp
            cash -= _round2(_px * vol + fee_buy(_px * vol, s))   # V2.6.71修复: 分批加仓现金扣减改用真实费用fee_buy(旧版粗估0.15%高估, 边界资金误判不足)
            h['plan_idx'] = idx + 1
            h['batch_ts'] = time.time()
            # P2-1: 批次计数必须先判日期再自增(旧版先赋batch_date再判, 条件恒真,
            # PYRAMID_MAX_PER_DAY 退化为"首日N批、其后每日仅1批")
            if h.get('batch_date') != G.today:
                h['batch_date'] = G.today
                h['batch_today_n'] = 1
            else:
                h['batch_today_n'] = int(h.get('batch_today_n', 0) or 0) + 1
            if h['plan_idx'] >= len(batches) or pyramid_remain(h) <= 0:
                # V2.6.44b: 发单不等于成交，最终批保持plan_done=False以继续进入在途管理；
                # 仅成交回报确认实际股数达到计划后才置完成。
                h['plan_done'] = False
                log(disp(s), '分批建仓最终批委托已发: 第%d/%d批%d股, 等待成交确认 | 当前已成交%d股, 在途%d股'
                       % (idx + 1, len(batches), vol, pos_vol(h), int(_f(h.get('pend_vol', 0)) or 0)))
            save_state()
    return cash


# ==================== 交易层(passorder) ====================
def _norm_reason(r):
    """把带动态数值/价格的"跳过原因"归一到稳定的分类键, 使同一类原因在小时桶里
    聚合为一条(而非每次数值变化生成新键)。规则: 数字(含百分比/价格)统一替换为 N,
    语义结构保留 —— 例如"缩量未到位(预估全天量/基准量=0.52>阈值0.396)"与
    "...=0.48>阈值0.396"会归并为同一条"缩量未到位(预估全天量/基准量=N > 阈值N)"。"""
    try:
        s = str(r).strip()
        s = re.sub(r'\d+\.?\d*%?', 'N', s)
        s = re.sub(r'[\s\u3000]+', ' ', s).strip()
        s = s.rstrip(' ,.;:()[]')
        return s or '未说明原因'
    except Exception:
        return '未说明原因'


def hourly_reason_note(side, code, name, reason):
    """2026-10-12新增: 登记"某只票因什么原因被跳过"到小时桶, 供每小时汇总打印。
    side: 'buy'/'sell'; 桶结构 {code: {'name': ..., 'reasons': {归一化原因: 次数}}},
    使汇总能按"每只票 + 每类原因"展示; 原样原因保留在 reasons 的 first 字段供追溯; V2.6.187 追加 last 字段(最近一次原文, 含当轮数值)并在展示时优先用它。
    reason 为空或非策略标的时跳过(避免噪声)。"""
    try:
        if not reason or not str(reason).strip():
            return
        if not code or (side == 'buy' and not is_strategy_target(code)):
            return
        if side == 'sell' and code not in (G.state.get('hold') or {}):
            return
        _d = G.hourly_buy_reason if side == 'buy' else G.hourly_sell_reason
        _code = str(code)
        _it = _d.get(_code)
        if not isinstance(_it, dict):
            _it = {'name': str(name or '') or _code, 'reasons': {}}
            _d[_code] = _it
        _rs = _it['reasons']
        _k = _norm_reason(reason)
        _cur = _rs.get(_k)
        if not isinstance(_cur, dict):
            _cur = {'n': 0, 'sample': '', 'last': ''}
            _rs[_k] = _cur
        _cur['n'] = int(_cur.get('n', 0) or 0) + 1
        if not _cur.get('sample'):
            _cur['sample'] = str(reason).strip()
        # V2.6.187: 同时记下【最近一次】的 reason 原文 —— reason 文本每轮都带入当轮数值
        #   (缩量比/现价/成本), 旧版只留 sample(首次文案)导致汇总里数值永远停在第一次, 易被误读成"判定被冻结"。
        _cur['last'] = str(reason).strip()
    except Exception:
        pass


def _hourly_fmt(d):
    """把桶格式化为可读字符串: 每只票一行 '代码 名称: 原因xN, 原因xN'。"""
    if not d:
        return ''
    _lines = []
    for _c, _it in d.items():
        _rs = _it.get('reasons') or {}
        if not _rs:
            continue
        _nm = _it.get('name') or _c
        _parts_list = []
        for _k, _v in sorted(_rs.items(), key=lambda x: -(x[1].get('n') if isinstance(x[1], dict) else x[1])):
            _cnt = _v.get('n') if isinstance(_v, dict) else _v
            _lab = str((_v.get('last') or _v.get('sample')) or '').strip() if isinstance(_v, dict) else ''
            _parts_list.append('%sx%d' % (_lab or _k, _cnt))
        _lines.append('%s %s: %s' % (_c, _nm, ', '.join(_parts_list)))
    return '; '.join(_lines)


def hourly_reason_dump(force=False):
    """2026-10-12新增: 每小时汇总一次"优选股未买入/持仓股未卖出"原因统计并清空桶。
    只在交易时段(trading)内触发; 每 HOURLY_REASON_LOG_SEC(默认3600秒=1小时)一次。
    输出示例: [小时汇总] 10:00 优选股未买入 2笔 | 中农立华: 缩量未到位x18, 动态手数x6; ..."""
    try:
        if HOURLY_REASON_LOG_SEC <= 0:
            return
        if market_phase() != 'trading':
            return
        now = time.time()
        if not force and (now - _f(G.hourly_reason_ts)) < HOURLY_REASON_LOG_SEC:
            return
        G.hourly_reason_ts = now
        bd = dict(G.hourly_buy_reason or {})
        sd = dict(G.hourly_sell_reason or {})
        G.hourly_buy_reason = {}
        G.hourly_sell_reason = {}
        # 修复2(2026-10-16): 卖出桶可能含刚卖出(已移出hold)标的的登记, 展示时按当前持仓过滤, 避免已平仓标的后出现在'持仓股未卖出'
        _hold_now = G.state.get('hold') or {}
        sd = {_c: _v for _c, _v in sd.items() if _c in _hold_now}
        # 实发单笔数 = 本次运行累计(G.buy_cnt/sell_cnt) - 上次汇总快照
        _bc = int(getattr(G, 'buy_cnt', 0) or 0)
        _sc = int(getattr(G, 'sell_cnt', 0) or 0)
        bn = max(0, _bc - int(getattr(G, 'hourly_buy_last_cnt', 0) or 0))
        sn = max(0, _sc - int(getattr(G, 'hourly_sell_last_cnt', 0) or 0))
        G.hourly_buy_last_cnt = _bc
        G.hourly_sell_last_cnt = _sc
        _h = datetime.datetime.now().strftime('%H:%M')
        _pb = _hourly_fmt(bd) or '无'
        _ps = _hourly_fmt(sd) or '无'
        if bn or bd:
            log('[小时汇总] %s 优选股未买入: 实发单%d笔 | %s' % (_h, bn, _pb))
        if sn or sd:
            log('[小时汇总] %s 持仓股未卖出: 实发单%d笔 | %s' % (_h, sn, _ps))
    except Exception:
        traceback.print_exc()


def cap_fit_volume(s, vol, px, lot=None, cap_amts=None, tag='买入'):
    """V2.6.168新增(2026-10-23 全量零预设独立审计·第三部分): 把"按实际委托价卡额度"做成
    一个统一函数, 买入 / 分批加仓 / 买入重报 三处共用, 避免各写各的、算出来的量能顶穿上限。

    为什么原来需要它: 上游 calc_size / buy_stock / pyramid_add 拿到的额度上限
        可买数量 = 额度 / 估算价(未含滑点与费用)
    天然偏乐观, 也没把"按委托价/滑点价取整"这两件事收进同一处, 于是"买不到一手就换一个
    便宜的标的"这种降级行为, 常常把单票额度或组合额度顶穿。举例: 额度上限 66666.66 元,
    算出来可以买 6600 股, 实际成交 = 6600x10.12 + 佣金5 + 过户费 ≈ 66797 元, 比额度上限
    多出约 130 元(单只就超限, 更别说同轮多只); 3元档买进 22000 股时手续费约占净买入金额
    的百分之一二, 漏算的那部分就成了没人管的余量。

    关键点: 委托价 px 已经过 clamp_order_price(估算价/滑点价)夹过, 是"真会发出去的价格",
    所以这里必须用"委托价 + 真实费用"去比额度, 而不是用上游那个估算价。

    口径: 用委托价 px + 按真实费率算出的 fee_buy, 直接算实际会付出多少钱, 与额度上限比较;
    只削不增, 额度内原样返回, 超额才按最小申报单位往下削。

    参数: cap_amts = 需要同时满足的多个额度上限(取最小值; 列表为空=不限制)
    参数: 返回值 = 削平后的股数(0 = 不允许买入)
    异常一律返回 0(绝不 fail-closed: 宁可少买不可多买), 与 abs_cap_left 同口径
    """
    try:
        _px = _f(px)
        v = int(vol)
        _lot = int(lot) if lot else (int(LOT_SIZE) if LOT_SIZE > 0 else 100)
        if _lot <= 0:
            _lot = 100
        if v <= 0 or _px <= 0:
            return 0
        _amts = [max(0.0, _f(x)) for x in (cap_amts or []) if x is not None]
        if not _amts:
            return v
        _cap = min(_amts)
        _paid = _px * v + fee_buy(_px * v, s)
        if _paid <= _cap + 1e-6:
            return v
        _v = v
        _guard = 0
        while _v > 0 and (_px * _v + fee_buy(_px * _v, s)) > _cap + 1e-6:
            _v -= _lot
            _guard += 1
            if _guard > 100000:
                _v = 0
                break
        if _v < 0:
            _v = 0
        _v = int(_v / _lot) * _lot if _lot > 1 else _v
        log(disp(s), '[额度上限削平] %s: %d股按委托价%.2f元实付%.2f元, 超出额度%.2f元, 削为%d股'
            % (tag, v, _px, _round2(_px * v + fee_buy(_px * v, s)), _cap, _v))
        return int(_v)
    except Exception:
        traceback.print_exc()
        return 0


def buy_stock(c, lp, est, ratio, cash, want_vol=None, atr=0.0, atr_pct=0.0, stop_pct=0.0, plan=None, tick=None, ords_snap=None):
    """低吸买入: 限价单(prType=11); 返回买入股数(未买返回None)。
    want_vol>0 时用动态手数(已过四级约束与取整降级), 否则退回固定手数/目标金额口径;
    plan=分批计划(各批股数列表)时, 本次只成交第一批, 其余批次由 run_pyramid_adds 按价格位置续买"""
    # V2.6.33修复(P0): 本函数入参已重构为候选字典 c, 函数体内 30 余处仍沿用股票代码变量 s。
    # 旧版缺此赋值 → NameError: name 's' is not defined → 每轮生成分批建仓计划后整轮抛异常
    # (2026-10-13 13:43~13:46 实测, 当日买入 0 笔), 计划无法落盘、30秒后重来, 首仓永远发不出去。
    # 补此一行即恢复; 其余 s 引用语义(path 日志/持仓键/发单代码/登记额度)全部正确, 不动任何交易逻辑。
    # S1(2026-10-24): 硬双实例防护 - 检测到存活同伴心跳即暂停本次新建买入, 杜绝双实例重复下单。
    #   只拦买入(最危险动作), 卖出/状态逻辑不受影响; 仍守用户'只告警不阻断'底线(不 halt 整个策略)。
    #   判定口径与 heartbeat_tick 一致(同账号/PID!=自身/ts 在 HEARTBEAT_SEC*1.5约45s内)。
    if _live_peer_exists():
        log('[安全][S1] 检测到存活的其它策略实例, 本轮回避新建买入(防重复下单); 卖出与状态逻辑正常')
        return None
    s = c['stock']   # V2.6.33修复: 由候选字典取股票代码, 供函数体内 s 引用使用
    if G.kcb_reject_date.get(s) == G.today:
        log(disp(s), '科创板买单今日已被柜台拒绝过，停止重复发单')
        return None
    # V2.6.87: 入参契约自愈 —— 下方 int(amount / lp / _lot) 在 lp<=0 时会除零崩溃,
    #   崩溃点不在 try 内, 会直接中断整轮 timer_poll(买卖全停)。主循环虽已拦 lp<=0,
    #   但函数级不应依赖调用方; 补一行兜底(语义: 无有效价格=不买), 不动任何交易逻辑。
    if _f(lp) <= 0:
        log(disp(s), '买入跳过: 无有效价格(lp=%.3f), 无法计算手数' % _f(lp))
        return None
    # 第6条修复(2026-10-17): tick量单位异常拉闸时强制拦截买入 —— 主买入发单前先查拉闸状态,
    # 已拉闸(TICK_UNIT_BLOCK_DAYS连续异常)则本轮不买入, 直到人工确认行情源正常才恢复。
    if _tick_unit_blocked():
        log(disp(s), '买入暂缓: tick量单位异常已拉闸(连续多日疑似"股"而非"手"), 暂停买入等待人工确认行情源')
        return None
    _eb = emergency_block('new')
    if _eb:
        log(disp(s), '买入暂缓: %s' % _eb)
        return None
    if not buy_scope_ok(s):
        # 交易铁律: 非策略标的(不在当日候选池且无本策略分批计划)一律拒绝买入
        scope_refuse(s, '买入')
        return None
    # V2.6.83: 发单前复核排雷清单(与选股层形成双重拦截; 只拦新增买入, 卖出/持仓管理不受影响)
    _rx = risk_excluded(s)
    if _rx:
        log(disp(s), '买入拒绝: %s(发单前复核)' % _rx)
        return None
    # P3-6(2026-10-24 第18轮零预设独立审计): 发单前即时复核人工黑名单 —— 旧版只在选股时
    #   经 risk_blocked 查一次, 且 load_blacklist 按日缓存, 盘中新写入的条目当日不生效
    #   (危害例见 load_blacklist 注释)。这里 force=True 绕过日缓存重读(带60秒节流)。
    _bl = load_blacklist(force=True)
    if s in _bl:
        log(disp(s), '买入拒绝: 人工黑名单(%s)(发单前即时复核)' % (_bl.get(s) or '人工标记'))
        return None
    # P3-6(第18轮审计): 发单前复核ST冠名 —— 旧版只在选股层查一次; A股ST冠名必伴随一日停牌、
    #   盘中不发生冠名, 且名称缓存最长滞后2天, inst_name 有缓存故成本近零, 只收紧不放松。
    if EXCLUDE_ST:
        _nm_now = inst_name(s)
        if _nm_now and is_st_name(_nm_now):
            log(disp(s), '买入拒绝: 已冠名ST/*ST(%s)(发单前复核)' % _nm_now)
            return None
    # P2-10修复(2026-10-19): 仙股下限当天现价复核——risk_blocked 里的 RISK_MIN_PRICE
    # 检查用的是已完成交易日收盘(comp[-1]), 盘中现价可能已跌破下限(昨收2.05元、
    # 今日跌到1.98元), 原逻辑当天不会再拦, 会在仙股上触发买入; 这里在发单前用
    # 实时最新价(lp)按同一阈值复核一次, 跌破即拒单。选股语义不变, 只补盘中时段
    # 缺口; lp 不可用(<=0)时跳过复核(仍由选股阶段的收盘口径把关)
    if RISK_MIN_PRICE > 0 and _f(lp) > 0 and _f(lp) < RISK_MIN_PRICE:
        log(disp(s), '买入拒绝: 现价%.3f已低于仙股下限%.1f元(盘中复核, 选股阶段收盘口径未覆盖盘中下跌)'
            % (_f(lp), RISK_MIN_PRICE))
        return None
    if plan:
        want_vol = int(plan[0])
    # 重审20261005(P2-3): 手数取整统一用 LOT_SIZE 常量(旧版硬编码100, 与 pyramid_alloc 口径分裂)
    _lot = _lot_of(s)   # P1-1(第18轮审计): 科创板200股/主板100股, 与 normalize_buy_volume 同口径
    if want_vol and want_vol >= _lot:
        vol = int(want_vol / _lot) * _lot
        # V2.6.161(第14轮审计-投资金额突破上限): 动态手数分支补双帽兜底, 与下方固定量回退分支同口径。
        #   want_vol 上游虽已过 calc_size 的 n2(单票绝对额度)/n5(组合剩余额度), 但两者均按未含滑点的
        #   价格折算; 实收价按动态滑点(低价股0.3%)成交时, 单票成本最高突破 MAX_POS_VALUE_ABS 约200元;
        #   同轮多笔买入时在途委托额度的登记时序差, 也靠这两帽兜底。只削不增: 帽内时 vol 不变。
        _px_g = _round2(lp * (1.0 + _slippage_for(lp)))
        if _px_g <= 0:
            _px_g = _round2(lp)
        _caps_g = []
        if MAX_POS_VALUE_ABS and MAX_POS_VALUE_ABS > 0:
            _caps_g.append(MAX_POS_VALUE_ABS / _px_g)
        _cl_g = abs_cap_left(_px_g)
        if _cl_g is not None:
            _caps_g.append(_cl_g)
        if _caps_g:
            _cv_g = int(min(_caps_g) / _lot) * _lot
            if _cv_g < _lot:
                log(disp(s), '动态手数: 仓位帽算下来不足一手(帽=%.0f股 价格=%.2f), 放弃'
                    % (min(_caps_g), _px_g))
                return None
            if vol > _cv_g:
                log(disp(s), '动态手数: %d股超过仓位帽, 削平为%d股' % (vol, _cv_g))
                vol = _cv_g
    elif FIXED_BUY_VOL > 0:
        # P2-5修复(2026-10-19): 固定量回退分支补双帽防御。该分支正常不可达(plan 总
        # 提供 want_vol), 但一旦被走到(计划缺失/异常), 原逻辑会绕过 abs_cap_left 与
        # MAX_POS_VALUE_ABS 全部仓位帽按固定量直接下单, 存在超限风险; 这里用限价
        # 折算后的双帽收紧, 超帽即拒单(与下方资金不足拒单同一风格)
        vol = int(FIXED_BUY_VOL / _lot) * _lot     # 每次固定手数
        _px_g = _round2(lp * (1.0 + _slippage_for(lp)))
        if _px_g <= 0:
            _px_g = _round2(lp)
        _caps_g = []
        if MAX_POS_VALUE_ABS and MAX_POS_VALUE_ABS > 0:
            _caps_g.append(MAX_POS_VALUE_ABS / _px_g)
        _cl_g = abs_cap_left(_px_g)
        if _cl_g is not None:
            _caps_g.append(_cl_g)
        if _caps_g:
            _cv_g = int(min(_caps_g) / _lot) * _lot
            if _cv_g < _lot:
                log(disp(s), '固定量回退: 仓位帽折算不足一手(帽=%.0f股 价格=%.2f), 拒单'
                    % (min(_caps_g), _px_g))
                return None
            if vol > _cv_g:
                log(disp(s), '固定量回退: %d股超仓位帽, 收紧为%d股' % (vol, _cv_g))
                vol = _cv_g
    else:
        amount = min(TARGET_BUY_AMOUNT, cash)
        # V2.6.161(第14轮审计-投资金额突破上限): 目标金额分支原本两帽皆无(单票绝对额度与
        #   组合剩余额度都不校验), 用户若把 TARGET_BUY_AMOUNT 设得超过帽子即可越界; 此处补同口径双帽。
        _px_g = _round2(lp * (1.0 + _slippage_for(lp)))
        if _px_g <= 0:
            _px_g = _round2(lp)
        _caps_g = []
        if MAX_POS_VALUE_ABS and MAX_POS_VALUE_ABS > 0:
            _caps_g.append(MAX_POS_VALUE_ABS / _px_g)
        _cl_g = abs_cap_left(_px_g)
        if _cl_g is not None:
            _caps_g.append(_cl_g)
        if _caps_g:
            _cv_g = int(min(_caps_g) / _lot) * _lot
            if _cv_g < _lot:
                log(disp(s), '目标金额: 仓位帽算下来不足一手(帽=%.0f股 价格=%.2f), 放弃'
                    % (min(_caps_g), _px_g))
                return None
            _amt_cap = _cv_g * _px_g
            if amount > _amt_cap:
                log(disp(s), '目标金额: %.0f元超过仓位帽, 削平为%.0f元' % (amount, _amt_cap))
                amount = _amt_cap
        vol = int(amount / lp / _lot) * _lot
        # V2.6.161补强(干跑 _dryrun_161.py 实测lp=10.10发现残余越界): 金额只削到帽值时,
        #   vol 按 lp 向下取整到整手后 vol*lp 仍贴近帽值, 实收价含滑点(最高0.3%)单票成本
        #   会再超帽约0.3% —— 实测6600股@10.12=66792.00元, 超MAX_POS_VALUE_ABS 125.34元,
        #   而日志还写着"削平为66667元"(日志数字与实收成本不一致, 属会骗人的观测)。
        #   此处按股数帽(与另两个分支同口径, 已取整到整手)直接削 vol, 超帽归零。
        if _caps_g and vol > _cv_g:
            log(disp(s), '目标金额: %d股超过仓位帽, 削平为%d股' % (vol, _cv_g))
            vol = _cv_g
    if vol < _lot:
        log(disp(s), '算出手数不足一手, 放弃')
        return None
    # P2-15: 资金校验必须用实际委托价(含滑点+夹取)而非最新价 —— 校验口径与发单口径
    # 不一致时, 边界资金会"校验通过但柜台拒单"(废单浪费当日买入机会)
    # P2-3修复(2026-10-17): 校验与发单统一用动态滑点 —— 旧版校验用固定SLIPPAGE_PCT(0.2%)、
    # 发单用_slippage_for(低价股0.3%), 边界资金会"校验通过但柜台拒单"成废单
    _slip_chk = _slippage_for(lp)
    _px_chk = clamp_order_price(_round2(lp * (1.0 + _slip_chk)), tick, True, s)
    if _px_chk <= 0:
        _px_chk = _round2(lp)
    if vol * _px_chk + fee_buy(vol * _px_chk, s) > cash:
        log(disp(s), '资金不够买入%d股(按委托价%.2f测算), 放弃(可用资金不足)' % (vol, _px_chk))
        return None
    # 审计修复I2: 买入限价按最新价上移滑点(更容易成交), 费用/净利闸门按含滑点价估算
    # P2-5: 夹到涨跌停/价格笼子内侧, 防废单; I4: 保护带宽度按标的自适应(20cm/30cm不夹得过窄)
    _slippage = _slippage_for(lp)   # 第六轮零预设审计修复(2026-10-04): 按价格动态滑点
    px = clamp_order_price(_round2(lp * (1.0 + _slippage)), tick, True, s)
    if px <= 0:
        log(disp(s), '委托价夹取异常, 本次买入暂缓')
        _safe_rollback_placeholder(s)
        return None
    # V2.6.29: 委托价(px)提前算出后再构造占位持仓记录 —— buy_price 改用实际委托价
    # (原用最新价lp, 未含滑点与价格笼子夹取, 与 _set_buy_ctx 登记的委托价口径不一致)。
    # 成交回报到达后 deal_callback 仍会用 fill_sum/fill_vol 加权均价覆盖, 仅缩短
    # 发单~成交回报窗口内的成本记录偏差, 不改任何交易闸门。
    if c.get('entry_note'):
        # 战法借鉴②③: 确认式进场(缩倍阴突破/五日线收复)的原因文案
        reason = '%s | 现价=%.2f T0=%s 第%d天' % (c['entry_note'], lp, c['t0'], c['offset'])
    else:
        reason = ('缩量低吸: 预估全日量/基准量=%.2f(阈值%.2f) 现价=%.2f T0=%s 第%d天'
                  % (ratio, sent_param('SHRINK_BUY_RATIO', SHRINK_BUY_RATIO) * BUY_TOL, lp, c['t0'], c['offset']))
    if atr_pct > 0:
        reason += ' | 手数=%d股(风险%.1f%%/市值占比%.1f%%/ATR%.2f=%.1f%%/止损%.1f%%)' % (
            vol, RISK_PCT * 100, vol * lp / size_equity() * 100 if size_equity() > 0 else 0,
            atr, atr_pct * 100, stop_pct * 100)
    vol = normalize_buy_volume(s, vol)
    if vol <= 0:
        log(disp(s), '买入数量不符合板块申报规则(科创板至少200股)，拒绝发单')
        return None
    # V2.6.168: 买入侧按实际委托价卡额度(单票绝对额度 / 组合剩余额度 / 本次可用现金, 三者取最小)
    #   上游 calc_size 用的是"估算价", 没含滑点, 算出的手数天然偏乐观; 真正下发前用委托价
    #   + 真实费用复核一次, 超额就按最小申报单位往下削, 削不动则不发单。
    #   注意: 必须放在 G.state['hold'][s] = h 之前 —— 若先写进持仓, used_capital()
    #   会看到一个半成品仓位, 算出的可用额度是错的, 自然会被算成 0 而拒买。
    _amts_168 = []
    if MAX_POS_VALUE_ABS and MAX_POS_VALUE_ABS > 0:
        _amts_168.append(float(MAX_POS_VALUE_ABS))
    _l168 = abs_cap_left(px)
    if _l168 is not None:
        _amts_168.append(max(0.0, _f(_l168) * _f(px)))
    if cash is not None and _f(cash) > 0:
        _amts_168.append(_f(cash))
    vol = cap_fit_volume(s, vol, px, _lot, _amts_168, '买入下单')
    if vol <= 0:
        log(disp(s), '买入被额度削平: 委托价%.2f元下已不足最小申报量, 放弃本次买入'
            % _f(px))
        return None
    amt = _round2(px * vol)
    # fee/cost_total 初始置0: 实盘成本以成交回报(deal_callback)累计为准,
    # 此处若预设估算值会与回报叠加导致成本翻倍(卖出门槛/净利闸门全部失真)
    # A2修复(2026-10-17): 占位时即按估算口径预填 fee 与 cost_total, 让两道闸门
    # (is_at_loss / net_pnl_if_sell) 在成交回报到达前就口径一致; 成交回报到达后
    # 由 deal_callback 用真实 fee/cost_total 覆盖此处预填值(只是精度修正)。
    _init_fee = fee_buy(px * vol, s)
    h = {'t0': c['t0'], 'base_vol': c['base_vol'], 'zt_close': c['zt_close'],
         'name': c['name'], 'buy_date': G.today, 'buy_price': px, 'buy_vol': vol,
         'paper': DRY_RUN, 'managed': True, 'fill_sum': 0.0, 'fill_vol': 0, 'exited': False,
         'fee': _init_fee, 'cost_total': _round2(px * vol + _init_fee), 'last_px': lp,
         # V2.6.158: 预填值只用于"发单到成交回报"这段窗口内的闸门口径, 必须留标记,
         #   否则成交回报会把真实费用叠加在预填值上, 一笔买入的费用被记两遍。
         'fee_pre': _init_fee,
         'open_ts': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
         'alert_win': 0, 'alert_loss': 0,
         'order_ts': 0.0, 'order_retries': 0, 'cancel_sent': False,
         'atr': _round2(atr), 'atr_pct': _round2(atr_pct * 100.0), 'stop_pct': _round2(stop_pct),
         'size_eq': _round2(size_equity()), 'risk_amt': _round2(vol * lp * (stop_pct or 0.0)),
         'prev_close': _round2(last_close_of(s))}
    if plan:
        # 分批建仓: 记下计划总股数/各批股数/已成交批次/首笔价, 后续批次按价格位置续买
        h.update({'plan_vol': int(sum(int(x) for x in plan)), 'plan_batches': [int(x) for x in plan],
                  'plan_idx': 1, 'plan_date': G.today, 'first_price': _round2(lp),
                  'batch_ts': time.time(), 'batch_date': G.today, 'batch_today_n': 1,
                  'plan_done': len(plan) <= 1})
    G.state['hold'][s] = h
    if not can_trade():
        log('交易未就绪, 本次买入暂缓')
        _safe_rollback_placeholder(s)
        return None

    if DRY_RUN:          # 审计修复I7: 模拟盘不真发单, 构造成交回报走deal_callback记账(与实盘同一状态机)
        h['order_ts'] = time.time()
        h['pend_vol'] = int(vol)
        try:
            if not _sim_deal('BUY|' + s, px, vol):
                # P2-01: 模拟成交未命中: 回滚占位记录, 该股回候选池下轮重新评估
                log(disp(s), '模拟盘买入未成交(成交概率%.0f%%), 本轮暂缓' % (SIM_FILL_PROB * 100))
                _safe_rollback_placeholder(s)
                return None
        except Exception:
            log(disp(s), '模拟盘构造成交回报异常, 本次买入暂缓')
            traceback.print_exc()
            _safe_rollback_placeholder(s)
            return None
        G.buy_cnt += 1
        dry_cash_delta(-_round2(vol * px + fee_buy(vol * px, s)))   # V2.6.71修复: 模拟盘买入扣款改用真实费用fee_buy(旧版粗估FEE_RATE_EST 0.15%高估; 与下方模拟卖出fee_sell回款口径对齐)
        daily_buy_done(s)
        log('[模拟盘] 买入成交 | %s | %d股 限价@%.2f | 金额约=%.2f元 | %s'
            % (disp_code(s, c['name']), vol, px, amt, reason))
        save_state()
        return vol
    try:
        if limit_gate_reject(s, px, True, '新开仓买入'):
            _safe_rollback_placeholder(s)
            return None
        # P0-2: 在途委托量必须在passorder之前设置, 否则同步成交回报(deal_callback)无法核销,
        # 会导致run_pyramid_adds误判"仍有在途委托"而跳过后续加仓批次
        h['order_ts'] = time.time()      # 方案三: 记录委托发出时刻, 供超时撤单重报
        h['pend_vol'] = int(vol)         # P0-2: 在途委托量(重报按它发, 不按buy_vol累计值)
        # 审计修复P1-1: 发单前先把在途标记(持仓占位/order_ts/pend_vol)落盘 ——
        # 防"passorder成功 -> save_state"崩溃窗口内重启后无记录而重复下单
        if not save_state(critical=True):
            log(disp(s), '交易关键状态无法落盘, 已取消本次买入发单')
            _safe_rollback_placeholder(s)
            return None
        # 2026-10-04: 买入放行触发日志 —— 在实发单前明确输出本次买入的完整触发条件与关键参数,
        # 便于核对"为什么买这只、按什么价、买多少、基于哪些信号与风控阈值"。
        trigger_log('买入放行', '买入',
                    '所有买入前置校验全部通过, 按此触发条件发限价单',
                    code=disp_code(s, c.get('name', '')),
                    t0=c.get('t0', ''), price=lp, est_full_vol=est,
                    shrink_ratio=ratio, threshold=sent_param('SHRINK_BUY_RATIO', SHRINK_BUY_RATIO) * BUY_TOL,
                    zt_close=c.get('zt_close', 0.0), base_vol=c.get('base_vol', 0),
                    order_price=px, vol=vol, amount=_round2(px * vol),
                    atr_pct=atr_pct, stop_pct=stop_pct,
                    reason=reason, mode=TRADE_MODE)
        # passorder: 23=股票买, 1101=按股, 11=限价, quickTrade=2立即下单, 备注BUY|代码
        log('[应急闸门][通过] 新开仓 | %s | mode=%s | %d股'
            % (disp_code(s, c.get('name', '')), emergency_mode_effective(), vol))
        _ret_new = _api(passorder, 23, 1101, G.accid, s, 11, px, vol,
                  STRAT_TAG, 2, 'BUY|' + s + '|NEW', G.C)   # 重审20261006(P0-B/问题2): 新建仓单加|NEW后缀区分加仓
        # P3-C-N7(2026-10-29 修复)：passorder 返回失败(-1/None)时不得计入买入笔数。
        #   原实现无条件 G.buy_cnt += 1，委托实际被柜台静默拒绝时，当日买入统计
        #   与「已发单笔数」都会虚高，事后核对成交记录对不上；且真正的失败
        #   既不重报也不给明确信号（僵尸占位一直挂到超时）。
        if _ret_new is None or (isinstance(_ret_new, (int, float)) and _ret_new < 0):
            log('[安全] %s 买入未成功发出(passorder 返回 %r)，不计入买入笔数，本次放弃'
                % (disp(s), _ret_new))
            _safe_rollback_placeholder(s)
            save_state()
            return None
        G.buy_cnt += 1
        _add_to_sector(s)
        # P1-3: 买入上下文兜底 —— 成交回报晚于持仓记录被清理时, 回报可凭此补录建仓
        # P0-2修复(2026-10-04): 统一走 _set_buy_ctx 公共函数(内部已含 3 天时效清理+异常兜底),
        # 与重报/分批加仓路径共用同一写入口径, 避免三处逻辑漂移
        _set_buy_ctx(s, {'name': c.get('name', ''), 't0': c.get('t0', ''),
                         'base_vol': c.get('base_vol', 0), 'zt_close': c.get('zt_close', 0.0),
                         'vol': int(vol), 'price': _round2(px)})
        log('[实盘] 买入委托已发 | %s | %d股 限价@%.2f | 金额约=%.2f元(实际以成交回报为准) | %s'
            % (disp_code(s, c['name']), vol, px, amt, reason))
        # 实盘盈亏账本以成交回报(deal_callback)为准, 此处不记账, 避免委托与成交重复
    except Exception:
        log('买入下单异常, 确认柜台委托状态后再决定处置')
        traceback.print_exc()
# 风险1修复: 异常不代表委托未送达 —— 先查柜台确认无在途委托再删记录,
        # 若委托实际已发出但仅返回异常, 直接删除会导致下一轮重复买入同一股票
        # 重审20261005(F4): 此处必须实时查柜台 —— ords_snap 是本轮发单【前】的预取快照,
        #   不可能包含本轮委托; 用它查询会把"已送达但返回异常"的委托误判为未发出而删除
        #   记录, 当日即可对同一标的重复下单(双倍占资)。传 None 强制实时柜台查询。
        # 风险1修复: 异常不代表委托未送达 —— 先查柜台确认无在途委托再删记录,
        #   若委托实际已发出但仅返回异常, 直接删除会导致下一轮重复买入同一股票
        #   重审20261005(F4): 此处必须实时查柜台 —— ords_snap 是本轮发单【前】的预取快照,
        #   不可能包含本轮委托; 用它查询会把"已送达但返回异常"的委托误判为未发出而删除
        #   记录, 当日即可对同一标的重复下单(双倍占资)。传 None 强制实时柜台查询。
        # V2.6.168(全量零预设独立审计·第三部分): 在原本的 except 外面再包一层 try, 防的是"查柜台这一步本身抛异常"
        #   (buy_order_obj / getattr / daily_buy_done 都可能抛), 一旦抛了整个 buy_stock 就
        #   带着未清理的 G.state['hold'][s] 退出, 下一轮会拿一个半成品仓位继续跑, 额度算错;
        #   现改为异常分支里也走 try: "异常时也要登记当日额度并保留记录", 保证不漏登记。
        try:
            _o = buy_order_obj(s, None)
            if _o == '_ERR':          # 风险2修复: 查询失败时保留记录+登记额度, 等下轮复核
                log(disp(s), '异常后查柜台失败, 保留记录等下轮复核(不占当日额度, 避免误堵后续买入)')
                save_state()
                return vol
            if _o is not None and int(getattr(_o, 'm_nOrderStatus', -1)) in ACTIVE_ORDER_STATUS + (56,):
                # 委托已在柜台存活/已成: 保留持仓记录, 等成交回报接管, 登记当日额度防重入
                _st_code = int(getattr(_o, 'm_nOrderStatus', -1))
                log(disp(s), '异常但委托已送达柜台(状态%s), 保留记录等回报, 已登记当日额度防重入'
                    % ORDER_STATUS_MAP.get(_st_code, '未知状态(%s)' % _st_code))
                daily_buy_done(s)
                save_state()
                return vol
            _o = None
        except Exception:
            log(disp(s), '异常后查柜台又抛异常, 按"委托可能已送达"处理: '
                '保留记录等下轮复核(已登记当日额度防重入)')
            traceback.print_exc()
            try:
                daily_buy_done(s)
                save_state()
            except Exception:
                traceback.print_exc()
            return vol
        # 委托确实未发出: 安全清理。登记当日买入codes后由买入循环的"同票当日重入守卫"
        # (重审20261005)拦截重入 —— 旧版仅靠当日额度上限, 默认不限时不构成屏障。
        _safe_rollback_placeholder(s)
        daily_buy_done(s)
        log(disp(s), '异常且委托未送达, 已清理记录并登记当日已尝试(同票今日不再重入, 防重复下单)')
        save_state()
        return None
    daily_buy_done(s)          # 当日买入计数(跨重载生效, 受MAX_DAILY_BUYS约束)
    save_state()
    return vol

def sell_stock(s, h, pos_avail, lp, reason, tick=None):
    """离场卖出: 限价保护单(P0-1加固)。T+1不可卖则次日重试。
    以成交回报(deal_callback)记账。
    卖出价 = max(解套保护价, 最新价下浮笼子价), 且按该价复核扣费净利>0才发单 ——
    即使盘口瞬间下杀, 限价单也不会以低于保护价成交"""
    if not can_trade():
        log('交易未就绪, 卖出暂缓等待下轮重试')
        return
    # 卖出次数上限(按交易模式独立): 上限>0 且已达上限时, 本轮跳过卖出(次日自动恢复)
    if daily_sell_left() <= 0:
        log('[%s] 当日卖出笔数已达上限%d笔, 跳过 %s 本次卖出(次日自动恢复)'
            % (TRADE_MODE, daily_sell_cap(), disp_code(s, h.get('name', ''))))
        return
    vol = int(pos_avail.get(s, 0))
    if vol <= 0:
        log(disp(s), '当日买入T+1不可卖, 标记待明日自动重试')
        h['sell_pending_t1'] = True        # 不设exited: 名额不提前释放, 仍算在持
        h['sell_ts'] = time.time()
        h['sell_retries'] = 0
        save_state()
        return
    # P1-4配套: 已giveup(重试用尽)的仓位当日不再发新的卖出决策 —— 否则exited复位后
    # 信号仍满足会立即重发, 拒单→重发→giveup无限循环。次日新决策自动复位状态机。
    if h.get('sell_giveup'):
        if h.get('giveup_note_date') != G.today:
            h['giveup_note_date'] = G.today
            log(disp(s), '卖出重试已用尽(giveup), 当日不再自动卖出, 请人工检查该持仓(次日自动恢复重试)')
            # P2-12修复(2026-10-17): 早退路径也落盘 —— 旧版改了h(giveup_note_date)直接return,
            # 若此时进程重启, 待重试标记丢失, 重启后会重新评估卖出决策(重复走一遍重试链)
            save_state()
        return
    # 新一笔卖出决策: 重置重试状态机(P1-2)
    h['sell_retries'] = 0
    h['sell_giveup'] = False
    h['sell_cancel_sent'] = False
    h.pop('sell_retry_now', None)   # 重审20261005(P2-2): 清残留立即重发标记, 防旧废单回调的幽灵标记误触发
    place_sell_order(s, h, vol, lp, reason, tick)


def place_sell_order(s, h, vol, lp, reason, tick=None, ords_snap=None):
    """实际发出卖出限价单(实盘)。价格保护逻辑(P0-1):
    ① 基准价=最新价lp, 先夹到笼子/涨跌停内侧(clamp_order_price);
    ② 绝不止损模式下再抬到解套保护价exit_price_needed(扣费后净利转正的最低价)之上;
    ③ 按最终委托价复核扣费净利>0, 不为正则本轮放弃(绝不亏本成交)。返回是否已发单"""
    _eb = emergency_block('sell')
    if _eb:
        log(disp(s), '卖出暂缓: %s' % _eb)
        return False
    # P1-2(2026-10-24 第18轮审计): 卖出侧只告警不阻断 —— 双实例误操作时卖出委托可能
    #   双边各发一单, 但卖出受 pos_avail(柜台可卖量)与"扣费净利为正"双重约束;
    #   且阻断卖出会违背"扣费后真正赚钱才允许卖出"的放行语义(可能把该卖的票卡住),
    #   故此处只做强告警, 与用户"只告警不阻断"的底线保持一致。
    if _live_peer_exists():
        log('[安全][P1-2][告警] 检测到存活的其它策略实例: 卖出委托可能双边各发一单, '
            '请立即关闭多余实例(卖出侧不阻断, 以免卡住本该成交的卖单)')
    if not sell_scope_ok(s):
        # 交易铁律: 非本策略持仓记录内的标的一律拒绝卖出(绝不碰其它任何股票)
        scope_refuse(s, '卖出')
        return False
    # P1-2修复(2026-10-17): 未登记手工加仓 → 成本基准不可信 → 暂停该股自动卖出。
    # 场景: 策略10元买100股, 用户App以20元加买100股未登记 → 对账只同步股数不改成本,
    # 系统眼里每股成本5元, 涨到12元即"盈利"放行卖出, 但整体实亏3000元(违反不赚钱不卖)。
    # 处置: 每日一次强提醒登记 manual_fill/manual_avg_cost, 登记/人工平仓前只持有不卖出。
    if (h or {}).get('unreg_manual_add'):
        if h.get('unreg_note_date') != G.today:
            h['unreg_note_date'] = G.today
            _u = h.get('unreg_manual_add') or {}
            log('[安全][注意] %s 存在未登记手工加仓(股数%s→%s), 成本基准不可信, '
                '本轮暂停自动卖出; 请在状态文件登记 manual_fill/manual_avg_cost 后恢复'
                % (disp_code(s, h.get('name', '')), _u.get('from', '?'), _u.get('to', '?')))
        return False
    # ===== 铁律: 亏损(含持平)持仓绝对禁止卖出(不可绕过的最终闸门) =====
    # 无论 NEVER_STOP_LOSS 开关、市场行情、亏损幅度多大或持有多久, 只要现价<=成本均价,
    # 一律拒绝卖出 —— 必须继续持有直至回本(转为盈利)或满足其它明确退出条件。
    # 此闸门独立于下方 NEVER_STOP_LOSS 逻辑, 即使该开关被误关也不会放行亏损卖出。
    # (2026-10-01 审计修复P1-6A 用户确认方案A: 维持无条件绝对闸门;
    #  与之配套, 下方的扣费净利复核也已无条件生效 —— 不赚钱就不卖, 亏损出口不可通过开关恢复)
    if is_at_loss(h, lp):
        cb = loss_cost_basis(h)
        # 2026-10-04: 亏损禁卖为"绝不止损"策略的最硬闸门, 单独输出结构化触发日志, 便于核对
        trigger_log('卖出拦截-亏损禁卖(铁律)', '卖出',
                    '现价不高于成本均价, 判为亏损/持平持仓, 无论行情/亏损幅度/持有多久一律禁止卖出',
                    code=disp_code(s, h.get('name', '')), price=lp, cost_basis=cb,
                    loss_pct=(lp / cb - 1) * 100 if cb > 0 else 0.0,
                    held_days=h.get('hold_days', 0), never_stop_loss=NEVER_STOP_LOSS)
        log('【铁律·亏损禁止卖出】%s 现价%.2f ≤ 成本均价%.2f, 判为亏损/持平持仓, '
            '无论行情、亏损幅度或持有多久一律禁止卖出, 继续持有直至回本或满足其它明确退出条件'
            % (disp_code(s, h.get('name', '')), lp, cb))
        return False
    # 审计修复I2: 卖出限价按最新价下移滑点(更容易成交); I4: 保护带宽度按标的自适应
    _slippage_sell = _slippage_for(lp)   # 第六轮零预设审计修复(2026-10-04): 按价格动态滑点
    px = clamp_order_price(_round2(lp * (1.0 - _slippage_sell)), tick, False, s)
    if NEVER_STOP_LOSS:
        floor_px = _f(exit_price_needed(h, s, vol))
        if floor_px > 0 and px < floor_px:
            px = _round2(floor_px)          # 限价单不会以低于保护价的价格成交
            # P2-2加固: 抬升保护价后复核涨跌停上沿, 超过则夹回内侧(旧逻辑只夹下方向,
            # 极端情形保护价可能高于当日涨停价导致必废单并触发重发循环);
            # 夹回后若净利闸门不过则本轮不卖(宁可等更优价格, 也不发必废的委托)
            # 重审20261005(1-2): 上沿优先取当日涨停价权威来源 get_instrument_detail.UpStopPrice
            # (get_full_tick 无 upperLimit 字段, 旧写法是死分支) —— ST化持仓不再受名称缓存滞后影响
            up = _f(day_limit_prices(s)[0])
            if up <= 0:
                up = 0.0   # 2026-10-09第五轮审计: 官方get_full_tick无upperLimit字段, 原读tick为死分支, 置0回退昨收带宽兜底
            if up > 0:
                if px > up:
                    px = up
            else:
                lc = _f((tick or {}).get('lastClose') or (tick or {}).get('last_close'))
                if lc > 0:
                    hi = math.floor(lc * (1.0 + _band_pct(s)) * 100 + 1e-6) / 100.0   # 审计修复I4: 上沿用自适应带宽
                    if px > hi:
                        px = hi
    if px <= 0:
        trigger_log('卖出拦截-委托价计算异常', '卖出', '委托价经涨跌停/价格笼子夹取后非正, 本轮暂缓',
                    code=disp_code(s, h.get('name', '')), price=lp, order_price=px)
        log(disp(s), '卖出委托价计算异常, 本轮暂缓')
        return False
    if net_pnl_if_sell(h, px, s, vol) <= 0:
        # 审计修复P1-6A(用户确认方案A): 扣费后不赚钱就不卖 —— 与亏损禁卖铁律同语义,
        # 无条件生效、不再依赖NEVER_STOP_LOSS开关, 消除"现价>成本但扣费净利<0仍放行卖出"
        # 的边界; 本轮不卖, 下一轮重新评估
        _np = net_pnl_if_sell(h, px, s, vol)
        _cb = loss_cost_basis(h)
        trigger_log('卖出拦截-扣费净利不为正', '卖出',
                    '按委托价测算扣费后净利不为正, 不赚钱就不卖, 本轮不卖等更优价',
                    code=disp_code(s, h.get('name', '')), order_price=px, net_pnl=_np,
                    cost_basis=_cb, slippage_pct=SLIPPAGE_PCT,
                    gross_pnl=(px - _cb) if _cb > 0 else 0.0)
        log(disp(s), '卖出复核: 按*委托*限价%.2f测算扣费净利不为正, 本轮不卖(等更优价格)' % px)
        return False
    if DRY_RUN:          # 审计修复I7: 模拟盘不真发单, 构造成交回报走deal_callback记账
        try:
            if not _sim_deal('SELL|' + s, px, vol):
                # P2-01: 模拟成交概率未命中: 本轮不卖, 下轮重新评估(不留卖出在途占位)
                log(disp(s), '模拟盘卖出未成交(成交概率%.0f%%), 本轮暂缓' % (SIM_FILL_PROB * 100))
                return False
        except Exception:
            log(disp(s), '模拟盘卖出构造成交回报异常, 本轮暂缓')
            traceback.print_exc()
            return False
        G.sell_cnt += 1
        # P2-02: 模拟卖出回款按"净到手金额"入账(卖出金额-卖出费用), 与实盘成交回报
        # (fee_sell)口径一致, 避免模拟资金虚高而放大后续仓位
        # P1-1(20261008): 部分成交时回款按实际成交量(剩余在途续卖), 防模拟现金虚增
        _sfv = int(getattr(G, '_sim_sell_fill', 0) or 0)
        _sfv = _sfv if 0 < _sfv <= int(vol) else int(vol)
        dry_cash_delta(_round2(_sfv * px - fee_sell(_sfv * px, s)))
        G._sim_sell_fill = 0   # P1-1补全(20261008): 读后即清, 防下次全额成交误用残留部分量回款
        if h.get('sell_counted_date') != G.today:   # P2-28: 与实盘口径一致, 首次发单计数
            daily_sell_done(s)
            h['sell_counted_date'] = G.today
        cost = h.get('buy_price') or 0.0
        est_pnl = (lp - cost) * vol if cost > 0 else 0.0
        est_pct = (lp / cost - 1.0) * 100.0 if cost > 0 else 0.0
        days = held_trd_days(h.get('buy_date', ''))
        log('[模拟盘] 卖出成交 | %s | %d股 限价@%.2f(保护价) | 金额约=%.2f元 | 持仓%d天 | %s(按最新价预估) | %s'
            % (disp_code(s, h.get('name', '')), vol, px, lp * vol, days,
               fmt_pnl(est_pnl, est_pct), reason))
        h['exited'] = True
        h['sell_ts'] = time.time()
        h['sell_retries'] = int(h.get('sell_retries', 0) or 0) + 1
        h['sell_cancel_sent'] = False
        try:
            ctx = G.state.setdefault('sell_ctx', {})
            now_ts = time.time()
            for k in [x for x, v in ctx.items() if now_ts - _f(v.get('ts', 0)) > 3 * 86400]:
                ctx.pop(k, None)
            ctx[s] = {'name': h.get('name', ''), 'buy_date': h.get('buy_date', ''),
                      'cost_total': pos_cost(h), 'hold_vol': int(vol), 't0': h.get('t0', ''),
                      'reason': reason, 'ts': now_ts}
        except Exception:
            log('[警告] 模拟盘卖出上下文(sell_ctx)保存失败, 成本结转可能失效')
        save_state()
        return True
    try:
        if limit_gate_reject(s, px, False, '卖出'):
            return False
        # P1-1: 发单前先落盘卖出在途状态(与买入侧对称) —— passorder成功与save_state之间
        # 崩溃/断电时, 旧版重启后 exited=False/sell_ts=0 而柜台卖单仍存活:
        # 仓位被冻结会被误判T+1挂起, 未冻结会再发一张卖单(重复发单)。
        h['exited'] = True
        h['sell_ts'] = time.time()
        h['sell_retries'] = int(h.get('sell_retries', 0) or 0) + 1
        h['sell_cancel_sent'] = False
        # P2-28: 当日卖出笔数只在该仓"首次发单"时计入(撤单重发/拒单重发不再重复计数,
        # 也不再被重发挤占 —— 旧版每次place_sell_order都+1, 上限从"限制总笔数"退化)
        if h.get('sell_counted_date') != G.today:
            daily_sell_done(s)      # 当日卖出计数(按模式独立, 跨重载生效)
            h['sell_counted_date'] = G.today
        if not save_state(critical=True):
            # A1修复(2026-10-17): 完整回滚 — 卖单未发到柜台前, 状态文件必须保持"未退出"语义,
            # 否则进程重启后此仓永久卡在 exited=True/柜台无单的"幽灵冻结"状态, 永不再被卖出决策触发。
            h['exited'] = False
            h['sell_ts'] = 0.0
            h['sell_retries'] = 0
            h['sell_cancel_sent'] = False
            h.pop('sell_submit_unknown', None)
            h.pop('sell_pending_t1', None)
            # 回滚卖出笔数计数(只回滚首次发单的当日计数; 部分成交后非首次计数不滚)
            if h.get('sell_counted_date') == G.today:
                try:
                    _b = daily_sell_state()
                    if isinstance(_b, dict):
                        _n = int(_b.get('n', 0) or 0)
                        if _n > 0:
                            _b['n'] = _n - 1
                        _codes = [c for c in (_b.get('codes') or []) if c != s]
                        _b['codes'] = _codes
                except Exception as _e_rb:
                    # 20261027审计: 原为静默 pass —— 回滚失败会导致当日卖出笔数虚增,
                    #   达到 MAX_DAILY_SELLS 后该票当日无法再卖; 至少留下可追溯证据。
                    log('[警告] 卖出笔数回滚失败(当日卖出计数可能虚增): %s' % repr(_e_rb)[:120])
                h['sell_counted_date'] = ''
            log(disp(s), '交易关键状态无法落盘, 已取消本次卖出发单(并完整回滚卖出在途/笔数/状态, 防幽灵冻结)')
            return False
        # 2026-10-04: 卖出放行触发日志 —— 实发单前明确输出卖出触发条件与关键参数, 便于核对调试
        _snp = net_pnl_if_sell(h, px, s, vol)
        _scb = loss_cost_basis(h)
        trigger_log('卖出放行', '卖出',
                    '所有卖出前置校验全部通过(非亏损持仓 + 扣费净利为正 + 委托价在笼子/涨跌停内侧), 按此发限价保护单',
                    code=disp_code(s, h.get('name', '')),
                    price=lp, order_price=px, vol=vol, amount=_round2(px * vol),
                    cost_basis=_scb, gross_pnl=(px - _scb) if _scb > 0 else 0.0,
                    net_pnl=_snp, slippage_pct=SLIPPAGE_PCT,
                    held_days=h.get('hold_days', 0), reason=reason, mode=TRADE_MODE)
        # passorder: 24=股票卖, 1101=按股, 11=限价(保护价), quickTrade=2立即下单, 备注SELL|代码
        _api(passorder, 24, 1101, G.accid, s, 11, px, vol,
                  STRAT_TAG, 2, 'SELL|' + s, G.C)
        G.sell_cnt += 1
        cost = h.get('buy_price') or 0.0
        est_pnl = (lp - cost) * vol if cost > 0 else 0.0
        est_pct = (lp / cost - 1.0) * 100.0 if cost > 0 else 0.0
        days = held_trd_days(h.get('buy_date', ''))
        log('[实盘] 卖出委托已发 | %s | %d股 限价@%.2f(保护价) | 金额约=%.2f元 | 持仓%d天 | %s(按最新价预估, 实际以成交回报为准) | %s'
            % (disp_code(s, h.get('name', '')), vol, px, lp * vol, days,
               fmt_pnl(est_pnl, est_pct), reason))
        # 卖出上下文留给成交回报记账用(成交回报可能晚于持仓清零, 保证成本可追溯);
        # P1-4: 存全量成本与股数, 多笔回报按成交量比例结转, 不会重复计成本
        try:
            ctx = G.state.setdefault('sell_ctx', {})
            now_ts = time.time()
            for k in [x for x, v in ctx.items() if now_ts - _f(v.get('ts', 0)) > 3 * 86400]:
                ctx.pop(k, None)
            ctx[s] = {'name': h.get('name', ''), 'buy_date': h.get('buy_date', ''),
                      'cost_total': pos_cost(h), 'hold_vol': int(vol), 't0': h.get('t0', ''),
                      'reason': reason, 'ts': now_ts}
        except Exception:
            log('[警告] 卖出委托上下文(sell_ctx)保存失败, 成本结转可能失效')
            traceback.print_exc()
        mark_sold(s)
        G.state['done'][s] = h['t0']
        save_state()
        return True
    except Exception as e:
        # P1-1配套: 发单失败必须回滚在途状态(否则柜台没单但本地停留在"卖出在途"态,
        # 常规卖出判定被跳过), 回滚后下轮重新评估; 发单异常时柜台状态未知, 以在途单查询复核
        log('卖出下单结果未知(%s), 保留在途占位并等待柜台ORDER复核，禁止盲目重发' % e)
        traceback.print_exc()
        h['sell_submit_unknown'] = True
        h['sell_ts'] = time.time()
        h['sell_cancel_sent'] = False
        save_state(critical=True)
        return False


def _own_order(o, s, side):
    """P1-20/P2-25: 判断柜台委托对象是否属于【本策略对s的指定方向】委托。
    ① 备注前缀(BUY|/SELL|)匹配 → 是; ② 备注非空但不匹配 → 他人委托, 否;
    ③ 备注为空(客户端不回传/截断) → 按策略名STRAT_TAG + ordids登记的委托侧兜底识别。
    P1-20: 策略名过滤防同账号多程序互相误撤; P2-25: 备注缺失不再一律当"无委托"。"""
    rm = str(getattr(o, 'm_strRemark', '') or '')
    pre = ('BUY|' if side == 'buy' else 'SELL|')
    if rm.startswith(pre):
        return True
    if rm.strip():
        return False          # 有备注但不匹配: 视为他人/其他策略委托
    tag = str(getattr(o, 'm_strStrategyName', '') or '')
    if tag and tag != STRAT_TAG:
        return False
    # V2.6.159: 按方向取登记(旧结构自动兼容) —— 原来是整条记录比对方向, 买卖一覆盖就判错
    return bool(str(_oid_rec(s, side).get('id', '') or ''))

def _find_order_obj(s, side, ords_snap=None):
    """查柜台侧本策略对s的指定方向委托; 返回优先级:
    ① 精确ID命中且仍存活(P2-24: 绝不返回已被取代的旧单当在途) → ② 任一存活委托(最新)
    → ③ 精确ID命中(已终结, 供已成/部成判定) → ④ 最新已终结委托(旧兜底, 维持重报链路)。
    查不到返回None, 查询失败返回'_ERR'哨兵。
    P1-01: ords_snap=锁外预取的委托快照, 传入则直接用快照, 避免锁内重复柜台查询"""
    try:
        ords = ords_snap if ords_snap is not None \
            else (_api(get_trade_detail_data, G.accid, 'STOCK', 'ORDER') or [])
    except Exception:
        return '_ERR'          # 风险2修复: 查询失败与"无委托"区分, 调用方据此 wait 不重发
    # V2.6.159: 按方向取登记单号(旧结构自动兼容)
    rec_id = str(_oid_rec(s, side).get('id', '') or '')
    act = None
    act_key = None
    rec_hit = None
    any_best = None
    any_key = None
    for o in ords:
        code = '%s.%s' % (getattr(o, 'm_strInstrumentID', ''), getattr(o, 'm_strExchangeID', ''))
        if code != s or not _own_order(o, s, side):
            continue
        oid = str(getattr(o, 'm_strOrderID', '') or getattr(o, 'm_strOrderSysID', '') or '')
        st = int(getattr(o, 'm_nOrderStatus', -1))
        key = _oid_sort_key(oid)
        if rec_id and oid == rec_id:
            rec_hit = o
            if st in ACTIVE_ORDER_STATUS:
                return o                      # 精确命中且仍存活: 最优
        if st in ACTIVE_ORDER_STATUS:
            if act_key is None or key >= act_key:
                act_key, act = key, o
        if any_key is None or key >= any_key:
            any_key, any_best = key, o
    if act is not None:
        return act              # P2-24: 优先存活委托, 防精确匹配命中已终结旧单导致误判/误撤
    if rec_hit is not None:
        return rec_hit
    return any_best

def sell_order_obj(s, ords_snap=None):
    """查柜台侧本策略对s的最新卖出委托对象; 查不到返回None, 查询失败返回'_ERR'哨兵。
    P1-3加固: 优先按order_callback记录的最新委托ID精确匹配(状态文件ordids),
    无记录时按ID数值序取最大(旧逻辑字符串序会把'9'排在'100'后, 撤单重报后可能选错
    委托导致误判已终结而重复发单)
    审计修复P1-5: DRY_RUN模拟盘无真实柜台委托, 统一按"无在途委托"处理(成交已即时回报)
    P1-01: ords_snap=锁外预取的委托快照"""
    if DRY_RUN:
        return None
    return _find_order_obj(s, 'sell', ords_snap)


def cancel_sell_order(o):
    """撤掉卖出委托(仅实盘)。P1-5加固: 只用委托对象自身的OrderID撤单,
    绝不回退到get_last_order_id(那会拿到账户最后一笔任意委托, 可能误撤其它策略/人工的单)"""
    try:
        oid = str(getattr(o, 'm_strOrderID', '') or '')
        if not oid or oid == '-1':
            return False
        if not _api(can_cancel_order, oid, G.accid, 'STOCK'):
            return False
        result = _api(cancel, oid, G.accid, 'STOCK', G.C)
        if result is False:
            return False
        code = '%s.%s' % (getattr(o, 'm_strInstrumentID', ''), getattr(o, 'm_strExchangeID', ''))
        log(disp(code), '卖出撤单指令已发出 OrderID=%s(确认撤销后按最新价重发)' % oid)   # P2-13: 撤单日志带OrderID
        return True
    except Exception:
        traceback.print_exc()
        return False


def handle_unfilled_sell(s, h, pos_avail, lp, tick=None, ords_snap=None):
    """卖出委托在途/超时处理(P1-2)。返回'wait'=继续等待(不重复发单) /
    'resent'=已重发新委托 / 'giveup'=重试用尽(停止自动卖出, 等待人工或T+1)。
    规则: 在途未超时一律等待; 超时查柜台: 仍存活先撤; 已终结(含部分成交后部撤/已撤)
    按可用持仓余量重发剩余部分(仍受净利闸门与重试上限约束)
    风险3修复: sell_retry_now标记(柜台拒单)时绕过超时等待, 立即重发;
    P1-1加固: 拒单重发同样受SELL_ORDER_RETRIES上限约束, 防持续拒单时全天无限重发废单"""
    now = time.time()
    # P2-4修复(2026-10-19): 对称消费 sell_submit_unknown(镜像买入侧 buy_submit_unknown
    # 处理)。原代码 place_sell_order 抛异常时置位该标记(委托状态未知, 可能已到柜台),
    # 但全文件无人读取它, 成为死标记: 该笔卖出永远停留在刚提交状态, 既不撤单也不
    # 重试, 挂单可能残留到收盘。现在入口处立即重查委托: 查询失败->刷新 sell_ts 下轮
    # 再查; 委托在途->刷新 sell_ts 继续等待(由超时逻辑撤单); 委托已终态->落入下方
    # 常规流程(撤单重试/放弃), 消除买卖两侧不对称
    if h.get('sell_submit_unknown'):
        h['sell_submit_unknown'] = False
        _o0 = sell_order_obj(s, ords_snap)
        if _o0 == '_ERR':
            h['sell_ts'] = now
            return 'wait'
        if _o0 is not None:
            h['sell_err_n'] = 0           # 查询恢复: 清零连续查询失败计数
        if _o0 is not None and int(getattr(_o0, 'm_nOrderStatus', -1)) in ACTIVE_ORDER_STATUS:
            h['sell_ts'] = now            # 委托确实在途: 继续等待, 超时后走撤单
            return 'wait'
    # 风险3修复: 柜台拒单后的立即重发通道 —— 不等300秒超时, 直接进入重发流程
    if h.get('sell_retry_now'):
        h['sell_retry_now'] = False
        if int(h.get('sell_retries', 0) or 0) >= SELL_ORDER_RETRIES:
            # P1-1加固: 拒单重发不豁免次数上限(旧逻辑持续拒单时每30秒无限重发废单)
            if not h.get('sell_giveup'):
                h['sell_giveup'] = True
                h['giveup_ts'] = time.time()  # giveup时间戳, 用于超时自动重试
                # P1-4: giveup必须复位exited —— 否则该仓永久停留在"卖出在途"态:
                # 名额被永久释放、盈亏快照跳过、常规卖出判定永不评估(止盈纪律失效)
                h['exited'] = False
                # P3-C-N4(2026-10-29 修复)：策略放弃自动卖出后必须清掉 sell_ctx，
                #   否则 deal_callback 的四重判据里 `not sell_ctx.get(code)` 恒不成立，
                #   用户在券商端手工卖出的成交永远不会被识别入账 -> 幽灵持仓占着名额与额度。
                try:
                    (G.state.get('sell_ctx') or {}).pop(s, None)
                except Exception:
                    pass
                save_state()
            if h.get('sell_note_date') != G.today:
                h['sell_note_date'] = G.today
                trigger_log('卖出未成交-拒单重发耗尽', '卖出',
                            '柜台多次拒单, 拒单重发次数已达上限, 停止自动卖出, 请人工检查',
                            code=disp(s), retries=SELL_ORDER_RETRIES, max_retries=SELL_ORDER_RETRIES)
                log(disp(s), '卖出拒单重发已达%d次上限, 停止自动卖出, 请人工检查该持仓(策略继续持有不动作)'
                    % SELL_ORDER_RETRIES)
            return 'giveup'
        vol = int(pos_avail.get(s, 0))
        if vol > 0 and lp > 0:
            if place_sell_order(s, h, vol, lp, '卖出拒单重发(柜台拒单, 已重夹价格)', tick, ords_snap):
                return 'resent'
        return 'wait'
    ts = _f(h.get('sell_ts', 0.0))
    if ts <= 0:
        h['sell_ts'] = now
        return 'wait'
    if SELL_ORDER_TIMEOUT_SEC > 0 and now - ts < SELL_ORDER_TIMEOUT_SEC:
        return 'wait'                     # 在途未超时: 绝不重复发单(旧逻辑每30秒重发一单)
    o = sell_order_obj(s, ords_snap)
    if o == '_ERR':                      # 风险2修复: 查询失败时一律 wait, 下轮复核
        # P2-6修复(2026-10-17): 与买入侧同口径 —— 查询失败不再无限续期, 连续
        # SELL_ORDER_ERR_MAX次失败即重置超时计时(sell_ts=0, 下轮按超时路径撤单重发)
        h['sell_err_n'] = int(h.get('sell_err_n', 0) or 0) + 1
        if h['sell_err_n'] >= SELL_ORDER_ERR_MAX:
            log(disp(s), '卖出委托状态连续%d次查询失败, 重置超时计时按撤单重发流程处理(防计时器无限续期)'
                % h['sell_err_n'])
            h['sell_err_n'] = 0
            h['sell_ts'] = 0.0
            h['sell_cancel_sent'] = False
        else:
            h['sell_ts'] = now
        return 'wait'
    st = int(getattr(o, 'm_nOrderStatus', -1)) if o else -1
    # P0-1(2026-10-24 第18轮零预设独立审计): 卖出侧补"撤单确认宽限期", 与买入侧
    #   handle_unfilled_buy 的 CANCEL_CONFIRM_GRACE_SEC 完全对称。
    #   旧版只有买入侧有该保护: 卖出侧撤单指令发出后, 只要委托对象从查询快照里消失,
    #   就直接按"已撤"重发余量, 会把"撤单已发但柜台还没落地"(在途委托仍挂着)的状态
    #   误判成已撤 -> 旧单与新单同时在场 -> 可能双倍成交(超卖)。
    #   危害例: 持仓1000股, 超时撤单后快照瞬时漏单 -> 立刻重发1000股 -> 旧单随后也成交
    #   -> 实际要卖2000股而只有1000股, 柜台拒次单或产生负债持仓。
    #   修法: 宽限期内只等待不重发; 宽限期已过仍未查到, 才视为已撤允许重报(只收紧不放松)。
    if h.get('sell_cancel_sent') and o is None:
        _cts_s = _f(h.get('cancel_ts', 0.0))
        if _cts_s > 0 and (now - _cts_s) < CANCEL_CONFIRM_GRACE_SEC:
            h['sell_ts'] = now
            return 'wait'
        log(disp(s), '卖出撤单确认等待超过%.0f秒仍未在柜台查到, 按已撤处理(宽限期已过), 允许重发余量'
            % CANCEL_CONFIRM_GRACE_SEC)
        h['sell_cancel_sent'] = False      # 视为已撤: 清标记, 允许按余量重发
        h['sell_err_n'] = 0
    if o and st in ACTIVE_ORDER_STATUS:
        if not h.get('sell_cancel_sent'):
            if cancel_sell_order(o):
                h['sell_cancel_sent'] = True
                h['cancel_ts'] = now        # P0-1: 记录撤单发出时刻, 供上方宽限期判定
                h['sell_ts'] = now
                trigger_log('卖出未成交-超时撤单', '卖出',
                            '委托超时未成交, 已发撤单指令, 确认撤销后按最新价重发余量',
                            code=disp(s), elapsed=int(now - ts), timeout_sec=SELL_ORDER_TIMEOUT_SEC,
                            order_id=getattr(o, 'm_strOrderID', '') or '',
                            retry=min(int(h.get('sell_retries', 0) or 0) + 1, SELL_ORDER_RETRIES),
                            max_retries=SELL_ORDER_RETRIES)
                log(disp(s), '卖出委托超时%d秒未成交, 撤单指令已发出, 确认撤销后按最新价重发(第%d/%d次)'
                    % (int(now - ts), int(h.get('sell_retries', 0) or 0) + 1, SELL_ORDER_RETRIES))
                save_state()
            else:
                h['sell_ts'] = now
        return 'wait'
    # 委托已终结: 全部未成交(已撤/废单)或部分成交后被撤(部撤) —— 统一按可用持仓余量重发。
    # P1-2加固: 旧逻辑对"有部分成交"一律永久wait, 剩余持仓从此无人再卖(自动卖出停摆);
    # 新逻辑重发余量 = 当前可用持仓(已成交部分柜台已扣减), 净利闸门与重试上限照常生效
    traded = int(getattr(o, 'm_nVolumeTraded', 0) or 0) if o else 0
    retries = int(h.get('sell_retries', 0) or 0)
    if retries >= SELL_ORDER_RETRIES:
        if not h.get('sell_giveup'):
            h['sell_giveup'] = True
            h['giveup_ts'] = time.time()  # giveup时间戳, 用于超时自动重试
            # P1-4: giveup必须复位exited(见拒单分支注释): 名额/盈亏口径恢复计入该仓,
            # 常规卖出判定恢复评估(次日sell_giveup由新一轮卖出决策自动复位)
            h['exited'] = False
            # P3-C-N4(2026-10-29 修复)：同拒单分支——放弃自动卖出即清 sell_ctx，
            #   让后续用户手工卖出能被四重判据正常识别入账。
            try:
                (G.state.get('sell_ctx') or {}).pop(s, None)
            except Exception:
                pass
            save_state()
        if h.get('sell_note_date') != G.today:
            h['sell_note_date'] = G.today
            trigger_log('卖出未成交-重发耗尽', '卖出',
                        '委托重发次数已达上限仍未全部成交, 停止自动卖出, 请人工检查该持仓',
                        code=disp(s), retries=retries, max_retries=SELL_ORDER_RETRIES,
                        traded=traded, remaining=int(pos_avail.get(s, 0) or 0))
            log(disp(s), '卖出委托重发%d次仍未完成%s, 停止自动卖出, 请人工检查该持仓(策略继续持有不动作)'
                  % (retries, ('(已部分成交%d股, 余量未续卖)' % traded) if traded > 0 else ''))
        return 'giveup'
    vol = int(pos_avail.get(s, 0))
    if vol <= 0 or lp <= 0:
        return 'wait'
    h['sell_retries'] = retries           # place_sell_order内会+1
    why = ('卖出超时重发(第%d次)' % (retries + 1) if traded <= 0 else
           '卖出部分成交%d股后剩余重发(余%d股, 第%d次)' % (traded, vol, retries + 1))
    if place_sell_order(s, h, vol, lp, why, tick, ords_snap):
        log(disp(s), '卖出委托已终结(已成交%d股), 按最新价%.2f重发剩余%d股(第%d/%d次)'
            % (traded, lp, vol, retries + 1, SELL_ORDER_RETRIES))
        return 'resent'
    return 'wait'

# ==================== 信号与轮询(规则2买点+规则3卖点) ====================
# ==================== 实盘买入委托超时管理(方案三) ====================
ACTIVE_ORDER_STATUS = (48, 49, 50, 51, 52, 55)  # 未报/待报/已报/已报待撤/部成待撤/部成: 委托仍存活

def buy_order_obj(s, ords_snap=None):
    """查柜台侧本策略对s的最新买入委托对象; 查不到返回None, 查询失败返回'_ERR'哨兵。
    P1-3加固: 选取规则同sell_order_obj(记录ID精确匹配优先, 数值序兜底)
    审计修复P1-5: DRY_RUN模拟盘无真实柜台委托, 统一按"无在途委托"处理(成交已即时回报)
    P1-01: ords_snap=锁外预取的委托快照"""
    if DRY_RUN:
        return None
    return _find_order_obj(s, 'buy', ords_snap)

def cancel_buy_order(s, o):
    """撤掉本策略对s的买入委托(仅实盘): 内置API can_cancel_order/cancel;
    返回True表示撤单指令已发出(最终结果以柜台委托状态为准)。
    P1-5加固: 只用委托对象自身的OrderID撤单, 拿不到ID直接返回False并告警 ——
    绝不回退get_last_order_id(那是账户最后一笔任意委托, 会误撤卖出单/其它策略的单)"""
    try:
        oid = str(getattr(o, 'm_strOrderID', '') or '')
        if not oid or oid == '-1':
            log(disp(s), '撤单受阻: 委托对象缺少OrderID, 为防误撤他人委托, 本轮不撤(下轮复核)')
            return False
        if not _api(can_cancel_order, oid, G.accid, 'STOCK'):
            return False
        result = _api(cancel, oid, G.accid, 'STOCK', G.C)
        if result is False:
            return False
        log(disp(s), '买入撤单指令已发出 OrderID=%s(确认撤销后按最新价重报)' % oid)   # P2-13: 撤单日志带OrderID
        return True
    except Exception:
        traceback.print_exc()
        return False

def handle_unfilled_buy(s, h, ords_snap=None):
    """买入委托全生命周期管理；部分成交后继续管理未成交余量。"""
    now = time.time()
    # P2-13修复(2026-10-19): 已有部分成交但放弃挂单管理的占位记录(A3保留路径),
    # 直接早返回, 不再走超时撤单/重试/删除流程; 该记录由主循环按正常持仓管理
    # (pos_total>0 时走卖出信号/金字塔), 或次日按空持仓结算清理
    if h.get('buy_abandoned'):
        return
    # P2-05: 消费"结果未知"死标记 —— buy_stock 发单异常分支置位后若无人消费,
    # 标记永久残留(既不重报也不清理, 交易卡在未知态); 本函数开头消费并查柜台:
    # 委托已送达且在途则继续等待成交, 未送达/终结则落回常规超时与重报流程
    if h.get('buy_submit_unknown'):
        h['buy_submit_unknown'] = False
        _o0 = buy_order_obj(s, ords_snap)
        if _o0 == '_ERR':
            h['order_ts'] = now
            return
        if _o0 != '_ERR':
            h['order_err_n'] = 0           # P2-6: 查询恢复即清零失败计数
        if _o0 is not None and int(getattr(_o0, 'm_nOrderStatus', -1)) in ACTIVE_ORDER_STATUS:
            h['order_ts'] = now            # 委托其实已送达且在途: 正常等待, 绝不重报
            return
    ts = _f(h.get('order_ts', 0.0))
    if ts <= 0:
        h['order_ts'] = now         # 兼容老记录: 无委托时间戳以本时刻起算
        return
    if BUY_ORDER_TIMEOUT_SEC <= 0:  # 关闭时维持旧行为: 每300秒提示一次
        if now - h.get('wait_note_ts', 0) >= 300:
            h['wait_note_ts'] = now
            ost = query_order_status(s, ords_snap)
            log(disp(s), '今日买入委托未成交(持仓回报未到), 柜台委托状态: %s'
                % (ost or '未查到本策略委托记录(委托可能未送达柜台, 请检查策略交易界面柜台选择)'))
        return
    if now - ts < BUY_ORDER_TIMEOUT_SEC:
        if now - h.get('wait_note_ts', 0) >= 300:
            h['wait_note_ts'] = now
            trigger_log('买入未成交-等待中', '买入',
                        '委托仍在柜台排队, 尚未成交, 继续等待至超时阈值',
                        code=disp(s), elapsed=int(now - ts), timeout_sec=BUY_ORDER_TIMEOUT_SEC,
                        pend_vol=int(h.get('pend_vol', 0)), order_id=h.get('ordid', ''))
            log(disp(s), '买入委托等待成交(%d/%d秒), 柜台委托状态: %s'
                % (int(now - ts), BUY_ORDER_TIMEOUT_SEC, query_order_status(s, ords_snap) or '未查到'))
        return
    # ---- 已超时: 查柜台委托状态 ----
    o = buy_order_obj(s, ords_snap)
    if o == '_ERR':                         # 风险2修复: 查询失败不重报, 等下轮复核
        # P2-6修复(2026-10-17): 查询失败不再无限续期 —— 单独计数, 连续BUY_ORDER_ERR_MAX次
        # 失败即重置超时计时(order_ts=0, 下轮按超时路径撤单重报), 防计时器被永远重置
        h['order_err_n'] = int(h.get('order_err_n', 0) or 0) + 1
        if h['order_err_n'] >= BUY_ORDER_ERR_MAX:
            log(disp(s), '买入委托状态连续%d次查询失败, 重置超时计时按撤单重报流程处理(防计时器无限续期)'
                % h['order_err_n'])
            h['order_err_n'] = 0
            h['order_ts'] = 0.0
            h['cancel_sent'] = False
        else:
            h['order_ts'] = now
        return
    st = int(getattr(o, 'm_nOrderStatus', -1)) if o else -1
    if o and st in ACTIVE_ORDER_STATUS:
        if not h.get('cancel_sent'):
            if cancel_buy_order(s, o):
                h['cancel_sent'] = True
                h['cancel_ts'] = now
                trigger_log('买入未成交-超时撤单', '买入',
                            '委托超时未成交, 已发撤单指令, 确认撤销后按最新价重报',
                            code=disp(s), elapsed=int(now - ts), timeout_sec=BUY_ORDER_TIMEOUT_SEC,
                            order_id=getattr(o, 'm_strOrderID', '') or h.get('ordid', ''),
                            retry=min(int(h.get('order_retries', 0)) + 1, BUY_ORDER_RETRIES),
                            max_retries=BUY_ORDER_RETRIES, pend_vol=int(h.get('pend_vol', 0)))
                log(disp(s), '买入委托超时%d秒未成交, 撤单指令已发出, 确认撤销后按最新价重报(额度%d/%d)'
                    % (int(now - ts), int(h.get('order_retries', 0)) + 1, BUY_ORDER_RETRIES))
            else:
                log(disp(s), '买入委托超时但撤单指令发送失败, 重新计时下轮再试')
                h['order_ts'] = now
            save_state()
        return
    # 委托已不在活动列表: 已撤(54)/废单(57)可直接重报; 已发撤单且委托消失也可重报;
    # 已成(56)交给持仓回报路径; 查不到且未撤过(可能未送达柜台): 维持提示不盲重报, 防止重复委托
    # 审计修复G5: 撤单确认加宽限期 —— 撤单指令发出后, 委托对象可能尚未从查询列表消失,
    # 直接按"cancel_sent且查不到"立即重报会在柜台撤单未落地时造成"边撤边发"竞态;
    # 增加CANCEL_CONFIRM_GRACE_SEC(默认5秒)宽限, 宽限内保持等待, 宽限后才允许重报
    terminal = bool(o and st in (53, 54, 57))
    _cancel_confirmed = False        # P0-2(第18轮审计): 撤单宽限期已过且委托彻底消失 = 按"已撤终态"处理
    if h.get('cancel_sent') and o is None:
        # V2.6.167修复(2026-10-23 全量零预设独立审计·第二部分): CANCEL_CONFIRM_GRACE_SEC
        #   原先只用"发过撤单"(cancel_sent)做记录, 没记下"什么时候发的撤单"(cancel_ts),
        #   于是每次重报都靠"查不到就当已撤"来判断, 会把"撤单指令已发出但柜台还没落地"
        #   (在途委托还挂着)的状态误判成已撤 -> 立刻重报, 结果旧单与新单同时在场,
        #   可能双份成交(双倍占资); 现改为用 CANCEL_CONFIRM_GRACE_SEC 宽限期兜底:
        #   撤单发出后宽限期内一律只等待不重报, 超过宽限期仍未在柜台查到才允许重报。
        _cts = _f(h.get('cancel_ts', 0.0))
        if _cts > 0 and (now - _cts) < CANCEL_CONFIRM_GRACE_SEC:
            # 宽限期内: 保持占位与在途量, 不重报, 避免旧单与重报单同时成交
            h['order_ts'] = now
            return
        log(disp(s), '撤单确认等待超过%.0f秒仍未在柜台查到, 按已撤处理(宽限期已过), 允许重报'
            % CANCEL_CONFIRM_GRACE_SEC)
        h['cancel_sent'] = False      # 视为已撤: 清标记, 允许下轮重报
        h['order_err_n'] = 0
        _cancel_confirmed = True      # P0-2(第18轮审计): 宽限期已过且委托从柜台彻底消失(o=None),
                                      #   属"已撤"终态, 必须继续走下方重报/放弃链路。
                                      #   旧版漏此标记 -> terminal 仍为 False -> 每轮只打印
                                      #   "等待下轮复核, 不盲目重报" -> 不重报、不计数、不清理,
                                      #   该买入当日退化为僵尸在途(白占持仓名额与资金额度),
                                      #   直到次日 buy_date != G.today 才自愈。
    if not terminal and not _cancel_confirmed:
        if now - h.get('wait_note_ts', 0) >= 300:
            h['wait_note_ts'] = now
            log(disp(s), '买入委托未查到活动记录(状态%s), 等待下轮复核, 不盲目重报'
                % ORDER_STATUS_MAP.get(st, '未知状态(%s)' % st))
        return
    h['cancel_sent'] = False
    traded = int(getattr(o, 'm_nVolumeTraded', 0) or 0) if o else 0
    ovol = int(getattr(o, 'm_nVolume', 0) or 0) if o else 0
    if traded > 0 and ovol > 0:
        # P2-23: 以柜台口径重建在途量 = 委托总量 - 已成交(成交回报可能已逐笔核销过,
        # 直接再减一次会重复扣, 导致重报数量偏小甚至"不足一手"放弃)
        h['pend_vol'] = max(0, ovol - traded)
        save_state()
        # 部分成交后的剩余量继续走下方重报流程补买(旧逻辑直接return, 剩余量永久放弃)
    elif traded > 0:
        h['pend_vol'] = max(0, int(_f(h.get('pend_vol', 0))) - traded)
        save_state()
        return
    # P0-2加固: 重报数量=原委托未成交量(pend_vol), 不是buy_vol累计值
    pend = int(_f(h.get('pend_vol', 0)))
    if pend <= 0:
        pend = int(_f(h.get('buy_vol', 0))) - int(_f(h.get('fill_vol', 0)))   # 兼容老记录
    pend = normalize_buy_volume(s, pend)
    _min_buy = 200 if is_kcb_code(s) else 100
    if pend < _min_buy:
        trigger_log('买入未成交-在途不足一手', '买入',
                    '撤单后剩余在途股数不足一手(100股), 无法重报, 放弃本次买入并退回当日额度',
                    code=disp(s), pend_vol=max(0, pend), lot_size=100)
        log(disp(s), '重报股数不足一手(在途%d股), 放弃重报' % max(0, pend))
        G.state['done'].pop(s, None)
        if _safe_rollback_placeholder(s):
            # 确认无成交也无残留挂单量: 执行原删除+退回当日买入名额逻辑
            b = daily_buy_state()
            b['n'] = max(0, b['n'] - 1)
            if s in (b.get('codes') or []):
                b['codes'].remove(s)
            _disk_adjust_daily_buy(-1, s)   # P2-21: 同步修正磁盘计数(防合并逻辑把退额改回)
            save_state()
        else:
            # P2-13修复(2026-10-19): 原为直接 del G.state['hold'][s]——该笔买入
            # 委托已有部分成交(fill_vol>0)时会把真实持仓记录删掉, 仓位从管理中消失
            # (无法止盈/金字塔/卖出); _safe_rollback_placeholder 已拒绝删除并日志,
            # 这里保留记录转正常持仓管理(详见 _keep_partial_hold)
            _keep_partial_hold(s)
        return
    retries = int(h.get('order_retries', 0) or 0)
    if retries >= BUY_ORDER_RETRIES:
        # 重报额度用尽: 放弃本次买入, 清理记录并退回当日买入额度(次日自动恢复)
        trigger_log('买入未成交-重试额度耗尽', '买入',
                    '委托重报次数已达上限仍未成交, 放弃本次买入, 退回当日买入额度(次日恢复)',
                    code=disp(s), retries=retries, max_retries=BUY_ORDER_RETRIES,
                    pend_vol=max(0, pend))
        log(disp(s), '买入委托%d次仍未成交, 放弃本次买入, 已退回当日买入额度(次日恢复)' % retries)
        G.state['done'].pop(s, None)    # 从未成交, 不留卖出间隔
        if _safe_rollback_placeholder(s):
            # 确认无成交也无残留挂单量: 执行原删除+退回当日买入名额逻辑
            b = daily_buy_state()
            b['n'] = max(0, b['n'] - 1)
            if s in (b.get('codes') or []):
                b['codes'].remove(s)
            _disk_adjust_daily_buy(-1, s)   # P2-21: 同步修正磁盘计数(防合并逻辑把退额改回)
            save_state()
        else:
            # P2-13修复(2026-10-19): 原为直接 del G.state['hold'][s]——该笔买入
            # 委托已有部分成交(fill_vol>0)时会把真实持仓记录删掉, 仓位从管理中消失
            # (无法止盈/金字塔/卖出); _safe_rollback_placeholder 已拒绝删除并日志,
            # 这里保留记录转正常持仓管理(详见 _keep_partial_hold)
            _keep_partial_hold(s)
        return
    try:
        t = (_api(G.C.get_full_tick, [s]) or {}).get(s) or {}
        lp = _f(t.get('lastPrice'))
    except Exception:
        lp = 0.0
    if lp <= 0:
        return                      # 行情异常不消耗重报次数, 下轮再试
    # 审计修复I2: 重报价同样上移滑点; I4: 保护带按标的自适应
    px = clamp_order_price(_round2(lp * (1.0 + _slippage_for(lp))), t, True, s)      # V2.6.58b: 重报滑点与主买入一致(低价股0.3%); P2-5: 重报价夹到笼子/涨跌停内侧
    if px <= 0:
        return
    # 审计修复G6: 重报属于买入动作, 应校验买入范围而非误用卖出范围
    if not buy_scope_ok(s):
        # 交易铁律: 记录已被清理(非策略标的)时拒绝重报
        scope_refuse(s, '买入重报')
        return
    _eb = emergency_block('new')
    if _eb:
        log(disp(s), '买入重报暂缓: %s (保留在途量, 待应急解除后继续)' % _eb)
        return
    # D6：重报必须按最新价重新走追高、单票/组合额度和现金检查，不能照搬旧数量。
    _zt0 = _f(h.get('zt_close', 0.0))
    if _zt0 > 0 and lp > _zt0 * (1.0 + MAX_CHASE_OVER_ZT):
        log(disp(s), '买入重报暂缓: 最新价%.2f超过涨停收盘价%.2f的追高上限%.1f%%'
            % (lp, _zt0, MAX_CHASE_OVER_ZT * 100.0))
        return
    try:
        _pt6, _pa6, _cash6 = query_account()
    except Exception:
        _cash6 = None
    if _cash6 is None:
        log(disp(s), '买入重报暂缓: 可用现金查询失败，保留在途量下轮复核')
        return
    _cash6 = eff_cash(_cash6)
    _lot6 = 1 if is_kcb_code(s) else (int(LOT_SIZE) if LOT_SIZE > 0 else 100)
    _caps6 = [int(pend)]
    # P3-C-N1(2026-10-29 修复)：重报额度必须【剔除本单自身占用的额度】。
    #   原实现直接用 MAX_POS_VALUE_ABS - pos_cost(h) 与 abs_cap_left(px)，而 used_capital()
    #   已把当前这笔在途买单的成本算在内 —— 同一笔钱被扣两次，重报数量被削到很小甚至
    #   不足一手而放弃，单批首单因此变成僵尸单（占着名额与额度一整天，既不成交也不释放）。
    #   这里按本单剩余量估算自身占用并从可用额度中加回，仅影响重报数量，不改任何闸门口径。
    _self_occ6 = _f(px) * _f(max(0, int(pend)))
    if MAX_POS_VALUE_ABS and MAX_POS_VALUE_ABS > 0:
        _remain_one6 = max(0.0, MAX_POS_VALUE_ABS - _f(pos_cost(h)) + _self_occ6)
        _caps6.append(int(_remain_one6 / px) if px > 0 else 0)
    _left6 = abs_cap_left(px)
    if _left6 is not None:
        _caps6.append(int((_f(_left6) + _self_occ6) / px) if px > 0 else 0)
    _cash_vol6 = 0
    if px > 0:
        _cash_vol6 = int(_cash6 / px)
        while _cash_vol6 > 0 and px * _cash_vol6 + fee_buy(px * _cash_vol6, s) > _cash6 + 1e-6:
            _cash_vol6 -= _lot6
    _caps6.append(max(0, _cash_vol6))
    pend = normalize_buy_volume(s, min(_caps6))
    if pend <= 0:
        log(disp(s), '买入重报暂缓: 最新价下单票/组合额度或现金不足最小申报量')
        return
    # V2.6.168: 重报侧与买入侧同口径卡帽子(单票绝对额度 / 组合剩余额度)
    #   重报数量若按估算价折算额度, 同样可能顶穿上限; 这里用委托价 + 真实费用复核,
    #   只削不增, 削平后不足一手则不发重报。
    _amts_r168 = []
    if MAX_POS_VALUE_ABS and MAX_POS_VALUE_ABS > 0:
        _amts_r168.append(max(0.0, float(MAX_POS_VALUE_ABS) - _f(pos_cost(h))))
    pend = normalize_buy_volume(s, cap_fit_volume(s, pend, px, _lot6, _amts_r168, '买入重报'))
    if pend <= 0:
        log(disp(s), '买入重报暂缓: 最新价下单票/组合额度或现金不足最小申报量(单票上限%.2f元)'
            % float(MAX_POS_VALUE_ABS))
        return
    if limit_gate_reject(s, px, True, '买入重报'):
        return
    # P3-C-N6(2026-10-29 修复)：对端实例检查必须【前移到计数自增之前】。
    #   原实现在 h['order_retries'] = retries + 1 之后才判断 _live_peer_exists()，
    #   检查不通过直接 return —— 但重试次数已经 +1 了。对端实例存活期间每根 bar
    #   都白耗一次，几轮就把 BUY_ORDER_RETRIES 耗尽，本实例恢复后已无重报机会。
    #   现先判对端，再动计数。
    if (not DRY_RUN) and _live_peer_exists():
        log('[安全][P1-2] 检测到存活的其它策略实例, 本轮回避买入重报(防重复下单, 不消耗重试次数)')
        return
    h['order_retries'] = retries + 1
    h['order_ts'] = time.time()
    h['pend_vol'] = int(pend)
    # P0-3修复(20261008): 仅零成交时用最新价覆盖成本; 已有部分成交保留加权均价
    # (fill_sum/fill_vol), 防污染 is_at_loss/net_pnl_if_sell/min_profit_pct 判据
    if int(_f(h.get('fill_vol', 0) or 0)) <= 0:
        h['buy_price'] = lp
    if not save_state(critical=True):
        h['order_retries'] = retries
        return
    try:
        if DRY_RUN:        # 审计修复I7: 模拟盘重报走构造成交回报
            if _sim_deal('BUY|' + s, px, int(pend)):
                log(disp(s), '[模拟盘] 买入委托重报成交, 按最新价%.2f成交%d股(第%d/%d次)'
                    % (px, pend, h['order_retries'], BUY_ORDER_RETRIES))
            else:
                # P2-01: 模拟重报未命中成交概率: 保留在途量(pend_vol), 下轮重试, 不虚报成交
                log(disp(s), '[模拟盘] 买入委托重报未成交(成交概率%.0f%%), 下轮重试'
                    % (SIM_FILL_PROB * 100))
        else:
            # P3-C-N6：对端实例检查已前移到计数自增之前，此处不再重复判断
            log('[应急闸门][通过] 买入重报 | %s | mode=%s | %d股'
                % (disp(s), emergency_mode_effective(), int(pend)))
            _api(passorder, 23, 1101, G.accid, s, 11, px, int(pend),
                      STRAT_TAG, 2, 'BUY|' + s, G.C)
            # P0-2修复(2026-10-04): 重报同样写buy_ctx兜底 —— 重报成交后若本地hold被
            # pend<100分支或重试耗尽分支清理, 补录建仓仍可凭新鲜buy_ctx恢复(旧版不写会失效)
            _set_buy_ctx(s, {'name': h.get('name', ''), 't0': h.get('t0', ''),
                             'base_vol': h.get('base_vol', 0), 'zt_close': h.get('zt_close', 0.0),
                             'vol': int(pend), 'price': _round2(px)})
            log(disp(s), '[实盘] 买入委托已撤, 按最新价%.2f重报%d股(第%d/%d次)'
                % (px, pend, h['order_retries'], BUY_ORDER_RETRIES))
    except Exception:
        log(disp(s), '买入重报结果未知, 保留重试计数并冻结该代码，等待柜台ORDER复核')
        h['buy_submit_unknown'] = True
        h['pend_vol'] = int(pend)
        traceback.print_exc()
    save_state(critical=True)

def run_round(sent_parsing=False):
    """每个策略状态执行一次: 先检查卖出, 再检查买入。
    P1修复(2026-10-02): 行情/柜台取数移到锁【外】—— 旧版全程持 G.state_lock 且函数内含
    get_full_tick / query_account 等网络IO, 而成交回报回调(deal_callback)需要同一把锁,
    会被整个轮询阻塞(最坏情况延迟成交回报处理数秒)。现只把"改写状态"的决策段持锁,
    取数在锁外完成。
    审计修复I5: 决策段仍持 G.state_lock —— 防与成交回报回调并发改写G.state"""
    # V2.6.66: 每轮入口先落盘一次缓冲 —— 非交易时段/静默期无新日志时,
    #   上一轮末行会滞留 G.log_buf 到下一次 log() 才写文件(文件比窗口少一行);
    #   此处非 force, 仍受 0.2秒/200条 节流约束, 开销可忽略。
    _flush_log()      # V2.6.66 心跳落盘
    if is_trading_day() is not True:      # 二次防线: 非交易日/日历异常绝不触发开平仓
        return
    now = datetime.datetime.now()
    elap = elapsed_trading_minutes(now)
    if elap <= 0:
        return
    # P1-4修复(2026-10-17): 盘中量能推算用放大系数k(默认linear, 贴合A股真实日内累计量能曲线)
    k = _proj_vol_ratio(elap)          # est = vol / k; 见 _proj_vol_ratio 注释
    with G.state_lock:
        trap_sweep()           # 套牢移交每日巡检: 已平仓的自动解除, 并输出一次移交概览
        hold = G.state['hold']
        cand_stocks = [c['stock'] for c in G.candidates if c['stock'] not in hold]
        watch = list(hold.keys()) + cand_stocks
    if not watch:
        return
    try:
        # V2.6.30 B→C: 统一走 _refresh_ticks(先订阅+get_full_tick, 空则1m K线兜底)
        ticks = _refresh_ticks(watch)             # P1修复: 网络IO在锁外
        # P0-1修复(20261008): 盘中首次核验tick快照volume单位, 与日线DAILY_VOL_UNIT换算防量能信号错100倍
        if getattr(G, 'tick_unit_probed', None) != G.today:
            G.tick_unit_probed = G.today
            # V2.6.17 口径锁定: tick快照volume单位=手, 与日线/分时同单位, 故换算系数恒为1;
            #   探测只核对不改判(原逻辑探测到"股"会把 G.tick_vol_unit 设为1, 量能预估偏差100倍)。
            #   TICK_VOL_UNIT: 0=按已确认口径(手); 100=强制手; 1=强制股(仅调试用, 会告警)。
            _forced = int(TICK_VOL_UNIT or 0)
            G.tick_vol_unit = 1 if _forced == 1 else 100
            if _forced == 1:
                log('[单位校准][告警] TICK_VOL_UNIT=1(强制按股) 与已确认口径(手)冲突: '
                    '量能预估将偏差100倍(缩量更易满足/放量更难过), 仅调试用, 建议改回0或100')
            # 20261027: 冷启动期 / 空观察池 两种情形跳过核对, 且不计异常天数。
            #   ① 开盘前 TICK_UNIT_COLDSTART_MIN 分钟: 多数票 volume 仍为0, 校验收敛不了;
            #   ② watch 为空(无持仓无候选): 没有标的可核对, 不存在"单位异常"。
            #   旧版两种情况都落进 else 分支记 _bad_days += 1, 三天即可把买入拉闸。
            #   G.tick_vol_unit 已在上面按 TICK_VOL_UNIT 锁定(默认恒按手=100), 交易数值零影响。
            _skip_unit_check = False
            _skip_reason = ''
            if not watch:
                _skip_unit_check = True
                _skip_reason = '观察池为空(无持仓无候选)'
            else:
                try:
                    _elapsed_uc = int(elapsed_trading_minutes(datetime.datetime.now()))
                except Exception:
                    _elapsed_uc = 999      # 取不到开盘时长则不跳过(按原逻辑核对, 保守)
                if _elapsed_uc < TICK_UNIT_COLDSTART_MIN:
                    _skip_unit_check = True
                    _skip_reason = ('开盘冷启动期(已开盘约%d分钟, 门槛%d分钟)'
                                    % (_elapsed_uc, TICK_UNIT_COLDSTART_MIN))
            if _skip_unit_check:
                if getattr(G, 'tick_unit_skip_logged', '') != (G.today + '|' + _skip_reason):
                    G.tick_unit_skip_logged = G.today + '|' + _skip_reason
                    log('[单位校准] 本轮跳过tick量单位核对: %s; 不计入异常天数'
                        '(量能换算仍按已确认口径=手, 系数1)' % _skip_reason)
            else:
                try:
                  _tu = detect_tick_volume_unit(watch)
                  if _tu == 100:
                      # 正常: 与已确认口径(手)一致 —— 重置异常天数; 若之前已拉闸且有人工确认则解除
                      _prev_blocked = False
                      _changed = False
                      with G.state_lock:
                          _prev_blocked = bool(G.state.get('tick_unit_blocked'))
                          if _prev_blocked or G.state.get('tick_unit_bad_days'):
                              _changed = True
                          G.state['tick_unit_bad_days'] = 0
                          G.state['tick_unit_bad_date'] = ''
                          if _prev_blocked and (TICK_UNIT_ACK or G.state.get('tick_unit_ack')):
                              G.state['tick_unit_blocked'] = False
                              G.state['tick_unit_ack'] = ''
                              _changed = True
                      # 20261027: 当天"先失败后成功"的处理见下面 with G.state_lock 内的清零逻辑 ——
                      #   判定为手即把 tick_unit_bad_days 归零(原逻辑), 叠加上方"跳过闸"(冷启动/空池不计数)
                      #   与 detect 的样本门槛按只数折算, 早盘样本不足不再被记成整天异常。
                      if _changed:
                          save_state()
                      log('[单位校准] tick快照volume核对: 判定为手, 与日线/分时口径一致(换算系数=1)')
                      if _prev_blocked:
                          log('[单位校准][恢复] 行情源已人工确认正常(tick量单位=手), 解除买入拉闸')
                  elif _tu == 1:
                      # 第6条修复(2026-10-17): 异常升级为"拉闸" —— 不再仅告警继续运行:
                      # 连续满 TICK_UNIT_BLOCK_DAYS 个交易日即强制暂停买入+每轮持续告警,
                      # 直到人工确认行情源正常(tick_unit_ack 或 TICK_UNIT_ACK)后才恢复买入。
                      _bad = 0
                      _need_save = False
                      _just_blocked = False
                      with G.state_lock:
                          _bad_day = G.state.get('tick_unit_bad_date')
                          _bad = int(G.state.get('tick_unit_bad_days', 0) or 0)
                          if _bad_day != G.today:
                              _bad += 1
                              G.state['tick_unit_bad_date'] = G.today
                              G.state['tick_unit_bad_days'] = _bad
                              _need_save = True
                          if _bad >= TICK_UNIT_BLOCK_DAYS and not G.state.get('tick_unit_blocked'):
                              G.state['tick_unit_blocked'] = True
                              G.state['tick_unit_ack'] = ''
                              _need_save = True
                              _just_blocked = True
                      if _need_save:
                          save_state()
                      if _just_blocked:
                          log('[单位校准][拉闸][告警] tick量单位异常已连续%d个交易日(判定为股, 与手口径冲突): '
                              '已强制暂停全部买入(主买入/分批加仓均拦截) —— 请人工检查行情源, 确认正常后: '
                              '①置 TICK_UNIT_ACK=True, 或 ②在状态文件写 "tick_unit_ack":"<确认日期>"'
                              % (_bad,))
                      elif _bad < TICK_UNIT_BLOCK_DAYS:
                          log('[单位校准][告警] tick快照volume核对不一致: 判定为股, 与已确认口径(手)冲突! '
                              '按已确认口径按手处理(换算系数=1); 异常第%d/%d天, 连续满%d天将强制暂停买入'
                              % (_bad, TICK_UNIT_BLOCK_DAYS, TICK_UNIT_BLOCK_DAYS))
                      else:
                          log('[单位校准][拉闸][告警] tick量单位异常持续(第%d天): 买入保持暂停, '
                              '等待人工确认行情源正常(TICK_UNIT_ACK=True或状态文件tick_unit_ack)' % (_bad,))
                  else:
                       # P3-X-N2(2026-10-29 修复)：观察池本身不足 3 只时, 样本永远凑不满,
                       #   这不是「行情源可疑」而是「压根没样本」。原实现无条件计入异常天数,
                       #   持仓+候选只有 1~2 只的组合连续 TICK_UNIT_BLOCK_DAYS 天就被拉闸停买。
                       #   现按只数短路: 样本先天不足不计入异常天数, 也不触发拉闸。
                       _watch_n_xn2 = len(watch or [])
                       if _watch_n_xn2 < TICK_UNIT_MIN_SAMPLES:
                           if getattr(G, 'tick_unit_skip_logged', '') != (G.today + '|few'):
                               G.tick_unit_skip_logged = G.today + '|few'
                               log('[单位校准] 观察池仅%d只(<%d), 样本先天不足, 本次不核对也不计入异常天数'
                                   % (_watch_n_xn2, TICK_UNIT_MIN_SAMPLES))
                       else:
                          # P3-7(2026-10-24 第18轮零预设独立审计): "核对不了"必须与"核对通过"区分开。
                          #   旧版探测失败(样本不足/接口异常)只打一行提示, 不计入 tick_unit_bad_days,
                          #   于是行情源真换成"股"口径且样本长期不足时, 量能信号会静默错100倍:
                          #     * MIN_DAILY_AMOUNT 成交额 = 收盘x量x100 虚高100倍 -> 1000万流动性
                          #       门槛形同虚设(垃圾股全放行);
                          #     * 换手率 = 量x100/流通股本 虚高100倍 -> 全部 >20% 被 ZT_TURNOVER_MAX
                          #       误杀(正常票全被剔)。
                          #   两侧方向相反、净效应不确定, 属最危险的"静默跑偏"形态。
                          #   现按同一阈值计入连续异常天数, 满 TICK_UNIT_BLOCK_DAYS 天同样拉闸停买,
                          #   仅日志措辞与"判定为股"区分(不把取不到数据说成数据错了)。
                          _bad = 0
                          _need_save = False
                          _just_blocked = False
                          with G.state_lock:
                              _bad_day = G.state.get('tick_unit_bad_date')
                              _bad = int(G.state.get('tick_unit_bad_days', 0) or 0)
                              if _bad_day != G.today:
                                  _bad += 1
                                  G.state['tick_unit_bad_date'] = G.today
                                  G.state['tick_unit_bad_days'] = _bad
                                  _need_save = True
                              if _bad >= TICK_UNIT_BLOCK_DAYS and not G.state.get('tick_unit_blocked'):
                                  G.state['tick_unit_blocked'] = True
                                  G.state['tick_unit_ack'] = ''
                                  _need_save = True
                                  _just_blocked = True
                          if _need_save:
                              save_state()
                          if _just_blocked:
                              log('[单位校准][拉闸][告警] tick量单位连续%d个交易日无法核对(样本不足/接口异常): '
                                  '已强制暂停全部买入(主买入/分批加仓均拦截) —— 请人工检查行情源, 确认正常后: '
                                  '①置 TICK_UNIT_ACK=True, 或 ②在状态文件写 "tick_unit_ack":"<确认日期>"'
                                  % (_bad,))
                          elif _bad < TICK_UNIT_BLOCK_DAYS:
                              log('[单位校准][告警] tick快照volume核对样本不足(无法核对口径): 按已确认口径=手处理; '
                                  '异常第%d/%d天, 连续满%d天将强制暂停买入'
                                  % (_bad, TICK_UNIT_BLOCK_DAYS, TICK_UNIT_BLOCK_DAYS))
                          else:
                              log('[单位校准][拉闸][告警] tick量单位持续无法核对(第%d天): 买入保持暂停, '
                                  '等待人工确认行情源正常(TICK_UNIT_ACK=True或状态文件tick_unit_ack)' % (_bad,))
                          if getattr(G, 'tick_unit_warn_date', '') != G.today:
                              G.tick_unit_warn_date = G.today
                except Exception:
                  G.tick_vol_unit = 1 if _forced == 1 else 100
    except Exception:
        log('get_full_tick 异常')
        return
    pos_total, pos_avail, cash = query_account()    # P1修复: 柜台查询在锁外
    if pos_total is None:
        return                      # 柜台查询失败: 跳过本轮, 绝不基于空数据误删持仓/重复下单
    # 2026-10-03 用户定稿硬约束: 本策略最大可用资金总额不可逾越(V2.6.74起已由66666.66元提高到200000元) ——
    # 在锁外对 query_account 返回的原始可用现金统一收敛, 使下方所有资金通道
    # (calc_size/buy_stock/run_pyramid_adds)拿到的都是本策略资金边界内的现金,
    # 防止"分批加仓传原始cash"等路径绕过 STRATEGY_CASH_CAP 用超上限的钱下单。
    cash = eff_cash(cash)
    # P1-01: 锁外预取委托快照, 供本轮决策段复用以避免持锁期间重复柜台查询;
    # 预取失败时置None, 查询函数在锁内按原路径回退(仅影响效率, 不影响正确性)
    try:
        ords_snap = _api(get_trade_detail_data, G.accid, 'STOCK', 'ORDER') or []
    except Exception:
        ords_snap = None
    # 第六轮零预设审计修复(2026-10-04): 并发防御 —— 监控决策段持锁耗时, 若频繁超时
    # 说明决策段存在性能瓶颈, 会延迟成交回报回调(deal_callback)处理。此处仅记录耗时
    # 并在超时告警, 不改变锁机制本身(改锁机制风险高)。
    _lock_start = time.time()
    # V2.6.167修复(2026-10-23 全量零预设独立审计·第二部分): _run_round_active 必须
    #   无论本轮是否抛异常都能复位。原先只在 _run_round_unlocked 入口置 True, 一旦
    #   决策段抛异常, 这个标志就永远停在 True, 之后每一轮都被"上一轮还没结束"
    #   (RUN_ROUND_GUARD_SEC 默认5秒)直接跳过, 策略会静默停摆且日志里看不出原因;
    #   现用 try/finally 保证异常路径也复位。
    try:
        with G.state_lock:
            _run_round_unlocked(ticks, pos_total, pos_avail, cash, elap, k, ords_snap, sent_parsing)
            _lock_used = time.time() - _lock_start
            if _lock_used > 1.0:
                log('[并发防御] 本轮决策段持锁%.2f秒(超过1秒), 若频繁触发将延迟成交回报处理, 建议优化'
                    % _lock_used)
    finally:
        G._run_round_active = False

def _run_round_unlocked(ticks, pos_total, pos_avail, cash, elap, k, ords_snap=None, sent_parsing=False):
    """原run_round主体(P1修复: 取数已由 run_round 在锁外完成, 本函数只做持锁决策)"""

    # [P2-4 FIX 2026-10-16] 双入口竞态防护:
    # handlebar(每笔行情) + timer_poll(30秒) 都调本函数, RLock保护状态一致但不防竞态;
    # 增加主动跳过保护: 若前一次调用结束不足 RUN_ROUND_GUARD_SEC 秒, 后到的跳过;
    # 避免同一标的在极端行情下(handlebar 高频触发 + timer_poll 定时触发)被重复扫描;
    if getattr(G, "_run_round_active", False):
        _sec_since = time.time() - float(getattr(G, "_run_round_active_ts", 0))
        if _sec_since < RUN_ROUND_GUARD_SEC:   # V2.6.83(P3): 5.0 提取为具名常量(原注释引用了不存在的常量)
            log("[竞态防护] 上一轮 run_round 仅%.1f秒前刚结束, 本轮跳过(防 handlebar + timer_poll 双入口同时进入)" % _sec_since)
            return
    G._run_round_active = True
    G._run_round_active_ts = time.time()
    # 注: 不在此处清 active 标志, 统一在函数末尾(所有return前)清; 因函数很长有多个 return, 改这里风险大;
    # 简单方案: active 标志 5 秒后自动过期(下次进入时按时间戳判断), 不强制手动清理;
    hold = G.state['hold']
    # P1-1修复(2026-10-02): 卖出回报登记的待结算项在此用本轮柜台持仓(pos_total, 锁外已取)确认
    settle_pending(pos_total)

    # ---------- 卖出检查 ----------
    for s in list(hold.keys()):
        h = hold[s]
        if h.get('reconciled'):
            # 对账补录的孤儿仓(其他策略/手工持有): 本策略绝不扫描、绝不卖出、绝不计其盈亏;
            # 其清理由 reconcile_positions 方向B 负责, 不在此处处理
            continue
        # giveup超时自动重试: 卖出giveup后达到SELL_GIVEUP_RETRY_SEC则复位重试用尽状态
        if h.get('sell_giveup') and SELL_GIVEUP_RETRY_SEC > 0:
            _gts = _f(h.get('giveup_ts', 0.0))
            if _gts > 0 and (time.time() - _gts) >= SELL_GIVEUP_RETRY_SEC:
                h['sell_giveup'] = False
                h['sell_retries'] = 0
                h['giveup_ts'] = 0.0
                h['sell_cancel_sent'] = False
                log(disp(s), '卖出giveup超时%d秒, 自动恢复重试(柜台拒单等已恢复)' % SELL_GIVEUP_RETRY_SEC)
        if is_handoff(h):
            # 已移交人工的套牢仓: 停止仓位运作 —— 不加仓、不自动卖出、不占名额,
            # 只做只读监控(维护持仓期最低价, 在反弹/接近解套/已达解套价时提醒人工择机解套)
            if pos_total.get(s, 0) <= 0 and h.get('buy_date') != G.today:
                # P1-7加固: 人工已在券商端卖出(移交仓策略永不自动卖, 持仓消失=人工解套完成)
                estimate_close(s, h)
                log(disp(s), '已无持仓: 套牢移交仓已在人工端平仓, 解除冻结并回收名额与额度')
                clear_handoff(s, '实盘持仓已清零(人工解套卖出)')
                G.state['done'][s] = h.get('t0', '')
                mark_sold(s)      # P2-33: 人工解套卖出同样计入REBUY_GAP_TRDAYS再买间隔
                del hold[s]
                save_state()
                continue
            _t = ticks.get(s) or {}
            monitor_handoff(s, h, _f(_t.get('lastPrice')))
            continue
        if pos_total.get(s, 0) <= 0:
            if h.get('buy_date') == G.today:
                # T+1当日买入不可能当日卖出: 持仓回报未到/委托未成交时绝不误判清仓;
                # 方案三: 超时未成交自动撤单重报, 重报用尽退回当日额度
                handle_unfilled_buy(s, h, ords_snap)
                continue
            # P1-3加固: 删除前先查柜台委托, 已成/部分成交的绝不判"未成交"删除(防幽灵持仓)
            _o = buy_order_obj(s, ords_snap)
            if _o == '_ERR':             # 风险2修复: 查询失败时不删记录, 等下轮复核
                continue
            if _o is not None and int(getattr(_o, 'm_nOrderStatus', -1)) == 56:
                # V2.6.184修复(2026-10-28): "委托已成"不得再挡住【已成交过】的仓位清算 ——
                #   根因: 委托备注为空时(V2.6.159空备注兜底: 状态文件登记过该代码某方向的OrderID
                #   即算本策略委托), buy_order_obj('002626.SZ','buy') 会把【今天那笔手工卖单】
                #   误认成"买入委托"返回, 其状态"已成(56)" 命中本守卫 -> 每轮continue,
                #   持仓记录永远删不掉 -> 幽灵持仓。
                #   实证: 002626金达威 10-28 09:55 手工卖出(2500股@18.22, 净利+255.22)后,
                #   全天日志无一条"已无持仓", 状态文件(10:22落盘)里 002626 仍在 hold
                #   (exited=False, fill_vol=2500), 真实持仓2只被算成3只 = 顶满MAX_POSITIONS
                #   -> 开新仓被挡死, 且市值/浮盈虚高, 卖出间隔(mark_sold)永不登记。
                #   现只在【本策略一笔未成交】(fill_vol<=0, 买入回报确实未到)时才继续等回报;
                #   已成交过的仓位还须有【本次建仓之后的卖出入账证据】(ledger_sold时间戳晚于
                #   order_ts)才放行 —— 既修好幽灵持仓, 又不放"柜台查数异常"被当成已卖出而凭空平仓。
                if int(_f(h.get('fill_vol', 0)) or 0) <= 0:
                    continue              # 买入回报确实未到: 等deal_callback接管(原保护不变)
                _ls_ts = _f((G.state.get('ledger_sold') or {}).get(s))
                _ots = _f(h.get('order_ts', 0.0))
                if _ls_ts <= 0 or (_ots > 0 and _ls_ts <= _ots):
                    continue              # 无本次卖出的入账证据: 保守等待, 绝不凭空判平仓
            if h.get('fill_vol', 0) > 0 or h.get('exited'):
                log(disp(s), '已无持仓, 本轮结束')
                estimate_close(s, h)   # 兜底补记: 持仓已消失但没有成交回报时避免账本缺笔
                mark_sold(s)      # 真实持有过才计入卖出间隔
                G.state['done'][s] = h['t0']
            else:
                _ot = int(getattr(_o, 'm_nVolumeTraded', 0) or 0) if _o else 0
                if _ot > 0:
                    continue              # 有部分成交但回报未到: 等成交回报, 不删记录
                log(disp(s), '委托始终未成交, 回到观察(不计卖出间隔)')
                G.state['done'].pop(s, None)
            clear_handoff(s, '实盘持仓已清零')   # 人工/系统平仓: 解除冻结并回收释放额度
            # P3-D4(2026-10-29 修复)：删除持仓记录前必须显式核销在途量。
            #   原实现直接 del hold[s]，若此时 pend_vol>0（委托未成交但持仓确认为 0），
            #   这部分在途量随记录一起消失，后续 used_capital / 额度统计不会扣回，
            #   等于这笔钱永久挂在「已用」里（报告 D4 遗留：在途总量 5 天后被静默丢弃）。
            try:
                _pv4 = int(_f(h.get('pend_vol', 0)) or 0)
                if _pv4 > 0:
                    log(disp(s), '清理持仓记录前核销遗留在途量 %d 股(委托未成交但持仓已清零)' % _pv4)
                    h['pend_vol'] = 0
            except Exception:
                pass
            del hold[s]
            save_state()
            continue
        if h.get('exited'):
            hourly_reason_note('sell', s, h.get('name', ''),
                               '已标记卖出但委托在途(等成交回报/清理路径)')
            # P1-2加固: 卖出委托在途状态机 —— 旧逻辑只要pos_avail>0就重置exited,
            # 每30秒重复发一单; 新逻辑超时前等待, 超时查柜台撤单/重发, 有次数上限
            if pos_avail.get(s, 0) <= 0:
                continue                  # 已无可用持仓: 等成交回报/清理路径
            t = ticks.get(s) or {}
            lp = _f(t.get('lastPrice'))
            if lp <= 0:
                continue
            act = handle_unfilled_sell(s, h, pos_avail, lp, t, ords_snap)
            if act == 'resent':
                pass                      # 已重发新委托(仍是exited在途态), 继续持有等回报
            continue
        # P0-2修复(20261008): 卖出侧行情新鲜度闸门 —— 与买入侧 data_gate 同源
        # (持仓行情连续 STALE_BLOCK_ROUNDS 轮取不到最新价 = 行情源不可用)。
        # 断流时暂停本票价格型新卖出决策(T+1挂起执行/放量止盈/滞涨确认), 防按陈旧价
        # 卖出; 无持仓清仓/在途委托管理路径不依赖现价, 保留执行; 行情恢复后自动继续。
        if int((G.pnl or {}).get('stale_n', 0) or 0) >= STALE_BLOCK_ROUNDS:
            hourly_reason_note('sell', s, h.get('name', ''),
                               '持仓行情连续%d轮取不到最新价(行情源不可用)' % STALE_BLOCK_ROUNDS)
            if getattr(G, 'stale_sell_note_date', '') != G.today:
                G.stale_sell_note_date = G.today
                log('[数据告警] 持仓行情连续%d轮取不到最新价(行情源不可用), '
                    '本轮暂停所有价格型卖出判定, 行情恢复后自动继续'
                    % int((G.pnl or {}).get('stale_n', 0) or 0))
            continue
        if h.get('sell_pending_t1'):
            # T+1标记: 昨日因T+1不可卖而挂起的卖出决策, 今日可卖后直接执行
            # (place_sell_order内部仍按net_pnl_if_sell>0闸门, 亏本不会成交)
            # P2-34: 受开盘时长约束(与常规卖出一致) —— 旧版开盘第1分钟就以限价卖出,
            # 若遇跳空/瞬时波动最剧烈时刻发单且未成交, 会进入重发→giveup链放大风险
            if pos_avail.get(s, 0) > 0 and elap >= SELL_MIN_ELAPSED_MIN:
                t = ticks.get(s) or {}
                lp = _f(t.get('lastPrice'))
                # P3-5(第18轮审计): ①无行情/行情陈旧时保留 sell_pending_t1 挂起标记 ——
                #   旧版先无条件清标记再判 lp, 导致"该卖的卖出决策被无声吞掉"(次日才重新评估,
                #   而次日可能已错过卖点); ②陈旧价不作为执行依据(同主卖出循环口径)。
                if lp > 0 and not _px_is_stale(t):
                    h['sell_pending_t1'] = False
                    sell_stock(s, h, pos_avail, lp, 'T+1可卖, 执行挂起的卖出决策', t)
                else:
                    hourly_reason_note('sell', s, h.get('name', ''),
                                       'T+1挂起卖出执行但当前无行情或行情陈旧, 保留挂起标记')
            else:
                hourly_reason_note('sell', s, h.get('name', ''),
                                   'T+1挂起卖出受开盘时长或可卖持仓约束')
            continue
        t = ticks.get(s) or {}
        lp = _f(t.get('lastPrice'))
        vol = _f(t.get('volume'))
        # P3-5(第18轮审计): 价格来自非当日 bar(陈旧价)时, 暂停一切价格型卖出决策。
        #   旧版 stale_n 闸门的口径是"一个有效最新价都取不到", 而陈旧价 lp>0 会被计入
        #   有效价, 闸门不触发; 放量止盈/换手率止盈因 est=0 天然被挡, 唯独
        #   "持有到期且已盈利"不看量, 会拿陈旧价判盈利并发卖单。
        if _px_is_stale(t):
            hourly_reason_note('sell', s, h.get('name', ''),
                               '行情陈旧(无当日bar, 价格来自上一交易日), 暂停价格型卖出决策')
            if h.get('px_stale_note') != G.today:
                h['px_stale_note'] = G.today
                log(disp(s), '当日无行情bar, 现价为上一交易日陈旧价, 暂停价格型卖出决策(等行情恢复)')
            continue
        if lp <= 0:
            hourly_reason_note('sell', s, h.get('name', ''),
                               '停牌或无行情, 卖出决策挂起')
            # 审计修复G6: 停牌/无行情预案 —— 保留持仓、挂起卖出决策, 复牌后下轮自动恢复; 每日提示一次
            if h.get('suspend_note') != G.today:
                h['suspend_note'] = G.today
                log(disp(s), '停牌/无行情, 卖出决策挂起, 保留持仓等复牌')
            continue
        est = vol * _tick_to_daily_scale() / k        # 审计修复I1 + P0-1: 预估量=vol换算系数/k(非线性外推), 与日线基准量同单位
        base = h.get('base_vol') or 0
        if base <= 0 and not h.get('reconciled') and G.hist.get(s):
            # 重审20261005(1-6): base_vol=0的持仓(旧版补录/ctx缺失遗留)放量卖出条件永假,
            # 自动止盈出口消失。日线就绪后按最近完成日量自愈估算一次(醒目标注)。
            _bv, _bv_est = _estimate_base_vol(s)
            if _bv > 0:
                h['base_vol'] = _bv
                base = _bv
                log(disp(s), '[安全] 补录持仓基准量缺失, 已按最近完成日成交量估算=%d(放量卖出口径恢复, 标注为估算值)' % _bv)
        # P2-4统一口径: 成本一律用含费均价(pos_cost/vol), 与浮亏预警/止损线/净利闸门一致;
        # 旧"止盈判定用不含费buy_price"会在费用边界上给出与净利闸门相反的结论
        cvol = pos_vol(h)
        cost_u = (pos_cost(h) / cvol) if cvol > 0 else 0.0
        cost = cost_u if cost_u > 0 else (h.get('buy_price') or 0)
        # 不赚钱就不卖: 现价须高于成本x(1+盈利门槛)才允许止盈卖出;
        # 门槛按该笔实际双边费用动态计算(方案一), 低价股自动抬高, 保证卖出净到手为正
        thr = min_profit_pct(h, s)
        profitable = cost > 0 and lp > cost * (1 + thr)
        if profitable and net_pnl_if_sell(h, lp, s) <= 0:
            # 绝不止损配套: 按实际卖出价重算一遍净利, 扣费后不为正就不卖(不留估算误差)
            profitable = False
        reason = ''
        _stnote = ''   # 2026-10-12: 预置空值, 避免滞涨确认分支未触发时登记块引用未定义变量
        held_days = (held_trd_days(h.get('buy_date', ''))
                     if MAX_HOLD_TRDAYS > 0 else 0)
        # 每笔专属止损线(方案A定稿): 建仓时按 N倍ATR 算出并写入持仓记录, 此处仅作
        # "绝不止损"提示参考价; 硬止损/固定止损/单日急跌/时间止损四个亏损出口已全部删除,
        # 该线不再触发任何卖出
        eq = size_equity()
        stop_pct = _f(h.get('stop_pct', 0.0))   # 方案A: 仅ATR口径(固定止损参数已删除)
        stop_px = cost_u * (1 - stop_pct + STOP_SLIPPAGE_BUF) if (cost_u > 0 and stop_pct > 0) else 0.0
        # 单票大额浮亏/市值超限: 只提示一次, 不动作(上涨超限是收益, 不减仓)
        if DAILY_LOSS_ALERT_PCT > 0 and eq > 0 and cost_u > 0 and cvol > 0:
            uloss = (lp - cost_u) * cvol
            if uloss <= -eq * DAILY_LOSS_ALERT_PCT and h.get('loss_alert_date') != G.today:
                h['loss_alert_date'] = G.today
                log(disp(s), '浮亏预警: 现价%.2f较成本均价%.2f浮亏%.2f元, 已达基准权益%.1f%%(仅提示, 不动作)'
                    % (lp, cost_u, -uloss, DAILY_LOSS_ALERT_PCT * 100))
        if SIZING_VALUE_ALERT_MULT > 0 and eq > 0 and cvol > 0:
            mv = lp * cvol
            if mv > min(eq * MAX_POS_VALUE_PCT, MAX_POS_VALUE_ABS) * SIZING_VALUE_ALERT_MULT and h.get('val_alert_date') != G.today:

                h['val_alert_date'] = G.today
                log(disp(s), '市值提示: 上涨致市值%.0f元达单票上限%.0f%%的%.1f倍, '

                    '只提示不减仓(让利润奔跑)' % (mv, MAX_POS_VALUE_PCT * 100, SIZING_VALUE_ALERT_MULT))
        # 套牢判定: 长期亏损且难以回本时提醒人工介入(并默认自动冻结移交, 释放名额与额度)
        check_trap(s, h, lp)
        if is_handoff(h):
            continue          # 本轮刚移交: 不再执行任何卖出判定(等人工处理)
        # P1-5修复(20261008): 早盘放量抑制区间参数化: <EARLY_SELL_BLOCK_MIN禁卖;
        # BLOCK~END分钟阈值乘EARLY_SELL_VOL_MULT; >=END分钟正常(原硬编码30/60)
        if elap < EARLY_SELL_BLOCK_MIN:
            _vol_sell_ok = False
        elif elap < EARLY_SELL_END_MIN:
            _vol_sell_ok = base > 0 and est >= base * sent_param('EXPAND_SELL_RATIO', EXPAND_SELL_RATIO) * SELL_TOL * EARLY_SELL_VOL_MULT
        else:
            _vol_sell_ok = base > 0 and est >= base * sent_param('EXPAND_SELL_RATIO', EXPAND_SELL_RATIO) * SELL_TOL
        if elap >= SELL_MIN_ELAPSED_MIN and _vol_sell_ok:
            if profitable:
                # 2026-10-02 借鉴: 放量止盈附加"滞涨"确认(开关关闭时与原文案逐字节一致)
                _st, _stnote, _stdeg = (sell_stall_confirmed(s, h, lp, t) if STALL_CONFIRM_ON
                                        else (True, '', False))
                if _st:
                    reason = ('放量止盈(预估量达基准量%.1f倍, 现价%.2f>成本%.2f%s)'
                              % (est / base, lp, cost, ('; ' + _stnote) if _stnote else ''))
                    if _stdeg and h.get('stall_deg_date') != G.today:
                        h['stall_deg_date'] = G.today
                        log(disp(s), '放量止盈: 滞涨确认所需数据(昨收/近高)不可得, '
                               '本轮退回纯量能口径卖出(不改既有行为)')
                elif h.get('stall_note_date') != G.today:
                    h['stall_note_date'] = G.today
                    log(disp(s), '放量已盈利但未确认滞涨, 继续持有(滞涨确认已开启): %s' % _stnote)
            elif h.get('hold_note_date') != G.today:
                h['hold_note_date'] = G.today
                log(disp(s), '放量但未盈利(现价%.2f<=成本%.2f含费), 不赚钱不卖, 继续持有' % (lp, cost))
        # 2026-10-08 第二轮零预设审计: 原 elif 结构使"换手率见顶"开启时"持有到期"出口
        # 被短路(该卖不卖), 且两个出口不受开盘时长约束(早盘可被瞬时换手率误触发卖出)。
        # 现改为独立判断、互不挡路: 放量止盈优先, 换手率见顶/持有到期在放量未命中时补位;
        # 并统一要求开盘满 SELL_MIN_ELAPSED_MIN 分钟(与放量止盈一致)。阈值与铁律不变。
        if not reason and elap >= SELL_MIN_ELAPSED_MIN and SELL_TURNOVER_TOP > 0:
            # 换手率见顶卖出: 当日预估换手率>SELL_TURNOVER_TOP且盈利 -> 卖出信号
            _zt_to = _f(h.get('zt_turnover'))
            _t0v = _f(h.get('t0_vol'))
            if (_zt_to <= 0 or _t0v <= 0) and G.hist.get(s):
                _t0d = h.get('t0', '')
                for _r in G.hist[s]:
                    if _r.get('date') == _t0d:
                        if _zt_to <= 0: _zt_to = _f(_r.get('turnover'))
                        if _t0v <= 0: _t0v = _f(_r.get('volume'))
                        break
            _to = (_zt_to * est / _t0v) if (_zt_to > 0 and _t0v > 0 and est > 0) else 0.0
            if _to > SELL_TURNOVER_TOP and profitable:
                reason = ('换手率见顶止盈(预估换手率%.1f%%>%.0f%%, 现价%.2f>成本%.2f)'
                          % (_to * 100, SELL_TURNOVER_TOP * 100, lp, cost))
        if not reason and elap >= SELL_MIN_ELAPSED_MIN and MAX_HOLD_TRDAYS > 0 \
                and held_days >= MAX_HOLD_TRDAYS:
            # 方案A: 硬止损/单日急跌/固定止损三个亏损出口已删除, 不再产生任何"亏损卖出"理由
            if profitable:
                reason = '持有到期且已盈利, 落袋为安(%d个交易日)' % held_days

                # [P2-1 FIX 2026-10-16] MAX_HOLD_TRDAYS 到期卖出死循环防护
                # 问题: 主循环触发"持有到期且已盈利" → place_sell_order里exit_price_needed抬价后
                # 超过当日涨停价被夹回 → net_pnl_if_sell<=0被拦; 每30秒一轮重复触发但卖不出去
                # 修复: 主循环提前算解套保护价vs涨停价, 若解套价>涨停则本轮跳过发单(减少无效循环)
                _deadlock_bypass = False
                try:
                    _xp_need = _f(exit_price_needed(h, s))
                    if _xp_need > 0:
                        _up = _f(day_limit_prices(s)[0])
                        if _up <= 0:
                            _lc = _f(t.get("lastClose"))
                            if _lc > 0:
                                _up = math.floor(_lc * (1.0 + _band_pct(s)) * 100 + 1e-6) / 100.0
                        if _up > 0 and _xp_need > _up:
                            _deadlock_bypass = True
                            if h.get("hold_deadlock_date") != G.today:
                                h["hold_deadlock_date"] = G.today
                                log(disp(s), "[到期卖不出] 持有%d天已盈利, 但解套保护价%.2f>涨停价%.2f, 本轮跳过等下轮"
                                       % (held_days, _xp_need, _up))
                except Exception:
                    pass
                if _deadlock_bypass:
                    reason = ""
            elif h.get('hold_note_date') != G.today:
                h['hold_note_date'] = G.today
                log(disp(s), '持有%d个交易日但仍亏损, 不赚钱不卖, 继续持有' % held_days)
        # 方案A: 时间止损(亏损出口之四)已删除, 亏损持仓唯一的动作是等待回本
        if reason:
            sell_stock(s, h, pos_avail, lp, reason, t)
        elif (NEVER_STOP_LOSS and stop_px > 0 and lp <= stop_px
              and h.get('nostop_note_date') != G.today):
            # 绝不止损: 跌破止损线也只提示一次, 绝不卖出(亏损只记浮亏, 等回本)
            h['nostop_note_date'] = G.today
            log(disp(s), '绝不止损: 现价%.2f已跌破止损线%.2f(成本均价%.2f, 浮亏%.2f元), '
                   '按设定继续持有等回本, 只在扣费后净利为正时卖出'
                   % (lp, stop_px, cost_u, (lp - cost_u) * cvol if cvol > 0 else 0.0))
        # 2026-10-12新增: 每轮对"仍未卖出"的持仓股登记原因(供小时汇总)
        try:
            if not reason and not is_handoff(h):
                if elap < EARLY_SELL_BLOCK_MIN:
                    hourly_reason_note('sell', s, h.get('name', ''),
                                       '开盘不足%d分钟(禁卖期内)' % EARLY_SELL_BLOCK_MIN)
                elif not _vol_sell_ok:
                    hourly_reason_note('sell', s, h.get('name', ''),
                                       '未触发放量卖出(预估量/基准量不足%.1f倍)'
                                       % sent_param('EXPAND_SELL_RATIO', EXPAND_SELL_RATIO))
                elif not profitable:
                    hourly_reason_note('sell', s, h.get('name', ''),
                                       '未盈利(现价%.2f<=成本%.2f含费), 不赚钱不卖'
                                       % (lp, cost))
                elif _stnote:
                    hourly_reason_note('sell', s, h.get('name', ''),
                                       '放量但未确认滞涨(现价涨幅或近高未达标)')
                else:
                    hourly_reason_note('sell', s, h.get('name', ''),
                                       '本轮无卖出信号(量能/盈利/滞涨均未触发)')
        except Exception:
            pass

    # D7：情绪解析期间卖出、在途委托处理、对账均已完成；从这里起只跳过新增买入/加仓。
    if sent_parsing:
        return

    # ---------- 买入检查 ----------
    # 组合熔断(R2合规): 【真实权益】跌破-PORTFOLIO_FUSE_LOSS时暂停新开仓(只卖不买)。
    #   P0修复(2026-10-02): 判定口径由 snap['ret'](仅运作中持仓)改为 snap['ret_all']
    #   (含已移交套牢仓浮亏) —— 旧口径下仓位移交后亏损被剔出, 深套时熔断反而看不见亏损。
    # P2-2统一口径: 暂停FUSE_PAUSE_TRDAYS个【交易日】后自动解除(截止日按交易日历计算,
    # 日历取不到未来交易日时按FUSE_AUTO_RESUME_DAYS自然日兜底);
    # ①盈利全平 ②人工manual_resume 仍可提前解除; 绝不因"回撤收窄"自动恢复开仓。
    if PORTFOLIO_FUSE_LOSS > 0 or PORTFOLIO_HARD_DD_PCT > 0:
        fm = pnl_meta()
        if fm.get('manual_resume'):
            fm['manual_resume'] = False
            fm['fuse_until'] = ''
            fm['fuse_note_date'] = ''
            fm['hard_dd_until'] = ''
            log('组合熔断/硬约束已由人工解除, 恢复开仓')
        snap = G.pnl or {}
        _base0 = _f(snap.get('base', 0.0))
        _rall = _f(snap.get('ret_all', snap.get('ret', 0.0)))
        _rown = _f(snap.get('ret', 0.0))
        # P0修复: 真实权益回撤达更深阈值 -> 硬熔断(不自动解除, 只能人工解除或盈利平仓解除)
        if PORTFOLIO_HARD_DD_PCT > 0 and _base0 > 0 and _rall <= -PORTFOLIO_HARD_DD_PCT * 100.0:
            if not fm.get('hard_dd_until'):
                fm['hard_dd_until'] = '99991231'
                fm['hard_dd_note_date'] = G.today
                log('[安全][硬约束] 真实权益(含移交仓浮亏)总收益%.2f%%已跌破-%.0f%%: '
                    '暂停全部新开仓与分批加仓(绝不自动解除; 人工解除: 状态文件pnl_meta.manual_resume=true, '
                    '盈利平仓亦自动解除)。注意: 本策略绝不止损, 该约束只停买入、不卖任何亏损仓'
                    % (_rall, PORTFOLIO_HARD_DD_PCT * 100.0))
            return
        if PORTFOLIO_FUSE_LOSS > 0 and _base0 > 0 and _rall <= -PORTFOLIO_FUSE_LOSS * 100.0:
            if not fm.get('fuse_until'):
                # P2-2: 优先按交易日数计算截止(FUSE_PAUSE_TRDAYS), 日历缺失时自然日兜底
                exp = ''
                if FUSE_PAUSE_TRDAYS > 0:
                    exp = trd_days_after(G.today, FUSE_PAUSE_TRDAYS)
                if not exp and FUSE_AUTO_RESUME_DAYS > 0:
                    d0 = datetime.date.today()
                    exp = (d0 + datetime.timedelta(days=FUSE_AUTO_RESUME_DAYS)).strftime('%Y%m%d')
                if not exp:
                    exp = '99991231'
                fm['fuse_until'] = exp
                fm['fuse_note_date'] = G.today
                log('组合熔断: 真实权益总收益%.2f%%(其中运作中持仓口径%.2f%%)已跌破-%.0f%%, '
                    '暂停新开仓%d个交易日(至%s, 只卖不买; 盈利全平/人工manual_resume可提前解除)'
                    % (_rall, _rown, PORTFOLIO_FUSE_LOSS * 100.0,
                       FUSE_PAUSE_TRDAYS, exp))
            return
    # 分批建仓的后续批次同样受统一增险门禁约束。
    if PYRAMID_ON:
        _risk_ok, _risk_why = risk_increase_allowed()
        if _risk_ok:
            cash = run_pyramid_adds(ticks, cash, ords_snap)
        else:
            log('暂停分批加仓: %s' % _risk_why)
    # 单仓串行闸门: 持仓上限 -> 解锁 -> 冷静/长停 -> 熔断, 任一不满足当日不开新仓(每天只提示一次)
    ok, why = can_open_new()
    if not ok:
        if G.lock_note_date != G.today:
            G.lock_note_date = G.today
            # 2026-10-04: 结构化触发日志, 输出 can_open_new 的完整拦截原因(含持仓/熔断/退潮/数据闸门等参数)
            trigger_log('买入拦截-开新仓闸门', '买入', '开新仓前置闸门未通过, 本轮不做买入决策',
                        reason=why, mode=TRADE_MODE)
            log('暂不开新仓: %s' % why)
        return
    if elap < sent_param('BUY_MIN_ELAPSED_MIN', BUY_MIN_ELAPSED_MIN):
        # 开盘不足30分钟时预估量严重失真(早盘量能非线性), 静默等待但每日提示一次, 避免用户误以为"不出手"
        if G.buy_open_note_date != G.today:
            G.buy_open_note_date = G.today
            trigger_log('买入拦截-开盘量能未成熟', '买入',
                        '开盘时间不足, 预估量能严重失真, 等待满时长后再判定缩量低吸',
                        elapsed_min=elap, required_min=sent_param('BUY_MIN_ELAPSED_MIN', BUY_MIN_ELAPSED_MIN), mode=TRADE_MODE)
            log('开盘不足%d分钟, 预估量失真, 等待开盘满%d分钟后再判定缩量低吸(今日不再提示)'
                % (sent_param('BUY_MIN_ELAPSED_MIN', BUY_MIN_ELAPSED_MIN), sent_param('BUY_MIN_ELAPSED_MIN', BUY_MIN_ELAPSED_MIN)))
        return
    # 每日买入笔数上限(按交易模式分离: MAX_DAILY_BUYS_LIVE / MAX_DAILY_BUYS_PAPER): 按交易日累计并持久化, 重载/补选股都不会超买
    _blk, _blkwhy = daily_buy_blocked()
    if _blk:
        if G.daybuy_note_date != G.today:
            G.daybuy_note_date = G.today
            trigger_log('买入拦截-外部手工封锁', '买入', '外部 set_daily_buys.py 已置手工封锁标记, 当日禁止开新仓',
                        block_reason=_blkwhy, mode=TRADE_MODE)
            log('[%s] 今日买入已被外部手工封锁(%s), 不再开新仓; 解除: 运行 set_daily_buys.py '
                'MODE=CLEAR(当日归零) 或 MODE=SHOW 查看当前状态' % (TRADE_MODE, _blkwhy))
        return
    left = daily_buy_left()
    if left <= 0:
        if G.daybuy_note_date != G.today:
            G.daybuy_note_date = G.today
            b = daily_buy_state()
            trigger_log('买入拦截-每日笔数上限', '买入',
                        '当日已买笔数达到每日上限, 今日不再开新仓(次日自动恢复)',
                        bought=b['n'], cap=daily_buy_cap(), mode=TRADE_MODE)
            log('[%s] 当日已买入%d笔(%s), 达到每日上限%d笔, 今日不再开新仓(次日自动恢复)'
                % (TRADE_MODE, b['n'], ','.join(b['codes']) or '-', daily_buy_cap()))
        return
    eq = size_equity()
    bought = 0                 # 本轮已买入笔数
    # 每日只买优选名单里排名最靠前的N只(DAILY_BUY_PICKS, 默认1=两只优选里只买最好的那一只);
    # 20261008 用户确认(零预设审计第3轮): 买入顺延补买 —— 排名第1的票被跳过
    # (缩量未达标/回撤过深/追高等)时自动顺延评估次优, 不再整轮放弃, 避免"有票却不买";
    # 仍以"成功买入笔数"限购(DAILY_BUY_PICKS)与当日笔数上限(left)双约束。
    picks = G.candidates  # 20261008零预设审计: 原"if DAILY_BUY_PICKS<=0 else G.candidates"两分支相同(死代码), 已精简; 限购由下方break(bought>=DAILY_BUY_PICKS)生效, 行为不变
    # 第六轮零预设审计修复(2026-10-04): 并发下单防御 —— 在每只候选评估前, 检查其实盘在途委托
    # (状态非终态且方向为买), 若已有在途委托则跳过该票(防重复下单)。现有 G.state_lock 已保证
    # 决策段与回调互斥, 此检查是额外一层保险, 覆盖"回调重入/外部触发"等非常规路径。
    for c in picks:
        eq = size_equity()   # V2.6.35b(D5修复): 同轮前一票成交后权益已变, 重算确保第二票仓位不超
        if bought >= left:
            break
        if DAILY_BUY_PICKS > 0 and bought >= DAILY_BUY_PICKS:
            break
        s = c['stock']
        # 第六轮零预设审计修复(2026-10-04): 在途委托防御 —— 若该股票已有实盘在途买入委托
        # (状态非终态且方向为买), 本轮跳过, 防重复下单(覆盖回调重入/外部触发等非常规路径)
        _has_inflight_buy = False
        try:
            if ords_snap:
                for _o in ords_snap:
                    try:
                        _os_st = int(getattr(_o, 'm_nOrderStatus', -1) or -1)
                        # P2-9修复(2026-10-17): 兼容两种方向口径 —— 48(开平方向口径)=买,
                        # 23(passorder的opType口径)=买; 该字段在某券商精简客户端的确切语义需
                        # 实盘打印核对, 若客户端恒返回-1则本层静默失效, 但其它防重层(当日同票
                        # 登记/在途量核销/发单前落盘)仍在, 不会造成重复下单
                        _os_side = int(getattr(_o, 'm_nOffsetFlag', -1) or -1)  # 48/23=买, 49/24=卖
                        _os_code = str(getattr(_o, 'm_strInstrumentID', '') or '')
                        _os_ex = str(getattr(_o, 'm_strExchangeID', '') or '')
                        if (_os_side in (48, 23) and _os_st in ACTIVE_ORDER_STATUS
                                and ('%s.%s' % (_os_code, _os_ex) == s or _os_code == s.split('.')[0])):
                            _has_inflight_buy = True
                            if c.get('inflight_note_date') != G.today:
                                c['inflight_note_date'] = G.today
                                log(disp(s), '[防重复] 本票已有在途买入委托(状态%s), 本轮跳过'
                                    % ORDER_STATUS_MAP.get(_os_st, _os_st))
                            break
                    except Exception:
                        pass
        except Exception:
            pass
        if _has_inflight_buy:
            hourly_reason_note('buy', s, c.get('name', ''), '已有在途买入委托，本轮跳过')
            continue
        _rb = rebuy_blocked(s, c['t0'])
        if _rb:
            hourly_reason_note('buy', s, c.get('name', ''),
                               '买入去重跳过(持仓中/同T0周期已操作/卖出后间隔不足): %s' % _rb)
            continue    # 买入去重: 持仓中/同T0周期已操作/卖出后间隔不足
        # 重审20261005(1-5): 同票当日重入守卫 —— "下单异常且委托未送达"分支会删除占位记录
        # 并登记当日买入codes(不退额), 旧版仅靠当日额度上限挡重入, MAX_DAILY_BUYS_*=0
        # (默认不限)时登记形同虚设; 若 passorder 实际已受理而柜台查询处于竞态窗口,
        # 下一轮(30秒后)会对同一票再次发单(双倍占资)。现在按"当日已尝试过的票不再重入"拦截:
        # codes 在退额路径(orderError废单/超时放弃)会同步移除, 不影响既有"废单回观察/次日恢复"语义。
        if s in (daily_buy_state().get('codes') or []):
            if c.get('retry_note_date') != G.today:
                c['retry_note_date'] = G.today
                log(disp(s), '[防重复] 本票今日已有买入尝试登记(下单结果未确认), '
                    '今日不再对同一票重复发单(防重复下单)')
            hourly_reason_note('buy', s, c.get('name', ''),
                               '本票今日已有买入尝试登记(下单结果未确认), 防重复下单')
            continue
        # 防重复买入: 实盘已有非本策略持仓时跳过, 不碰非本策略标的, 也避免叠加超配(不暴露实盘持仓股数)
        if pos_total.get(s, 0) > 0:
            if c.get('skip_note_date') != G.today:
                c['skip_note_date'] = G.today
                log(disp(s), '该标的已有非本策略在管记录, 不碰此标的(今日不再提示)')
            hourly_reason_note('buy', s, c.get('name', ''),
                               '实盘已有非本策略持仓(避免重复/超配), 跳过')
            continue
        t = ticks.get(s) or {}
        lp = _f(t.get('lastPrice'))
        vol = _f(t.get('volume'))
        if lp <= 0 or vol <= 0:
            # 审计修复G6: 停牌(量=0)/无行情天然不参与买入决策, 不消耗当日额度
            hourly_reason_note('buy', s, c.get('name', ''),
                               '停牌(量=0)或无行情, 不参与买入决策')
            continue
        if t.get('vol_ok') is False:
            # V2.6.33新增: 量能可信度闸门(只减买入, 不动卖出) —— 行情断档/重连后当日1m缓存不完整,
            # 累计量被严重低估会让"缩量到位"被假数据满足(2026-10-13 实测: 累计15手 vs 基准825683手);
            # 数据不可信即不开新仓, 等缓存补齐(通常次日)后自动恢复。
            hourly_reason_note('buy', s, c.get('name', ''),
                               '量能数据不完整(%s), 不参与买入决策' % (t.get('vol_src') or '行情断档后当日1m缓存缺失'))
            continue
        est = vol * _tick_to_daily_scale() / k        # 审计修复I1 + P0-1: 预估量=vol换算系数/k(非线性外推), 与日线基准量同单位
        ratio = est / c['base_vol']
        if VOL_IMPLAUSIBLE_MIN_RATIO > 0 and ratio < VOL_IMPLAUSIBLE_MIN_RATIO:
            # V2.6.33新增: 兜底闸门 —— 真实成交缩到涨停基准量的5%以下在A股几乎不可能,
            # 出现即判"量能数据不完整", 不当作缩量信号(旧版会按"极度缩量"直接买入)。
            hourly_reason_note('buy', s, c.get('name', ''),
                               '预估量异常偏低(量能数据不完整), 不参与买入决策')
            continue
        # ---- 战法借鉴②③: 确认式进场触发(默认关, 与缩量低吸并存; 其余风控闸门全部保留) ----
        _entry_note = ''
        cf = c.get('confirm') or {}
        if CONFIRM_ENTRY_ON and cf:
            _topen = _f(t.get('open'))
            _yang = (lp > _topen) if _topen > 0 else (lp > _f(t.get('lastClose')))
            _yv = _f(cf.get('yin_vol', 0.0))
            if (lp > _f(cf.get('yin_high', 0.0)) and _yang
                    and est >= _yv * CONFIRM_YANG_VOL_RATIO):
                _entry_note = ('缩倍阴确认进场(阴线高%.2f, 预估量/阴线量=%.1f>=%.1f, 阴线%s)'
                               % (_f(cf.get('yin_high', 0.0)),
                                  (est / _yv) if _yv > 0 else 0.0,
                                  CONFIRM_YANG_VOL_RATIO, cf.get('yin_date', '-')))
        if not _entry_note and MA5_RECLAIM_ON and c.get('ma5_break'):
            _ma5 = _f(c.get('ma5', 0.0))
            _lclose = _f(t.get('lastClose'))
            # 重审20261006(P1-B/问题4): 补传当日交易日期, 使300/301按当日实际涨跌停制度取系数(旧版漏传导致空日期默认20%)
            _zt_px = _round2(_lclose * _zt_coef(s, G.today)) if _lclose > 0 else 0.0
            if (_ma5 > 0 and _zt_px > 0 and lp >= _zt_px - 0.005 and lp > _ma5):
                _entry_note = ('五日线收复进场(涨停价%.2f收复MA5=%.2f)'
                               % (lp, _ma5))
        if _entry_note:
            c['entry_note'] = _entry_note
        if MIN_BUY_AMOUNT > 0 and not DYN_SIZING_ON:
            _lot0 = int(LOT_SIZE) if LOT_SIZE > 0 else 100   # 重审20261005(P2-3): 与buy_stock同口径
            amt1 = (int(FIXED_BUY_VOL / _lot0) * _lot0 if FIXED_BUY_VOL > 0 else _lot0) * lp
            if amt1 < MIN_BUY_AMOUNT:
                if c.get('skip_note_date') != G.today:
                    c['skip_note_date'] = G.today
                    trigger_log('买入拦截-单票金额过低', '买入',
                                '一手金额低于最低买入金额, 手续费占比过高, 跳过本票',
                                code=disp(s), one_hand_amount=amt1, min_amount=MIN_BUY_AMOUNT,
                                price=lp)
                    log(disp(s), '单票金额%.0f元低于最低买入金额%.0f元(手续费占比过高), 跳过(今日不再提示)'
                        % (amt1, MIN_BUY_AMOUNT))
                hourly_reason_note('buy', s, c.get('name', ''),
                                   '单票金额%.0f元低于最低买入金额%.0f元(手续费占比过高)'
                                   % (amt1, MIN_BUY_AMOUNT))
                continue
        if not _entry_note and ratio > sent_param('SHRINK_BUY_RATIO', SHRINK_BUY_RATIO) * BUY_TOL:
            if c.get('skip_note_date') != G.today:
                c['skip_note_date'] = G.today
                trigger_log('买入拦截-缩量未达标', '买入',
                            '预估全日量相对基准量缩量不足, 未达缩量低吸阈值, 放弃本票',
                            code=disp(s), ratio=ratio, threshold=sent_param('SHRINK_BUY_RATIO', SHRINK_BUY_RATIO) * BUY_TOL,
                            base_ratio=sent_param('SHRINK_BUY_RATIO', SHRINK_BUY_RATIO), tolerance=BUY_TOL)
                log(disp(s), '缩量未达标(预估全日量/基准量=%.2f > 阈值%.2f, 今日不再提示)'
                    % (ratio, sent_param('SHRINK_BUY_RATIO', SHRINK_BUY_RATIO) * BUY_TOL))
            hourly_reason_note('buy', s, c.get('name', ''),
                               '缩量未到位(预估全天量/基准量=%.2f > 阈值%.2f)'
                               % (ratio, sent_param('SHRINK_BUY_RATIO', SHRINK_BUY_RATIO) * BUY_TOL))
            continue            # 缩量不够, 直接放弃(确认式进场命中时不做此要求)
        # P2-3修复配套: 取本票 tick, 供后面"按实际委托价扣减现金"使用
        _tk = (ticks or {}).get(s) or {}
        # P3-9(2026-10-24 第18轮零预设独立审计): 回撤/追高比价改用"不复权"涨停收盘价。
        #   旧注释(P2-2复核)认为"前复权最新一根锚定真实价, 故 lp 与 zt_close 口径一致" ——
        #   该结论仅在 T0 到今日之间无除权除息时成立。一旦期间发生分红送股, 前复权
        #   zt_close 被下调而 lp(真实价)不调, 回撤会算浅、追高会算低, 把本该放弃的票放行。
        #   危害例: T0真实涨停收10.00, 期间10派5 -> 前复权zt_close=9.50; 今日真实价9.60,
        #   按复权价判定"回撤+1.05%"(追高检查3%内放行), 按真实价实际回撤4% —— 已越过
        #   MAX_PULLBACK_FROM_ZT 的警戒区却照样买入。
        #   现优先用 screen_candidates 补取的 zt_close_raw(不复权), 取不到才回退前复权值。
        _ztc = _f(c.get('zt_close_raw', 0.0)) or _f(c.get('zt_close', 0.0))
        if _ztc <= 0:
            _ztc = _f(c.get('zt_close', 0.0))
        if lp < _ztc * (1 - MAX_PULLBACK_FROM_ZT):
            # 与其它"放弃"分支保持一致: 同一只股票每日最多提示一次,
            # 避免30秒轮询把同一行日志反复写入客户端日志窗(刷屏/涨内存)
            if c.get('skip_note_date') != G.today:
                c['skip_note_date'] = G.today
                trigger_log('买入拦截-回撤过深', '买入',
                            '现价相对涨停收盘回撤超过阈值, 放弃本票(只低吸不深跌)',
                            code=disp(s), price=lp, zt_close=_ztc,
                            pullback_pct=(lp / _ztc - 1) * 100,
                            max_pullback_pct=MAX_PULLBACK_FROM_ZT * 100)
                log(disp(s), '缩量达标但回撤过深(%.2f 低于涨停收盘%.2f的%.0f%%), 放弃(今日不再提示)'
                    % (lp, _ztc, MAX_PULLBACK_FROM_ZT * 100))
            hourly_reason_note('buy', s, c.get('name', ''),
                               '现价偏低但回撤过大(%.2f 低于涨停收盘%.2f的%.0f%%)'
                               % (lp, _ztc, MAX_PULLBACK_FROM_ZT * 100))
            continue
        if lp > _ztc * (1 + MAX_CHASE_OVER_ZT):
            if c.get('skip_note_date') != G.today:
                c['skip_note_date'] = G.today
                trigger_log('买入拦截-追高', '买入',
                            '现价高于涨停收盘过多, 只低吸不追, 放弃本票',
                            code=disp(s), price=lp, zt_close=_ztc,
                            chase_pct=(lp / _ztc - 1) * 100,
                            max_chase_pct=MAX_CHASE_OVER_ZT * 100)
                log(disp(s), '现价%.2f高于涨停收盘%.2f的%.1f%%(追高上限%.1f%%), 只低吸不追, 今日不再提示'
                    % (lp, _ztc, (lp / _ztc - 1) * 100,
                       MAX_CHASE_OVER_ZT * 100))
            hourly_reason_note('buy', s, c.get('name', ''),
                               '现价%.2f高于涨停收盘%.2f的%.1f%%(追高上限%.1f%%), 只低吸不追'
                               % (lp, _ztc, (lp / _ztc - 1) * 100,
                                  MAX_CHASE_OVER_ZT * 100))
            continue            # 高于涨停收盘过多, 只低吸不追
        # ---- 动态手数(四级约束 + 取整降级); 关闭时退回固定手数 ----
        want, atr, atr_pct, stop_pct = None, 0.0, 0.0, 0.0
        if DYN_SIZING_ON:
            atr, atr_pct, _pc = atr_of(s)
            if atr_pct <= 0:
                if c.get('skip_note_date') != G.today:
                    c['skip_note_date'] = G.today
                    trigger_log('买入拦截-ATR数据不足', '买入',
                                '补拉日线失败或根数不足, 无法计算真实波幅, 本轮跳过本票',
                                code=disp(s), atr_pct=atr_pct, atr=atr,
                                required_period=ATR_PERIOD + 1)
                    log(disp(s), 'ATR数据不足(补拉日线失败或根数不足%d根), 本轮跳过(今日不再提示)'
                        % (ATR_PERIOD + 1))
                hourly_reason_note('buy', s, c.get('name', ''),
                                   'ATR数据不足(补拉日线失败或根数不足%d根)' % (ATR_PERIOD + 1))
                continue
            want, info = calc_size(s, lp, atr, atr_pct, eq, eff_cash(cash))
            if want <= 0:
                if c.get('skip_note_date') != G.today:
                    c['skip_note_date'] = G.today
                    trigger_log('买入拦截-手数评估不通过', '买入',
                                '动态手数计算被拒, 无法满足最低可买手数',
                                code=disp(s), want=want, atr_pct=atr_pct, price=lp,
                                equity=eq, reason=info.get('reason', ''))
                    log(disp(s), '手数评估不通过: %s(今日不再提示)' % info['reason'])
                hourly_reason_note('buy', s, c.get('name', ''),
                                   '手数评估不通过: %s' % info['reason'])
                continue
            stop_pct = info['stop_pct']
            if info['degraded']:
                log(disp(s),info['reason'])
        # ---- 分批建仓: 首笔也先做"当日价格位置"过滤, 高位区不建仓 ----
        plan = None
        if PYRAMID_ON and want and want >= 100:
            _pos = day_pos(t, lp)
            if in_high_zone(_pos):
                if c.get('skip_note_date') != G.today:
                    c['skip_note_date'] = G.today
                    log(disp(s), '分批首笔暂缓: 现价%.2f处于当日振幅前%.0f%%高位区(位置%.0f%%, 区间%.2f~%.2f), '
                           '等回落或后续交易日再建仓(今日不再提示)'
                           % (lp, PYRAMID_HIGH_ZONE_PCT * 100, (_pos or 0) * 100,
                              _f(t.get('low')), _f(t.get('high'))))
                hourly_reason_note('buy', s, c.get('name', ''),
                                   '日内高位区(%d%%~%d%%)分批递延'
                                   % (int(PYRAMID_HIGH_ZONE_PCT * 100), int(PYRAMID_HIGH_ZONE_PCT * 100)))
                continue
            _pa = pyramid_alloc(want, s)      # P1-1(第18轮审计): 传入代码, 科创板按200股拆批
            _pa_lot = _lot_of(s)                # P1-1: 首笔门槛与板块最小申报单位对齐
            if len(_pa) > 1 and _pa[0] >= _pa_lot:
                plan = _pa                     # 计划总仓位不变, 只是拆成多笔成交
                log(disp(s), '分批建仓计划: 总量%d股拆%d批=%s(比例%s), 首笔%d股'
                       % (sum(_pa), len(_pa), _pa, PYRAMID_RATIOS, _pa[0]))
        got = buy_stock(c, lp, est, ratio, eff_cash(cash), want, atr, atr_pct, stop_pct, plan, t, ords_snap)
        if got:
            bought += 1
            # P2-3修复(2026-10-02): 同轮多笔买入按【实际委托价】(含滑点+夹取)与费用扣减 ——
            #   旧版按最新价lp扣, 与 buy_stock 内"按委托价校验资金"口径不一致, 同轮第二笔
            #   可能低估占用而超用资金(柜台废单浪费当日买入机会)。
            # 第1条修复(2026-10-17): 扣减口径统一用动态滑点 _slippage_for(lp) —— 旧版此处
            #   仍写死 SLIPPAGE_PCT, 与主买入发单(动态滑点)不一致, 边界资金会多扣/少扣。
            _px_used = clamp_order_price(_round2(lp * (1.0 + _slippage_for(lp))), _tk, True, s)
            if _px_used <= 0:
                _px_used = _round2(lp)
                        # Q1修复(2026-10-19): 同轮多笔扣减改用精确买入费(旧版用粗估FEE_RATE_EST, 边界资金会多扣/少扣)
            cash -= got * _px_used + fee_buy(got * _px_used, s)
            # P2-30: 每次买入成功后复核持仓上限 —— 旧版只在循环外查一次,
            # DAILY_BUY_PICKS>1或0=不限时, 一轮可连买到超过MAX_POSITIONS
            _ok2, _why2 = can_open_new()
            if not _ok2:
                log('达到持仓上限, 本轮停止继续开仓: %s' % _why2)
                break
            if pos_limit() <= 1:
                break           # 单仓串行: 买到一只即停, 不再看第二只
    # 2026-10-12新增: 每小时汇总"优选股未买入/持仓股未卖出"原因(按股票+原因分组)
    try:
        hourly_reason_dump()
    except Exception:
        pass

# ==================== 交易回调(框架自动调用, 需init里set_account) ====================
def order_callback(ContextInfo, orderInfo):
    """委托回报：登记OrderID、短窗幂等去重；空OrderID醒目告警但不伪造柜台ID。"""
    G.state_lock.acquire()
    try:
        rm = str(getattr(orderInfo, 'm_strRemark', '') or '')
        code = '%s.%s' % (getattr(orderInfo, 'm_strInstrumentID', ''),
                          getattr(orderInfo, 'm_strExchangeID', ''))
        if not (rm.startswith('BUY|') or rm.startswith('SELL|')):
            return
        _oid = str(getattr(orderInfo, 'm_strOrderID', '')
                   or getattr(orderInfo, 'm_strOrderSysID', '') or '').strip()
        _ost = int(getattr(orderInfo, 'm_nOrderStatus', -1))
        _vol = int(getattr(orderInfo, 'm_nVolume', 0) or 0)
        _px = _f(getattr(orderInfo, 'm_dPrice', 0.0))
        _side = 'BUY' if rm.startswith('BUY|') else 'SELL'
        _key = '%s|%s|%s|%s|%d|%.4f|%d' % (G.today, code, _side, _oid or 'NOID', _ost, _px, _vol)
        if not _oid:
            # P2-7修复(2026-10-17): 空OrderID时键追加单调序号 —— 同状态同价同量的重复回调
            # 原会被短窗去重合并(撤单/状态推进丢失), 序号保证每次回调键唯一
            G.order_cb_seq = int(getattr(G, 'order_cb_seq', 0) or 0) + 1
            _key += '|seq%d' % G.order_cb_seq
        _seen = getattr(G, 'order_cb_seen', None)
        if not isinstance(_seen, dict):
            _seen = {}
            G.order_cb_seen = _seen
        _now = time.time()
        if _now - _f(_seen.get(_key, 0.0)) < ORDER_CB_DEDUP_SEC:
            return
        _seen[_key] = _now
        if len(_seen) > 1000:
            for _k in sorted(_seen, key=lambda x: _seen[x])[:200]:
                _seen.pop(_k, None)
        if not _oid:
            log('[安全][告警] 委托回报OrderID为空 | %s | %s | 状态=%s | %d股@%.2f | '
                '无法按券商OrderID精确绑定；本轮已按代码/方向/状态/价格/数量短窗去重，撤单继续以柜台委托对象为准'
                % (rm, disp(code), ORDER_STATUS_MAP.get(_ost, '未知状态(%s)' % _ost), _vol, _px))
        note_order_id(code, rm, _oid)
        if not save_state(critical=True):
            G.state_broken = True
            log('[安全] OrderID绑定落盘失败，已冻结新增下单，等待对账恢复')
        log('委托回报', rm, getattr(orderInfo, 'm_strInstrumentID', ''),
            '状态', ORDER_STATUS_MAP.get(_ost, '未知状态(%s)' % _ost),
            'OrderID=%s' % (_oid or '<空>'))
    except Exception:
        log('[警告] 委托回报回调处理异常')
        traceback.print_exc()
    finally:
        G.state_lock.release()

def _sim_fill_prob_dynamic(s, price, volume):
    """第六轮零预设审计修复(2026-10-04): 模拟成交概率按流动性动态调整 ——
    原逻辑用固定 SIM_FILL_PROB, 不区分股票流动性差异, 导致模拟结果对低流动性股票高估、
    对高流动性股票低估。本函数按以下维度微调成交概率:
      1) 股价高低: 低价股(<10元)更易成交(散户多/对手量大) → 概率微升;
         高价股(>50元)更难成交(机构主导/盘口薄) → 概率微降。
      2) 成交金额大小: 大单更易部分成交或延迟 → 概率微降。
    返回值在 [0.05, 1.0] 区间内; SIM_FILL_PROB=1.0 时本函数不影响(保持全成交)。
    """
    try:
        if SIM_FILL_PROB >= 1.0:
            return 1.0    # 默认全成交(与原行为一致)
        _p = float(SIM_FILL_PROB)
        _px = float(price or 0)
        _amt = float(price or 0) * float(volume or 0)
        # 低价股(<10元)微升
        if 0 < _px < 10.0:
            _p = min(1.0, _p * 1.10)
        # 高价股(>50元)微降
        elif _px > 50.0:
            _p = max(0.05, _p * 0.90)
        # 大单(>20万元)微降
        if _amt > 200000.0:
            _p = max(0.05, _p * 0.95)
        return max(0.05, min(1.0, _p))
    except Exception:
        return float(SIM_FILL_PROB) if SIM_FILL_PROB < 1.0 else 1.0

def _sim_deal(remark, price, volume):
    """审计修复I7: DRY_RUN模拟成交 —— 构造QMT风格dealInfo并同步触发deal_callback,
    使模拟盘与实盘共用同一套记账/持仓/清仓路径, 但不走真实柜台。
    P2-01: 支持模拟成交概率(SIM_FILL_PROB<1时随机未命中), 未命中返回False,
    命中并完成回调返回True, 供调用方(place_sell_order/buy_stock/pyramid_add等)区分
    "未成交"与"成交", 避免模拟盘无脑成交掩盖真实成交不确定性。
    重审20261006(P2-C/问题8): 新增封板/部分成交可行性检查 —— 旧版无脑按保护价全额成交,
    未模拟一字涨停(买不到)/跌停封板(卖不掉)/盘口深度不足/部分成交, 导致回测收益系统性高估。"""
    try:
        # 重审20261006(P0-B/问题2): 备注加|NEW/|ADD后缀后取最后一段会取到NEW/ADD而非代码, 改为取第二段(格式: 方向|代码|来源)
        s = str(remark).split('|')[1]
        # 第六轮零预设审计修复(2026-10-04): 按流动性动态调整成交概率
        # 零预设审计V2.6.36b修复(P0): 原代码把 _sim_fill_prob_dynamic(s,...) 写在 try 块之外,
        # 而 s 在 try 块内才被赋值, 且 _sim_deal(remark, price, volume) 根本没有 s 形参,
        # 导致 DRY_RUN=True 模拟盘 100% 抛 NameError('s' is not defined)。现移入 try 块内 s 赋值之后,
        # 并加防御 try 兜底到 SIM_FILL_PROB, 确保概率函数异常不会误吞整笔模拟成交。
        try:
            _s_fp = _sim_fill_prob_dynamic(s, price, volume)
        except Exception:
            _s_fp = SIM_FILL_PROB
        # 第5条修复(2026-10-17): 模拟盘不再默认保证100%成交 —— 原 SIM_FILL_PROB=1.0 时
        # _sim_fill_prob_dynamic 兜底恒返回1.0, 模拟盘100%成交、收益系统性偏乐观;
        # 现即使 SIM_FILL_PROB>=1.0, 实际成交概率也按 SIM_DRY_FILL_PROB(默认95%)封顶,
        # 未命中即本轮暂缓/下轮重新评估(既有撤单重报/暂缓链路不变, 演练全流程仍可走通)。
        if SIM_FILL_PROB >= 1.0:
            _s_fp = min(_s_fp, float(SIM_DRY_FILL_PROB))
        if _s_fp < 1.0 and random.random() > _s_fp:
            return False                 # P2-01: 未命中模拟成交概率, 不构造成交回报
        _parts = [p.strip() for p in str(remark).split('|') if p.strip()]
        _side = ''
        for _p in _parts:
            if _p == 'BUY':
                _side = 'BUY'
                break
            if _p == 'SELL':
                _side = 'SELL'
                break
        # P2-C/问题8: 封板可行性检查 —— 一字涨停买入/一字跌停卖出在真实市场无法成交,
        # 模拟盘若仍按保护价全额成交会高估收益。此处对接近封板的委托降低成交概率。
        try:
            _up, _dn = day_limit_prices(s)
        except Exception:
            _up, _dn = 0.0, 0.0
        _px = float(price)
        if _side == 'BUY' and _up > 0 and _px >= _up - 0.005:
            # 买入委托价已达涨停价: 视为一字涨停封板, 显著降低成交概率(真实市场需排队)
            if SIM_FILL_PROB < 1.0 or random.random() > 0.15:
                return False
        if _side == 'SELL' and _dn > 0 and _px <= _dn + 0.005:
            # 卖出委托价已达跌停价: 视为一字跌停封板, 显著降低成交概率
            if SIM_FILL_PROB < 1.0 or random.random() > 0.15:
                return False
        # P1-1修复(20261008): 模拟部分成交 —— 真实市场限价单常只成交一部分(盘口深度/
        # 对手量不足), 旧版总是全额成交使模拟收益系统性高估(买入全额到位+卖出全额出手)。
        # 开启后按 MIN~MAX 随机比例缩量(至少一手), 剩余在途走既有撤单重报链路;
        # 卖出侧把实际成交量记入 G._sim_sell_fill 供 place_sell_order 按实回款(防现金虚增);
        # 默认关 = 与原行为完全一致。
        if SIM_PARTIAL_FILL_ON and int(volume) > 0 \
                and 0.0 < SIM_PARTIAL_FILL_MIN < SIM_PARTIAL_FILL_MAX < 1.0:
            try:
                _fill_ratio = SIM_PARTIAL_FILL_MIN + random.random() * (
                    SIM_PARTIAL_FILL_MAX - SIM_PARTIAL_FILL_MIN)
                _fvol = max(int(LOT_SIZE), int(
                    int(volume) * _fill_ratio / int(LOT_SIZE)) * int(LOT_SIZE))
                if 0 < _fvol < int(volume):
                    if _side == 'SELL':
                        G._sim_sell_fill = _fvol
                    log('[模拟] 部分成交: %s %d股(委托%d股), 剩余在途走撤单重报链路'
                        % (_side, _fvol, int(volume)))
                    volume = _fvol
            except Exception:
                pass
        di = type('DI', (), {})()
        di.m_strInstrumentID = s.split('.')[0]
        di.m_strExchangeID = s.split('.')[1] if '.' in s else ''
        di.m_dPrice = float(price)
        di.m_nVolume = int(volume)
        di.m_strRemark = str(remark)

        # V2.6.35零预设审计配套: 模拟成交原本无成交号/委托号/成交时间, 会走 _deal_key 兜底键;

        # 同价同量的多笔模拟成交(如分批加仓)兜底键相同, 会被误判重复而丢弃。

        # 这里补一个当日单调递增的合成成交号, 使每笔模拟成交的键唯一。

        G.deal_seq = int(getattr(G, 'deal_seq', 0) or 0) + 1

        di.m_strTradeID = 'SIM%08d' % G.deal_seq

        di.m_strTradeTime = datetime.datetime.now().strftime('%H:%M:%S')

        deal_callback(None, di)
        return True
    except Exception:
        traceback.print_exc()
        return False

def _deal_key(dealInfo, code, side, price, volume):
    """成交幂等键：稳定字段组合；重复回放得到同一键，不再追加递增序号。"""
    trade_id = str(getattr(dealInfo, 'm_strTradeID', '') or getattr(dealInfo, 'm_strDealID', '') or '')
    order_id = str(getattr(dealInfo, 'm_strOrderID', '') or getattr(dealInfo, 'm_strOrderSysID', '') or '')
    ts = str(getattr(dealInfo, 'm_strTradeTime', '') or getattr(dealInfo, 'm_strTime', '') or '')
    cum = str(getattr(dealInfo, 'm_nDealtVolume', '') or getattr(dealInfo, 'm_nVolumeTraded', '') or '')
    acc = str(getattr(G, 'accid', '') or '')
    if trade_id:
        return '%s|%s|%s|%s|%s|%s' % (G.today, acc, code, side, order_id, trade_id)
    return '%s|%s|%s|%s|%s|%s|%.4f|%d|cum%s' % (
        G.today, acc, code, side, order_id or 'NOORDER', ts or 'NOTIME', price, volume, cum)

def deal_callback(ContextInfo, dealInfo):
    """成交回报: 按备注BUY|代码 / SELL|代码 累计成交, 更新持仓成本价, 并按实际成交价记账盈亏。
    P1-3加固: BUY回报到达时持仓记录已被清理(委托误判未成交) -> 用buy_ctx/回报自身补录建仓,
    绝不让真实持仓脱离策略管理(幽灵持仓); P1-4加固: SELL多笔回报按成交量比例结转成本上下文,
    成本缺失时拒绝按0成本记账(旧逻辑会把本金全额记成利润)
    P1-8: 备注解析容错 —— 兼容多段/带前缀/含空格形态; 无法识别时响亮告警绝不静默丢弃
    (旧版备注形态不符时全部回报落入else: fill_vol恒0/成本永不校准/策略误以为未成交而重发)"""
    G.state_lock.acquire()       # 审计修复3: 成交回报修改G.state, 加锁防并发
    try:
        rm = str(getattr(dealInfo, 'm_strRemark', '') or '')
        parts = [p.strip() for p in rm.split('|') if p.strip()]   # P1-8: 去空格/空段
        code = '%s.%s' % (getattr(dealInfo, 'm_strInstrumentID', ''),
                          getattr(dealInfo, 'm_strExchangeID', ''))
        price = _f(getattr(dealInfo, 'm_dPrice', 0))
        volume = int(getattr(dealInfo, 'm_nVolume', 0) or 0)
        # P1-8: 容错识别方向 —— 任意段等于BUY/SELL即认可; 识别失败绝不静默丢弃
        side = ''
        # V2.6.188: 本笔是否为【用户手工卖出】(券商端手工操作, 成交回报无 BUY/SELL 备注)
        _manual_sell = False
        for _p in parts:
            if _p == 'BUY':
                side = 'BUY'
                break
            if _p == 'SELL':
                side = 'SELL'
                break
        # P1-3修复(20261008): 备注被柜台截断/改写丢失时的方向交叉兜底 —— 按成交回报
        # 自带OrderID精确反查本策略委托登记表(ordids, 由order_callback按委托回报写入),
        # 只有ID精确匹配才采用, 绝不猜测; 反查不到维持下方"无法识别"响亮告警路径。
        if not side and volume > 0 and price > 0:
            _oid_q = str(getattr(dealInfo, 'm_strOrderID', '') or getattr(dealInfo, 'm_strOrderSysID', '') or '')
            if _oid_q:
                # V2.6.159: 按委托号在两个方向里反查(旧结构自动兼容)
                _qside = _oid_side_of(code, _oid_q)
                if _qside == 'buy':
                    side = 'BUY'
                elif _qside == 'sell':
                    side = 'SELL'
                if side:
                    log('[兜底] %s 成交回报备注无法识别(remark=%r), 已按委托号%s反查登记方向=%s'
                        % (disp(code), rm, _oid_q, side))
        # V2.6.41b: 手工卖出自动入账(方案B精确识别) —— 用户在券商 app 手动卖出本策略持仓时,
        # 成交回报备注不含 BUY|/SELL| 前缀(策略不认), 旧版走对账清理不记账, 盈亏账本永久缺一笔。
        # 现按"本策略持仓 + 有效成交 + 无策略卖单在途 + 无已入账记录"四重判据识别为手工卖出,
        # 走与策略卖出完全相同的 ledger_sell 入账路径(精确到成交价/成交量/真实费用), 全自动零操作。
        # P1-1修复(2026-10-17): 手工成交先辨方向 —— 成交回报m_nDirection(23=买/24=卖)。
        # 旧版不辨方向: 备注被柜台截断的【策略买入】成交会落入下方四重判据被误判为
        # "手工卖出"并入账(幽灵卖出, 一股没卖却记账); 买入方向成交(疑手工补仓)不记账。
        _ddir = int(getattr(dealInfo, 'm_nDirection', 0) or 0)
        if not side and volume > 0 and price > 0 and _ddir == 23:
            log('[注意] %s 成交回报无 BUY/SELL 备注且方向=买入(疑手工补仓), 不按卖出入账; '
                '如需策略识别该加仓成本, 请在状态文件登记 manual_fill/manual_avg_cost '
                '(remark=%r, %d股@%.2f)' % (disp(code), rm, volume, price))
        if not side and volume > 0 and price > 0 and _ddir != 23:
            _hh0 = (G.state.get('hold') or {}).get(code)
            if isinstance(_hh0, dict) and _f(pos_vol(_hh0)) > 0 \
                    and int(volume) <= int(_f(pos_vol(_hh0))) \
                    and not (G.state.get('sell_ctx') or {}).get(code):
                side = 'SELL'
                # V2.6.188: 标记本笔为【用户手工卖出】, 供账本 reason 标注来源
                _manual_sell = True
                log('[手工卖出] %s 成交回报无 BUY/SELL 备注(方向字段缺失, 按本策略持仓四重判据), '
                    '自动识别为手工卖出入账 %d股 @%.2f(remark=%r)' % (disp(code), volume, price, rm))

        if side and volume > 0 and price > 0:
            _dk = _deal_key(dealInfo, code, side, price, volume)
            _seen = G.state.setdefault('processed_deals', {})
            if _dk and _dk in _seen:
                if is_strategy_target(code):
                    log('[安全] 重复成交回报已忽略: %s %s %d股@%.2f' % (side, disp(code), volume, price))
                return
            if _dk:
                _seen[_dk] = time.time()
            # P3-1拍板(2026-10-08): 去重表上限 2000 -> 5000(成交回报留存能力扩大),
            # 每次仍只清理最旧 500 条, 防长跑积累被截断后旧成交重复入账
            if len(_seen) > 5000:
                for _old in sorted(_seen, key=lambda x: _seen[x])[:500]:
                    _seen.pop(_old, None)
        # V2.6.156: 取委托单号 —— 费用按委托单只归并一次, 同单多笔成交不重复起收
        _order_id = str(getattr(dealInfo, 'm_strOrderID', '')
                        or getattr(dealInfo, 'm_strOrderSysID', '') or '')
        if side == 'BUY':
            h = G.state['hold'].get(code)
            if h is None:
                # P1-3: 持仓记录已被"误判未成交"清理, 但委托实际成交了 —— 补录建仓接管管理
                bctx = (G.state.get('buy_ctx') or {}).get(code) or {}
                _bv, _bv_est = int(bctx.get('base_vol', 0) or 0), False
                if _bv <= 0:            # 重审20261005(1-6): base_vol兜底估算, 防补录仓永无自动卖出出口
                    _bv, _bv_est = _estimate_base_vol(code)
                h = {'t0': bctx.get('t0', ''), 'base_vol': _bv,
                     'zt_close': _f(bctx.get('zt_close', 0.0)), 'name': bctx.get('name', ''),
                     'buy_date': G.today or datetime.datetime.now().strftime('%Y%m%d'),
                     'buy_price': price, 'buy_vol': volume, 'paper': DRY_RUN,
                     'fill_sum': 0.0, 'fill_vol': 0, 'exited': False,
                     'fee': 0.0, 'cost_total': 0.0, 'last_px': price,
                     'open_ts': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                     'alert_win': 0, 'alert_loss': 0, 'order_ts': 0.0, 'order_retries': 0,
                     'cancel_sent': False, 'recovered': True}
                G.state['hold'][code] = h
                log('[实盘] 买入成交补录 | %s | 持仓记录曾被误判未成交清理, 已按成交回报重建接管 | %d股 @%.2f%s'
                    % (disp_code(code, h.get('name', '')), volume, price,
                       ('; 基准量ctx缺失, 已按最近完成日量估算=%d' % _bv) if _bv_est else ''))
            amt = _round2(price * volume)
            # V2.6.156: 先判该委托单是否已建账(算费会写账, 必须先判), 再按委托单归并算费
            _ordk = ('%s|%s' % (G.today or '', _order_id)) if _order_id else ''
            _new_ord = bool(_ordk) and (not (G.state.get('order_fee_acc') or {}).get(_ordk))
            fee = fee_buy(amt, code, order_id=_order_id)
            if _new_ord:      # 该仓累计委托单张数, 供启动校准按张数估算起收
                h['order_cnt'] = int(_f(h.get('order_cnt', 0)) or 0) + 1
            was_new = int(_f(h.get('fill_vol', 0) or 0)) <= 0   # 本笔是否该股首笔成交(分批第2/3批不是新开仓)
            if _f(h.get('fee_pre', 0.0)) > 0:
                # V2.6.158: 首笔成交回报到达时先清掉发单占位预填的估算费用, 再按真实费用重算。
                #   旧版从不重置, 回报又累加一次 —— 实测一张 900 股委托真实 5.25 元记成 10.50 元,
                #   成本虚高一倍, 会抬高"扣完全部费用真赚钱才卖"这道门槛, 变成该卖不卖。
                #   非首笔却仍带标记属异常路径: 保留原值不清(宁可偏高), 只清标记防残留。
                if was_new:
                    h['fee'] = 0.0
                    h['cost_total'] = 0.0
                else:
                    # P3-D9(2026-10-29 修复)：非首笔(分批第2/3批、加仓)也必须扣掉本批占位的估算费用。
                    #   原实现只在 was_new 时清零，非首笔直接把真实费用 += 到已含估算的 h['fee'] 上，
                    #   同一笔费用被算两次(估算 + 真实)，成本虚高 -> 「扣完全部费用真赚钱才卖」
                    #   闸门被抬高 -> 该卖不卖。现按本批占位金额等比扣除后再累加真实费用。
                    try:
                        _pre9 = _f(h.get('fee_pre', 0.0))
                        if _pre9 > 0:
                            h['fee'] = _round2(max(0.0, _f(h.get('fee', 0.0)) - _pre9))
                            h['cost_total'] = _round2(max(0.0, _f(h.get('cost_total', 0.0)) - _pre9))
                    except Exception:
                        pass
                h.pop('fee_pre', None)
            h['fill_sum'] += price * volume
            h['fill_vol'] += volume
            h['buy_vol'] = int(h['fill_vol'])      # 分批建仓: buy_vol同步为实际累计成交股数
            h['pend_vol'] = max(0, int(_f(h.get('pend_vol', 0))) - volume)   # 在途量核销
            if h['fill_vol'] > 0:
                h['buy_price'] = h['fill_sum'] / h['fill_vol']
            h['fee'] = _round2(_f(h.get('fee', 0.0)) + fee)
            # 成本按累计成交金额+累计费用重算(避免buy_stock预设估算值与成交回报叠加导致成本翻倍)
            h['cost_total'] = _round2(h['fill_sum'] + h['fee'])
            h['last_px'] = price
            log('[实盘] 买入成交回报 | %s | %d股 @%.2f | 本笔金额=%.2f元 本笔费用=%.2f元(已按委托单归并) | 持仓均价=%.2f | 备注=%s'
                % (disp_code(code, h.get('name', '')), volume, price, amt, fee, h['buy_price'], rm))
            npos_before = max(0, mode_pos_count() - (1 if was_new else 0))   # 仅首笔成交才算新开仓(回退1只)
            # V2.6.39b: 传入 was_new 与加仓前股数, 修正账本"该股A->B股/组合只数"显示
            pos_before = 0 if was_new else int(_f(h.get('fill_vol', 0) or 0) or 0) - int(volume)
            alert_open(ledger_buy(code, h, price, volume,
                                  '实盘买入成交回报(备注%s)' % rm, npos_before,
                                  was_new=was_new, pos_before=pos_before, fee=fee))
            # V2.6.43b: 最终批全部成交后才输出“建仓成交完成”，股数/均价取成交回报后的真实累计值
            if (int(_f(h.get('pend_vol', 0)) or 0) <= 0
                    and pos_vol(h) >= int(_f(h.get('plan_vol', 0)) or 0) > 0):
                h['plan_done'] = True
                _done_key = 'pyramid_fill_done_%s' % (G.today or '')
                if not h.get(_done_key):
                    h[_done_key] = True
                    log(disp(code), '分批建仓成交完成: %d批共%d股, 成本均价=%.2f'
                        % (len(h.get('plan_batches') or []), pos_vol(h), _f(h.get('buy_price', 0.0))))
            save_state()
        elif side == 'SELL':
            h = G.state['hold'].get(code)
            ctx = (G.state.get('sell_ctx') or {}).get(code)
            info = {'name': (h or {}).get('name', '') or (ctx or {}).get('name', ''),
                    'buy_date': (h or {}).get('buy_date', '') or (ctx or {}).get('buy_date', '')}
            if h:
                info['cost_total'] = pos_cost(h)
                info['buy_vol'] = pos_vol(h)
                info['fee'] = h.get('fee', 0.0)
                # P2-26: 卖出成交后同步扣减本地持仓股数与成本 —— 旧版记录股数/成本从不减少,
                # 部分成交期间 pos_vol 仍是卖出前股数 → 市值/浮盈/策略总资产虚高 →
                # size_equity 偏高(手数放大)且组合熔断对这部分亏损失明
                _pv = int(info['buy_vol'] or 0)
                if _pv > 0:
                    _remain = max(0, _pv - volume)
                    if _remain > 0:
                        _ratio = _remain / float(_pv)
                        if int(_f(h.get('fill_vol', 0) or 0)) > 0:
                            h['fill_vol'] = _remain
                        h['buy_vol'] = _remain
                        h['cost_total'] = _round2(_f(h.get('cost_total', 0.0)) * _ratio)
                        h['fee'] = _round2(_f(h.get('fee', 0.0)) * _ratio)
                        if _f(h.get('fill_sum', 0.0)) > 0:
                            h['fill_sum'] = _round2(_f(h.get('fill_sum', 0.0)) * _ratio)
                    # _remain==0: 全部卖出, 持仓记录由"柜台持仓归零"清理路径整条删除
                    # V2.6.185: 立即打"已清仓"标记(closed) —— 全部卖出的仓位不该再占资金额度
                    #   (used_capital)/持仓名额(MAX_POSITIONS)/盈亏快照, 不必等清理路径删记录;
                    #   成本基准刻意保留(estimate_close 兜底补记与人工审计要用), 记录随后由清理路径整条删除。
                    if _remain == 0:
                        h['closed'] = True
                if ctx:
                    # P1-4: 持仓记录还在时, 同步结转ctx, 保证后续回报(记录被删后)成本不重复
                    _cv = max(1, int(ctx.get('hold_vol', 0) or 0))
                    _share = _f(ctx.get('cost_total', 0.0)) * min(volume, _cv) / _cv
                    ctx['cost_total'] = _round2(_f(ctx.get('cost_total', 0.0)) - _share)
                    ctx['hold_vol'] = int(ctx.get('hold_vol', 0)) - volume
                    if int(ctx.get('hold_vol', 0)) <= 0:
                        G.state['sell_ctx'].pop(code, None)
            elif ctx:
                # P1-4: 记录已删, 按成交量比例从ctx结转本笔成本(不再一次性pop导致后续成本为0)
                _cv = max(1, int(ctx.get('hold_vol', 0) or 0))
                _share = _round2(_f(ctx.get('cost_total', 0.0)) * min(volume, _cv) / _cv)
                info['cost_total'] = _share
                info['buy_vol'] = int(volume)
                ctx['cost_total'] = _round2(_f(ctx.get('cost_total', 0.0)) - _share)
                ctx['hold_vol'] = int(ctx.get('hold_vol', 0)) - volume
                if int(ctx.get('hold_vol', 0)) <= 0:
                    G.state['sell_ctx'].pop(code, None)
            else:
                # P1-4: 成本上下文彻底缺失 —— 拒绝按0成本记账(旧逻辑会把本金全额记成利润)
                log('[实盘] 卖出成交回报 | %s | %d股 @%.2f | 成本上下文缺失, 该笔未入盈亏账本, 请核对柜台成交单!'
                    % (disp_code(code), volume, price))
                pnl_alert('[盈亏][异常] %s 卖出回报成本上下文缺失, 未记账, 请人工核对: %d股 @%.2f'
                          % (disp_code(code), volume, price))
                save_state()
                return
            npos_before = mode_pos_count() + (0 if h else 1)
            # V2.6.188: reason 前缀标注来源 —— 手工卖出(用户券商端操作) vs 策略卖出(策略自己发的单)
            _src = '手工卖出(用户券商端手工操作)' if _manual_sell else '策略卖出'
            rec = ledger_sell(code, info, price, volume,
                              '%s 实盘卖出成交回报(备注%s)' % (_src, rm), npos_before,
                              order_id=_order_id)
            try:
                G.state.setdefault('ledger_sold', {})[code] = time.time()
            except Exception:
                log('[警告] ledger_sold登记失败, 同股平仓可能被estimate_close重复补记')
                traceback.print_exc()
            days = rec['hold_days']
            log('[实盘] 卖出成交回报 | %s | %d股 @%.2f | 本笔金额=%.2f元 费用=%.2f元 净收入=%.2f元 | '
                '持仓%d天 | %s | 备注=%s'
                % (disp_code(code, info.get('name', '')), volume, price, rec['amount'], rec['fee'],
                   rec['net'], days, fmt_pnl(rec['pnl'], rec['pnl_pct']), rm))
            alert_close(rec)
            # P1-1修复(2026-10-02): 旧版在持锁状态下调用 query_account()(内部两次
            #   get_trade_detail_data 柜台查询) —— 柜台卡顿时长时间占住 G.state_lock, 阻塞
            #   order_callback(OrderID绑定落盘)/其他成交回报, 属"堵塞开仓/下单"类隐患。
            #   现一律登记待结算, 由 run_round(锁外已取到 pos_total)在锁内确认清零后结算;
            #   同时补齐 pending_settlements 的消费端(旧版只写不读, 登记后永不结算)。
            # D4：同一次退出可能分多笔成交，必须累计后等柜台清零再统一结算；
            # 不能让最后一笔覆盖前面成交，否则亏损退出可能被误判盈利并解除熔断。
            _ps_all = G.state.setdefault('pending_settlements', {})
            _ps = _ps_all.get(code)
            if not isinstance(_ps, dict):
                _ps = {'ts': time.time(), 'pnl': 0.0, 'fee': 0.0, 'vol': 0, 'fills': 0}
            _ps['ts'] = min(_f(_ps.get('ts', time.time())) or time.time(), time.time())
            _ps['pnl'] = _round2(_f(_ps.get('pnl', 0.0)) + _f(rec.get('pnl', 0.0)))
            _ps['fee'] = _round2(_f(_ps.get('fee', 0.0)) + _f(rec.get('fee', 0.0)))
            _ps['vol'] = int(_f(_ps.get('vol', 0))) + int(volume)
            _ps['fills'] = int(_f(_ps.get('fills', 0))) + 1
            _ps_all[code] = _ps
            log('  %s 卖出回报已入账, 待对账确认柜台持仓清零后结算"赚到手"判定'
                % disp_code(code, info.get('name', '')))
            save_state()
        else:
            # P1-8: 备注无法识别时绝不静默丢弃 —— 该成交可能是本策略委托(策略成本/在途
            # 状态将无法校准, 策略还会误判未成交而重发), 必须响亮告警让用户核对柜台
            if volume > 0 and price > 0:
                if not is_strategy_target(code):
                    # 非策略标的的成交回报: 不写入策略日志/不推送(20261008 用户定稿)
                    return
                log('[实盘][告警] 成交回报备注无法识别(remark=%r 代码=%s %d股@%.2f) —— '
                    '未入账! 若这是本策略委托, 请核对柜台成交并检查备注格式(应为 BUY|代码/SELL|代码)'
                    % (rm, code, volume, price))
                try:
                    pnl_alert('[盈亏][异常] 成交回报备注无法识别未入账: %s %d股@%.2f(remark=%r)'
                              % (code, volume, price, rm))
                except Exception as _e:
                    # 第六轮零预设审计修复(2026-10-04): 关键路径(成交回报)异常不静默 ——
                    # 即使推送失败也要在日志留痕, 避免"推送悄悄失败"导致用户不知道异常
                    log('[告警][deal_callback] 成交回报告警推送异常(仍已写入日志): %s'
                        % repr(_e)[:120])
    except Exception:
        traceback.print_exc()
    finally:
        G.state_lock.release()

# ============================================================
# 【框架自动调用钩子, 勿删】orderError_callback: QMT框架废单回报钩子, 框架按函数名自动调用;
#   代码内搜不到调用点是正常的(框架按函数名反射调用), 不属于死代码。
# ============================================================

def orderError_callback(ContextInfo, orderArgs, errMsg):
    """下单异常: 买入失败且无成交则回到观察。
    P2-1加固: 同步退回当日买入额度(旧逻辑漏退, 废单占用当日买入机会);
    P2-2加固: orderArgs键名做兼容(orderCode/stockCode), 拿不到代码时只告警不误删"""
    G.state_lock.acquire()       # 审计修复3: 异常回调修改G.state, 加锁防并发
    try:
        # P2-1加固: 回报代码可能不带交易所后缀, 先归一化(hold记录键形如002142.SZ),
        # 否则买入废单不清理/不退额度, 卖出废单不触发立即重发
        code = _code_with_suffix(str(orderArgs.get('orderCode', '') or orderArgs.get('stockCode', '')
                                    or orderArgs.get('sStock', '') or ''))
        op = orderArgs.get('opType', 0) or orderArgs.get('nOpType', 0)
        # P1-1修复(2026-10-04): opType/nOpType 均取不到时按备注前缀反推方向, 避免 op=0
        # 导致下方四个分支全不命中而静默吞掉废单(买入不退额度 / 卖出不重发)。
        if not op:
            _remark = str(orderArgs.get('m_strRemark', '') or orderArgs.get('remark', '')
                          or orderArgs.get('m_strRemarkEx', '') or '')
            if _remark.strip().upper().startswith('SELL|'):
                op = 24
            elif _remark.strip().upper().startswith('BUY|'):
                op = 23
        err_oid = str(orderArgs.get('orderId', '') or orderArgs.get('orderID', '')
                      or orderArgs.get('order_id', '') or orderArgs.get('m_strOrderID', '') or '')
        # V2.6.159: 按本笔方向取登记; 方向不明时退回"两个方向里取较新的那条"(与旧行为等价)
        if op == 23:
            current = _oid_rec(code, 'buy')
        elif op == 24:
            current = _oid_rec(code, 'sell')
        else:
            _cb, _cs = _oid_rec(code, 'buy'), _oid_rec(code, 'sell')
            current = _cb if _f(_cb.get('ts', 0.0)) >= _f(_cs.get('ts', 0.0)) else _cs
        current_oid = str(current.get('id', '') or '')
        matched = bool(err_oid and current_oid and err_oid == current_oid)
        log('下单异常', disp(code), 'OrderID=%s' % (err_oid or '未知'), errMsg)
        if op == 23 and is_kcb_code(code):
            G.kcb_reject_date[code] = G.today
            # P3-1(2026-10-24 第18轮零预设独立审计): 科创板拒单后同样退回当日买入笔数 ——
            #   旧版只登记 codes 不退 b['n'], 而下方普通买入废单分支是退的, 口径不一致。
            #   危害例: MAX_DAILY_BUYS_LIVE=3, 科创板拒单1次 -> 当日剩余额度从3变2,
            #   等于白耗一个买入机会(当日实际只能再买2只主板股票)。
            #   防重复废单已由 G.kcb_reject_date(当日屏蔽)专职负责, 不需要再占用笔数额度。
            b = daily_buy_state()
            b['n'] = max(0, int(_f(b.get('n', 0))) - 1)
            if code in (b.get('codes') or []):
                b['codes'].remove(code)
            _disk_adjust_daily_buy(-1, code)   # 同步修正磁盘计数(防合并逻辑把退额改回)
            log('[安全][D3] 科创板买单被拒，已将%s屏蔽至当日结束，防每轮重复废单(已退回当日买入额度)' % disp(code))
            # P3-C-N2(2026-10-29 修复)：科创板分支已退过一次当日额度，必须在此结束。
            #   原实现继续往下走到通用买入废单分支(L12738)，又退一次 —— 报告实测
            #   拒单后当日额度从 3 变 1（应只变 2），等于白丢一个买入机会；
            #   减持/重报路径同理。此处直接清理持仓记录并返回，避免双重退额。
            _hk = G.state['hold'].get(code)
            if _hk and _hk.get('fill_vol', 0) <= 0:
                del G.state['hold'][code]
                G.state['done'].pop(code, None)
            G.buy_cnt = max(0, G.buy_cnt - 1)
            save_state()
            return
        if err_oid and current_oid and not matched:
            log('[安全] 忽略迟到的旧委托错误回调: 当前OrderID=%s 回调OrderID=%s' % (current_oid, err_oid))
            return
        if op == 23 and code:
            h = G.state['hold'].get(code)
            if h and h.get('fill_vol', 0) <= 0 and (matched or not current_oid):
                del G.state['hold'][code]
                G.state['done'].pop(code, None)
                G.buy_cnt = max(0, G.buy_cnt - 1)   # 委托失败, 回退计数
                # V2.6.165: 删除原此处 h['pend_vol'] = 0 —— 上一行 del 已把本条持仓记录
                #   从 hold 摘除, 此刻 h 只是内存里无人引用的孤立字典, 写进去进不了任何状态,
                #   属纯无效代码; 且它会误导维护者以为"在途量已清理", 实际整条记录连同在途量已一并消失。
                # P2-1: 退回当日买入额度, 废单不占用当日买入机会
                b = daily_buy_state()
                b['n'] = max(0, b['n'] - 1)
                if code in (b.get('codes') or []):
                    b['codes'].remove(code)
                _disk_adjust_daily_buy(-1, code)   # P2-21: 同步修正磁盘计数(防合并逻辑把退额改回)
                log(disp(code), '买入委托失败且无成交, 回到观察(已退回当日买入额度)')
                # [旧版简易台账已停用, 需要时取消以下注释; 盈亏账本只记成交, 不记失败委托]
                try:
                    pnl_alert('[盈亏] 买入委托失败, 回到观察(未成交不记账): %s %s' % (disp(code), errMsg))
                except Exception:
                    pass
                save_state()
        elif op == 23 and not code:
            log('下单异常(买入): 回报未携带代码, 无法自动清理, 请人工核对持仓记录')
        elif op == 24 and code and (matched or not current_oid):
            # 卖出委托失败(如价格超限被柜台拒单): 设置立即重发标记, 下一轮直接重发,
            # 不占用重试次数(不是超时未成交, 是柜台直接拒单, 重报价会被clamp_order_price修正)
            h = G.state['hold'].get(code)
            if h and h.get('exited'):
                h['sell_cancel_sent'] = False
                h['sell_giveup'] = False
                h['sell_retry_now'] = True      # 风险3修复: 标记立即重发, 绕过超时等待
                log(disp(code), '卖出委托失败, 已标记立即重发(不占用重试次数):', errMsg)
                save_state()
        elif op == 24 and not code:
            log('下单异常(卖出): 回报未携带代码, 等待超时重发机制处理')
        elif op not in (23, 24):
            # P1-1修复(2026-10-04): op 无法识别时不再静默吞掉 —— 打告警日志 + 保守回退买入额度
            # (code 若在当日买入 codes 中则退额, 防额度泄漏), 并提示人工核对回调字段。
            log('[告警] 下单异常回调方向无法识别(op=%r, 备注=%r), 请人工核对 orderArgs 字段; '
                'errMsg=%s' % (op, orderArgs.get('m_strRemark', '') or '', errMsg))
            try:
                if code:
                    _b = daily_buy_state()
                    if _b.get('date') == G.today and code in (_b.get('codes') or []):
                        _b['n'] = max(0, int(_b.get('n', 0) or 0) - 1)
                        _b['codes'].remove(code)
                        _disk_adjust_daily_buy(-1, code)
                        save_state()
                        log(disp(code), '方向未知的废单已保守退回当日买入额度, 请人工核对')
            except Exception:
                traceback.print_exc()
    except Exception:
        traceback.print_exc()
    finally:
        G.state_lock.release()

def print_summary():
    """V2.6.82修复(2026-10-19): 本函数此前从未定义 —— init() 中 atexit.register(print_summary)
    抛NameError被 except Exception: pass 静默吞掉, 连带下一行 _flush_names_cache 的注册一并
    死亡(策略停止时无交易笔数汇总, 退出时名称缓存不强制落盘)。
    现补全: 输出本次运行买卖笔数(进程内计数, 重启清零; 准确账本见状态文件trades)
    + 当前持仓只数, 收尾强制落盘日志。整体 try/except 保底(atexit 内绝不能再抛)。
    """
    try:
        _bc = int(getattr(G, 'buy_cnt', 0) or 0)
        _sc = int(getattr(G, 'sell_cnt', 0) or 0)
        _st = getattr(G, 'state', None)
        _hn = len(_st.get('hold') or {}) if isinstance(_st, dict) else 0
        log('================ 本次运行结束汇总 ================')
        log('[汇总] 本次运行买入%d笔 卖出%d笔, 当前持仓%d只 (进程内计数, 重启清零; '
            '准确账本见状态文件trades)' % (_bc, _sc, _hn))
    except Exception:
        traceback.print_exc()
    try:
        _flush_log(force=True)      # 收尾强制落盘, 保证最后一屏日志与汇总进文件
    except Exception:
        traceback.print_exc()

# ==================== 框架入口 ====================
def init(ContextInfo):
    """框架初始化: 启动横幅最先输出, 其余步骤全部容错, 保证任何客户端版本都能启动"""
    # [本地文件日志已停用, 需要时取消以下注释]
    # try:
    # except Exception:
    #     pass
    G.C = ContextInfo
    G.accid = str(globals().get('account') or ACCOUNT_ID or '').strip()
    try:
        G.state = load_state()
    except Exception:
        traceback.print_exc()
        G.state_broken = True
        G.state_broken_lock = True          # V2.6.158: 人工核对型冻结, 写盘成功不解除
    # P1-17: 状态文件记录账号标识(多账号共用目录防串号; 不匹配的文件在load_state已拒绝装载)
    if isinstance(G.state, dict):
        G.state['account'] = G.accid
        if G.state_broken:
            log('[安全][告警] 状态不可用: 已禁止一切下单(修复状态文件后重启策略恢复)。'
                '在状态不可信时下单会导致重复买入/持仓失管/手数虚高。')
    G.ready = True
    try:
        import atexit
        atexit.register(print_summary)   # 策略停止时输出交易笔数汇总, 保证收尾记录可见
        atexit.register(_flush_names_cache, True)   # 重审20261005(1-7): 退出前强制落盘名称缓存
    except Exception:
        pass
    log('涨停缩量低吸策略启动 [%s] 账号=%s | 真实passorder=%s | 版本=%s'
        % ('模拟盘' if DRY_RUN else '实盘', G.accid or '(未绑定)', not DRY_RUN, VERSION))
    # 启动横幅之后第一件事: 立即刷新日历并打出"今日交易日状态 + 当前时段"清晰日志
    # V2.6.16: 启动自检横幅(文件基准目录 + 各清单/状态文件实际读取路径, 只读不影响启动)
    startup_selftest()
    # (refresh_calendar 内部会自动调用 log_day_phase_banner, 这里不必再单独打一次)
    try:
        refresh_calendar()
    except Exception:
        traceback.print_exc()

    # 情绪模块: 启动初始化(仅置状态+日志; V2.6.61 R2: 数据刷新延后至定时器首轮, 不阻塞宿主init)
    try:
        sent_bootstrap()
    except Exception:
        traceback.print_exc()
    log('资金与手数: 基准权益模式=%s 单笔风险=%.1f%% | 单票相对上限%.0f%% 单票绝对额度%.2f元 | 持仓上限=%d只 动态手数=%s'
        ' (具体资金金额不在日志中显示)'
        % (SIZE_EQUITY_MODE, RISK_PCT * 100, MAX_POS_VALUE_PCT * 100, MAX_POS_VALUE_ABS,
           pos_limit(), DYN_SIZING_ON))
