                                         #   归一化权重, 等于悄悄换了一条指数), 改为沿用上次信号
SENT_CARRY_LOG_SEC = 1800                # V2.6.87: 沿用上次信号期间, 告警日志最小间隔(秒)
SENT_CACHE_FILE = 'zt_shrink_sent_cache.json'   # V2.6.87: 上一次成功信号缓存(跨重启沿用)
HEARTBEAT_FILE = 'zt_shrink_heartbeat.json'     # V2.6.87: 实例心跳文件(实际名带账号+PID)
