        _abort = False          # V2.6.90(2): 接口整体不可用 -> 已触发熔断
        _budget_hit = False     # V2.6.90(1): 已耗尽总预算, 带已取到的部分收尾
        _nb_ok = 0   # V2.6.93(3): 已完成批数, 供预算告警算"均X秒/批"(局部变量, 不入指纹)
        _t_dl = 0.0    # V2.6.113(B): 批内下载累计秒数(各批 _dt_b 之和)。
