        #   纯收尾开销 —— 这部分不影响结果, 只影响接口/CPU 占用时长, 属可优化项。
        _t_loop_beg = time.time()     # V2.6.115: 预算循环起点
        _t_loop_end = _t_loop_beg     # V2.6.115: 预算循环终点(无批次时退化为起点)
        for _attempt in (0, 1):   # 第2轮改用全字段(兼容个别客户端不认preClose字段名)
            _stats = {}
