                _pb2_a = 0
                for _pb2_i in range(50000):
                    _pb2_a += _pb2_i & 7
                _pb2_t1 = time.time()
                _pb2_dt = _pb2_t1 - _pb2_t0
                _pb2_loop += 1
                _pb2_sum += _pb2_dt
                if _pb2_dt > _pb2_max:
                    _pb2_max = _pb2_dt
                if _pb2_dt >= 1.0:
                    # V2.6.132: 落点取【结束时刻】的秒内余数 —— 阻塞是在这段时间
                    #   里被恢复的, 恢复点才贴着定时器节拍。
                    # V2.6.135: 补记 %30 相位与冻结合计时长。
                    #   %10 无法区分 10/20/30 秒节拍: 30 秒周期在 %10 下余数同样恒定,
                    #   集中度照样 100%。V2.6.134 实测 sec2=4 / 集中度100% 正是这种
                    #   "看着确证、其实分不清"的读数, 必须配 %30 才能定周期。
                    _pb2_k = int(_pb2_t1) % 10
                    _pb2_k30 = int(_pb2_t1) % 30
                    _pb2_slow[_pb2_k] = _pb2_slow.get(_pb2_k, 0) + 1
                    _pb2_slow30[_pb2_k30] = _pb2_slow30.get(_pb2_k30, 0) + 1
                    _pb2_slow_n += 1
                    _pb2_slow_sum += _pb2_dt
