# 信号计算(纯标准库)
# ---------------------------------------------------------------------------


def _winsorize_list(vals):
    # 分位数缩尾(缺失保持None)
    ok = [x for x in vals if x is not None]
    if not ok:
        return list(vals)
    lo = _sent_quantile(ok, SENT_WINSORIZE_LOWER)
    hi = _sent_quantile(ok, SENT_WINSORIZE_UPPER)
    return [max(lo, min(hi, x)) if x is not None else None for x in vals]


def _sent_comp_note(sig):
    # V2.6.87(3): 合成指数的分量可用性说明 —— 旧版只打一个总 sentiment, 缺分量时
    #   按剩余分量重新归一化权重, 阈值却是按3分量标定的, 看日志完全不知道指数定义变了。
    # V2.6.159: 名字按实际口径改准 —— 这一项统计的是"涨幅>=4.9%的家数"(ST与非ST统一门槛),
    #   不是真涨停家数。旧名会让人拿它对真涨停数比, 一对就差5~10倍, 误以为数据错了。
    # 20261027: 用户要求把三个 z 值具体标注出来 —— 旧版只列"哪些分量可用(3/3 全可用)",
    #   看不到 z 值本身, 无法判断"今天到底是成交额砸下来的还是涨跌广度拖下来的"。
    #   现改为逐个分量输出: 名称=z值 x 权重 = 贡献分, 并汇总合成指数。
    #   只改展示, 不改任何判定; 取不到 z_parts 时自动退回旧文案, 保证不因格式问题报错。
    _meta = {'z_advpct': '涨跌广度', 'z_limit_up': '强势股家数(涨幅>=4.9%)',
             'z_turnover': '成交额'}
    try:
        _have = list(sig.get('comp_have') or [])
        _miss = list(sig.get('comp_miss') or [])
        _tot = int(sig.get('comp_total') or 0)
        _parts = sig.get('z_parts') or []
        # 有明细就展开打印, 没有则退回旧的一句话
        if not _parts:
            _hs = ','.join(_meta.get(k, k) for k in _have) or '无'
            if not _miss:
                return '%s(%d/%d 全可用)' % (_hs, len(_have), _tot)
            _ms = ','.join(_meta.get(k, k) for k in _miss)
            return '%s(%d/%d, 缺%s -> 权重已按剩余分量归一化, 阈值仍按%d分量标定)' % (
                _hs, len(_have), _tot, _ms, _tot)

        def _sig_txt(z):
            """给 z 值配一句大白话。分档与全系统的"2σ=极端事件"口径对齐:
               |z|>=2 极热/极冷(同时触发 L1 事件闸门) ; 1<=|z|<2 偏热/偏冷 ; |z|<1 中性。
               注意 z 是"多少个标准差", 不是百分比。"""
            if z >= 2.0:
                return '极热'
            if z >= 1.0:
                return '偏热'
            if z <= -2.0:
                return '极冷'
            if z <= -1.0:
                return '偏冷'
            if z <= -0.5:
                return '略偏冷'
            if z >= 0.5:
                return '略偏热'
            return '中性'

        # 20261027: 每个分量独占一行。旧版把三个分量用 ' | ' 连成一行(约120字符),
        #   在 QMT 日志窗里超宽折行, 折下来的半行会和下一条日志首尾相接, 看起来像
        #   两条记录粘在一起(21:39 实测: "合成情绪=-0.715(3/3分量)" 后紧跟 "人话解读")。
        #   现改为: 首行标题 + 每分量一行 + 末行合成值, 每行 < 50 字符, 不再折行。
        #   数值与顺序完全不变, 只改换行位置。
        _NL2 = chr(10)
        _lines = ['信号详细构成(逐分量 标准差倍数 z值 x 权重 = 贡献):']
        for p in _parts:
            _nm = _meta.get(p.get('k'), p.get('k'))
            _z = float(p.get('z') or 0.0)
            _w = float(p.get('nw') or 0.0)
            _c = float(p.get('contrib') or 0.0)
            _lines.append('  %s = %.3f[%s] x %.0f%% = %+.3f'
                          % (_nm, _z, _sig_txt(_z), _w * 100.0, _c))
        _s = float(sig.get('sentiment') or 0.0)
        _tail = '  合成情绪 = %.3f (%d/%d 分量' % (_s, len(_have), _tot)
        if _miss:
            _ms = ','.join(_meta.get(k, k) for k in _miss)
            _tail += ', 缺%s 权重已按剩余分量归一化, 阈值仍按%d分量标定' % (_ms, _tot)
        _lines.append(_tail + ')')
        return _NL2.join(_lines)
    except Exception:
        return '分量信息不可用'


def _sent_compute(rows):
    # 在已完成交易日序列(升序, 不含今天)上计算情绪信号; 无法计算返回 None
    n = len(rows)
    if n < SENT_MIN_PERIODS:
        _sent_wlog('历史交易日不够(仅%d天,至少要%d天),算不了情绪信号' % (n, SENT_MIN_PERIODS))
        return None
    adv = _sent_col_series(rows, 'mkt_advance')
    dec = _sent_col_series(rows, 'mkt_decline')
    lu = _sent_col_series(rows, 'limit_up_cnt')
    amt = _sent_col_series(rows, 'mkt_amount')
    advpct = []
    limit_up_ratio = []
    for i in range(n):
        if adv[i] is None or dec[i] is None:
            advpct.append(None)
            limit_up_ratio.append(None)
            continue
        denom = (adv[i] or 0.0) + (dec[i] or 0.0)
        if denom <= 0:
            advpct.append(None)
            limit_up_ratio.append(None)
            continue
        advpct.append((adv[i] or 0.0) / denom)
        limit_up_ratio.append((lu[i] if lu[i] is not None else 0.0) / denom)
    # 缩尾 -> EWMA平滑 -> 滚动z(最后一行)
    advpct_s = _sent_ewma(_winsorize_list(advpct), SENT_EWMA_SPAN)
    limit_up_ratio_s = _sent_ewma(_winsorize_list(limit_up_ratio), SENT_EWMA_SPAN)
    amt_s = _sent_ewma(_winsorize_list(amt), SENT_EWMA_SPAN)
    z_advpct = _sent_z_last(advpct_s, SENT_ZSCORE_WIN)
    z_limit_up = _sent_z_last(limit_up_ratio_s, SENT_ZSCORE_WIN)
    z_turnover = _sent_z_last(amt_s, SENT_ZSCORE_WIN)
    # 合成指数(按可用分量重新归一化权重)
    keys = []
    for _k, _w in SENT_SENTIMENT_WEIGHTS:
        _z = {'z_advpct': z_advpct, 'z_limit_up': z_limit_up, 'z_turnover': z_turnover}.get(_k)
        if _z is not None:
            keys.append((_k, _w, _z))
    _all_k = [k for k, _ in SENT_SENTIMENT_WEIGHTS]
    _have_k = [k for k, _, _ in keys]
    _miss_k = [k for k in _all_k if k not in _have_k]
    if not keys:
        _sent_wlog('所有情绪指标都取不到有效值,没法合成情绪信号')
        return None
    wsum = sum(_w for _, _w, _ in keys)
    s = 0.0
    for _k, _w, _z in keys:
        s += (_w / wsum) * _z
    # 事件哑变量
    evt_frenzy = (z_advpct is not None and z_advpct > SENT_EVT_FRENZY_ADVPCT) or \
                 (z_limit_up is not None and z_limit_up > SENT_EVT_FRENZY_LIMITUP)
    evt_panic = (z_advpct is not None and z_advpct < SENT_EVT_PANIC_ADVPCT)
    # L1 过滤
    gate = (s < SENT_CORE_PARAMS['gate_panic_th']) or \
           (s > SENT_CORE_PARAMS['gate_frenzy_th']) or evt_frenzy or evt_panic
    # L3 Regime
    if s < SENT_REGIME_PANIC_LO:
        regime = 'panic'
    elif s > SENT_REGIME_FRENZY_HI:
        regime = 'frenzy'
    else:
        regime = 'neutral'
    # L4 仓位(仅过热收缩, 下限保护)
    hot = s if s > 0.0 else 0.0
    size_mult = 1.0 - SENT_CORE_PARAMS['size_hot_scale'] * _sent_tanh(SENT_SIZE_HOT_TANH_K * hot)
    if size_mult < SENT_SIZE_MIN_MULT:
        size_mult = SENT_SIZE_MIN_MULT
    overrides = dict(SENT_REGIME_PARAMS.get(regime) or {})
    return {
        'date': rows[-1]['date'],
        'sentiment': s,
        'regime': regime,
        'gate_skip': bool(gate),
        'evt_frenzy': evt_frenzy,
        'evt_panic': evt_panic,
        'size_mult': size_mult,
        'overrides': overrides,
        'comp_have': _have_k,
        'comp_miss': _miss_k,
        'comp_total': len(_all_k),
        # 20261027: 把三个分量 z 值、原始权重、归一化权重、贡献分一并带出 ——
        #   旧版只带 comp_have/comp_miss(哪些可用), 日志看不出 z 值到底多少、谁贡献大。
        #   仅新增字段, 不参与任何判定(gate/regime/size_mult 仍用上面已算好的变量)。
        'z_parts': [{'k': _k, 'w': _w, 'nw': (_w / wsum) if wsum > 0 else 0.0,
                     'z': _z, 'contrib': ((_w / wsum) * _z) if wsum > 0 else 0.0}
                    for _k, _w, _z in keys],
        'z_advpct': z_advpct, 'z_limit_up': z_limit_up, 'z_turnover': z_turnover,
        'w_sum': wsum,
    }


def _sent_fresh_enough(last_date, today):
    # 判断情绪数据最近完成日是否过期(交易日历优先, 缺失时自然日宽松兜底)
    try:
        _cal = getattr(G, 'calendar', None)
        if _cal:
            _cal = [str(x)[:8] for x in _cal]
            if today in _cal and last_date in _cal:
                return 0 < (_cal.index(today) - _cal.index(last_date)) <= SENT_MONITOR_MAX_STALE_DAYS
        import datetime
        try:
            _nat = (datetime.datetime.strptime(today, '%Y%m%d') -
                    datetime.datetime.strptime(last_date, '%Y%m%d')).days
        except Exception:
            _nat = 0
        return 0 < _nat <= max(SENT_MONITOR_MAX_STALE_DAYS * 2, 10)
    except Exception:
        # V2.6.167修复(2026-10-23): 兜底判断在异常时原来返回 True(可"沿用"), 实际是
        #   "沿用信号过旧或交易日未知", 而这里却把它当作可沿用的旧信号(情绪闸门前只取
        #   "最近一次信号"), 行为与文案相反; 兜底一律按 False(不沿用 -> 走保守 -> 拦截),
        #   与"取数未知=保守拦截"保持一致, 情绪闸门也不可被绕开。
        return False


