def sent_bootstrap():
    # 启动初始化: 初始化状态字典并打版本/指纹日志; V2.6.61 R2起不在此处拉数据(详见下方说明)
    global _SENTIMENT_READY
    if not _SENTIMENT_ON:
        return
    try:
        # V2.6.110: clear() 会连 last_fetch_date 一起清掉 -> 换代码重启后当天重取一遍。
        #   今天无害(本就还没出信号), 但明天盘中换代码就会把已成功的信号标记抹掉,
        #   重取一轮(几十秒~几分钟接口占用), 并可能覆盖已算好的信号。
        #   故 clear 前把该标记取出来; V2.6.159 起改为与信号本体一起取出,
        #   只有本体完整才放回(见下方恢复条件), 否则丢弃标记让当天重取一次。
        _keep_fetch_date = SENT_STATE.get('last_fetch_date')
        _keep_sig_date = SENT_STATE.get('date')
        # V2.6.159: 旧版只留"今天已刷新"标记、不留信号本体 —— 这是个死锁:
        #   标记留着 -> 刷新入口首句"今天刷过"直接返回, 当天不再取数;
        #   信号本体却被 clear 清空, 就绪开关又是关着的 -> 没人能把它打开。
        #   V2.6.151 起"未就绪即不许买", 于是整天一笔不买, 日志只有一句"还没就绪"。
        #   现在把信号本体一起快照, 标记与本体同进同出。
        _keep_sig = {}
        for _k in ('sentiment', 'regime', 'gate_skip', 'size_mult',
                   'overrides', 'events', 'carried', 'last_sig_ts'):
            if _k in SENT_STATE:
                _keep_sig[_k] = SENT_STATE[_k]
        _keep_ready = bool(_SENTIMENT_READY)
        SENT_STATE.clear()
        SENT_STATE['gate_skip'] = False
        SENT_STATE['size_mult'] = 1.0
        SENT_STATE['overrides'] = {}
        SENT_STATE['acc_pending'] = False
        # V2.6.106(方案9): 重启即清空累积池 —— 换日/换进程都从零开始拼
        # V2.6.110: gen 写 -1.0 哨兵, 不写 _GEN_STATE['id']。
        #   病因: sent_bootstrap() 在 init() 里跑, 而 gen_announce() 在 after_init() 里跑,
        #   init 时 _GEN_STATE['id'] 还是 0.0 -> 池子记下 gen=0.0; 首次取数时本代已宣告
        #   (非0), 比对必然不符 -> 白打一条【累积池重置: 换日(空 -> 20261020)】, 像是
        #   真有旧代污染, 实则池子本来就是空的(已清0只)。
        #   -1.0 = 【尚未绑定任何代】, 首次取数时直接绑定当前代, 不算换代、不打日志。
        _SENT_ACC.update({'date': '', 'gen': -1.0,
                          'md': {}, 'ok': 0, 'fail': 0,
                          'retry': 0, 'rounds': 0, 'pend_rounds': 0})
        # V2.6.159: 只有"当天已成功刷新 + 信号本体完整 + 当时确实就绪"才把标记放回,
        #   并同时恢复就绪; 任何一项不满足就丢弃标记, 让刷新入口当天正常重取一次 ——
        #   多取一轮最多几十秒, 也绝不能整天卡在未就绪。
        _restored = False
        _drop_note = False
        if _keep_fetch_date and _keep_fetch_date == _sent_today() \
                and _keep_sig_date and _keep_ready \
                and _keep_sig.get('sentiment') is not None:
            SENT_STATE['last_fetch_date'] = _keep_fetch_date
            SENT_STATE['date'] = _keep_sig_date
            for _k2 in _keep_sig:
                SENT_STATE[_k2] = _keep_sig[_k2]
            _restored = True
        elif _keep_fetch_date or _keep_sig_date:
            _drop_note = True
        SENT_STATE['rows'] = []
        _SENTIMENT_READY = _restored
        _sent_wlog('情绪模块初始化: 版本=%s 阶段=%d 参数校验码=%s (数据没准备好前暂停开新仓)'
                   % (SENT_VERSION, _SENTIMENT_PHASE, sent_fingerprint()))
        if _restored:
            _sent_wlog('情绪信号沿用本进程已算好的结果(日期=%s, 情绪值=%.2f): '
                       '不重取、直接就绪' % (_keep_sig_date, _f(_keep_sig.get('sentiment'))))
        elif _drop_note:
            _sent_wlog('上次的"今日已刷新"标记已丢弃(信号本体不完整), 当天将重新取数一次')
        if _SENTIMENT_PHASE >= 3:
            _sent_wlog('L2增强说明: 宿主为规则型买入(缩量低吸), 无独立技术评分通道, '
                       'L2增强保留参数与指纹但不改变买入结果; L1/L3/L4 全量生效')
        # V2.6.61 R2修复(2026-10-17用户确认方案A): 启动绝不在init中同步拉取情绪数据 ——
        #   旧版此处直接调sent_daily_refresh()→sent_fetch_all_data()同步拉取
        #   SENT_BACKFILL_DAYS自然日x全市场5227只日线(客户端22:00实测init被堵死在此步),
        #   宿主初始化全部推迟: 启动横幅后半段/资金风控口径/账号探测/对账/定时器注册
        #   迟迟不执行, 策略长时间处于"半就绪"状态。
        #   情绪信号为日频滞后1日数据, 晚数分钟就绪无任何损失; 首次刷新延后至
        #   timer_poll首轮(挂载点已就位: 幂等+SENT_RETRY_SEC节流+失败降级中性),
        #   就绪前买入侧一律暂停(V2.6.151 起, 见 sent_gate_skip); size_mult 仍置 1.0 只是中性占位, 不再代表"允许买"。
        _sent_wlog('启动初始化完成(仅置状态未拉数据): 首次情绪刷新延后至定时器首轮, '
                   '宿主初始化不被阻塞')
    except Exception as _e:
        _SENTIMENT_READY = False
        _sent_wlog('情绪初始化出了问题(未就绪将暂停开新仓, 卖出不受影响): %s' % _e)


def sent_daily_refresh():
    # 每交易日刷新情绪信号(滞后1日); V2.6.76: 取数已移交后台线程(见 sent_fetch_all_data),
    #   主线程此处只做幂等节流判定并"发一条刷新指令", 立即返回, 绝不阻塞盘中轮询。
    #   幂等: 今日已成功刷新过则不再发起; 失败则按 SENT_RETRY_SEC 节流重试。
    if not _SENTIMENT_ON:
        return
    try:
        _t = _sent_today()
        if SENT_STATE.get('last_fetch_date') == _t:
            return                      # 今日已刷新
        _now = time.time()
        # V2.6.99(1) 建此退避, V2.6.107 改判据: 只有"累积覆盖不再推进"才退避。
        #   旧判据看本轮是否 budget_hit, 双实例下每轮都命中 -> 永远退避 1800 秒,
        #   与 V2.6.106 的跨轮累积冲突(累积需 4 轮, 30 分钟一轮 = 2 小时才拼满)。
        #   新判据由取数侧写入: 累积增长 >= 2 个百分点即清零, 保持 300 秒节奏。
        _bh_streak = int(SENT_STATE.get('bh_streak') or 0)
        # V2.6.108: 累积挂起(acc_pending) 优先于退避 —— 挂起只说明【还没拼满】, 不是
        #   【接口取不动】, 必须按 300 秒节奏继续拼; 否则 acc_pending 一旦被 1800 秒
        #   退避接住, 累积池有余量也白等(11:31 那次启动就是这样整天出不了信号)。
        if SENT_STATE.get('acc_pending'):
            _retry_sec = SENT_RETRY_SEC
        else:
            _retry_sec = 1800.0 if _bh_streak >= 2 else SENT_RETRY_SEC
        if (_now - (SENT_STATE.get('last_try_ts') or 0.0)) < _retry_sec:
            if _bh_streak >= 2 and (_now - (SENT_STATE.get('bh_backoff_log_ts') or 0.0)) >= _retry_sec:
                SENT_STATE['bh_backoff_log_ts'] = _now
                _sent_wlog('情绪取数已连续%d轮触发总预算(接口慢约11~21倍), 重试间隔退避300->1800秒;'
                           '某轮不再命中预算即自动恢复300秒' % _bh_streak)
            return                      # 重试节流
        # V2.6.96(1): 日线下载期间不发起情绪取数 —— 两者都是"全市场批量打行情接口"。
        #   2026-10-20 00:22:33 那次启动, 5226 只日线下载与 5226 只情绪取数同一秒并发:
        #   下载每轮 8 秒只推进 153 只(正常 400), 情绪取数从常态约 40 秒拖到 151~195 秒,
        #   互相抢接口, 谁也跑不快, 5226 只下完要 17 分钟。现改为串行: 下载阶段1
        #   (G.dl_phase==1)期间只推迟、不发起; 下载完成后的下一轮定时器(30 秒内)自动发起,
        #   推迟期间情绪仍未就绪 -> V2.6.151 起买入侧一律暂停(与"信号没算出来"同档)。
        #   注意这里不写 last_try_ts, 所以每轮都会重新判一次 dl_phase, 不会被 300 秒节流卡住。
        #   但下载卡死不能把情绪一起拖死: 推迟满 30 分钟就告警并强行发起。
        if int(getattr(G, 'dl_phase', 0) or 0) == 1:
            _dl_since = SENT_STATE.get('dl_wait_ts') or 0.0
            if _dl_since <= 0:
                SENT_STATE['dl_wait_ts'] = _now
                _dl_since = _now
            if (_now - _dl_since) < 1800.0:
                if (_now - (SENT_STATE.get('dl_wait_log_ts') or 0.0)) >= 300.0:
                    SENT_STATE['dl_wait_log_ts'] = _now
                    _sent_wlog('股票日线还在下载中,本轮情绪取数延后(两者同时跑会抢行情接口)'
                               '(实测下载每轮8秒只推进153只、情绪取数从约40秒拖到151秒以上)。'
                               '下载结束后的下一轮定时器(30秒内)自动发起, 期间情绪未就绪故买入一律暂停')
                return
            _sent_wlog('[告警] 日线下载已持续%d分钟仍未完成, 不再等它: 本轮情绪取数照常发起'
                       '(两者并发会互相拖慢, 但情绪迟迟不就绪对明早的闸门判断影响更大)'
                       % int((_now - _dl_since) / 60.0))
        else:
            SENT_STATE['dl_wait_ts'] = 0.0
        SENT_STATE['last_try_ts'] = _now
        # 发起后台取数(立即返回None, 不阻塞); 幂等由 sent_fetch_all_data 内的非阻塞锁保证
        sent_fetch_all_data()
    except Exception as _e:
        # V2.6.78 P2-1: 异常节流 — 每60秒最多一条, 持续故障持续有信号但不刷屏
        import time as _t
        _now_ts = _t.time()
        _last_err_ts = SENT_STATE.get("last_err_ts", 0.0)
        if _now_ts - _last_err_ts >= 60.0:
            SENT_STATE["last_err_ts"] = _now_ts
            _sent_wlog('情绪刷新调度出了问题(未就绪将暂停开新仓, 卖出不受影响): %s' % _e)


def _sent_reset_ready(why):
    # 降级中性: 清空信号并复位就绪标记
    global _SENTIMENT_READY
    _SENTIMENT_READY = False
    SENT_STATE['err'] = why
    SENT_STATE['gate_skip'] = False
    SENT_STATE['size_mult'] = 1.0
    SENT_STATE['overrides'] = {}
    _sent_wlog('情绪信号暂时退回中性(此时暂停开新仓, 卖出不受影响): %s' % why)


def sent_gate_skip():
    # L1闸门: 恐慌/狂热/极端事件暂停新开仓
    # V2.6.151(用户要求): 情绪模块开着但还没就绪时, 一律不许买。
    #   旧版此处 "not (_SENTIMENT_ON and _SENTIMENT_READY) -> return False" 是放行,
    #   等于"今天情绪数据没到, 就当我没看见" —— 启动后首轮取数要 20~30 秒,
    #   这段空窗期里 can_open_new 会判定情绪通过, L1闸门形同虚设。
    #   实测 2026-10-21 13:00:54 启动, 13:01:21 首轮已判买入, 13:01:22 情绪才算出。
    #   现在改成: 模块开着 + 未就绪 -> 视为拦阻(卖出一侧完全不受影响)。
    if not _SENTIMENT_ON:
        return False
    if not _SENTIMENT_READY:
        return True
    return bool(SENT_STATE.get('gate_skip', False))


def sent_block_note():
    # V2.6.151: 返回情绪侧当前的拦阻原因(空串=放行)。
    #   为什么另外开一个函数: 两种拦阻都停买, 但处置完全不同 ——
    #   "恐慌/狂热" 是策略要的效果(等市场冷下来), 属正常运行;
    #   "未就绪" 是数据管道出问题(行情接口没登录/取数降级), 必须人工介入。
    #   日志里混成一句"情绪L1闸门", 事后根本分不清该不该修。
    if not _SENTIMENT_ON:
        return ''
    if not _SENTIMENT_READY:
        return '情绪数据未就绪(取数未完成或已降级, 需检查QMT行情接口)'
    if sent_gate_skip():
        return '情绪L1闸门(恐慌/狂热/极端事件)'
    return ''


def sent_size_mult():
    # L4仓位乘数: 过热收缩, 下限保护
    # P3-4(2026-10-24 第18轮零预设独立审计): 旧版把"模块关闭"和"模块开启但数据未就绪"
    #   混为一律返回 1.0(中性占位)。数据未就绪时返回 1.0 意味着"乘数不缩仓" —— 单看本函数
    #   闸门形同虚设; 当前闭环靠 sent_gate_skip()(未就绪返回True=停买)兜底才成立,
    #   属"单点依赖"的设计脆弱性: 任何人将来新增买入路径不过 sent_block_note,
    #   size_mult=1.0 会静默放行。现区分两种语义: 模块关闭=不干预(1.0);
    #   模块开启但未就绪=不允许开出任何仓位(0.0), 与 sent_gate_skip 同口径。
    if not _SENTIMENT_ON:
        return 1.0
    if not _SENTIMENT_READY:
        return 0.0
    m = SENT_STATE.get('size_mult')
    if isinstance(m, (int, float)) and m > 0:
        return float(m)
    return 1.0


def sent_param_overrides():
    # L3 Regime参数覆写字典(键=宿主常量名); 未就绪={}
    if not (_SENTIMENT_ON and _SENTIMENT_READY):
        return {}
    o = SENT_STATE.get('overrides')
    if isinstance(o, dict):
        return dict(o)
    return {}


def sent_param(name, default):
    # 读取宿主参数(带L3覆写); 未覆写返回 default
    o = sent_param_overrides()
    if name in o:
        # S2(2026-10-24): 覆写生效时按交易日节流打印一次, 让操作员明知哪些参数被情绪Regime改了
        _ov_day = getattr(G, 'today', '')
        if _ov_day and _ov_day != sent_param._last_day:
            sent_param._last_day = _ov_day
            try:
                log('[情绪Regime覆写] 本交易日生效: %s'
                    % (', '.join('%s=%s' % (k, o[k]) for k in sorted(o.keys()))))
            except Exception:
                pass
        return o[name]
    return default
sent_param._last_day = ''


# ===== 情绪模块(单文件合并) END =====
